#[cfg(test)]
fn verify_full_bundle_with_optional_native_trust_ir(
    engine: &trust_router::FullVerificationEngine,
    bundle: &trust_verifier_api::TrustContractBundle,
    obligations: &[trust_verifier_api::TrustObligation],
    native_trust_ir_bundle: Option<&trust_ir_bridge::NativeVerificationBundle>,
    context: &trust_router::VerifierExecutionContext,
) -> trust_router::VerificationRunResult {
    // Keep even result-only compiler tests on the same optional-native dispatch
    // seam as production. Destructuring deliberately drops both private maps;
    // the returned public carrier therefore remains attribution-only.
    let (result, _live_receipts) = engine
        .verify_obligations_with_optional_native_trust_ir_bundle_and_live_receipts(
            bundle,
            obligations,
            native_trust_ir_bundle,
            context,
        )
        .into_parts();
    result
}

struct LiveFullVerificationDispatch {
    result: trust_router::VerificationRunResult,
    body_bound_receipts: Vec<InitialLiveBodyBoundReceipt>,
    live_receipts: Option<trust_router::LiveVerificationReceiptBatch>,
}

/// Execute the real in-process native verifier and immediately freeze the
/// exact body-bound Trust-WP rows it returned. This wrapper is the sole mint
/// site for [`InitialLiveBodyBoundReceipt`]; callers cannot turn a deserialized
/// `VerificationRunResult` into one after the fact. The private finalizer below
/// is the sole promotion from that live receipt to consumable authority.
fn verify_full_bundle_with_body_bound_receipts(
    bundle: &trust_verifier_api::TrustContractBundle,
    obligations: &[trust_verifier_api::TrustObligation],
    native_bundle: Option<&trust_ir_bridge::NativeVerificationBundle>,
    body_bound_carriers: &[CompilerFinalizedBodyBoundCarrier],
    context: &trust_router::VerifierExecutionContext,
    per_obligation_timeout_ms: u64,
) -> LiveFullVerificationDispatch {
    // The mint boundary owns the production engine set. In particular, no
    // caller can inject a trust-wp-named fake engine and obtain a private live
    // receipt from its otherwise well-shaped composite evidence.
    //
    // Build at the session's configured `-Z trust-verify-timeout-ms` rather than
    // the engine's session-less default: the native trust-mc engine used to
    // hardcode a mirror of that default, so raising the flag bought no extra
    // budget here and hard-but-provable obligations kept reporting
    // Unknown/Timeout no matter what the user asked for. SOUND: the budget
    // bounds only how long a sound solver lane may run; a larger budget can turn
    // Unknown into a definite verdict, never an unproved obligation into a proof.
    let engine = trust_router::FullVerificationEngine::with_required_native_engines_timeout_ms(
        per_obligation_timeout_ms,
    );
    // The ordinary entry points deliberately discard all affine sidecars.
    // Always use the optional-native live API, including when no native bundle
    // exists: the dedicated direct TrustVC lane is precisely the no-native-
    // identity route, while S3 still requires a typed native CHC/PDR request.
    let (result, live_receipts) = engine
        .verify_obligations_with_optional_native_trust_ir_bundle_and_live_receipts(
            bundle,
            obligations,
            native_bundle,
            context,
        )
        .into_parts();
    // Keep receipt construction lexically inside the live-call wrapper. There
    // is intentionally no helper that accepts an arbitrary/deserialized run
    // and returns receipts (including under `cfg(test)`).
    let body_bound_receipts = if let Some(native_bundle) = native_bundle {
        let capture_live_result =
            || {
                if body_bound_carriers.is_empty()
                    || result.requested_obligations != obligations
                    || result.bundle_id != bundle.bundle_id
                    || result.subject != bundle.subject
                    || result.validate_derived_state().is_err()
                {
                    return Vec::new();
                }
                let Ok(manifest) = result.try_to_manifest() else { return Vec::new() };
                let mut receipts = Vec::new();
                for carrier in body_bound_carriers {
                    if !carrier.matches_compiler_inputs(bundle, native_bundle) {
                        continue;
                    }
                    let mut returned = result.requested_obligations.iter().filter(|obligation| {
                        obligation.obligation_id == carrier.canonical_obligation.obligation_id
                    });
                    let Some(returned_obligation) = returned.next() else { continue };
                    if returned.next().is_some()
                        || returned_obligation != &carrier.canonical_obligation
                    {
                        continue;
                    }
                    let mut matching_evidence = result.evidence.iter().filter(|evidence| {
                        evidence.obligation_id == returned_obligation.obligation_id
                    });
                    let Some(evidence) = matching_evidence.next() else { continue };
                    if matching_evidence.next().is_some()
                    || evidence.status != trust_verifier_api::EvidenceStatus::Proved
                    || evidence.proof_strength.as_ref()
                        != Some(&trust_verifier_api::ProofStrength::deductive())
                    // The full verifier deliberately rewrites accepted child
                    // evidence to its composite manifest. The exact native
                    // request/route above binds this row to trust-wp; requiring
                    // the child manifest here would reject every genuine live
                    // result after that ownership-preserving wrapper step.
                    || evidence.engine != result.engine
                    || evidence.engine.name != "trust-full-verifier"
                    || evidence.engine.kind != trust_verifier_api::EngineKind::Composite
                    || evidence.engine.repository.is_some()
                    || !evidence.is_unbounded_proof()
                    || !evidence_has_exact_native_trust_ir_artifact_lineage(
                        returned_obligation,
                        evidence,
                    )
                    || result.skipped.iter().any(|skipped| {
                        skipped.obligation_id == returned_obligation.obligation_id
                    }) {
                        continue;
                    }
                    let mut decisions = manifest.accepted_evidence.iter().filter(|decision| {
                        decision.obligation_id == returned_obligation.obligation_id
                    });
                    let Some(decision) = decisions.next() else { continue };
                    if decisions.next().is_some()
                        || decision.disposition
                            != trust_verifier_api::EvidenceDisposition::AcceptedProof
                        || !manifest_decision_matches_exact_evidence(decision, evidence)
                        || manifest.rejected_evidence.iter().any(|rejected| {
                            rejected.obligation_id == returned_obligation.obligation_id
                                && matches!(
                                    rejected.status,
                                    trust_verifier_api::EvidenceStatus::Proved
                                        | trust_verifier_api::EvidenceStatus::Failed
                                )
                        })
                    {
                        continue;
                    }
                    receipts.push(InitialLiveBodyBoundReceipt {
                        carrier: carrier.clone(),
                        returned_obligation: returned_obligation.clone(),
                        evidence: evidence.clone(),
                        manifest_decision: decision.clone(),
                        run_manifest: manifest.clone(),
                    });
                }
                receipts
            };
        capture_live_result()
    } else {
        Vec::new()
    };
    LiveFullVerificationDispatch { result, body_bound_receipts, live_receipts: Some(live_receipts) }
}

#[derive(Debug, Default)]
struct DirectTrustVcMintReport {
    minted: usize,
    rejected: Vec<String>,
}

/// Accept only the compiler's transactional AY bridge publication between the
/// router source run sealed by the live dispatch and the final public carrier.
/// Definitive native evidence is immutable. A changed row must replace only
/// non-definitive evidence (and at most one matching skip) with the exact
/// bridge-owned proved shape; all envelope identity and unrelated rows remain
/// byte-for-byte fixed.
fn is_permitted_bridge_publication_transition(
    source_run: &trust_verifier_api::VerificationRunResult,
    final_run: &trust_verifier_api::VerificationRunResult,
) -> bool {
    if source_run.validate_derived_state().is_err()
        || final_run.validate_derived_state().is_err()
        || source_run.schema_version != final_run.schema_version
        || source_run.run_id != final_run.run_id
        || source_run.bundle_id != final_run.bundle_id
        || source_run.subject != final_run.subject
        || source_run.engine != final_run.engine
        || source_run.context != final_run.context
        || source_run.requested_obligations != final_run.requested_obligations
        || source_run.publication != final_run.publication
        || source_run.summary.publication_conflicts != 0
        || final_run.summary.publication_conflicts != 0
    {
        return false;
    }

    let requested_ids = source_run
        .requested_obligations
        .iter()
        .map(|obligation| obligation.obligation_id.as_str())
        .collect::<BTreeSet<_>>();
    let mut source_evidence_by_id = BTreeMap::<&str, Vec<_>>::new();
    let mut final_evidence_by_id = BTreeMap::<&str, Vec<_>>::new();
    let mut source_skips_by_id = BTreeMap::<&str, Vec<_>>::new();
    let mut final_skips_by_id = BTreeMap::<&str, Vec<_>>::new();
    for evidence in &source_run.evidence {
        source_evidence_by_id.entry(evidence.obligation_id.as_str()).or_default().push(evidence);
    }
    for evidence in &final_run.evidence {
        final_evidence_by_id.entry(evidence.obligation_id.as_str()).or_default().push(evidence);
    }
    for skipped in &source_run.skipped {
        source_skips_by_id.entry(skipped.obligation_id.as_str()).or_default().push(skipped);
    }
    for skipped in &final_run.skipped {
        final_skips_by_id.entry(skipped.obligation_id.as_str()).or_default().push(skipped);
    }
    if source_evidence_by_id
        .keys()
        .chain(final_evidence_by_id.keys())
        .chain(source_skips_by_id.keys())
        .chain(final_skips_by_id.keys())
        .any(|obligation_id| !requested_ids.contains(obligation_id))
    {
        return false;
    }

    let mut changed_ids = BTreeSet::new();
    for obligation in &source_run.requested_obligations {
        let obligation_id = obligation.obligation_id.as_str();
        let source_evidence =
            source_evidence_by_id.get(obligation_id).map_or(&[][..], Vec::as_slice);
        let final_evidence = final_evidence_by_id.get(obligation_id).map_or(&[][..], Vec::as_slice);
        let source_skips = source_skips_by_id.get(obligation_id).map_or(&[][..], Vec::as_slice);
        let final_skips = final_skips_by_id.get(obligation_id).map_or(&[][..], Vec::as_slice);
        if source_evidence == final_evidence && source_skips == final_skips {
            continue;
        }
        changed_ids.insert(obligation_id.to_string());
        if source_evidence.iter().any(|evidence| {
            matches!(
                evidence.status,
                trust_verifier_api::EvidenceStatus::Proved
                    | trust_verifier_api::EvidenceStatus::Failed
            )
        }) || source_skips.len() > 1
            || !final_skips.is_empty()
        {
            return false;
        }
        let [bridged] = final_evidence else { return false };
        if bridged.evidence_id != format!("bridge-ay:{obligation_id}")
            || bridged.engine != final_run.engine
            || bridged.status != trust_verifier_api::EvidenceStatus::Proved
            || bridged.proof_strength.as_ref()
                != Some(&trust_verifier_api::ProofStrength::smt_unsat())
            || bridged.counterexample.is_some()
            || bridged.publication != trust_verifier_api::EvidencePublicationMetadata::default()
            || !bridged.satisfies_proof_artifact_policy()
        {
            return false;
        }
    }

    let expected_diagnostics = source_run
        .diagnostics
        .iter()
        .filter(|diagnostic| {
            let Some(rest) = diagnostic.strip_prefix("release-blocking proof gap: obligation ")
            else {
                return true;
            };
            let obligation_id = rest.split_once(' ').map_or(rest, |(id, _)| id);
            !changed_ids.contains(obligation_id)
        })
        .cloned()
        .collect::<Vec<_>>();
    expected_diagnostics == final_run.diagnostics
}

/// Consume the opaque same-solve receipts for the dedicated direct TrustVC
/// lane and install exact compiler-private Ownership authority against the
/// final post-publication carrier. The public run is attribution only: without
/// one of these affine receipts, an otherwise byte-identical public `Proved`
/// row cannot enter this authority variant.
fn install_direct_trust_vc_live_authorities(
    bundle: &trust_verifier_api::TrustContractBundle,
    dispatched_obligations: &[trust_verifier_api::TrustObligation],
    context: &trust_router::VerifierExecutionContext,
    final_run: &trust_verifier_api::VerificationRunResult,
    live_receipts: Option<&mut trust_router::LiveVerificationReceiptBatch>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) -> DirectTrustVcMintReport {
    let mut report = DirectTrustVcMintReport::default();
    let Some(live_receipts) = live_receipts else { return report };
    let direct_receipts = live_receipts.take_direct_trust_vc_receipts();
    if direct_receipts.is_empty() {
        return report;
    }
    let Some(source_run) = live_receipts.source_run() else {
        report.rejected.extend(direct_receipts.into_keys().map(|obligation_id| {
            format!("{obligation_id}: live receipt batch has no source dispatch authority")
        }));
        return report;
    };

    let global_error = if bundle.validate().is_err() {
        Some("the exact compiler bundle is invalid")
    } else if !live_receipts.matches_bundle(bundle) {
        Some("the live receipt batch was minted for a different exact bundle")
    } else if bundle.validate_requested_obligations(dispatched_obligations).is_err() {
        Some("the dispatched obligation inventory is not an exact canonical bundle subset")
    } else if context.is_cancelled() {
        Some("the verifier execution context was cancelled before compiler mint")
    } else if context.budget_exceeded() {
        Some("the verifier execution deadline expired before compiler mint")
    } else if source_run.validate_derived_state().is_err()
        || final_run.validate_derived_state().is_err()
    {
        Some("the source or final public run has invalid derived state")
    } else if !is_permitted_bridge_publication_transition(source_run, final_run) {
        Some("the source-to-final public run transition is not an exact bridge publication")
    } else if final_run.bundle_id != bundle.bundle_id || final_run.subject != bundle.subject {
        Some("the final public run identifies a different bundle or subject")
    } else if source_run.bundle_id != bundle.bundle_id || source_run.subject != bundle.subject {
        Some("the source public run identifies a different bundle or subject")
    } else if final_run.context != context.snapshot() || final_run.run_id != context.run_id {
        Some("the final public run has a different execution context")
    } else if source_run.context != context.snapshot() || source_run.run_id != context.run_id {
        Some("the source public run has a different execution context")
    } else if final_run.requested_obligations != dispatched_obligations {
        Some("the final public run has a different dispatched obligation inventory")
    } else if source_run.requested_obligations != dispatched_obligations {
        Some("the source public run has a different dispatched obligation inventory")
    } else if final_run.summary.publication_conflicts != 0 {
        Some("the final public run contains publication conflicts")
    } else if results.len() != result_bindings.len() || results.len() != proof_authorities.len() {
        Some("the compiler result, binding, and authority carriers are not row-aligned")
    } else {
        None
    };
    if let Some(error) = global_error {
        report.rejected.extend(
            direct_receipts.into_keys().map(|obligation_id| format!("{obligation_id}: {error}")),
        );
        return report;
    }
    let (dispatched_by_id, duplicate_dispatched_ids) =
        unique_index_and_duplicates_by_id(dispatched_obligations, |obligation| {
            obligation.obligation_id.as_str()
        });
    let binding_rows = build_exact_result_binding_row_index(results, result_bindings);
    let final_index = build_full_verification_evidence_index(final_run);
    let strict_accepted_evidence_positions = strict_accepted_evidence_positions(final_run);
    let run_seal = Arc::new(DirectTrustVcLiveRunSeal {
        bundle: bundle.clone(),
        dispatched_obligations: dispatched_obligations.to_vec(),
        context: context.snapshot(),
        dispatch_deadline: context.deadline(),
        source_run: source_run.clone(),
        final_run: final_run.clone(),
        strict_accepted_evidence_positions,
    });
    if !run_seal.envelope_is_valid() {
        report.rejected.extend(direct_receipts.into_keys().map(|obligation_id| {
            format!("{obligation_id}: compiler-private direct run seal failed exact validation")
        }));
        return report;
    }

    for (map_id, receipt) in direct_receipts {
        let reject = |report: &mut DirectTrustVcMintReport, reason: &str| {
            report.rejected.push(format!("{map_id}: {reason}"));
        };
        if receipt.public_obligation_id() != map_id {
            reject(&mut report, "receipt/map obligation identity mismatch");
            continue;
        }
        let Some(obligation) = dispatched_by_id.get(map_id.as_str()).copied() else {
            reject(&mut report, "receipt obligation is absent from the dispatched inventory");
            continue;
        };
        if duplicate_dispatched_ids.contains(map_id.as_str())
            || obligation.is_default_admission()
            || obligation.kind != trust_verifier_api::ObligationKind::Ownership
            || !has_exact_direct_trust_vc_deferred_marker(obligation)
        {
            reject(
                &mut report,
                "receipt obligation is duplicated, synthetic, non-Ownership, or not exact-direct",
            );
            continue;
        }
        let Some(evidence) =
            final_index.strict_accepted_by_obligation_id.get(map_id.as_str()).copied()
        else {
            reject(
                &mut report,
                "no unique conflict-free accepted Proved evidence row survived final publication",
            );
            continue;
        };
        if receipt.dispatch_deadline() != context.deadline() {
            reject(&mut report, "receipt deadline differs from the compiler execution deadline");
            continue;
        }
        let Ok(proof_strength) =
            live_receipts.authorizes_direct_trust_vc_receipt(&receipt, obligation, evidence)
        else {
            reject(&mut report, "affine receipt rejected the final accepted evidence row");
            continue;
        };
        if context.is_cancelled()
            || context.budget_exceeded()
            || receipt.dispatch_deadline() != context.deadline()
        {
            reject(&mut report, "execution context became late, cancelled, or changed at mint");
            continue;
        }
        if evidence.engine != final_run.engine
            || evidence.proof_strength.as_ref() != Some(&proof_strength)
            || !direct_trust_vc_strength_is_authoritative(&proof_strength)
            || !evidence_has_exact_direct_trust_vc_lineage(obligation, evidence)
        {
            reject(
                &mut report,
                "receipt is not exact certified OwnershipAnalysis direct TrustVC evidence",
            );
            continue;
        }

        if binding_rows.ambiguous_ids.contains(map_id.as_str()) {
            reject(&mut report, "multiple current compiler result rows match the receipt");
            continue;
        }
        let Some(row_index) = binding_rows.unique_rows.get(map_id.as_str()).copied() else {
            reject(&mut report, "no exact current compiler result binding matches the receipt");
            continue;
        };
        if !result_bindings[row_index]
            .as_ref()
            .is_some_and(|binding| binding.matches_public_obligation(obligation))
        {
            reject(&mut report, "no exact current compiler result binding matches the receipt");
            continue;
        }
        let (vc, result) = &results[row_index];
        let Some(expected_legacy_strength) = legacy_proof_strength(&proof_strength) else {
            reject(&mut report, "receipt strength has no exact compiler result representation");
            continue;
        };
        if !matches!(
            result,
            VerificationResult::Proved { strength, .. } if strength == &expected_legacy_strength
        ) {
            reject(&mut report, "current compiler result row or proof strength changed");
            continue;
        }
        let Some(compiler_result) = ExactLiveCompilerProvedResult::from_result(result) else {
            reject(&mut report, "current compiler result is not an exact Proved carrier");
            continue;
        };
        // Kernel/S1/R1/source/body/S3/assumption authority retains precedence;
        // no private capability is interchangeable with this exact live solve.
        if proof_authorities[row_index].is_some() {
            reject(&mut report, "current row already carries a different private authority");
            continue;
        }
        let Some(row) = exact_result_row_identity(row_index, vc) else {
            reject(&mut report, "current compiler result row has no canonical exact identity");
            continue;
        };
        let Some(binding) = result_bindings[row_index].as_ref().cloned() else {
            reject(&mut report, "current compiler result binding disappeared");
            continue;
        };
        let authority = DirectTrustVcLiveAuthority {
            row,
            binding,
            obligation: obligation.clone(),
            compiler_result,
            accepted_evidence: evidence.clone(),
            dispatch_deadline: context.deadline(),
            run_seal: Arc::clone(&run_seal),
        };
        if !authority.authorizes_row(row_index, vc, result_bindings[row_index].as_ref())
            || !authority.authorizes_compiler_result(result)
        {
            reject(&mut report, "compiler-private exact carrier self-check failed");
            continue;
        }
        if context.is_cancelled()
            || context.budget_exceeded()
            || receipt.dispatch_deadline() != context.deadline()
        {
            reject(
                &mut report,
                "execution context became late, cancelled, or changed at final mint",
            );
            continue;
        }
        proof_authorities[row_index] = Some(ResultProofAuthority::DirectTrustVcLive { authority });
        report.minted += 1;
    }

    report
}

#[derive(Debug, Default)]
struct FreshExactDirectChcPdrMintReport {
    minted: usize,
    rejected: Vec<String>,
}

/// Consume the affine sidecars returned by the genuine native dispatch and
/// mint compiler-private S3 tokens only against the final, post-bridge public
/// carrier. The public run is never edited here. Every rejection is local and
/// fail-closed; malformed global carrier state rejects the whole receipt set.
fn install_fresh_exact_direct_chc_pdr_authorities(
    bundle: &trust_verifier_api::TrustContractBundle,
    dispatched_obligations: &[trust_verifier_api::TrustObligation],
    context: &trust_router::VerifierExecutionContext,
    final_run: &trust_verifier_api::VerificationRunResult,
    live_receipts: Option<&mut trust_router::LiveVerificationReceiptBatch>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) -> FreshExactDirectChcPdrMintReport {
    let mut report = FreshExactDirectChcPdrMintReport::default();
    let Some(live_receipts) = live_receipts else { return report };
    let fresh_receipts = live_receipts.take_fresh_exact_direct_chc_pdr_receipts();
    if fresh_receipts.is_empty() {
        return report;
    }
    let Some(source_run) = live_receipts.source_run() else {
        report.rejected.extend(fresh_receipts.into_keys().map(|obligation_id| {
            format!("{obligation_id}: live receipt batch has no source dispatch authority")
        }));
        return report;
    };

    let global_error = if bundle.validate().is_err() {
        Some("the exact compiler bundle is invalid")
    } else if !live_receipts.matches_bundle(bundle) {
        Some("the live receipt batch was minted for a different exact bundle")
    } else if bundle.validate_requested_obligations(dispatched_obligations).is_err() {
        Some("the dispatched obligation inventory is not an exact canonical bundle subset")
    } else if context.is_cancelled() {
        Some("the verifier execution context was cancelled before compiler mint")
    } else if context.budget_exceeded() {
        Some("the verifier execution deadline expired before compiler mint")
    } else if source_run.validate_derived_state().is_err()
        || final_run.validate_derived_state().is_err()
    {
        Some("the source or final public run has invalid derived state")
    } else if !is_permitted_bridge_publication_transition(source_run, final_run) {
        Some("the source-to-final public run transition is not an exact bridge publication")
    } else if final_run.bundle_id != bundle.bundle_id || final_run.subject != bundle.subject {
        Some("the final public run identifies a different bundle or subject")
    } else if source_run.bundle_id != bundle.bundle_id || source_run.subject != bundle.subject {
        Some("the source public run identifies a different bundle or subject")
    } else if final_run.context != context.snapshot() || final_run.run_id != context.run_id {
        Some("the final public run has a different execution context")
    } else if source_run.context != context.snapshot() || source_run.run_id != context.run_id {
        Some("the source public run has a different execution context")
    } else if final_run.requested_obligations != dispatched_obligations {
        Some("the final public run has a different dispatched obligation inventory")
    } else if source_run.requested_obligations != dispatched_obligations {
        Some("the source public run has a different dispatched obligation inventory")
    } else if final_run.summary.publication_conflicts != 0 {
        Some("the final public run contains publication conflicts")
    } else if results.len() != result_bindings.len() || results.len() != proof_authorities.len() {
        Some("the compiler result, binding, and authority carriers are not row-aligned")
    } else {
        None
    };
    if let Some(error) = global_error {
        report.rejected.extend(
            fresh_receipts.into_keys().map(|obligation_id| format!("{obligation_id}: {error}")),
        );
        return report;
    }
    let (dispatched_by_id, duplicate_dispatched_ids) =
        unique_index_and_duplicates_by_id(dispatched_obligations, |obligation| {
            obligation.obligation_id.as_str()
        });
    let binding_rows = build_exact_result_binding_row_index(results, result_bindings);
    let final_index = build_full_verification_evidence_index(final_run);
    let strict_accepted_evidence_positions = strict_accepted_evidence_positions(final_run);
    let run_seal = Arc::new(FreshExactDirectChcPdrRunSeal {
        bundle: bundle.clone(),
        dispatched_obligations: dispatched_obligations.to_vec(),
        context: context.snapshot(),
        dispatch_deadline: context.deadline(),
        source_run: source_run.clone(),
        final_run: final_run.clone(),
        strict_accepted_evidence_positions,
    });
    if !run_seal.envelope_is_valid() {
        report.rejected.extend(fresh_receipts.into_keys().map(|obligation_id| {
            format!("{obligation_id}: compiler-private FreshExact run seal failed exact validation")
        }));
        return report;
    }

    for (map_id, receipt) in fresh_receipts {
        let reject = |report: &mut FreshExactDirectChcPdrMintReport, reason: &str| {
            report.rejected.push(format!("{map_id}: {reason}"));
        };
        if receipt.public_obligation_id() != map_id {
            reject(&mut report, "receipt/map obligation identity mismatch");
            continue;
        }
        let Some(obligation) = dispatched_by_id.get(map_id.as_str()).copied() else {
            reject(&mut report, "receipt obligation is absent from the dispatched inventory");
            continue;
        };
        if duplicate_dispatched_ids.contains(map_id.as_str()) || obligation.is_default_admission() {
            reject(&mut report, "receipt obligation is duplicated or is a synthetic admission");
            continue;
        }
        let Some(evidence) =
            final_index.strict_accepted_by_obligation_id.get(map_id.as_str()).copied()
        else {
            reject(
                &mut report,
                "no unique conflict-free accepted Proved evidence row survived final publication",
            );
            continue;
        };
        if receipt.dispatch_deadline() != context.deadline() {
            reject(&mut report, "receipt deadline differs from the compiler execution deadline");
            continue;
        }
        let Ok(proof_strength) = live_receipts
            .authorizes_fresh_exact_direct_chc_pdr_receipt(&receipt, obligation, evidence)
        else {
            reject(&mut report, "affine receipt rejected the final accepted evidence row");
            continue;
        };
        if context.is_cancelled()
            || context.budget_exceeded()
            || receipt.dispatch_deadline() != context.deadline()
        {
            reject(&mut report, "execution context became late, cancelled, or changed at mint");
            continue;
        }
        if evidence.proof_strength.as_ref() != Some(&proof_strength)
            || !exact_direct_chc_pdr_strength_is_authoritative(&proof_strength)
        {
            reject(&mut report, "receipt is not CHC/PDR evidence at SmtBacked assurance");
            continue;
        }

        if binding_rows.ambiguous_ids.contains(map_id.as_str()) {
            reject(&mut report, "multiple current compiler result rows match the receipt");
            continue;
        }
        let Some(row_index) = binding_rows.unique_rows.get(map_id.as_str()).copied() else {
            reject(&mut report, "no exact current compiler result binding matches the receipt");
            continue;
        };
        if !result_bindings[row_index]
            .as_ref()
            .is_some_and(|binding| binding.matches_public_obligation(obligation))
        {
            reject(&mut report, "no exact current compiler result binding matches the receipt");
            continue;
        }
        let (vc, result) = &results[row_index];
        let Some(expected_legacy_strength) = legacy_proof_strength(&proof_strength) else {
            reject(&mut report, "receipt strength has no exact compiler result representation");
            continue;
        };
        if !matches!(
            result,
            VerificationResult::Proved { strength, .. } if strength == &expected_legacy_strength
        ) {
            reject(&mut report, "current compiler result row or proof strength changed");
            continue;
        }
        let Some(compiler_result) = ExactLiveCompilerProvedResult::from_result(result) else {
            reject(&mut report, "current compiler result is not an exact Proved carrier");
            continue;
        };
        // Kernel authority has precedence. S1/R1, source-derived, certified,
        // body-bound, assumption, and compatibility-native authority are not
        // interchangeable with this receipt and are never overwritten.
        if proof_authorities[row_index].is_some() {
            reject(&mut report, "current row already carries a different private authority");
            continue;
        }
        let Some(row) = exact_result_row_identity(row_index, vc) else {
            reject(&mut report, "current compiler result row has no canonical exact identity");
            continue;
        };
        let Some(binding) = result_bindings[row_index].as_ref().cloned() else {
            reject(&mut report, "current compiler result binding disappeared");
            continue;
        };
        let authority = FreshExactDirectChcPdrAuthority {
            row,
            binding,
            obligation: obligation.clone(),
            compiler_result,
            accepted_evidence: evidence.clone(),
            evidence_id: evidence.evidence_id.clone(),
            proof_strength,
            dispatch_deadline: context.deadline(),
            run_seal: Arc::clone(&run_seal),
        };
        if !authority.authorizes_row(row_index, vc, result_bindings[row_index].as_ref())
            || !authority.authorizes_compiler_result(result)
        {
            reject(&mut report, "compiler-private exact carrier self-check failed");
            continue;
        }
        if context.is_cancelled()
            || context.budget_exceeded()
            || receipt.dispatch_deadline() != context.deadline()
        {
            reject(
                &mut report,
                "execution context became late, cancelled, or changed at final mint",
            );
            continue;
        }
        proof_authorities[row_index] =
            Some(ResultProofAuthority::FreshExactDirectChcPdr { authority });
        report.minted += 1;
    }

    report
}

impl CompilerFinalizedBodyBoundCarrier {
    fn matches_compiler_inputs(
        &self,
        bundle: &trust_verifier_api::TrustContractBundle,
        native_bundle: &trust_ir_bridge::NativeVerificationBundle,
    ) -> bool {
        if bundle.validate().is_err()
            || native_bundle.validate().is_err()
            || native_bundle.stable_digest() != self.native_bundle_digest
            || native_bundle.trust_ir_module_digest != self.trust_ir_module_digest
            || native_bundle.compiler_facts.stable_digest() != self.compiler_facts_digest
            || native_bundle.source_digest() != Some(self.body_source_digest)
        {
            return false;
        }
        let mut obligations = bundle.obligations.iter().filter(|obligation| {
            obligation.obligation_id == self.canonical_obligation.obligation_id
        });
        if obligations.next() != Some(&self.canonical_obligation) || obligations.next().is_some() {
            return false;
        }
        let mut contracts = bundle
            .contracts
            .iter()
            .filter(|contract| contract.contract_id == self.canonical_contract.contract_id);
        if contracts.next() != Some(&self.canonical_contract) || contracts.next().is_some() {
            return false;
        }
        if bundle.canonical_obligation_semantic_digest_sha256(&self.canonical_obligation).as_deref()
            != Ok(self.public_semantic_digest.as_str())
        {
            return false;
        }

        let mut requests = native_bundle.requests.iter().filter(|request| {
            request.id() == self.native_request.id()
                && request
                    .obligations()
                    .iter()
                    .any(|proof_id| *proof_id == self.native_proof_obligation.id)
        });
        if requests.next() != Some(&self.native_request) || requests.next().is_some() {
            return false;
        }
        let mut proof_obligations = native_bundle
            .module
            .proof_obligations
            .iter()
            .filter(|proof| proof.id == self.native_proof_obligation.id);
        if proof_obligations.next() != Some(&self.native_proof_obligation)
            || proof_obligations.next().is_some()
        {
            return false;
        }
        let mut sources = native_bundle
            .compiler_facts
            .obligation_sources
            .iter()
            .filter(|source| source.obligation == self.native_proof_obligation.id);
        if sources.next() != Some(&self.native_obligation_source) || sources.next().is_some() {
            return false;
        }
        native_json_digest(
            "trust.trust_ir.native.obligation-source.digest.v1",
            &native_compiler_fact_source_json(&self.native_obligation_source),
        )
        .as_deref()
            == Ok(self.obligation_source_digest.as_str())
    }
}

impl InitialLiveBodyBoundReceipt {
    fn matches_live_dispatch(
        &self,
        bundle: &trust_verifier_api::TrustContractBundle,
        native_bundle: &trust_ir_bridge::NativeVerificationBundle,
        run: &trust_verifier_api::VerificationRunResult,
    ) -> bool {
        if !self.carrier.matches_compiler_inputs(bundle, native_bundle)
            || run.bundle_id != bundle.bundle_id
            || run.subject != bundle.subject
            || run.validate_derived_state().is_err()
        {
            return false;
        }
        let Ok(manifest) = run.try_to_manifest() else { return false };
        if manifest != self.run_manifest {
            return false;
        }
        let mut returned = run.requested_obligations.iter().filter(|obligation| {
            obligation.obligation_id == self.returned_obligation.obligation_id
        });
        if returned.next() != Some(&self.returned_obligation)
            || returned.next().is_some()
            || self.returned_obligation != self.carrier.canonical_obligation
        {
            return false;
        }
        let mut evidence = run
            .evidence
            .iter()
            .filter(|evidence| evidence.obligation_id == self.evidence.obligation_id);
        if evidence.next() != Some(&self.evidence)
            || evidence.next().is_some()
            || self.evidence.obligation_id != self.returned_obligation.obligation_id
            || self.evidence.status != trust_verifier_api::EvidenceStatus::Proved
            || self.evidence.proof_strength.as_ref()
                != Some(&trust_verifier_api::ProofStrength::deductive())
            || self.evidence.engine != run.engine
            || self.evidence.engine.name != "trust-full-verifier"
            || self.evidence.engine.kind != trust_verifier_api::EngineKind::Composite
            || self.evidence.engine.repository.is_some()
            || !self.evidence.is_unbounded_proof()
            || !evidence_has_exact_native_trust_ir_artifact_lineage(
                &self.returned_obligation,
                &self.evidence,
            )
            || run
                .skipped
                .iter()
                .any(|skipped| skipped.obligation_id == self.returned_obligation.obligation_id)
        {
            return false;
        }
        let mut accepted = manifest
            .accepted_evidence
            .iter()
            .filter(|decision| decision.obligation_id == self.returned_obligation.obligation_id);
        if accepted.next() != Some(&self.manifest_decision)
            || accepted.next().is_some()
            || self.manifest_decision.disposition
                != trust_verifier_api::EvidenceDisposition::AcceptedProof
            || !manifest_decision_matches_exact_evidence(&self.manifest_decision, &self.evidence)
        {
            return false;
        }
        !manifest.rejected_evidence.iter().any(|decision| {
            decision.obligation_id == self.returned_obligation.obligation_id
                && matches!(
                    decision.status,
                    trust_verifier_api::EvidenceStatus::Proved
                        | trust_verifier_api::EvidenceStatus::Failed
                )
        })
    }
}

/// Seal the exact post-publication manifest without weakening the live receipt
/// to target-row-only validation. The initial receipt must still match the
/// immutable real dispatch; the final run must be the same invocation and must
/// retain the target row/evidence/decision exactly. Only then is its complete
/// final manifest frozen for the downstream consumer.
fn finalize_body_bound_native_replay_receipts(
    bundle: &trust_verifier_api::TrustContractBundle,
    native_bundle: Option<&trust_ir_bridge::NativeVerificationBundle>,
    live_run: &trust_verifier_api::VerificationRunResult,
    final_run: &trust_verifier_api::VerificationRunResult,
    initial_receipts: &[InitialLiveBodyBoundReceipt],
) -> Vec<BodyBoundNativeReplayReceipt> {
    let Some(native_bundle) = native_bundle else { return Vec::new() };
    let Ok(final_manifest) = final_run.try_to_manifest() else { return Vec::new() };
    if live_run.run_id != final_run.run_id
        || live_run.bundle_id != final_run.bundle_id
        || live_run.subject != final_run.subject
        || live_run.engine != final_run.engine
        || live_run.context != final_run.context
        || live_run.requested_obligations != final_run.requested_obligations
    {
        return Vec::new();
    }

    initial_receipts
        .iter()
        .filter_map(|initial| {
            if !initial.matches_live_dispatch(bundle, native_bundle, live_run) {
                return None;
            }
            let mut final_stage = initial.clone();
            final_stage.run_manifest = final_manifest.clone();
            if !final_stage.matches_live_dispatch(bundle, native_bundle, final_run) {
                return None;
            }
            Some(BodyBoundNativeReplayReceipt {
                live: initial.clone(),
                final_run_manifest: final_manifest.clone(),
            })
        })
        .collect()
}

impl BodyBoundNativeReplayReceipt {
    fn matches_current_carriers(
        &self,
        bundle: &trust_verifier_api::TrustContractBundle,
        native_bundle: &trust_ir_bridge::NativeVerificationBundle,
        run: &trust_verifier_api::VerificationRunResult,
    ) -> bool {
        let mut final_stage = self.live.clone();
        final_stage.run_manifest = self.final_run_manifest.clone();
        final_stage.matches_live_dispatch(bundle, native_bundle, run)
    }
}

/// Compiler-private, affine classification of the exact definition-site
/// `Requires` catalog rows constructed for this invocation. A public
/// `Contract { Requires }` context is necessary shape, but cannot by itself
/// authorize proof-request elision or an entry-assumption discharge.
///
/// The first seal is made against the independently rebuilt contract-only
/// reference before monitor/native annotations.  `seal_final_bundle` then
/// validates that compiler-owned annotation passes preserved that exact core
/// and freezes the complete final public rows immediately before dispatch.
/// Consumers compare against those frozen rows byte-for-byte; a returned,
/// duplicated, reordered, or self-consistently forged public carrier cannot
/// mint this private bit.
#[derive(Debug)]
struct ExactDefinitionEntryMarker {
    obligation: trust_verifier_api::TrustObligation,
    contract: trust_verifier_api::TrustContract,
}

#[derive(Debug, Default)]
struct ExactDefinitionEntryMarkerSet {
    bundle_id: Option<String>,
    subject: Option<trust_verifier_api::BundleSubject>,
    by_index: BTreeMap<usize, ExactDefinitionEntryMarker>,
}

impl ExactDefinitionEntryMarkerSet {
    fn freeze_from_compiler_reference(
        reference: &trust_verifier_api::TrustContractBundle,
        bundle: &trust_verifier_api::TrustContractBundle,
    ) -> Self {
        if reference.bundle_id != bundle.bundle_id
            || reference.subject != bundle.subject
            || reference.validate().is_err()
            || bundle.validate().is_err()
        {
            return Self::default();
        }

        let mut by_index = BTreeMap::new();
        for expected_obligation in reference
            .obligations
            .iter()
            .filter(|obligation| is_definition_site_requires_marker(obligation))
        {
            let mut matches = bundle.obligations.iter().enumerate().filter(|(_, actual)| {
                obligation_matches_monitor_reference(actual, expected_obligation)
            });
            let Some((index, actual_obligation)) = matches.next() else {
                return Self::default();
            };
            if matches.next().is_some() || by_index.contains_key(&index) {
                return Self::default();
            }

            let Some(contract_id) = expected_obligation.contract_id.as_deref() else {
                return Self::default();
            };
            let Some(expected_contract) =
                exactly_one_monitor_contract(&reference.contracts, contract_id)
            else {
                return Self::default();
            };
            let Some(actual_contract) =
                exactly_one_monitor_contract(&bundle.contracts, contract_id)
            else {
                return Self::default();
            };
            if !contract_matches_monitor_reference(actual_contract, expected_contract) {
                return Self::default();
            }

            by_index.insert(
                index,
                ExactDefinitionEntryMarker {
                    obligation: actual_obligation.clone(),
                    contract: actual_contract.clone(),
                },
            );
        }

        // A second row with a plausible Contract{Requires} context is an
        // ambiguous catalog, even if it chose a different public ID. Refuse
        // every elision instead of selecting a winner from public shape.
        if bundle.obligations.iter().enumerate().any(|(index, obligation)| {
            is_definition_site_requires_marker(obligation) && !by_index.contains_key(&index)
        }) {
            return Self::default();
        }

        Self {
            bundle_id: Some(bundle.bundle_id.clone()),
            subject: Some(bundle.subject.clone()),
            by_index,
        }
    }

    fn seal_final_bundle(mut self, bundle: &trust_verifier_api::TrustContractBundle) -> Self {
        if self.bundle_id.as_deref() != Some(bundle.bundle_id.as_str())
            || self.subject.as_ref() != Some(&bundle.subject)
            || bundle.validate().is_err()
        {
            return Self::default();
        }

        for (index, marker) in &mut self.by_index {
            let Some(obligation) = bundle.obligations.get(*index) else {
                return Self::default();
            };
            if !is_definition_site_requires_marker(obligation)
                || !definition_entry_obligation_core_matches(obligation, &marker.obligation)
                || !metadata_preserves_exact_compiler_entries(
                    &obligation.metadata,
                    &marker.obligation.metadata,
                )
                || bundle
                    .obligations
                    .iter()
                    .filter(|candidate| candidate.obligation_id == obligation.obligation_id)
                    .count()
                    != 1
            {
                return Self::default();
            }

            let Some(contract_id) = obligation.contract_id.as_deref() else {
                return Self::default();
            };
            let Some(contract) = exactly_one_monitor_contract(&bundle.contracts, contract_id)
            else {
                return Self::default();
            };
            if !contract_matches_monitor_reference(contract, &marker.contract) {
                return Self::default();
            }

            // Freeze the complete post-annotation carrier. From this point on
            // no metadata allowlist or structural reclassification is needed.
            marker.obligation = obligation.clone();
            marker.contract = contract.clone();
        }

        if bundle.obligations.iter().enumerate().any(|(index, obligation)| {
            is_definition_site_requires_marker(obligation) && !self.by_index.contains_key(&index)
        }) {
            return Self::default();
        }
        self
    }

    fn matches(
        &self,
        index: usize,
        bundle: &trust_verifier_api::TrustContractBundle,
        obligation: &trust_verifier_api::TrustObligation,
    ) -> bool {
        if self.bundle_id.as_deref() != Some(bundle.bundle_id.as_str())
            || self.subject.as_ref() != Some(&bundle.subject)
        {
            return false;
        }
        let Some(marker) = self.by_index.get(&index) else { return false };
        if bundle.obligations.get(index) != Some(obligation)
            || obligation != &marker.obligation
            || bundle
                .obligations
                .iter()
                .filter(|candidate| candidate.obligation_id == obligation.obligation_id)
                .count()
                != 1
        {
            return false;
        }
        obligation.contract_id.as_deref().is_some_and(|contract_id| {
            exactly_one_monitor_contract(&bundle.contracts, contract_id) == Some(&marker.contract)
        })
    }
}

fn definition_entry_obligation_core_matches(
    actual: &trust_verifier_api::TrustObligation,
    expected: &trust_verifier_api::TrustObligation,
) -> bool {
    actual.obligation_id == expected.obligation_id
        && actual.kind == expected.kind
        && actual.contract_id == expected.contract_id
        && actual.proof_item_id == expected.proof_item_id
        && actual.source == expected.source
        && actual.description == expected.description
        && actual.required_strength == expected.required_strength
        && actual.summary_facts == expected.summary_facts
}

fn metadata_preserves_exact_compiler_entries(
    actual: &[trust_verifier_api::MetadataEntry],
    expected: &[trust_verifier_api::MetadataEntry],
) -> bool {
    expected.iter().all(|entry| {
        let mut same_key = actual.iter().filter(|candidate| candidate.key == entry.key);
        same_key.next() == Some(entry) && same_key.next().is_none()
    })
}

/// Select the proof-request subset without erasing compiler-authored catalog
/// rows. The exact definition-site `Requires` origin is an assumption, not a
/// proof request; caller-side preconditions and ordinary panic-freedom
/// obligations remain dispatched.
fn full_verification_dispatched_obligations_for_function(
    func: &trust_types::VerifiableFunction,
    bundle: &trust_verifier_api::TrustContractBundle,
    definition_entry_markers: &ExactDefinitionEntryMarkerSet,
) -> Vec<trust_verifier_api::TrustObligation> {
    bundle
        .obligations
        .iter()
        .enumerate()
        .filter(|(index, obligation)| {
            !definition_entry_markers.matches(*index, bundle, obligation)
                && !api_obligation_is_assumed_total_callee_marker(func, bundle, obligation)
        })
        .map(|(_, obligation)| obligation.clone())
        .collect()
}

/// Test-only catalog selection without a compiler function carrier. It may
/// classify definition-entry markers, whose exact origin is independently
/// checked, but deliberately cannot skip an assumed-total lookalike.
#[cfg(test)]
fn full_verification_dispatched_obligations(
    bundle: &trust_verifier_api::TrustContractBundle,
    definition_entry_markers: &ExactDefinitionEntryMarkerSet,
) -> Vec<trust_verifier_api::TrustObligation> {
    bundle
        .obligations
        .iter()
        .enumerate()
        .filter(|(index, obligation)| !definition_entry_markers.matches(*index, bundle, obligation))
        .map(|(_, obligation)| obligation.clone())
        .collect()
}

#[derive(Debug, Clone)]
struct PendingNativeTrustIrBinding {
    obligation_index: usize,
    verifier_suite: &'static str,
    proof_obligation_id: trust_ir::ProofId,
}

/// Private witness that the compiler's body-bound finalizer, rather than
/// public metadata, replaced one original `Ensures` marker with the exact
/// let-bound Trust-WP claim. This value is created only on the guarded
/// finalizer branch and is consumed while the still-held native bundle is
/// sealed below; it is never serialized or reconstructed from a verifier
/// result.
#[derive(Debug, Clone, PartialEq)]
struct PendingCompilerBodyBoundClaim {
    obligation_index: usize,
    proof_obligation_id: trust_ir::ProofId,
    derived_contract: trust_verifier_api::TrustContract,
}

/// Exact compiler-owned carrier for a finalized body-bound Trust-WP claim.
///
/// The public obligation and contract bind the source surface. The exact
/// native request, proof obligation (including its final formula), compiler
/// source row, and body/module/facts digests bind the compiler-to-Trust-WP
/// handoff. Possessing similarly-shaped public metadata is deliberately
/// insufficient: instances originate only from a
/// [`PendingCompilerBodyBoundClaim`] minted by the guarded finalizer.
#[derive(Debug, Clone, PartialEq)]
struct CompilerFinalizedBodyBoundCarrier {
    canonical_obligation: trust_verifier_api::TrustObligation,
    canonical_contract: trust_verifier_api::TrustContract,
    public_semantic_digest: String,
    native_request: trust_ir::NativeVerificationRequest,
    native_proof_obligation: trust_ir::ProofObligation,
    native_obligation_source: trust_ir::NativeObligationSource,
    native_bundle_digest: trust_ir::ProofDigest,
    trust_ir_module_digest: trust_ir::ProofDigest,
    compiler_facts_digest: trust_ir::ProofDigest,
    body_source_digest: trust_ir::ProofDigest,
    obligation_source_digest: String,
}

/// First-stage non-serializable receipt captured around the genuine in-process
/// native dispatch. It freezes the exact returned row, evidence, decision, and
/// complete validated live manifest. This is not yet consumable authority:
/// compiler-owned bridge publication must seal the exact final manifest below.
#[derive(Debug, Clone, PartialEq)]
struct InitialLiveBodyBoundReceipt {
    carrier: CompilerFinalizedBodyBoundCarrier,
    returned_obligation: trust_verifier_api::TrustObligation,
    evidence: trust_verifier_api::ObligationEvidence,
    manifest_decision: trust_verifier_api::ManifestEvidenceDecision,
    /// Exact validated envelope observed on the live dispatch. This binds the
    /// receipt to its run/context/request inventory as well as the target row;
    /// a separately rebuilt canonical run cannot replay the capability.
    run_manifest: trust_verifier_api::VerificationRunManifest,
}

/// Second-stage receipt emitted only after compiler-owned bridge publication.
/// It preserves the exact initial live dispatch and freezes the complete final
/// manifest that downstream authority consumers must observe byte-for-byte.
#[derive(Debug, Clone, PartialEq)]
struct BodyBoundNativeReplayReceipt {
    live: InitialLiveBodyBoundReceipt,
    final_run_manifest: trust_verifier_api::VerificationRunManifest,
}

