    "trust-trust-mc.typed-chc-obligation.original_contract.v1";
const TRUST_MC_TYPED_CHC_BINDING_SCHEMA: &str = "trust-mc.typed-chc-binding.v1";
const TRUST_MC_TYPED_CHC_BINDING_METADATA_KEY: &str = "trust-mc.typed-chc-obligation.binding.v1";
