    "trust-trust-wp.typed-formula.synthetic_contract.v1";
const TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY: &str =
    "trust-trust-wp.typed-formula.original_contract.v1";
const TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY: &str = "trust-trust-wp.typed-formula.source";
// Trust (#23 Slice 1): `TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY` values.
// The vc value marks contracts synthesized from typed VC-formula obligation
// metadata (`finalize_trust_wp_public_semantic_contracts`); the body-bound
// value marks contracts derived by `finalize_trust_wp_body_bound_public_claims`
// from an ORIGINAL mir-extract Ensures contract plus the trust-ir defining
// expression of the function's return value. The body-bound guard rejects the
// vc value (amendment 2, provenance-tight: a refutation-form vc formula must
// never be let-wrapped into a positive goal).
const TRUST_WP_TYPED_FORMULA_SOURCE_COMPILER_VC_VALUE: &str =
    "compiler-native-trust-ir-trust-spec-vc";
const TRUST_WP_TYPED_FORMULA_SOURCE_BODY_BOUND_VALUE: &str =
    "compiler-native-trust-ir-body-bound-ensures";
const NATIVE_TRUST_IR_MAX_LOCAL_CALLEE_CLOSURE: usize = 32;

fn append_compiler_certified_paired_condvar_wait_sites<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    certificate: &trust_mir_extract::PairedCondvarCrateCertificate,
    out: &mut Vec<trust_mir_extract::CertifiedPairedCondvarWaitCallSite>,
) {
    out.extend(trust_mir_extract::collect_certified_paired_condvar_wait_calls(
        tcx,
        body,
        certificate,
    ));
}

fn build_native_trust_ir_bundle_for_verifier_api<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    compiler_contract_reference: &trust_verifier_api::TrustContractBundle,
    compiler_contracts: &trust_types::CompilerContractBundle,
    policy: &TrustVerifyPolicy,
    body_bound_carriers: &mut Vec<CompilerFinalizedBodyBoundCarrier>,
    // Trust (sealed-authority reconciliation): the exact VC slice the
    // verifier-api bundle was minted from, so the trust-vc lane planner can
    // consult the clean CIC kernel on an obligation's own source VC before
    // attaching an unreplayable imported certificate. See
    // `append_verifier_api_obligations_to_native_trust_ir`.
    all_vcs: &[VerificationCondition],
) -> Result<Option<trust_ir_bridge::NativeVerificationBundle>, String> {
    body_bound_carriers.clear();
    ensure_default_trust_mc_function_obligation(func, bundle)?;

    let any_routable = bundle
        .obligations
        .iter()
        .any(|obligation| native_trust_ir_route_for_api_obligation(obligation).is_some());
    if env_flag_enabled("TRUST_NATIVE_DEBUG") {
        eprintln!(
            "[NATIVE_TRUSTMC_GATE] func={} obligations={} any_routable={any_routable} kinds={:?}",
            func.def_path,
            bundle.obligations.len(),
            bundle
                .obligations
                .iter()
                .map(|o| (
                    format!("{:?}", o.kind),
                    native_trust_ir_route_for_api_obligation(o).map(|(s, _)| s)
                ))
                .collect::<Vec<_>>()
        );
    }
    if !any_routable {
        return Ok(None);
    }

    let mut bundled_def_ids: FxHashSet<DefId> = FxHashSet::default();
    let trust_ir_functions =
        native_trust_ir_verifiable_function_closure(tcx, body, func, policy, &mut bundled_def_ids)?;
    // PAIRED-CONDVAR authority is a fresh compiler-owned sidecar, never a
    // serialized callee suffix. Reconcile the whole-crate certificate against
    // this exact rustc MIR and extracted target before bridge lowering.
    let paired_condvar_certificate =
        with_crate_verification_state(tcx.sess, |state| state.paired_condvar_certificate.clone());
    let mut certified_paired_condvar_wait_sites = Vec::new();
    if let Some(certificate) = paired_condvar_certificate.as_deref() {
        append_compiler_certified_paired_condvar_wait_sites(
            tcx,
            body,
            certificate,
            &mut certified_paired_condvar_wait_sites,
        );
    }
    // Compute the EXPECTED-absent callee set: calls deliberately omitted by a
    // user `#[trust::skip]`, plus compiler-authenticated non-unwinding C-family
    // boundaries. Unresolved generic trait dispatch is deliberately excluded:
    // a future monomorphization may select a panicking implementation (the one
    // narrow, strictly STRONGER exception is SEALED closed-world dispatch whose
    // every enumerated target is verified panic-free — the rung-2 arm inside
    // `collect_expected_absent_callees`). The bridge marks this class
    // distinctly; survey may record the resulting assumption, while
    // strict and memory-safe reject it. Computed over the whole closure so an
    // omission in a deep frame is classified too.
    let mut expected_absent = FxHashSet::default();
    // Structural-drop ADTs: user structs with NO `Drop` impl whose drop glue is
    // purely structural (field drops). The bridge's drop-glue gate fail-closes
    // on every non-std Adt because it cannot see the (absent) `Drop` impl at
    // that layer; this set carries the compiler's `!has_dtor` fact so a drop of
    // e.g. `HashTable4KU16` (its only field a panic-free `Box<[u16; N]>`) is
    // recognized panic-free instead of fatally undischarged. SOUND: a struct
    // WITH a `Drop` impl is excluded (has_dtor), so its drop keeps failing
    // closed; the bridge still independently verifies every FIELD's drop is
    // panic-free before accepting a set member.
    let mut structural_drop = FxHashSet::default();
    // Distinct compiler-authenticated bodyless-foreign ABI lane. A local Rust
    // extern function is deliberately excluded by `is_foreign_item`.
    let mut abi_total_panic_free = FxHashSet::default();
    let mut assumed_total = FxHashSet::default();
    // Compiler type-verified total std iterator advances (own lane; see
    // `CrateVerificationState::type_total_std_callees`).
    let mut type_total_std = FxHashSet::default();
    // Compiler-decided totals the bridge cannot decide (the `?` desugar).
    let mut compiler_total = FxHashSet::default();
    collect_expected_absent_callees(
        tcx,
        body,
        &mut expected_absent,
        &mut abi_total_panic_free,
        &mut assumed_total,
        &mut type_total_std,
        &mut compiler_total,
    );
    collect_structural_drop_adts(tcx, body, &mut structural_drop);
    // Trust: NEVER query `optimized_mir` for a closure member whose peek would form an
    // E0391 cycle. For a LOCAL member, use its immutable elaborated-MIR snapshot
    // instead, preserving complete expected-absent and structural-drop classification
    // without re-entering an in-progress ancestor query. A direct self-call remains
    // safe and may use optimized MIR.
    // Walk EVERY BUNDLED body (from the closure's own DefId set), not just the
    // ones `mir_keys` can name: since the workspace-sibling extension, a
    // CROSS-CRATE body can be bundled and verified, and its own call sites
    // (e.g. `write_some`'s `libc::write`) must be classified in THIS crate's
    // expected-absent set — otherwise a bundled sibling's ordinary extern-C
    // call resurfaces as an unresolvable absent callee in the caller. A
    // NON-LOCAL cyclic member has no elaborated-MIR snapshot query, so it is
    // skipped — fail-CLOSED graceful degradation (it loses classifications,
    // never gains a proof), identical to the `!is_mir_available` case.
    let caller_def_id = body.source.def_id();
    // The closure builder returns an FxHashSet. Consume it once and impose a
    // stable compiler identity order before any query or diagnostic side effect.
    #[allow(rustc::potential_query_instability)]
    let mut bundled_def_ids = bundled_def_ids.into_iter().collect::<Vec<_>>();
    bundled_def_ids.sort_by_key(|&member| tcx.def_path_hash(member));
    for &member in &bundled_def_ids {
        if member == caller_def_id {
            continue;
        }
        if !tcx.is_mir_available(member) {
            continue;
        }
        let callee_body = if optimized_mir_query_would_cycle(tcx, member) {
            match member.as_local() {
                Some(local) => tcx.mir_for_trust_verification(local),
                None => continue,
            }
        } else {
            tcx.optimized_mir(member)
        };
        collect_expected_absent_callees(
            tcx,
            callee_body,
            &mut expected_absent,
            &mut abi_total_panic_free,
            &mut assumed_total,
            &mut type_total_std,
            &mut compiler_total,
        );
        collect_structural_drop_adts(tcx, callee_body, &mut structural_drop);
        if let Some(certificate) = paired_condvar_certificate.as_deref() {
            let member_path = trust_mir_extract::safe_def_path_str(tcx, member);
            let mut matches =
                trust_ir_functions.iter().filter(|function| function.def_path == member_path);
            if matches.next().is_some() && matches.next().is_none() {
                append_compiler_certified_paired_condvar_wait_sites(
                    tcx,
                    callee_body,
                    certificate,
                    &mut certified_paired_condvar_wait_sites,
                );
            }
        }
    }
    // Make these exact identities visible before the later interprocedural
    // assertion/panic-freedom discharge. Set insertion is idempotent.
    #[allow(rustc::potential_query_instability)]
    for callee in &abi_total_panic_free {
        register_abi_nonunwind_total_callee(tcx.sess, callee);
    }
    #[allow(rustc::potential_query_instability)]
    for callee in &type_total_std {
        register_type_total_std_callee(tcx.sess, callee);
    }
    // The COMPILER is the only party that knows the real compilation target, so
    // it stamps the module's `target_info` (the bridge stays target-agnostic).
    // trust-mc's proof-grade CHC admission fail-closes on a missing/non-64-bit
    // profile (`native.rs`: "proof-grade CHC translation requires an explicit
    // 64-bit target profile"), so without this stamp every native obligation on
    // a 64-bit host was rejected as Unsupported despite modeling exactly this
    // target. Values are read from the Session target, never hardcoded: a
    // genuinely 32-bit target produces `pointer_size: 4` and keeps failing
    // closed — that refusal is trust-mc's sound boundary, not ours to bypass.
    let native_target_info = Some(trust_ir::TargetInfo {
        triple: tcx.sess.opts.target_triple.to_string(),
        pointer_size: u32::from(tcx.sess.target.pointer_width) / 8,
        endianness: match tcx.sess.target.endian {
            rustc_abi::Endian::Little => trust_ir::Endianness::Little,
            rustc_abi::Endian::Big => trust_ir::Endianness::Big,
        },
        abi: None,
        struct_passing: Default::default(),
    });
    let native = build_native_trust_ir_bundle_from_verifiable_functions(
        func,
        bundle,
        Some(compiler_contract_reference),
        Some(compiler_contracts),
        trust_ir_functions,
        &expected_absent,
        &structural_drop,
        &abi_total_panic_free,
        &assumed_total,
        &compiler_total,
        paired_condvar_certificate.as_deref(),
        &certified_paired_condvar_wait_sites,
        body_bound_carriers,
        all_vcs,
        native_target_info,
    )?;
    if let Some(native_bundle) = native.as_ref()
        && let Some(dump_dir) = tcx.sess.opts.unstable_opts.trust_dump.native_bundle.as_deref()
    {
        publish_native_bundle_dump(tcx, func, native_bundle, dump_dir);
    }
    Ok(native)
}

/// Trust: collect the def-path names of user structs whose drop glue is purely
/// STRUCTURAL — no `Drop` impl (`!adt_def.has_dtor`), so their drop is only the
/// field drops (a panic-free `Box`/`Vec`/Copy dealloc when the fields are). The
/// bridge's drop-glue gate declines every non-std Adt (it cannot check for a
/// `Drop` impl); this set supplies that `has_dtor` fact so a structurally-simple
/// user container (e.g. `HashTable4KU16(Box<[u16; N]>)`) is recognized panic-
/// free-drop. Keyed by `safe_def_path_str` — the SAME string the bridge's
/// `Ty::Adt.name` carries. FIX b59: drives a BOUNDED transitive FIELD-TYPE closure
/// of the dropped type (each no-`Drop` ADT's field types AND generic args, recursively)
/// so a no-`Drop` struct/enum reachable only through a NESTED field — e.g.
/// `serde_json::Number`/`Map`/`Vec<Value>` inside an `Option<serde_json::Value>` — is
/// classified too, not just the generic-argument tree the old `ty::walk()` reached.
fn collect_structural_drop_adts<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    out: &mut FxHashSet<String>,
) {
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    for block in body.basic_blocks.iter() {
        let TerminatorKind::Drop { place, .. } = &block.terminator().kind else {
            continue;
        };
        let drop_ty = place.ty(&body.local_decls, tcx).ty;
        let drop_ty = tcx.normalize_erasing_regions(typing_env, ty::Unnormalized::new_wip(drop_ty));
        // FIX b59 (drop-glue transitive field-type closure): the previous
        // `for arg in drop_ty.walk()` iteration visited only the dropped type's
        // GENERIC-ARGUMENT tree (so `Option<serde_json::Value>` reached `Value` — a
        // generic arg of `Option` — but NOT `Value`'s own variant field types
        // `serde_json::Number` / `Map` / `Vec<Value>`, which are NOT generic args of
        // the non-generic `Value`). A transitively-nested no-`Drop` serde type was
        // therefore absent from the set, so the bridge's drop-glue gate declined it
        // and the panic-freedom row stayed UNKNOWN. Drive a BOUNDED transitive
        // FIELD-TYPE closure instead: explore each no-`Drop` ADT's field types (and
        // generic args, so a type-erased owning container still reaches its element),
        // certifying every ADT in the closure independently as `!has_dtor`.
        //
        // SOUNDNESS: a node WITH a user `Drop` impl is NEVER inserted and its subtree
        // is NOT explored (the bridge re-checks every field and declines any ADT
        // absent from this set, so it still FAILS CLOSED on it); a fuel-bail or the
        // visited-set truncating the walk likewise leaves deeper ADTs out of the set,
        // which fails closed — never a false PROVE. This is a sound STRENGTHENING:
        // the closure over-approximates the set to certify (fuel-bail → fail-closed →
        // Unknown), it can never mark a Drop-bearing type structural.
        drive_structural_drop_closure(
            drop_ty,
            STRUCTURAL_DROP_CLOSURE_FUEL,
            // has_drop: only an ADT carrying a user `Drop` impl — that node is cut.
            |ty| matches!(ty.kind(), ty::Adt(adt_def, _) if adt_def.has_dtor(tcx)),
            // on_structural: record each no-`Drop` ADT's def-path (the `!has_dtor`
            // fact the bridge cannot see); non-ADT component nodes carry no name.
            |ty| {
                if let ty::Adt(adt_def, _) = ty.kind() {
                    out.insert(trust_mir_extract::safe_def_path_str(tcx, adt_def.did()));
                }
            },
            // fields: the component types to explore transitively.
            |ty| structural_drop_component_types(tcx, typing_env, *ty),
        );
    }
}

/// FIX b59: the transitive-closure recursion budget for [`collect_structural_drop_adts`].
/// A `visited`-set already guarantees termination on any real (finite) monomorphized
/// field graph; this decrementing budget is pure defense-in-depth so a pathological or
/// malformed type graph fails CLOSED (the deeper ADTs stay out of the set, so the
/// bridge declines them) instead of looping unboundedly.
const STRUCTURAL_DROP_CLOSURE_FUEL: u32 = 16_384;

/// FIX b59: the pure, TyCtxt-free driver of the structural-drop transitive field-type
/// closure. Explores from `root` using `has_drop` (does this node carry a user `Drop`
/// impl?) and `fields` (its component/field nodes), invoking `on_structural` for every
/// reachable node that has NO `Drop` impl. Factored out from [`collect_structural_drop_adts`]
/// so its FAIL-CLOSED pins can be unit-tested without a `TyCtxt`:
///   * a node WITH a `Drop` impl is NEVER passed to `on_structural` and its fields are
///     NOT explored (the subtree is cut — the bridge, which re-checks every field and
///     declines any node absent from the recorded set, still fails closed on it);
///   * a decrementing `fuel` budget bounds the walk — a fuel-bail stops the closure,
///     leaving deeper nodes unrecorded (fail closed, never a false PROVE);
///   * a `visited`-set makes a cyclic type graph terminate.
fn drive_structural_drop_closure<N: Eq + Hash + Clone>(
    root: N,
    fuel: u32,
    mut has_drop: impl FnMut(&N) -> bool,
    mut on_structural: impl FnMut(&N),
    mut fields: impl FnMut(&N) -> Vec<N>,
) {
    let mut visited: FxHashSet<N> = FxHashSet::default();
    let mut worklist: Vec<N> = vec![root];
    let mut fuel = fuel;
    while let Some(node) = worklist.pop() {
        // FUEL EXHAUSTED: stop closing. Any node not yet recorded stays out of the
        // set, so the bridge declines it and fails closed. Never a false PROVE.
        let Some(next) = fuel.checked_sub(1) else { return };
        fuel = next;
        if !visited.insert(node.clone()) {
            continue;
        }
        // A user `Drop` impl: NEVER structural — record nothing and cut the subtree.
        if has_drop(&node) {
            continue;
        }
        on_structural(&node);
        worklist.extend(fields(&node));
    }
}

/// FIX b59: the component/field types the structural-drop closure explores from `ty`.
/// For an ADT it returns its FIELD types (the concrete variant payloads `ty::walk`
/// never yields — the leg that reaches `serde_json::Value`'s `Number`/`Map`/`Vec<Value>`)
/// PLUS its generic-argument types (so a type-erased owning container such as `Vec<T>`
/// or `Box<T>`, whose element only survives in a `PhantomData<T>`, still reaches `T`).
/// Arrays/slices yield their element, tuples their members, a raw pointer its owned
/// pointee, and a closure its captured upvars — mirroring the bridge's
/// `is_panic_free_drop_ext` recursion so every ADT the bridge visits is certifiable.
fn structural_drop_component_types<'tcx>(
    tcx: TyCtxt<'tcx>,
    typing_env: ty::TypingEnv<'tcx>,
    ty: Ty<'tcx>,
) -> Vec<Ty<'tcx>> {
    match ty.kind() {
        ty::Adt(adt_def, args) => {
            let mut comps: Vec<Ty<'tcx>> = adt_def
                .all_fields()
                .map(|field| tcx.normalize_erasing_regions(typing_env, field.ty(tcx, *args)))
                .collect();
            comps.extend(args.types());
            comps
        }
        ty::Array(elem, _) | ty::Slice(elem) => vec![*elem],
        ty::Tuple(members) => members.iter().collect(),
        ty::RawPtr(pointee, _) => vec![*pointee],
        ty::Closure(_, args) => args.as_closure().upvar_tys().iter().collect(),
        _ => Vec::new(),
    }
}

/// Trust (box-deref doc-lint false-positive fix): collect source spans of
/// raw-pointer-deref statements that dereference a COMPILER-SYNTHESIZED `Box`
/// pointer. A user's `a.eval(env)` with `a: &Box<Expr>` is a *builtin* box
/// autoderef which the required `ElaborateBoxDerefs` pass
/// (elaborate_box_derefs.rs:70-84) lowers to
/// `_p = Transmute(Copy(box_place.0:Unique.0:NonNull)) as *const T; _r = &(*_p)`
/// inside the caller's OWN scope (scope.inlined == None, span == the caller's
/// receiver token). trust-vcgen flags `&(*_p)` as an unsafe block and charges the
/// caller a "missing SAFETY comment" for a raw deref it never wrote. These spans
/// let that always-`Bool(true)` DOCUMENTATION lint be dropped.
///
/// DROP-ONLY. The predicate matches ONLY the `ElaborateBoxDerefs` / box-drop-glue
/// source shape (a `.0:Unique.0:NonNull` projection off an `owned_box`), so a
/// genuine first-party `mem::transmute::<NonNull<T>,*const T>(nn)` — whose
/// Transmute source is a BARE `NonNull` local (lower_intrinsics.rs:279), not a
/// box projection — is NOT collected and keeps its lint. The deref's REAL
/// validity (non-null/aligned, guaranteed by `NonNull`'s type invariant) is still
/// enforced by `synthetic_nonmodeled_unsafe_op_vcs`, not filtered here.
///
/// The inserted span is `source_span_from_rustc_span(tcx, stmt.source_info.span)`,
/// byte-identical to `trust_mir_extract::convert_span` which stamps
/// `UnsafeBlock.span` — so set membership matches exactly.
fn collect_synthesized_box_deref_spans<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    out: &mut FxHashSet<SourceSpan>,
) {
    use rustc_abi::FieldIdx;
    use rustc_middle::mir::{CastKind, Local, Operand, Place, PlaceElem, Rvalue, StatementKind};

    // Resolve the exact Unique/NonNull adt-defs Box uses — same derivation as
    // ElaborateBoxDerefs (elaborate_box_derefs.rs:95-107) and box drop glue
    // (elaborate_drop.rs:752-758). No Box lang item ⇒ no box derefs to find.
    let Some(owned_box_did) = tcx.lang_items().owned_box() else { return };
    let unique_did = tcx.adt_def(owned_box_did).non_enum_variant().fields[FieldIdx::ZERO].did;
    let Some(unique_def) =
        tcx.type_of(unique_did).instantiate_identity().skip_normalization().ty_adt_def()
    else {
        return;
    };
    let nonnull_did = unique_def.non_enum_variant().fields[FieldIdx::ZERO].did;
    let Some(nonnull_def) =
        tcx.type_of(nonnull_did).instantiate_identity().skip_normalization().ty_adt_def()
    else {
        return;
    };

    // Pass 1: map each bare-local assignment target to its defining rvalue.
    // Box-deref ptr temps are fresh single-assigned; a whole-body map also
    // catches a def/use split across blocks by later code motion.
    let mut defs: FxHashMap<Local, &Rvalue<'tcx>> = FxHashMap::default();
    for bbdata in body.basic_blocks.iter() {
        for stmt in &bbdata.statements {
            if let StatementKind::Assign(assign) = &stmt.kind {
                let (dest, rvalue) = &**assign;
                if dest.projection.is_empty() {
                    defs.insert(dest.local, rvalue);
                }
            }
        }
    }

    // True iff `local` is the raw ptr minted by ElaborateBoxDerefs / box drop
    // glue: `Cast(Transmute, Copy|Move(box_place.0:Unique.0:NonNull), *T)` whose
    // base is an `owned_box`. EXCLUDES a first-party transmute of a bare NonNull.
    let is_synth_box_ptr = |local: Local| -> bool {
        let Some(Rvalue::Cast(CastKind::Transmute, src_op, _dst)) = defs.get(&local).copied()
        else {
            return false;
        };
        let (Operand::Copy(src) | Operand::Move(src)) = src_op else { return false };
        let proj = src.projection;
        let n = proj.len();
        if n < 2 {
            return false;
        }
        // last two projections must be Field(0): Unique<_> then Field(0): NonNull<_>.
        let PlaceElem::Field(uq_idx, uq_ty) = proj[n - 2] else { return false };
        let PlaceElem::Field(nn_idx, nn_ty) = proj[n - 1] else { return false };
        if uq_idx != FieldIdx::ZERO || nn_idx != FieldIdx::ZERO {
            return false;
        }
        if uq_ty.ty_adt_def() != Some(unique_def) || nn_ty.ty_adt_def() != Some(nonnull_def) {
            return false;
        }
        // base (src minus the two field projections) must be an `owned_box`.
        Place::ty_from(src.local, &proj[..n - 2], &body.local_decls, tcx).ty.boxed_ty().is_some()
    };

    // Pass 2: any raw-deref rvalue whose deref'd base local is such a ptr.
    // Mirrors detection.rs::has_raw_deref's rvalue forms.
    for bbdata in body.basic_blocks.iter() {
        for stmt in &bbdata.statements {
            let StatementKind::Assign(assign) = &stmt.kind else { continue };
            let (_dest, rvalue) = &**assign;
            let place = match rvalue {
                Rvalue::Ref(_, _, place) | Rvalue::CopyForDeref(place) => place,
                Rvalue::Use(Operand::Copy(place) | Operand::Move(place), _) => place,
                _ => continue,
            };
            if place.projection.first() == Some(&PlaceElem::Deref) && is_synth_box_ptr(place.local)
            {
                out.insert(source_span_from_rustc_span(tcx, stmt.source_info.span));
            }
        }
    }
}

/// Is `callee_def_id`'s ABI
/// NON-UNWINDING — an `extern "C"` / `"system"` / `"cdecl"` / … boundary declared
/// `unwind: false`? This is classification only; it becomes eligible for the
/// narrow ABI panic boundary only when rustc also reports `is_foreign_item`.
/// Local Rust extern bodies remain ordinary potentially-aborting callees. We do not use
/// `layout::fn_can_unwind` because it folds in `panic=abort` and would classify
/// ordinary Rust callees as ABI boundaries. Only genuine fns have an `fn_sig` (the
/// query panics for closures/consts), so guard the `def_kind`.
fn native_callee_abi_is_non_unwinding<'tcx>(
    tcx: TyCtxt<'tcx>,
    callee_def_id: DefId,
    gen_args: ty::GenericArgsRef<'tcx>,
) -> bool {
    use rustc_hir::def::DefKind;
    if !matches!(tcx.def_kind(callee_def_id), DefKind::Fn | DefKind::AssocFn) {
        return false;
    }
    let abi = tcx.fn_sig(callee_def_id).instantiate(tcx, gen_args).skip_binder().abi();
    extern_abi_is_non_unwinding(abi)
}

/// Pure ABI classifier used by absent-boundary bookkeeping. The explicit
/// `unwind: false` C-family ABIs return true; `extern "C-unwind"`, Rust-family,
/// and every other ABI return false. Neither result alone is a proof verdict.
fn extern_abi_is_non_unwinding(abi: rustc_abi::ExternAbi) -> bool {
    use rustc_abi::ExternAbi::*;
    matches!(
        abi,
        C { unwind: false }
            | System { unwind: false }
            | Cdecl { unwind: false }
            | Stdcall { unwind: false }
            | Fastcall { unwind: false }
            | Thiscall { unwind: false }
            | Vectorcall { unwind: false }
            | Aapcs { unwind: false }
            | SysV64 { unwind: false }
            | Win64 { unwind: false }
    )
}

/// Preserve an extractor-produced call identity byte-for-byte in an
/// expected-absent classification set. In particular, do not shorten it to a
/// DefId display path: generic arguments and stable-crate disambiguators are
/// part of the bridge lookup key.
/// Fuel for the adapter recursion. An adapter chain deeper than this fails
/// closed: no recursive-shape assumption is proof authority for an arbitrary
/// std iterator type.
const TOTAL_STD_ITER_FUEL: u32 = 12;

/// Does `did`'s REAL def-path contain a module segment named `expected`?
///
/// Walks `tcx.def_path(did).data` — the definition path, never a rendered
/// string. Containment rather than an immediate-parent test because
/// `core::slice::Iter` is DEFINED at `core::slice::iter::Iter` (re-exported from
/// the `iter` submodule), so a parent check would see `iter`, not `slice`, and
/// reject every genuine slice iterator.
///
/// Sound as a DISAMBIGUATOR only: the caller has already authenticated the crate
/// via the real `CrateNum` (core/alloc/std). Segment names then distinguish items
/// WITHIN an authenticated sysroot crate, where no user or dependency code can
/// introduce an item. This is therefore not the "rendered path as identity"
/// pattern that `adt_path_is_std_anchored` (trust-ir-bridge lower.rs:13092)
/// exists to prevent — that hazard is a DEPENDENCY crate's `dep::slice::Iter`
/// matching on spelling, which cannot happen once `CrateNum` is pinned.
fn def_path_has_module_segment(tcx: TyCtxt<'_>, did: DefId, expected: &str) -> bool {
    let path = tcx.def_path(did);
    // Skip the LAST segment: that is the type itself, so a type literally named
    // `slice` cannot satisfy its own module anchor.
    let n = path.data.len();
    path.data
        .iter()
        .take(n.saturating_sub(1))
        .filter_map(|seg| seg.data.get_opt_name())
        .any(|name| name.as_str() == expected)
}

/// Trust: is `ty` a CONCRETE, sysroot-authenticated std iterator whose
/// `next`/`next_back` provably runs NO user code and cannot panic?
///
/// SOUNDNESS — every arm is an allowlist over an ADT whose crate identity is the
/// real `CrateNum` of its `DefId`. Anything unrecognized returns `false`.
///
/// DELIBERATELY EXCLUDED, each for a refutation that must survive:
///  - `Chunks`/`Windows` (and the `RChunks`/`ChunksExact` family): totality is
///    CONSTRUCTOR-conditional (`assert!(n != 0)`) — a call-site ARGUMENT
///    property that a TYPE predicate cannot see.
///    `tests/trust-falsification/mutant/chunks_zero.rs` survives if admitted.
///  - `Map`/`Filter`/`Cloned`/`FilterMap`/`FlatMap`/`TakeWhile`/`SkipWhile`/
///    `Scan`: their `next` drives a user closure or a user `Clone`.
///  - `RangeFrom`: `next` runs an UNGUARDED `Step::forward`, a real
///    debug-profile overflow panic (`0u8..` reaching 255).
///  - `RangeInclusive`: excluded pending its own analysis (fail-closed default).
///  - Non-slice std `Iter`s (`btree_map::Iter`, `hash_map::Iter`, …): sound in
///    principle but analyzed separately; fail closed here.
fn total_std_iterator_ty<'tcx>(tcx: TyCtxt<'tcx>, ty: Ty<'tcx>, fuel: u32) -> bool {
    if fuel == 0 {
        return false;
    }
    let ty::Adt(def, args) = ty.kind() else {
        return false;
    };
    let did = def.did();
    // REAL crate identity, not a rendered path. A local type never qualifies.
    if did.is_local() {
        return false;
    }
    if !matches!(tcx.crate_name(did.krate).as_str(), "core" | "alloc" | "std") {
        return false;
    }
    let inner = |n: usize| args.types().nth(n);

    match tcx.item_name(did).as_str() {
        // ---- Base: bounds-guarded pointer bumps, no user code. ----
        "Iter" | "IterMut" => def_path_has_module_segment(tcx, did, "slice"),
        "IntoIter" => def_path_has_module_segment(tcx, did, "array"),
        "Chars" | "CharIndices" => def_path_has_module_segment(tcx, did, "str"),

        // ---- Integer Range / StepBy<Range>. ----
        // Integer element only: a user newtype with a hand-written `Step` could
        // panic, and `char` is excluded for simplicity (fail-closed).
        "Range" => {
            def_path_has_module_segment(tcx, did, "range")
                && inner(0).is_some_and(|t| matches!(t.kind(), ty::Int(_) | ty::Uint(_)))
        }
        "StepBy" => inner(0).is_some_and(|t| total_std_iterator_ty(tcx, t, fuel - 1)),

        // ---- Total adapters: wrap/reorder/count only. ----
        "Rev" | "Enumerate" | "Take" | "Skip" | "Copied" | "Peekable" => {
            inner(0).is_some_and(|t| total_std_iterator_ty(tcx, t, fuel - 1))
        }
        // `Zip::next` pulls from BOTH sides, so requiring only ONE to be total is
        // a FALSE PROOF (a Zip of a slice iter and a user iterator would certify
        // while the user `next` panics).
        "Zip" => match (inner(0), inner(1)) {
            (Some(a), Some(b)) => {
                total_std_iterator_ty(tcx, a, fuel - 1) && total_std_iterator_ty(tcx, b, fuel - 1)
            }
            _ => false,
        },

        _ => false,
    }
}

/// Trust: is this `IntoIterator::into_iter` call TOTAL?
///
/// The trait is pinned by diagnostic item. The receiver must be either:
///  - a primitive slice or array (`&[T]`, `[T; N]`) — building `slice::Iter` /
///    `array::IntoIter` is a pointer+len construction that runs no user code; or
///  - an ALREADY-total std iterator, where `into_iter` is the identity (the
///    blanket `impl<I: Iterator> IntoIterator for I`).
///
/// A std CONTAINER receiver (`Vec<T>`, `&Vec<T>`, `HashMap`, …) is NOT admitted
/// here: it is sound in principle but its yielded iterator type is outside
/// `total_std_iterator_ty`'s allowlist, so admitting the constructor alone would
/// register a call whose subsequent `next` still fails closed — no benefit, and
/// it widens the surface. Fail-closed.
fn callee_is_total_std_into_iter<'tcx>(
    tcx: TyCtxt<'tcx>,
    callee_def_id: DefId,
    gen_args: ty::GenericArgsRef<'tcx>,
) -> bool {
    let Some(trait_did) = tcx.trait_of_assoc(callee_def_id).or_else(|| {
        tcx.trait_impl_of_assoc(callee_def_id).map(|impl_did| {
            tcx.impl_trait_ref(impl_did).instantiate_identity().skip_normalization().def_id
        })
    }) else {
        return false;
    };
    if !tcx.is_diagnostic_item(sym::IntoIterator, trait_did) {
        return false;
    }
    let Some(self_ty) = gen_args.types().next() else {
        return false;
    };
    if self_ty.has_non_region_param() {
        return false;
    }
    let mut base = self_ty;
    let mut peel = 0;
    while let ty::Ref(_, i, _) = base.kind() {
        base = *i;
        peel += 1;
        if peel > 4 {
            return false;
        }
    }
    match base.kind() {
        ty::Slice(_) | ty::Array(_, _) => true,
        _ => total_std_iterator_ty(tcx, base, TOTAL_STD_ITER_FUEL),
    }
}

/// Trust: does this call advance a type-verified TOTAL std iterator?
///
/// The trait is pinned by DIAGNOSTIC ITEM (`sym::Iterator`), never by path
/// spelling — the same callee renders as both `std::iter::Iterator::next` and
/// `core::iter::traits::iterator::Iterator::next` (trust-ir-bridge
/// lower.rs:11481), and a USER trait named `Iterator` must not match.
///
/// The RECEIVER type is the only thing separating the total case from arbitrary
/// user code: `<I as Iterator>::next` on a generic `I` can drive anything, so a
/// non-monomorphized receiver fails closed.
fn callee_is_type_verified_total_std_iterator<'tcx>(
    tcx: TyCtxt<'tcx>,
    callee_def_id: DefId,
    gen_args: ty::GenericArgsRef<'tcx>,
) -> bool {
    // `for &x in s` desugars to `IntoIterator::into_iter(s)` FOLLOWED BY repeated
    // `Iterator::next(&mut it)`. The interprocedural gate requires EVERY call
    // terminator to be registered, so the constructor hop must be recognized too
    // or the loop still fails closed on it.
    if tcx.item_name(callee_def_id).as_str() == "into_iter" {
        return callee_is_total_std_into_iter(tcx, callee_def_id, gen_args);
    }
    if !matches!(tcx.item_name(callee_def_id).as_str(), "next" | "next_back") {
        return false;
    }
    let Some(trait_did) = tcx.trait_of_assoc(callee_def_id).or_else(|| {
        tcx.trait_impl_of_assoc(callee_def_id).map(|impl_did| {
            tcx.impl_trait_ref(impl_did).instantiate_identity().skip_normalization().def_id
        })
    }) else {
        return false;
    };
    // `Iterator` has a diagnostic item. `DoubleEndedIterator` does NOT in this
    // tree, so it is pinned by (real `CrateNum` ∈ {core, std}) ∧ item name —
    // sound because a user crate cannot define an item INSIDE core/std, so the
    // CrateNum carries the identity and the name only disambiguates within it.
    let is_iterator = tcx.is_diagnostic_item(sym::Iterator, trait_did);
    let is_double_ended = !trait_did.is_local()
        && matches!(tcx.crate_name(trait_did.krate).as_str(), "core" | "std")
        && tcx.item_name(trait_did).as_str() == "DoubleEndedIterator";
    if !(is_iterator || is_double_ended) {
        return false;
    }
    let Some(self_ty) = gen_args.types().next() else {
        return false;
    };
    // Fail closed rather than ask a fully-monomorphic resolver a param-env
    // question.
    if self_ty.has_non_region_param() {
        return false;
    }
    // Peel references: `<&mut Iter<'_, T> as Iterator>::next` is the same advance.
    let mut base = self_ty;
    let mut peel = 0;
    while let ty::Ref(_, i, _) = base.kind() {
        base = *i;
        peel += 1;
        if peel > 4 {
            return false;
        }
    }
    total_std_iterator_ty(tcx, base, TOTAL_STD_ITER_FUEL)
}

fn insert_exact_absent_call_identity(out: &mut FxHashSet<String>, call_key: &str) {
    out.insert(call_key.to_owned());
}

/// Trust: collect the callee strings in `body` that are EXPECTEDLY absent — a
/// callee the user `#[trust::skip]`'d, or a NON-UNWINDING C-family (`extern "C"`)
/// boundary. This is quarantine bookkeeping, not a discharge: strict policies still
/// reject the resulting visible assumption. Unresolved generic dispatch is
/// intentionally absent. Keyed by the exact
/// [`trust_mir_extract::func_operand_name`] used for the extracted
/// `Terminator::Call.func`, including concrete generic arguments and duplicate-crate
/// disambiguation. Membership matters only when a callee is absent
/// from the lowered bundle; a concrete bundled body remains a normal call even
/// if its ABI also has the non-unwind classification.
fn collect_expected_absent_callees<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    out: &mut FxHashSet<String>,
    // Exact call identities for genuinely bodyless foreign non-unwinding
    // imports. These reach the bridge's ABI discharge arm, not the ordinary
    // expected-absent assumption arm.
    abi_total_out: &mut FxHashSet<String>,
    assumed_total_out: &mut FxHashSet<String>,
    // Exact call identities the compiler TYPE-VERIFIED as total std iterator
    // advances. Decided from real `ty::Ty` + `CrateNum`; never populated from an
    // attribute, a rendered path, or a callee-name marker.
    type_total_out: &mut FxHashSet<String>,
    // Exact call identities the compiler decided are TOTAL from the full
    // monomorphized signature and that the BRIDGE cannot decide for itself —
    // today the `?`-desugar calls, whose residual/target error types are lost
    // by the time the bridge sees them. Carried to the bridge on the
    // authenticated SET channel instead of a forgeable `::<__trust_*>` name
    // suffix (the "spelling as authority" hazard).
    compiler_total_out: &mut FxHashSet<String>,
) {
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());
    for block in body.basic_blocks.iter() {
        let (func, _) = match &block.terminator().kind {
            TerminatorKind::Call { func, args, .. }
            | TerminatorKind::TailCall { func, args, .. } => (func, args),
            _ => continue,
        };
        let Some((callee_def_id, gen_args)) = func.const_fn_def() else {
            continue;
        };
        // This must be computed from the operand, not reconstructed from a DefId:
        // extraction includes instantiated generic arguments and stable-crate
        // disambiguation in this exact key. A shorter `safe_def_path_str` silently
        // misses the bridge call row and turns an authenticated skip boundary
        // into a fatal ordinary absent callee.
        let call_key = trust_mir_extract::func_operand_name(tcx, func);
        // ROBUST user-skip: a call to a `#[trust::skip]` callee is EXPECTED-absent
        // regardless of how `try_resolve` classifies it (a const-generic skip'd fn
        // can resolve `Ok(Some)`, or — depending on the caller's typing env — come
        // back `Ok(None)`/`Err`; the skip fact must not depend on that). Check the
        // SYNTACTIC def_id up front and record this exact call-site key. The
        // resolution arm below handles an attribute carried only by a resolved
        // implementation while retaining the same operand identity.
        if item_has_trust_skip_attr(tcx, callee_def_id) {
            insert_exact_absent_call_identity(out, &call_key);
        }
        if item_has_trust_attr(tcx, callee_def_id, "assume_total") {
            insert_exact_absent_call_identity(assumed_total_out, &call_key);
        }
        // COMPILER-decided, type-verified total std iterator advance. Kept in its
        // own set (never merged into `assumed_total_out`, which is the user
        // `#[trust::assume_total]` axiom lane) so the gate can credit a proof
        // without ever crediting a user declaration.
        if callee_is_type_verified_total_std_iterator(tcx, callee_def_id, gen_args) {
            insert_exact_absent_call_identity(type_total_out, &call_key);
        }
        // The `?`-desugar totality decision needs the monomorphized residual
        // and target error types, which only exist here. Same fail-closed
        // predicate the extractor uses for its marker; a CONVERTING `?` (a real
        // `From` conversion that can panic) is not matched.
        if trust_mir_extract::trust_try_total_marker(tcx, callee_def_id, gen_args) {
            insert_exact_absent_call_identity(compiler_total_out, &call_key);
        }
        // ROBUST FOREIGN / extern-"C" absent-callee classification. A bodyless
        // extern-block fn often does not resolve to `Ok(Some)`, so decide on the
        // syntactic def-id up front while recording the exact call-site key.
        // Non-unwinding alone is not enough: only rustc-authenticated bodyless
        // foreign imports reach the ABI discharge set. A local Rust extern body
        // remains a visible expected-absent boundary.
        let callee_non_unwinding = native_callee_abi_is_non_unwinding(tcx, callee_def_id, gen_args);
        if callee_non_unwinding {
            if tcx.is_foreign_item(callee_def_id) {
                insert_exact_absent_call_identity(abi_total_out, &call_key);
            } else {
                insert_exact_absent_call_identity(out, &call_key);
            }
        }
        match ty::Instance::try_resolve(tcx, typing_env, callee_def_id, gen_args) {
            // GENERIC DISPATCH: `ImplSource::Param` — a trait method on a type
            // PARAMETER, no single impl to bundle in this polymorphic unit.
            //
            // Trust (R3 soundness, probes T5b/T5d/T9): this is NOT expected-absent.
            // An unresolvable `<T as D>::m` is instantiation-dependent — at mono an
            // impl may supply a body that PANICS (or `D::m` may be bodyless and only
            // an impl provides one), so demoting the call to a non-fatal
            // `expected-absent-callee` assumption would prove the caller's
            // panic-freedom against a callee whose real target could panic (a false
            // proof: `fn f<T: D>(t: &T) { t.m() }` must NOT verify clean). The call
            // therefore stays on the bridge's FATAL absent-callee arm and fails
            // closed — the only sound verdict for a target that isn't pinned until
            // monomorphization. (The narrow completeness cost is the sound
            // direction, exactly as the R3 mutant fixtures state.) A `#[trust::skip]`
            // callee that happens to resolve `Ok(None)` is already recorded above by
            // the syntactic-skip check, so the user escape hatch is unaffected.
            //
            // ONE exception, strictly stronger than the R3 reasoning above:
            // CLOSED-WORLD dispatch (lattice rung 2). When the trait is SEALED
            // (impl set provably closed at this crate) and every enumerated
            // dispatch target — each overriding impl method plus the inherited
            // default body — is itself verified panic-free, the "an impl may
            // supply a panicking body at mono" counterexample cannot exist: any
            // instantiation's target is inside the verified conjunction. Only
            // then is the call expected-absent (the bridge demotes its row);
            // every other shape (open trait, blanket impl, unverified/cycling
            // impl, zero impls) falls through to the fatal arm unchanged.
            Ok(None) => {
                if let Some(trait_def_id) = tcx.trait_of_assoc(callee_def_id) {
                    if sealed_generic_dispatch_impls_all_panic_free(
                        tcx,
                        body.source.def_id(),
                        trait_def_id,
                        callee_def_id,
                    ) {
                        out.insert(trust_mir_extract::safe_def_path_str(tcx, callee_def_id));
                    }
                }
            }
            // RESOLVED: a concrete instance. Fatal-absent only if it is a real
            // out-of-bundle body (std/extern) — NOT expected-absent — so leave
            // it out. But if the resolved callee carries `#[trust::skip]`, the
            // user took responsibility: classify this exact call-site identity
            // as expected-absent.
            Ok(Some(instance)) => {
                let resolved = instance.def_id();
                if item_has_trust_skip_attr(tcx, resolved) {
                    insert_exact_absent_call_identity(out, &call_key);
                }
                if callee_non_unwinding {
                    if tcx.is_foreign_item(resolved) {
                        insert_exact_absent_call_identity(abi_total_out, &call_key);
                    } else {
                        insert_exact_absent_call_identity(out, &call_key);
                    }
                }
                if item_has_trust_attr(tcx, resolved, "assume_total") {
                    insert_exact_absent_call_identity(assumed_total_out, &call_key);
                }
            }
            Err(_) => {}
        }
    }
}

#[cfg(test)]
fn build_native_trust_ir_bundle_for_test_verifier_api(
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    all_vcs: &[VerificationCondition],
) -> Result<Option<trust_ir_bridge::NativeVerificationBundle>, String> {
    build_native_trust_ir_bundle_for_test_verifier_api_with_carriers(
        func,
        bundle,
        None,
        None,
        &mut Vec::new(),
        all_vcs,
    )
}

#[cfg(test)]
fn build_native_trust_ir_bundle_for_test_verifier_api_with_carriers(
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    compiler_contract_reference: Option<&trust_verifier_api::TrustContractBundle>,
    compiler_contracts: Option<&trust_types::CompilerContractBundle>,
    body_bound_carriers: &mut Vec<CompilerFinalizedBodyBoundCarrier>,
    all_vcs: &[VerificationCondition],
) -> Result<Option<trust_ir_bridge::NativeVerificationBundle>, String> {
    body_bound_carriers.clear();
    ensure_default_trust_mc_function_obligation(func, bundle)?;

    if !bundle
        .obligations
        .iter()
        .any(|obligation| native_trust_ir_route_for_api_obligation(obligation).is_some())
    {
        return Ok(None);
    }

    build_native_trust_ir_bundle_from_verifiable_functions(
        func,
        bundle,
        compiler_contract_reference,
        compiler_contracts,
        vec![func.clone()],
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        &FxHashSet::default(),
        None,
        &[],
        body_bound_carriers,
        all_vcs,
        // Test harness: no Session in scope; a target-independent module keeps
        // every pre-existing test expectation (target_info stays None).
        None,
    )
}

fn build_native_trust_ir_bundle_from_verifiable_functions(
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    compiler_contract_reference: Option<&trust_verifier_api::TrustContractBundle>,
    compiler_contracts: Option<&trust_types::CompilerContractBundle>,
    trust_ir_functions: Vec<trust_types::VerifiableFunction>,
    expected_absent_callees: &FxHashSet<String>,
    structural_drop_adts: &FxHashSet<String>,
    // Exact compiler-authenticated bodyless-foreign non-unwinding callees.
    abi_total_panic_free_callees: &FxHashSet<String>,
    assumed_total_callees: &FxHashSet<String>,
    // Compiler-decided totals the bridge cannot decide for itself (the `?`
    // desugar). Authenticated by provenance: only this compiler path supplies it.
    compiler_total_callees: &FxHashSet<String>,
    paired_condvar_certificate: Option<&trust_mir_extract::PairedCondvarCrateCertificate>,
    certified_paired_condvar_wait_sites: &[trust_mir_extract::CertifiedPairedCondvarWaitCallSite],
    body_bound_carriers: &mut Vec<CompilerFinalizedBodyBoundCarrier>,
    // Trust (sealed-authority reconciliation): the exact VC slice the
    // verifier-api bundle was minted from; consumed by the trust-vc lane's
    // planning-time kernel-certification gate.
    all_vcs: &[VerificationCondition],
    // Compiler-supplied target profile, stamped onto the module BEFORE the
    // native-bundle construction boundary so every derived identity (module
    // stable_digest, lineage, replay) commits to it. `None` (tests) keeps the
    // module target-independent.
    target_info: Option<trust_ir::TargetInfo>,
) -> Result<Option<trust_ir_bridge::NativeVerificationBundle>, String> {
    body_bound_carriers.clear();
    let panic_source_function_paths: FxHashSet<String> =
        trust_ir_functions.iter().map(|function| function.def_path.clone()).collect();
    // FAIL-SOFT BUNDLING: one unloweable CALLEE must not push every obligation
    // of the target to Unknown. On a bundle failure, pre-filter: keep the
    // target (always index 0) plus every callee that lowers ALONE, and lower
    // that survivor set — a dropped callee's call sites lower via the bridge's
    // absent-callee arm (honest may-panic marker + PanicFreedom obligation).
    // Set-independence: with the absent-callee arm, a function that lowers
    // alone also lowers in any bundle (a larger known-function set only turns
    // absent-callee markers into real calls, never the reverse). If the TARGET
    // itself cannot lower, propagate the ORIGINAL error — an honest hard fail.
    // A paired-condvar site and the opaque certificate that minted it are one
    // authority object. Never lower a retained site through the ordinary
    // public bridge surface, and never accept a site without the current
    // compiler Session's exact crate certificate. Test-only callers with no
    // authority use the stable rustc-private-free surface.
    let lower_functions =
        |functions: &[trust_types::VerifiableFunction],
         paired_sites: &[trust_mir_extract::CertifiedPairedCondvarWaitCallSite]| {
            match paired_condvar_certificate {
                Some(certificate) => {
                    trust_ir_bridge::lower_to_trust_ir_functions_with_compiler_context(
                        &func.def_path,
                        functions,
                        expected_absent_callees,
                        structural_drop_adts,
                        abi_total_panic_free_callees,
                        assumed_total_callees,
                        certificate,
                        paired_sites,
                        compiler_total_callees,
                    )
                }
                None if paired_sites.is_empty() => {
                    trust_ir_bridge::lower_to_trust_ir_functions_with_assumed_total_context(
                        &func.def_path,
                        functions,
                        expected_absent_callees,
                        structural_drop_adts,
                        abi_total_panic_free_callees,
                        assumed_total_callees,
                        compiler_total_callees,
                    )
                }
                None => {
                    let site = &paired_sites[0];
                    Err(trust_ir_bridge::BridgeError::InvalidPairedCondvarAuthority {
                        function_def_path: site.function_def_path().to_string(),
                        block: site.block().0,
                        callee: site.callee().to_string(),
                        reason: "compiler supplied paired-condvar authority without its current crate certificate"
                            .into(),
                    })
                }
            }
        };
    let mut module = match lower_functions(&trust_ir_functions, certified_paired_condvar_wait_sites)
    {
        Ok(module) => module,
        Err(first_error) => {
            // CONTEXT-AWARE survivor pre-filter, iterated to a FIXED POINT.
            //
            // The former probe lowered each callee in ISOLATION
            // (`lower_to_trust_ir(vf).is_ok()`, an EMPTY known-set). That
            // mis-drops any callee that only lowers WITH bundle context:
            //   * a closure whose captured-environment CONSTRUCTION site lives in
            //     its PARENT (never its own body), so alone its env param is
            //     unrefined and `map_type(Ty::Closure)` errs; and
            //   * a closure that itself invokes another closure, whose
            //     `Fn::call(&inner)` shim needs the inner body's signature
            //     registered.
            // Dropping such a closure pushes its `Fn::call` sites to the
            // untypeable-receiver / absent-callee arm → runtime_checked, and a
            // dropped inner closure then hard-fails its parent's shim in the
            // retry (cascading one capped/missing closure into a whole-bundle
            // failure).
            //
            // Instead probe each candidate WITH the whole survivor set's
            // closure-env registry and names/signatures registered
            // (`verifiable_function_lowers_in_module_context`, which seeds
            // `collect_closure_env_types` over the FULL set and carries the real
            // expected-absent / structural-drop context). Because dropping a
            // member can invalidate one that referenced it, re-probe the shrunk
            // set until it stabilizes — a monotonically shrinking set bounded
            // below by the target, so the loop terminates. The target (index 0)
            // is never dropped. At the fixed point EVERY surviving non-target
            // member lowers in the survivor context, so the survivor-bundle
            // lowering below fails ONLY if the TARGET itself is unloweable —
            // restoring the documented invariant.
            //
            // SOUNDNESS: the probe decides bundle MEMBERSHIP only, never an
            // obligation. A retained callee lowers with the SAME env/signature
            // context the full bundle would give it (set-independence, above), so
            // it yields the SAME obligations. A callee that still cannot lower in
            // context is still dropped (fail-closed), and its call sites lower via
            // the bridge's absent-callee / shim arms (honest may-panic marker +
            // PanicFreedom obligation).
            let mut survivors: Vec<trust_types::VerifiableFunction> = trust_ir_functions.clone();
            loop {
                let mut next: Vec<trust_types::VerifiableFunction> =
                    Vec::with_capacity(survivors.len());
                for index in 0..survivors.len() {
                    if index == 0
                        || trust_ir_bridge::verifiable_function_lowers_in_module_context(
                            &survivors,
                            index,
                            expected_absent_callees,
                            structural_drop_adts,
                        )
                    {
                        next.push(survivors[index].clone());
                    }
                }
                let stabilized = next.len() == survivors.len();
                survivors = next;
                if stabilized {
                    break;
                }
            }
            // Capabilities are bound to an exact function body. A fail-soft
            // retry that drops an unlowerable member must drop only that
            // member's sidecars as well; otherwise the bridge correctly rejects
            // the now-missing capability owner and the retry cannot be fail-
            // soft. Calls into a dropped member remain ordinary absent calls
            // with their may-panic obligation, so filtering cannot discharge
            // anything new.
            let survivor_paths: FxHashSet<&str> =
                survivors.iter().map(|function| function.def_path.as_str()).collect();
            let survivor_paired_condvar_wait_sites = certified_paired_condvar_wait_sites
                .iter()
                .filter(|site| survivor_paths.contains(site.function_def_path()))
                .cloned()
                .collect::<Vec<_>>();
            let module = lower_functions(
                &survivors,
                &survivor_paired_condvar_wait_sites,
            )
            .map_err(
                |error| {
                    // At the fixed point the survivor bundle fails ONLY if the
                    // TARGET is the unloweable one (every retained callee lowers
                    // in the survivor context). Report the retry error, noting
                    // the original.
                    format!(
                        "failed to lower `{}` and its local callees into typed TrustIr NativeVerificationBundle input: {error} (first attempt: {first_error})",
                        func.def_path
                    )
                },
            )?;
            module
        }
    };
    // Trust: surface bridge-emitted native panic-freedom (user `assert!` /
    // `unreachable!` with no public VC twin) as a counted public Assertion
    // obligation, so a function whose only obligation is panic-freedom is
    // verified non-vacuously instead of hitting the empty-bundle skipped guard.
    // The proof comes solely from the native trust-mc CHC reachability of the
    // lowered `Inst::Assert`; no new trust assumption is introduced.
    synthesize_native_panic_freedom_to_verifier_api_obligations(
        func,
        bundle,
        &module,
        &panic_source_function_paths,
    )?;
    let function_id = native_trust_ir_function_id(&module, func)?;
    let native_function_name = module
        .function_by_id(function_id)
        .ok_or_else(|| {
            format!(
                "typed TrustIr module lost the selected function {} for `{}`",
                function_id.index(),
                func.def_path
            )
        })?
        .name
        .clone();
    let bindings = append_verifier_api_obligations_to_native_trust_ir(
        &mut module,
        func,
        bundle,
        function_id,
        all_vcs,
    )?;
    if bindings.is_empty() {
        return Ok(None);
    }

    // Any compiler-derived contract that changes the public claim must exist
    // before the native module commits that claim. In particular, trust-wp's
    // metadata-only typed predicates need a real public contract link; creating
    // and linking that contract after bundle construction leaves the TrustIr
    // identities authorizing an older public record.
    finalize_trust_mc_public_semantic_contracts(&native_function_name, func, bundle, &bindings)?;
    finalize_trust_wp_public_semantic_contracts(bundle, &bindings)?;
    // Trust (#23 Slice 1): body-bound trust-wp claims for uncited `ensures`.
    // Same pre-digest invariant as above: the derived let-envelope contract
    // changes the public claim, so it must exist before the canonical semantic
    // digest index below mints the identities the native module commits to.
    let pending_body_bound_claims = finalize_trust_wp_body_bound_public_claims(
        &module,
        function_id,
        func,
        bundle,
        compiler_contract_reference,
        compiler_contracts,
        &bindings,
    )?;
    let public_semantic_digests = canonical_native_public_semantic_digest_index(bundle, &bindings)?;
    populate_native_trust_ir_proof_sources(
        &mut module,
        bundle,
        &bindings,
        function_id,
        &public_semantic_digests,
    )?;

    // Finalize every public-claim formula before crossing the native-bundle
    // construction boundary. That boundary derives the module, lineage,
    // monomorphization, request, and replay identities from the module it is
    // given; mutating formulas afterwards would either fail validation or
    // leave some of those identities authorizing a different claim.
    populate_native_trust_ir_proof_formulas(&mut module, bundle, &bindings)?;
    // Last module mutation before the construction boundary below derives the
    // digest/lineage/replay identities: stamp the compiler-known target profile
    // so those identities commit to it (`target_info` is serialized, so it
    // flows into `Module::stable_digest` automatically).
    module.target_info = target_info;
    let source_digest = native_trust_ir_source_digest(func)?;
    let native_trust_ir_bundle =
        trust_ir_bridge::native_verification_bundle_from_module(module, source_digest, function_id)
            .map_err(|error| {
                format!(
                    "failed to build typed TrustIr NativeVerificationBundle for `{}`: {error:?}",
                    func.def_path
                )
            })?;

    annotate_verifier_api_obligations_with_native_trust_ir(
        bundle,
        &native_trust_ir_bundle,
        &bindings,
    )?;
    let annotated_public_semantic_digests =
        canonical_native_public_semantic_digest_index(bundle, &bindings)?;
    if annotated_public_semantic_digests != public_semantic_digests {
        return Err(format!(
            "native TrustIr transport annotation changed canonical public semantics for `{}` after native identities were minted",
            func.def_path
        ));
    }
    bundle.validate()?;
    let finalized_body_bound_carriers = seal_compiler_finalized_body_bound_carriers(
        bundle,
        &native_trust_ir_bundle,
        &pending_body_bound_claims,
        &annotated_public_semantic_digests,
    )?;
    *body_bound_carriers = finalized_body_bound_carriers;
    Ok(Some(native_trust_ir_bundle))
}

fn canonical_native_public_semantic_digest_index(
    bundle: &trust_verifier_api::TrustContractBundle,
    bindings: &[PendingNativeTrustIrBinding],
) -> Result<trust_verifier_api::CanonicalObligationSemanticDigestIndex, String> {
    let mut requested = Vec::with_capacity(bindings.len());
    for binding in bindings {
        requested.push(
            bundle
                .obligations
                .get(binding.obligation_index)
                .ok_or_else(|| {
                    format!(
                        "native TrustIr binding referenced missing public obligation index {}",
                        binding.obligation_index
                    )
                })?
                .clone(),
        );
    }
    bundle.canonical_obligation_semantic_digest_index_sha256(&requested)
}

fn populate_native_trust_ir_proof_sources(
    module: &mut trust_ir::Module,
    bundle: &trust_verifier_api::TrustContractBundle,
    bindings: &[PendingNativeTrustIrBinding],
    function_id: trust_ir::FuncId,
    semantic_digests: &trust_verifier_api::CanonicalObligationSemanticDigestIndex,
) -> Result<(), String> {
    let mut proof_positions = FxHashMap::default();
    for (position, proof_obligation) in module.proof_obligations.iter().enumerate() {
        if proof_positions.insert(proof_obligation.id, position).is_some() {
            return Err(format!(
                "native TrustIr proof inventory contains duplicate proof obligation ID {}",
                proof_obligation.id.index()
            ));
        }
    }

    for binding in bindings {
        let obligation = bundle.obligations.get(binding.obligation_index).ok_or_else(|| {
            format!(
                "native TrustIr binding referenced missing public obligation index {}",
                binding.obligation_index
            )
        })?;
        let digest = semantic_digests.get(&obligation.obligation_id).ok_or_else(|| {
            format!(
                "canonical semantic digest index omitted native public obligation {}",
                obligation.obligation_id
            )
        })?;
        let public_digest = trust_ir_sha256_digest_from_hex(digest, &obligation.obligation_id)?;
        let source_id = obligation
            .contract_id
            .as_deref()
            .or(obligation.proof_item_id.as_deref())
            .unwrap_or(&obligation.obligation_id);
        let assertion_id = format!("trust-assertion:{source_id}");
        let mut source = trust_ir::ProofObligationSourceIdentity::new(source_id, assertion_id)
            .with_public(trust_ir::PublicObligationIdentity {
                obligation_id: obligation.obligation_id.clone(),
                semantic_digest: public_digest,
            });
        if let Some(file) = obligation.source.file.as_deref().filter(|file| !file.is_empty()) {
            let file = module.intern_file(file.to_string());
            let start_line = obligation.source.line.unwrap_or_default();
            let start_col = obligation.source.column.unwrap_or_default();
            source = source.with_range(trust_ir::ProofObligationSourceRange {
                file,
                start_line,
                start_col,
                end_line: obligation.source.end_line.unwrap_or(start_line),
                end_col: obligation.source.end_column.unwrap_or(start_col),
            });
        }
        let position =
            proof_positions.get(&binding.proof_obligation_id).copied().ok_or_else(|| {
                format!(
                    "native TrustIr proof inventory omitted proof obligation {}",
                    binding.proof_obligation_id.index()
                )
            })?;
        let proof_obligation = &mut module.proof_obligations[position];
        proof_obligation.function = Some(function_id);
        proof_obligation.source = Some(source);
    }
    Ok(())
}

fn trust_ir_sha256_digest_from_hex(
    value: &str,
    obligation_id: &str,
) -> Result<trust_ir::ProofDigest, String> {
    if value.len() != 64 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
        return Err(format!(
            "canonical semantic digest for public obligation `{obligation_id}` is not a 64-character SHA-256 hex digest"
        ));
    }
    let mut bytes = [0_u8; 32];
    for (index, pair) in value.as_bytes().chunks_exact(2).enumerate() {
        let high = (pair[0] as char).to_digit(16).expect("validated hexadecimal digit") as u8;
        let low = (pair[1] as char).to_digit(16).expect("validated hexadecimal digit") as u8;
        bytes[index] = (high << 4) | low;
    }
    if bytes == [0; 32] {
        return Err(format!(
            "canonical semantic digest for public obligation `{obligation_id}` must not be zero"
        ));
    }
    Ok(trust_ir::ProofDigest::sha256(bytes))
}

fn publish_native_bundle_dump(
    tcx: TyCtxt<'_>,
    func: &trust_types::VerifiableFunction,
    bundle: &trust_ir_bridge::NativeVerificationBundle,
    dump_dir: &Path,
) {
    std::fs::create_dir_all(dump_dir).unwrap_or_else(|error| {
        tcx.dcx().fatal(format!(
            "failed to create -Ztrust-dump=native-bundle: directory `{}`: {error}",
            dump_dir.display()
        ))
    });
    let json = serde_json::to_string_pretty(bundle).unwrap_or_else(|error| {
        tcx.dcx().fatal(format!(
            "failed to serialize native TrustIr bundle for `{}`: {error}",
            func.def_path
        ))
    });
    let path = dump_dir.join(native_bundle_dump_filename(&func.def_path, &json));
    write_mir_dump_create_new(&path, &json).unwrap_or_else(|error| {
        tcx.dcx().fatal(format!(
            "failed to publish -Ztrust-dump=native-bundle: evidence for `{}` at `{}`: {error}",
            func.def_path,
            path.display()
        ))
    });
}

/// Trust: true iff querying `tcx.optimized_mir(callee)` from WITHIN the currently
/// running `trust_verify` pass would form an E0391 query cycle — i.e. `callee`'s
/// `optimized_mir` is already on the stack (`callee` IS an in-progress ancestor,
/// e.g. the other member of a `ping`↔`pong` pair being peeked while `ping` is
/// optimized), OR `callee` transitively REACHES such an in-progress ancestor.
///
/// The in-progress set ([`OPTIMIZED_MIR_VERIFY_IN_PROGRESS`]) supplies exact live
/// query ancestors. Mutual-recursion membership comes from the compact, cached
/// `trust_mir_mutually_recursive_functions` query, so this hot path never rescans or retains
/// full MIR snapshots. A direct self edge is excluded by that query; the exact
/// in-progress check still prevents re-entering the currently optimizing body.
// Trust: pub(crate) for `trust_r1_oracle`'s coroutine-body recovery, which reads
// `optimized_mir` (the steal consumer) and must not re-enter an in-flight computation.
pub(crate) fn optimized_mir_query_would_cycle(tcx: TyCtxt<'_>, callee: DefId) -> bool {
    OPTIMIZED_MIR_VERIFY_IN_PROGRESS.with(|s| {
        let in_progress = s.borrow();
        in_progress.contains(&callee)
            || callee.as_local().is_some_and(|local| trust_mir_is_mutually_recursive(tcx, local))
    })
}

fn native_trust_ir_verifiable_function_closure<'tcx>(
    tcx: TyCtxt<'tcx>,
    root_body: &Body<'tcx>,
    root_func: &trust_types::VerifiableFunction,
    policy: &TrustVerifyPolicy,
    // Trust: the DefIds actually BUNDLED (root + every collected callee),
    // reported so the expected-absent scan can walk each bundled body's OWN
    // call sites — including CROSS-CRATE ones. Before the workspace-sibling
    // closure extension every non-local frame was absent (never bundled), so
    // the local-only `mir_keys` lookup sufficed; now a bundled sibling body
    // (e.g. `aterm_pty::write_some` inside aterm-session's bundle) contains
    // real calls — its `libc::write` must be classified too, or it surfaces
    // as an unresolvable absent callee in the CALLER's crate.
    bundled: &mut FxHashSet<DefId>,
) -> Result<Vec<trust_types::VerifiableFunction>, String> {
    let mut functions = vec![root_func.clone()];
    let mut seen: FxHashSet<DefId> = FxHashSet::default();
    seen.insert(root_body.source.def_id());
    bundled.insert(root_body.source.def_id());

    // Trust: skip recursive callee expansion during stage1 bootstrap.
    // `tcx.optimized_mir(callee)` triggers a query cycle when the callee
    // is recursive (e.g. rustc-demangle::v0::print_path, slice::sort::drift::sort).
    // Returning the root function alone is sound for daily-driver build; deeper
    // bundles are a Phase 4+ enhancement once query-cycle-safe traversal is wired.
    if !policy.includes_native_trust_ir_callee_closure() {
        return Ok(functions);
    }

    let mut pending = native_trust_ir_direct_local_fn_callees(tcx, root_body);
    let mut cursor = 0usize;
    while let Some(callee_def_id) = pending.get(cursor).copied() {
        // `seen` bounds this transitive callee walk by distinct-callee count; the
        // deadline poll caps its slow-but-bounded tail. A truncated bundle is
        // sound — an omitted callee's obligations fail closed downstream (Unknown
        // / absent-callee), never a hidden proof.
        if trust_types::verify_budget::budget_exhausted() {
            break;
        }
        cursor += 1;
        if !seen.insert(callee_def_id) {
            continue;
        }
        // Trust (escape-hatch contradiction fix): a `#[trust::skip]` callee's body is
        // NOT bundled and NOT traversed into. The user took responsibility for that
        // function's safety, so re-lowering its (often DELIBERATELY panicking, e.g.
        // idiomatic-alloc `.unwrap()`) body as a member of THIS bundle would resurrect
        // the very panic obligations the skip waives — turning every caller's full
        // verification fatal on the skip'd body's absent-callee rows and making the
        // documented escape hatch self-defeating. Leaving it out keeps the caller's
        // CALL site absent, where the expected-absent marker fires (the callee is
        // in the caller's set via the syntactic-skip collector). Survey turns
        // that marker into a visible assumption row; strict and memory-safe reject
        // it. The skipped function itself is likewise a strict-scope error, so the
        // omission cannot become a hidden strict proof.
        if item_has_trust_skip_attr(tcx, callee_def_id) {
            continue;
        }
        // An assumed-total callee remains outside the proof bundle so its call
        // site takes the dedicated recorded-assumption boundary. Re-lowering
        // the body here would contradict the explicit user assumption.
        if item_has_trust_attr(tcx, callee_def_id, "assume_total") {
            continue;
        }
        if functions.len() >= NATIVE_TRUST_IR_MAX_LOCAL_CALLEE_CLOSURE {
            // FAIL-SOFT: bundle what fits instead of failing the whole bundle.
            // Every callee left out lowers at its call sites via the bridge's
            // absent-callee arm (honest may-panic marker + PanicFreedom
            // obligation) — an omitted callee only makes the bundle LESS
            // complete (Unknown), never a fabricated proof.
            break;
        }

        // Trust #540 (R1 completeness #4 — mutual-recursion query-cycle safety): calling
        // `tcx.optimized_mir(callee)` on a callee that is part of a call CYCLE reachable back
        // into the already-`seen` closure (a MUTUAL-recursion SCC — e.g. an entry `E` calling
        // `ping`↔`pong`) forms an `optimized_mir` QUERY CYCLE (E0391: "optimizing MIR for ping …
        // requires optimizing MIR for pong … requires optimizing MIR for ping"), which HARD-
        // ABORTS compilation. That cycle is INDEPENDENT of R1 (it reproduces with
        // `-Ztrust-no-r1`),
        // but before R1 could prove recursive callees there was never a reason to bundle one. A
        // DIRECT self-call does NOT cycle `optimized_mir` (rustc handles single-fn self-recursion),
        // so it keeps the optimized body. For a MUTUAL-recursion callee we instead read the
        // NON-cycling elaborated-MIR snapshot (`mir_for_trust_verification` — the same MIR the
        // verifier already extracts everywhere at this seam, minus the opt pipeline that cycles).
        // `inner_optimized_mir` caches every mutual-recursion member's snapshot before stealing
        // its source, so this branch is independent of query order and never probes mutable
        // `Steal` state without doubling ordinary functions' MIR residency.
        // SOUND: the recursive callee's OWN safety obligations are separately verified on its own
        // `mir_keys` body (and R1 flips its bounds VC there); bundling the elaborated vs optimized
        // body only changes which faithful MIR of the SAME function the caller's panic-freedom
        // reasons over.
        // Trust: `optimized_mir_query_would_cycle` also covers live query ancestors outside
        // this closure's own `seen` path. Either signal routes the callee to the non-cycling
        // elaborated-MIR snapshot below.
        let cyclic = optimized_mir_query_would_cycle(tcx, callee_def_id);
        let callee_func = if cyclic {
            let Some(local) = callee_def_id.as_local() else { continue };
            let body = tcx.mir_for_trust_verification(local);
            // FAIL-SOFT: an unextractable callee is SKIPPED (its call sites
            // lower via the bridge's absent-callee may-panic marker) instead
            // of failing the whole bundle — less complete, never falsely
            // proved.
            let Ok(cf) = native_trust_ir_extract_callee_function(tcx, body) else {
                continue;
            };
            pending.extend(native_trust_ir_direct_local_fn_callees(tcx, body));
            cf
        } else {
            let callee_body = tcx.optimized_mir(callee_def_id);
            // FAIL-SOFT: skip unextractable callees (see the snapshot arm).
            let Ok(cf) = native_trust_ir_extract_callee_function(tcx, callee_body) else {
                continue;
            };
            pending.extend(native_trust_ir_direct_local_fn_callees(tcx, callee_body));
            cf
        };
        bundled.insert(callee_def_id);
        functions.push(callee_func);
    }

    Ok(functions)
}

fn native_trust_ir_extract_callee_function<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Result<trust_types::VerifiableFunction, String> {
    // The `trust_contracts` query is LOCAL-ONLY (its provider takes a
    // `LocalDefId`, so a non-local key `expect_local()`-panics). A bundled
    // CROSS-CRATE callee — e.g. an `#[automatically_derived]` `Clone` impl pulled
    // in to VERIFY `result.clone()` — has no Trust contracts, so extract it with
    // an empty bundle rather than querying contracts for a non-local def_id.
    let compiler_contracts = if body.source.def_id().is_local() {
        let empty_contracts = TrustContractBundle::empty(body.source.def_id());
        let rustc_contracts =
            trust_contracts_if_any(tcx, body.source.def_id()).unwrap_or(&empty_contracts);
        Some(trust_mir_extract::convert_trust_contract_bundle(tcx, rustc_contracts).map_err(
            |reason| {
                format!(
                    "unsupported compiler contract bundle for `{}`: {reason}",
                    trust_mir_extract::safe_def_path_str(tcx, body.source.def_id())
                )
            },
        )?)
    } else {
        None
    };
    let vf = trust_mir_extract::extract_function_with_contract_bundle(
        tcx,
        body,
        compiler_contracts.as_ref(),
    );
    Ok(vf)
}

/// True when `def_id` is an associated fn of an `#[automatically_derived]` impl —
/// i.e. a `#[derive(Clone/PartialEq/Default/…)]`-generated method. Such bodies are
/// compiler-generated and panic-free by construction, small, and bottom out at
/// primitive/std leaf calls. Bundling a CROSS-CRATE one (which `as_local()` would
/// otherwise skip) lets the native lowering VERIFY e.g.
/// `<trust_types::Formula as Clone>::clone` (reached from `result.clone()`) instead
/// of erroring "Call target not present", WITHOUT opening the callee closure to
/// arbitrary cross-crate functions — only derived impls qualify.
fn callee_is_automatically_derived_method(tcx: TyCtxt<'_>, def_id: DefId) -> bool {
    if !matches!(tcx.def_kind(def_id), DefKind::AssocFn) {
        return false;
    }
    let impl_def_id = tcx.parent(def_id);
    matches!(tcx.def_kind(impl_def_id), DefKind::Impl { .. })
        && tcx.is_automatically_derived(impl_def_id)
}

fn native_trust_ir_direct_local_fn_callees<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
) -> Vec<DefId> {
    let mut callees = Vec::new();
    let mut seen = FxHashSet::default();
    let typing_env = ty::TypingEnv::post_analysis(tcx, body.source.def_id());

    // Trust (R3 soundness guard, blueprint §5 / probe T5): PASS 1 — collect every
    // TRAIT-DECLARATION callee this body calls that `Instance::try_resolve` could
    // NOT resolve to a concrete instance (`Ok(None)`/`Err` — a still-generic
    // receiver, e.g. `<T as D>::m` in a polymorphic fn). Such a call's target is
    // instantiation-dependent: an impl may OVERRIDE the trait's default body with
    // a panicking one, so the default body may be bundled ONLY when the instance
    // RESOLVES to it (final/no-override is knowable only at mono). The set feeds
    // two skips in pass 2:
    //   (a) the unresolved call itself never falls back to bundling the
    //       syntactic trait-method def_id (whose default body has MIR); and
    //   (b) a SIBLING call in the same body that legitimately resolves to that
    //       same default body (concrete receiver, no override) is also not
    //       bundled — the bridge matches callees BY RENDERED NAME
    //       (`func_operand_name` = the generic def path), so bundling the body
    //       for the sibling would let the UNRESOLVED site match it too and be
    //       falsely proved against the wrong body (the mixed-case collision,
    //       probe T9).
    // Both skips route the affected call sites to the bridge's absent-callee
    // may-panic arm — fail-closed via the counted whole-function carrier.
    let mut unresolved_trait_decl_callees: FxHashSet<DefId> = FxHashSet::default();
    for block in body.basic_blocks.iter() {
        let (TerminatorKind::Call { func, .. } | TerminatorKind::TailCall { func, .. }) =
            &block.terminator().kind
        else {
            continue;
        };
        let Some((callee_def_id, gen_args)) = func.const_fn_def() else {
            continue;
        };
        if tcx.trait_of_assoc(callee_def_id).is_some()
            && !matches!(
                ty::Instance::try_resolve(tcx, typing_env, callee_def_id, gen_args),
                Ok(Some(_))
            )
        {
            unresolved_trait_decl_callees.insert(callee_def_id);
        }
    }

    for block in body.basic_blocks.iter() {
        let terminator = block.terminator();
        let (func, call_args) = match &terminator.kind {
            TerminatorKind::Call { func, args, .. }
            | TerminatorKind::TailCall { func, args, .. } => (func, args),
            _ => continue,
        };
        // HOF closure-invocation: a closure passed as a call ARG (e.g. `r.map_err(closure)`) is
        // DRIVEN by the callee. Bundle its (always-local) body so the bridge's HOF arm can emit a
        // real `Inst::Call` into it, making the closure's panic join the caller's verdict. Bounded
        // by the closure-callee cap on this collection; harmless when the call is not a HOF (the
        // body is then simply never invoked).
        for arg in call_args.iter() {
            let closure_def_id = match arg.node.ty(&body.local_decls, tcx).kind() {
                ty::Closure(did, _) => Some(*did),
                ty::Ref(_, inner, _) => match inner.kind() {
                    ty::Closure(did, _) => Some(*did),
                    _ => None,
                },
                _ => None,
            };
            if let Some(cdid) = closure_def_id {
                if tcx.is_mir_available(cdid) && seen.insert(cdid) {
                    callees.push(cdid);
                }
            }
        }
        // Resolve the callee to its concrete instance so a derived impl's field
        // call (`Clone::clone::<Inner>` — a non-local trait-method def_id carrying
        // a type arg) is captured as the impl `<Inner as Clone>::clone` and
        // bundled into the native callee closure (otherwise the bridge can't
        // resolve the call and the whole function is reported Unsupported). Falls
        // back to the syntactic def_id when the instance does not resolve.
        let Some((callee_def_id, gen_args)) = func.const_fn_def() else {
            continue;
        };
        // A provably-total derived trait call (`PartialEq`/`PartialOrd`/`Ord`/`Hash`/`Default`)
        // is SUMMARIZED to the total sentinel by `convert_terminator`, so it must NOT be pulled
        // into the bundle. Otherwise a generic std method like `Option<T>::hash` is bundled
        // POLYMORPHICALLY (its `optimized_mir` has `T` unbound) and the bundle then fails on the
        // unresolved `<T as Hash>::hash`. Skipping keeps the callee-closure consistent with the
        // call-site rewrite. SOUND: the SAME predicate proves it total (no `derived ⇒ total`
        // axiom — the receiver type is checked structurally, fail-closed for hand-written impls).
        if trust_mir_extract::is_total_derived_trait_call(tcx, callee_def_id, gen_args) {
            continue;
        }
        let resolved_def_id =
            match ty::Instance::try_resolve(tcx, typing_env, callee_def_id, gen_args) {
                Ok(Some(instance)) => instance.def_id(),
                // Trust (R3 soundness guard, probe T5): the instance did NOT
                // resolve. If the syntactic callee is a trait-declaration method,
                // do NOT fall back to bundling it: its default body (if any) is
                // only ONE possible target — an impl may override it with a
                // panicking body, and the caller's panic-freedom would be proved
                // against the wrong body (a false proof; probe T5b false-proved
                // `fn f<T: D>(t: &T) { t.m() }` against `D::m`'s default body on
                // the pre-guard compiler). Skipping keeps the call on the
                // absent-callee fail-closed arm.
                _ if tcx.trait_of_assoc(callee_def_id).is_some() => continue,
                _ => callee_def_id,
            };
        // Trust (R3 soundness guard, probe T9 — mixed-case collision): even a
        // RESOLVED default-body instance must not be bundled when this same body
        // ALSO calls the same trait method unresolved — the bridge matches
        // callees by rendered name, and both call sites render the trait method's
        // generic def path, so the bundled body would falsely serve the
        // unresolved site too. Completeness cost is narrow (only the co-located
        // resolved call loses its bundled proof) and fail-closed.
        if unresolved_trait_decl_callees.contains(&resolved_def_id) {
            continue;
        }
        if !tcx.is_mir_available(resolved_def_id) {
            continue;
        }
        // LOCAL callees always qualify. A CROSS-CRATE callee qualifies when it
        // is the method of an `#[automatically_derived]` impl with available
        // MIR (bundling its compiler-generated body VERIFIES the derived call
        // rather than assuming it), OR any other NON-STD callee whose MIR the
        // dep encoded (`#[inline]`/generic bodies of workspace siblings —
        // e.g. `aterm_sandbox::Limits::shell_default` called from aterm-pty):
        // an available cross-crate body is bundled and VERIFIED exactly like
        // a local one, so this adds proof surface, never an assumption. Std/
        // core/alloc stay excluded (hard-skipped by the verifier's std tier;
        // pulling their internals would only churn the bundle), and the
        // closure cap bounds growth either way. MIR availability was already
        // established above.
        if resolved_def_id.as_local().is_none()
            && !callee_is_automatically_derived_method(tcx, resolved_def_id)
            && {
                let krate = tcx.crate_name(resolved_def_id.krate);
                matches!(krate.as_str(), "std" | "core" | "alloc")
            }
        {
            continue;
        }
        if seen.insert(resolved_def_id) {
            callees.push(resolved_def_id);
        }
    }

    callees
}

/// Compact, stable adjacency provider for Trust's optimized-MIR cycle oracle.
/// The full elaborated body is borrowed only long enough to extract direct
/// local callees; the query result retains just `LocalDefId`s and is disk-cached.
pub(crate) fn trust_mir_direct_local_callees<'tcx>(
    tcx: TyCtxt<'tcx>,
    def_id: LocalDefId,
) -> &'tcx [LocalDefId] {
    // Trust: this borrow is unguarded BY CONSTRUCTION, and must stay that way. Its only caller is
    // the SCC builder below, whose node set now excludes every body without an `optimized_mir`
    // (i.e. `hir_body_const_context` outside `None | Some(ConstFn)`) — see the filter there. A
    // `#[rustc_comptime]` fn, whose elaborated MIR `inner_mir_for_ctfe` steals, is therefore never
    // passed to this query and the `Steal` cannot have been consumed.
    //
    // Do NOT "harden" this with `is_stolen()`. That call is documented as unusable inside rustc
    // (`rustc_data_structures/src/steal.rs`: "leaks information not tracked by the query system,
    // breaking incremental compilation") and this query is `cache_on_disk`, so it would make the
    // cached result depend on query order. And its natural fallback — an empty adjacency — is
    // anti-conservative here, because singleton components are discarded and `[]` therefore reads
    // as "known leaf" rather than "unknown". Exclude the node instead.
    let elaborated = tcx.mir_drops_elaborated_and_const_checked(def_id);
    let mut callees: Vec<LocalDefId> = {
        let body = elaborated.borrow();
        native_trust_ir_direct_local_fn_callees(tcx, &body)
            .into_iter()
            .filter_map(DefId::as_local)
            .filter(|&callee| !tcx.is_constructor(callee.to_def_id()))
            .collect()
    };
    callees.sort_unstable_by_key(|callee| callee.local_def_index.as_u32());
    callees.dedup_by_key(|callee| callee.local_def_index.as_u32());
    tcx.arena.alloc_from_iter(callees)
}

/// Compute every mutual-recursion SCC once for the crate. The result is sorted
/// by `DefIndex`, making the disk-cached value deterministic and membership a
/// binary search. This replaces the old per-root transitive BFS, whose aggregate
/// cost was quadratic on a long acyclic call chain.
pub(crate) fn trust_mir_mutually_recursive_functions<'tcx>(
    tcx: TyCtxt<'tcx>,
    (): (),
) -> &'tcx [LocalDefId] {
    let mut nodes: Vec<LocalDefId> = tcx
        .mir_keys(())
        .iter()
        .copied()
        .filter(|&def_id| {
            matches!(tcx.def_kind(def_id), DefKind::Fn | DefKind::AssocFn | DefKind::Closure)
                // Trust: a body with no `optimized_mir` cannot participate in an
                // `optimized_mir` query cycle, so it is not an SCC node. This excludes
                // `#[rustc_comptime]` fns, whose constness is `Const { always: true }` and which
                // therefore map to `ConstContext::Const` (`hir_body_const_context`,
                // `rustc_middle/src/hir/map.rs:346-365`) — so `inner_mir_for_ctfe` STEALS their
                // elaborated MIR rather than cloning it, as an ordinary `const fn` would.
                // `check_crate` eagerly evaluates non-generic const items before the whole-crate
                // verification walk runs, so by the time this graph is built the steal has already
                // happened and reading such a body would hard-ICE.
                //
                // Filtering here rather than guarding the borrow is deliberate. `Steal::is_stolen`
                // documents that it "should not be used within rustc as it leaks information not
                // tracked by the query system, breaking incremental compilation", and it carries
                // `#[rustc_lint_untracked_query_information]`. Both this adjacency provider and the
                // aggregate SCC query are `cache_on_disk`, so an `is_stolen()` branch would let
                // their cached output depend on query ORDER rather than on tracked inputs.
                // `hir_body_const_context` is a tracked query and has no such hazard.
                //
                // Equally important: an empty adjacency would be the WRONG fallback even setting
                // that aside. Singleton components are discarded below, so dropping a node's edges
                // SHRINKS the mutually-recursive set — `[]` reads as "known leaf", not "unknown".
                // That is anti-conservative: it suppresses the pre-steal snapshot taken only for
                // SCC members, makes `optimized_mir_query_would_cycle` answer false, and lets
                // sealed-dispatch analysis proceed where it would otherwise refuse.
                && matches!(
                    tcx.hir_body_const_context(def_id),
                    None | Some(rustc_hir::ConstContext::ConstFn)
                )
        })
        .collect();
    nodes.sort_unstable_by_key(|def_id| def_id.local_def_index.as_u32());

    let index_of: FxHashMap<LocalDefId, usize> =
        nodes.iter().enumerate().map(|(index, &def_id)| (def_id, index)).collect();
    let adjacency: Vec<Vec<usize>> = nodes
        .iter()
        .map(|&def_id| {
            tcx.trust_mir_direct_local_callees(def_id)
                .iter()
                .filter_map(|callee| index_of.get(callee).copied())
                .collect()
        })
        .collect();

    let mut recursive: Vec<LocalDefId> =
        mutually_recursive_node_indices(&adjacency).into_iter().map(|index| nodes[index]).collect();
    recursive.sort_unstable_by_key(|def_id| def_id.local_def_index.as_u32());
    tcx.arena.alloc_from_iter(recursive)
}

/// O(log N) lookup in the stable crate-wide mutual-SCC set.
pub(crate) fn trust_mir_is_mutually_recursive(tcx: TyCtxt<'_>, def_id: LocalDefId) -> bool {
    tcx.trust_mir_mutually_recursive_functions(())
        .binary_search_by_key(&def_id.local_def_index.as_u32(), |member| {
            member.local_def_index.as_u32()
        })
        .is_ok()
}

/// Iterative Tarjan SCC over a dense adjacency list. Only SCCs with two or
/// more members are returned: direct self recursion does not induce the
/// `optimized_mir` query cycle this oracle prevents.
fn mutually_recursive_node_indices(adjacency: &[Vec<usize>]) -> Vec<usize> {
    const UNVISITED: usize = usize::MAX;

    let node_count = adjacency.len();
    let mut discovery = vec![UNVISITED; node_count];
    let mut lowlink = vec![0usize; node_count];
    let mut on_scc_stack = vec![false; node_count];
    let mut scc_stack = Vec::new();
    let mut dfs_stack: Vec<(usize, usize)> = Vec::new();
    let mut next_discovery = 0usize;
    let mut mutually_recursive = Vec::new();

    for start in 0..node_count {
        if discovery[start] != UNVISITED {
            continue;
        }
        dfs_stack.push((start, 0));
        while let Some(&(node, successor_cursor)) = dfs_stack.last() {
            if successor_cursor == 0 && discovery[node] == UNVISITED {
                discovery[node] = next_discovery;
                lowlink[node] = next_discovery;
                next_discovery += 1;
                scc_stack.push(node);
                on_scc_stack[node] = true;
            }

            if successor_cursor < adjacency[node].len() {
                dfs_stack.last_mut().unwrap().1 += 1;
                let successor = adjacency[node][successor_cursor];
                if successor >= node_count {
                    continue;
                }
                if discovery[successor] == UNVISITED {
                    dfs_stack.push((successor, 0));
                } else if on_scc_stack[successor] {
                    lowlink[node] = lowlink[node].min(discovery[successor]);
                }
                continue;
            }

            if lowlink[node] == discovery[node] {
                let component_start = scc_stack.len();
                loop {
                    let member = scc_stack.pop().expect("Tarjan stack contains current node");
                    on_scc_stack[member] = false;
                    mutually_recursive.push(member);
                    if member == node {
                        break;
                    }
                }
                let component_len = component_start - scc_stack.len();
                if component_len == 1 {
                    mutually_recursive.pop();
                }
            }

            dfs_stack.pop();
            if let Some(&(parent, _)) = dfs_stack.last() {
                lowlink[parent] = lowlink[parent].min(lowlink[node]);
            }
        }
    }

    mutually_recursive.sort_unstable();
    mutually_recursive
}

fn ensure_default_trust_mc_function_obligation(
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
) -> Result<(), String> {
    let obligation_id = default_trust_mc_function_obligation_id(func);
    if bundle.obligations.iter().any(|obligation| obligation.obligation_id == obligation_id) {
        return Ok(());
    }

    let source_digest = if let Some(source_digest) = bundle
        .metadata
        .iter()
        .find(|entry| entry.key == TRUST_SOURCE_DIGEST_METADATA_KEY)
        .map(|entry| entry.value.clone())
    {
        source_digest
    } else {
        compiler_function_source_digest_hex(func)?
    };
    let predicate = trust_verifier_api::TrustSpecPredicate::new(
        trust_verifier_api::TrustSpecExpr::bool_literal(false),
        Vec::new(),
    );
    let payload = serde_json::to_string(&predicate).map_err(|error| {
        format!(
            "failed to serialize default trust-mc typed CHC predicate for `{}`: {error}",
            func.def_path
        )
    })?;
    let vc_digest = default_trust_mc_function_obligation_digest(func, &payload)?;
    let source = source_location_from_trust_span(&func.span);

    bundle.obligations.push(trust_verifier_api::TrustObligation {
        obligation_id,
        kind: trust_verifier_api::ObligationKind::ArithmeticSafety,
        contract_id: None,
        proof_item_id: None,
        source,
        description: "default trust-mc typed CHC function admission".to_string(),
        required_strength: None,
        summary_facts: Vec::new(),
        metadata: vec![
            trust_verifier_api::MetadataEntry {
                key: TRUST_MC_DEFAULT_FUNCTION_OBLIGATION_METADATA_KEY.to_string(),
                value: trust_verifier_api::TRUST_MC_DEFAULT_FUNCTION_OBLIGATION_METADATA_VALUE
                    .to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: "trust.vc.kind".to_string(),
                value: "trust_mc_default_function".to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_SOURCE_DIGEST_METADATA_KEY.to_string(),
                value: source_digest,
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_DIGEST_METADATA_KEY.to_string(),
                value: vc_digest,
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_FORMULA_SCHEMA_METADATA_KEY.to_string(),
                value: trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION.to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_FORMULA_SORT_METADATA_KEY.to_string(),
                value: "Bool".to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_FORMULA_SMTLIB_METADATA_KEY.to_string(),
                value: "false".to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY.to_string(),
                value: payload,
            },
            trust_verifier_api::MetadataEntry {
                key: "trust.vc.engine.trust-mc.formula_schema".to_string(),
                value: trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION.to_string(),
            },
        ],
    });
    Ok(())
}

fn default_trust_mc_function_obligation_id(func: &trust_types::VerifiableFunction) -> String {
    format!(
        "vc:{}:trust_mc_default_function:0",
        trust_types::canonical_artifact_id_component(&func.def_path)
    )
}

fn source_location_from_trust_span(
    span: &trust_types::SourceSpan,
) -> trust_verifier_api::SourceLocation {
    trust_verifier_api::SourceLocation {
        file: (!span.file.is_empty()).then(|| span.file.clone()),
        line: (span.line_start != 0).then_some(span.line_start),
        column: (span.col_start != 0).then_some(span.col_start),
        end_line: (span.line_end != 0).then_some(span.line_end),
        end_column: (span.col_end != 0).then_some(span.col_end),
    }
}

fn domain_length_bound_sha256_hex(domain: &str, payload: &[u8]) -> String {
    let mut framed = Vec::with_capacity(
        "trustc.digest-frame.v1"
            .len()
            .saturating_add(8)
            .saturating_add(domain.len())
            .saturating_add(8)
            .saturating_add(payload.len()),
    );
    framed.extend_from_slice(b"trustc.digest-frame.v1");
    framed.extend_from_slice(&(domain.len() as u64).to_be_bytes());
    framed.extend_from_slice(domain.as_bytes());
    framed.extend_from_slice(&(payload.len() as u64).to_be_bytes());
    framed.extend_from_slice(payload);
    trust_types::stable_sha256_hex(&framed)
}

fn compiler_function_source_digest_hex(
    func: &trust_types::VerifiableFunction,
) -> Result<String, String> {
    let bytes = serde_json::to_vec(func).map_err(|error| {
        format!(
            "failed to serialize compiler function `{}` for its exact source digest: {error}",
            func.def_path
        )
    })?;
    Ok(domain_length_bound_sha256_hex("trustc.compiler-function-source.v1", &bytes))
}

fn default_trust_mc_function_obligation_digest(
    func: &trust_types::VerifiableFunction,
    payload: &str,
) -> Result<String, String> {
    let material = serde_json::json!({
        "schema": "trustc.default-trust-mc-function-obligation-digest.v1",
        "function": func.def_path,
        "span": func.span,
        "payload": payload,
    });
    let bytes = serde_json::to_vec(&canonical_json_value(&material)).map_err(|error| {
        format!(
            "failed to serialize default trust-mc obligation digest material for `{}`: {error}",
            func.def_path
        )
    })?;
    Ok(domain_length_bound_sha256_hex("trustc.default-trust-mc-function-obligation.v2", &bytes))
}

fn native_trust_ir_function_id(
    module: &trust_ir::Module,
    func: &trust_types::VerifiableFunction,
) -> Result<trust_ir::FuncId, String> {
    module
        .functions
        .iter()
        .find(|function| function.name == func.name || function.name == func.def_path)
        .map(|function| function.id)
        .ok_or_else(|| {
            if module.functions.is_empty() {
                return format!("typed TrustIr lowering for `{}` produced no functions", func.def_path);
            }
            let lowered = module
                .functions
                .iter()
                .map(|function| function.name.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            format!(
                "typed TrustIr lowering for `{}` did not produce a matching function; lowered functions: {lowered}",
                func.def_path
            )
        })
}

/// Surface whole-function panic-freedom as a counted public `Assertion`
/// obligation when a user `assert!` / `unreachable!` has no public verifier-api
/// twin.
///
/// A function whose only proof obligation is a user `assert!` / `unreachable!`
/// (no arithmetic, bounds, or contract VC) produces an empty public bundle: the
/// panic site lives only as a native `PanicFreedom` obligation in
/// `module.proof_obligations`. With nothing public to count, the full verifier
/// hits the `summary.total == 0` skipped guard and fails closed.
///
/// This pushes ONE public `Assertion` obligation (tagged
/// [`TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY`] for diagnostics) carrying
/// proof-grade digests but NO typed-CHC formula. With no formula the direct
/// typed-CHC lowering is `Unsupported`, so the trust-mc adapter falls back to the
/// path-sensitive transport CHC/PDR solve over the full native bundle — exactly
/// the fallback arithmetic obligations use. The transport translates every
/// `Inst::Assert` into a semantic `error`-reachability rule
/// (`add_error_rule(¬cond)` under the path constraints, joins resolved through
/// SSA block params) and proves `error` unreachable — i.e. no panic /
/// `unreachable!` / assert-fail is reachable, over the full control-flow graph.
/// The bridge's whole-function assertion supplies the exact source span, but it
/// is deliberately not exposed as a `proof_item_id`: bridge-local proof rows are
/// removed at the public-inventory boundary and therefore cannot authorize a
/// public proof-item reference. The public obligation ID is the native source
/// identity, and its typed source embeds the obligation's canonical semantic
/// digest. Unlike the default admission, the verdict is COUNTED, so the proof
/// gates the public result. No new trust assumption is introduced.
///
/// Synthesis fires for every function with the bridge's whole-function panic
/// aggregate, including functions that also have arithmetic, bounds, or contract
/// obligations. Restricting this to otherwise-empty bundles dropped the panic
/// disjunct whenever an incidental public VC was present and could therefore
/// verify a reachable panic vacuously. The exact public identity and deduplication
/// below keep this one counted row per panic-bearing function. The obligation set
/// is monotone: adding a contract, loop, or resource VC must never suppress the L0
/// whole-function panic-freedom row.
fn synthesize_native_panic_freedom_to_verifier_api_obligations(
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    module: &trust_ir::Module,
    panic_source_function_paths: &FxHashSet<String>,
) -> Result<(), String> {
    // SOUNDNESS (dropped-panic-disjunct false proof): surface the COUNTED
    // whole-function panic-freedom obligation for EVERY function that has a
    // bridge-level panic site (the `mir-assertions:…:panic-freedom` obligation
    // located below), NOT only empty-bundle "pure-panic" functions.
    //
    // The previous restriction (`any(!is_default_admission()) → return`, fire only
    // when the public bundle is otherwise empty) left a soundness gap: a function
    // carrying an INCIDENTAL non-panic obligation — e.g. the `let da = match a {…}`
    // exhaustive-enum reachability / discriminant VCs — had its whole-function
    // panic-freedom check SUPPRESSED. A no-return `panic!()` Call is ONLY ever
    // checked by this whole-function obligation (it never becomes a counted
    // per-obligation VC on the direct lane), so suppressing it dropped the only
    // check: a genuinely-reachable panic guarded by an enum-discriminant comparison
    // (`if disc(a) != disc(b) { panic!() }`, w01/w13/w16/w19) was vacuously PROVED.
    //
    // Monotone-sound: this only ADDS a counted obligation, so a verdict can move
    // PROVED → UNKNOWN/REFUTED, never the reverse — no previously-refuted case can
    // become proved, and a genuinely-panic-free function still proves (the transport
    // CHC over the full CFG is UNSAT). The early-return below (no panic-freedom
    // obligation present) limits this to panic-bearing functions, and the dedup
    // guard keeps it idempotent. Control proof: `discriminant(a) != discriminant(b)`
    // panic has an empty bundle, already surfaces this obligation today, and is
    // correctly INCONCLUSIVE — the transport path handles this exact family.

    // Locate the bridge's function-level panic-freedom obligation
    // (`mir-assertions:{def_path}:panic-freedom`, suffix-free `assertion_id`).
    let mut function_level_source_id: Option<String> = None;
    for obligation in &module.proof_obligations {
        if obligation.kind != trust_ir::ObligationKind::PanicFreedom {
            continue;
        }
        let Some(formula) = obligation.formula.as_ref() else {
            continue;
        };
        let Ok(payload) = serde_json::from_str::<serde_json::Value>(&formula.payload) else {
            continue;
        };
        let Some(source_id) = payload.get("source_id").and_then(|value| value.as_str()) else {
            continue;
        };
        if let Some(remainder) = source_id.strip_prefix("mir-assertions:") {
            let Some(function_path) = remainder.strip_suffix(":panic-freedom") else {
                return Err(format!(
                    "native panic-freedom source `{source_id}` did not use the exact compiler aggregate schema"
                ));
            };
            if function_path.is_empty() || !panic_source_function_paths.contains(function_path) {
                return Err(format!(
                    "native panic-freedom source `{source_id}` was not owned by the compiler-held target/callee inventory"
                ));
            }
            function_level_source_id.get_or_insert_with(|| source_id.to_string());
        }
    }

    let Some(function_level_source_id) = function_level_source_id else {
        return Ok(());
    };
    // Trust (assumption ledger, W3.5): if the bridge lowered a print/format/write
    // DISPATCH call, it raised a `PanicFreedom` obligation whose description is stamped
    // with `EXTERN_CALL_ASSUMPTION_PREFIX` (see `extern_fmt_dispatch_call`). Carry that
    // marked description onto THIS synthesized whole-function panic-freedom obligation,
    // so the reconstructed transport row (`VcKind::Assertion { message }`) still carries
    // the marker and names the dispatch callee — letting the authenticated memory-safe
    // no-unsafe policy demote the resulting UNKNOWN row to `assumption:extern-call`.
    // The whole-function catch-all
    // goes UNKNOWN via the dispatch's in-body `Assert(false)+NoPanic` marker anyway; we
    // only enrich its description. The prefix is marker-free, so the strict lane's row
    // text does not trip targo's `is_full_verifier_text` (it never demotes there).
    let extern_call_description = module
        .proof_obligations
        .iter()
        .find(|obligation| {
            obligation.kind == trust_ir::ObligationKind::PanicFreedom
                && (obligation
                    .description
                    .starts_with(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
                    || obligation
                        .description
                        .starts_with(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
                    || obligation.description.starts_with(
                        trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX,
                    )
                    || obligation
                        .description
                        .starts_with(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX))
        })
        // An assumed-total marker may label the aggregate only when no fatal,
        // strict-fatal, or policy-gated marker exists. This prevents one
        // audited callee from masking an unrelated absent/drop gap.
        .or_else(|| {
            module.proof_obligations.iter().find(|obligation| {
                obligation.kind == trust_ir::ObligationKind::PanicFreedom
                    && obligation.description.starts_with(
                        trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX,
                    )
            })
        })
        .map(|obligation| obligation.description.clone());

    let obligation_id = format!(
        "vc:{}:assertion:panic-freedom:0",
        trust_types::canonical_artifact_id_component(&func.def_path)
    );
    // The source row that triggered the aggregate may belong to a reachable
    // local callee. The one public aggregate is nevertheless the target
    // function's claim, so its diagnostics and identity use the target span.
    let source = source_location_from_trust_span(&func.span);

    // Proof-grade digests. The obligation carries NO typed-CHC formula metadata
    // and no public contract: `TrustMcVerifierApiAdapter` therefore declines the
    // direct per-VC path and defers this row to `NativeTrustIrChcPdrRunner`, whose
    // path-sensitive translation consumes the full typed module (`Inst::Assert`,
    // SSA block parameters, and control-flow guards). The source-only replay atom
    // remains an identity/span witness; it is not the predicate being proved.
    let digest_seed = format!("panic-freedom:{}", func.def_path);
    // This aggregate is a claim about one exact function. Creation and
    // recognition therefore share the compiler-held per-function digest;
    // inheriting a bundle-level extract-time digest after `func` was enriched
    // makes the two authorities diverge and demotes valid proofs to Unknown.
    let source_digest = compiler_function_source_digest_hex(func)?;
    let vc_digest = default_trust_mc_function_obligation_digest(func, &digest_seed)?;

    let function_context = match &bundle.subject {
        trust_verifier_api::BundleSubject::Function { crate_name, path }
            if !crate_name.trim().is_empty() && path == &func.def_path =>
        {
            trust_verifier_api::FunctionContext {
                crate_name: crate_name.clone(),
                path: path.clone(),
            }
        }
        _ => {
            return Err(format!(
                "cannot bind synthesized panic-freedom obligation for `{}` to an exact bundle subject",
                func.def_path
            ));
        }
    };

    let mut metadata = Vec::new();
    if let Ok(context_entry) = trust_verifier_api::ObligationContext::new(
        trust_verifier_api::ObligationProducer::CompilerMirExtract,
        trust_verifier_api::ObligationOrigin::VerificationCondition {
            vc_kind: "panic_freedom".to_string(),
            vc_index: 0,
            formula_schema: None,
        },
    )
    .with_function(function_context)
    .to_metadata_entry()
    {
        metadata.push(context_entry);
    }
    metadata.extend([
        trust_verifier_api::MetadataEntry {
            key: TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY.to_string(),
            value: "enabled".to_string(),
        },
        trust_verifier_api::MetadataEntry {
            key: "trust.vc.kind".to_string(),
            value: "panic_freedom".to_string(),
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_SOURCE_DIGEST_METADATA_KEY.to_string(),
            value: source_digest,
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_VC_DIGEST_METADATA_KEY.to_string(),
            value: vc_digest,
        },
    ]);
    if env_flag_enabled("TRUST_NATIVE_DEBUG") {
        eprintln!(
            "[NATIVE_PANIC_SURFACE] fn={} surfaced counted panic-freedom obligation {} (function-level {})",
            func.def_path, obligation_id, function_level_source_id
        );
    }

    let synthesized = trust_verifier_api::TrustObligation {
        obligation_id,
        kind: trust_verifier_api::ObligationKind::Assertion,
        contract_id: None,
        // The bridge-local assertion is intentionally not a public proof item.
        // Referencing it here leaves a dangling proof_item_id after the private
        // proof inventory is reset and makes canonical public digesting fail.
        proof_item_id: None,
        source,
        description: extern_call_description.unwrap_or_else(|| {
            "panic freedom: no assertion, `unreachable!`, or panic is reachable".to_string()
        }),
        required_strength: None,
        summary_facts: Vec::new(),
        metadata,
    };
    if let Some(existing) = bundle
        .obligations
        .iter()
        .find(|obligation| obligation.obligation_id == synthesized.obligation_id)
    {
        if existing == &synthesized {
            return Ok(());
        }
        return Err(format!(
            "compiler synthesized panic-freedom identity `{}` collided with a different public obligation",
            synthesized.obligation_id
        ));
    }
    bundle.obligations.push(synthesized);
    Ok(())
}

fn append_verifier_api_obligations_to_native_trust_ir(
    module: &mut trust_ir::Module,
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    function_id: trust_ir::FuncId,
    all_vcs: &[VerificationCondition],
) -> Result<Vec<PendingNativeTrustIrBinding>, String> {
    reset_native_trust_ir_proof_inventory_to_public_bundle(module);
    let mut next_proof_id = 0;
    // Freeze exact compiler-owned source bindings before this planner adds any
    // transport annotations. A public row can nominate a VC index, but only a
    // byte-semantic match to the fresh mir-extract identity may consume that
    // compiler-private VC. Duplicate rows make the index ambiguous and disable
    // the optimization for every copy.
    let planning_vc_indices = exact_native_planning_vc_indices(func, bundle, all_vcs);

    let mut bindings = Vec::new();
    for obligation_index in 0..bundle.obligations.len() {
        let Some((verifier_suite, trust_ir_kind)) =
            native_trust_ir_route_for_api_obligation(&bundle.obligations[obligation_index])
        else {
            continue;
        };
        if verifier_suite.eq_ignore_ascii_case("trust-mc") {
            annotate_trust_mc_typed_chc_lowering_status(&mut bundle.obligations[obligation_index]);
        }

        let proof_obligation_id = trust_ir::ProofId::new(next_proof_id);
        if verifier_suite.eq_ignore_ascii_case("trust-vc") {
            // Trust (tip reconciliation: sealed-authority S2/S3 x recognizer
            // strategy): under 20a96aeac02 the trust-ir bundle admits proof only
            // from REPLAYED evidence — the imported trust-vc certificate is an
            // opaque Alethe `SmtProof` no in-process validator can replay, so a
            // SUCCESSFUL import now fail-closes the WHOLE native bundle
            // (`TrustVcCertificateNotDischarged`), even when the obligation is
            // independently provable by the clean CIC kernel. trust-vc
            // deliberately has no Clean replay bridge (owner decision: per-shape
            // trust-certify recognizers ARE the coverage strategy), so the
            // reconciliation is a planning-time exclusion: when the narrowly
            // bounded unsigned-BV-order recognizer certifies this obligation's
            // own source VC with the SAME zero-trust kernel authority that the
            // post-solve path rechecks, the obligation does not need the
            // trust-vc lane at all. Keep it OUT of the native
            // module (mirroring the `Unavailable` arm) so its unreplayable
            // certificate is never attached and, when nothing else routes to
            // trust-vc, no trust-vc request is planned; the legacy bridge lane
            // then re-proves it and the kernel re-certifies it into the
            // transport row's CleanCic authority. The general certifier is
            // deliberately NOT called here: it can exceed the function budget
            // inside one non-preemptible kernel walk. The planning API caps its
            // input/work before normalization and admits only this small shape.
            // FAIL-CLOSED: `Some` still means kernel-rechecked UNSAT; any size,
            // shape, identity, multiplicity, or kernel doubt keeps today's
            // conservative behavior.
            if let Some(vc) = planning_vc_indices
                .get(obligation_index)
                .copied()
                .flatten()
                .and_then(|index| all_vcs.get(index))
                && trust_certify::certify_vc_for_native_planning(vc).is_some()
            {
                if env_flag_enabled("TRUST_NATIVE_DEBUG") {
                    eprintln!(
                        "[TRUST_VC_IMPORT] obl={} KERNEL-CERTIFIED (clean CIC kernel certifies the source VC; excluded from the native trust-vc lane)",
                        bundle.obligations[obligation_index].obligation_id
                    );
                }
                annotate_kernel_certified_trust_vc_native_trust_ir_exclusion(
                    &mut bundle.obligations[obligation_index],
                );
                continue;
            }
            match trust_vc_native_trust_ir_certificate_import(&bundle.obligations[obligation_index])
            {
                TrustVcNativeTrustIrCertificateImport::Unavailable { status, reason } => {
                    if env_flag_enabled("TRUST_NATIVE_DEBUG") {
                        eprintln!(
                            "[TRUST_VC_IMPORT] obl={} UNAVAILABLE ({status}): {reason}",
                            bundle.obligations[obligation_index].obligation_id
                        );
                    }
                    annotate_unsupported_trust_vc_native_trust_ir_import(
                        &mut bundle.obligations[obligation_index],
                        status,
                        reason,
                    );
                    continue;
                }
                // Trust: trust-vc refuted the obligation. A refutation is NOT a
                // proof binding, so we don't push a certificate (like
                // `Unavailable`, this `continue`s). Unlike `Unavailable`, we
                // record the refutation on the obligation via the
                // `trust.vc.refuted` metadata key so the bundle→results mapping
                // (`full_verification_legacy_result_for_obligation`) maps it to
                // `VerificationResult::Failed` under `-full` instead of Unknown.
                TrustVcNativeTrustIrCertificateImport::Refuted { counterexample } => {
                    if env_flag_enabled("TRUST_NATIVE_DEBUG") {
                        eprintln!(
                            "[TRUST_VC_IMPORT] obl={} REFUTED ({})",
                            bundle.obligations[obligation_index].obligation_id,
                            counterexample.as_deref().unwrap_or("<no model>")
                        );
                    }
                    set_obligation_metadata(
                        &mut bundle.obligations[obligation_index],
                        TRUST_VC_REFUTED_METADATA_KEY,
                        counterexample.unwrap_or_else(|| "1".to_string()),
                    );
                    continue;
                }
                TrustVcNativeTrustIrCertificateImport::NotApplicable => {}
            }
        }
        next_proof_id = next_proof_id.saturating_add(1);
        let obligation = &bundle.obligations[obligation_index];
        module.proof_obligations.push(
            trust_ir::ProofObligation::new(
                proof_obligation_id,
                trust_ir_kind,
                // Every request this planner mints is a CLAIM, never a discharge.
                // The module is sealed into its request/replay identity below and
                // the router runs afterwards, so no evidence this compilation
                // produces can reach the module it is asked to verify — the
                // kernel-checked CleanCic term lands on the transport report row
                // instead. A `Discharged` status here would assert a proof the
                // module does not carry.
                trust_ir::ProofStatus::Pending,
                format!(
                    "{} (public verifier obligation {})",
                    obligation.description, obligation.obligation_id
                ),
            )
            .with_formula(native_trust_ir_obligation_source_formula(obligation))
            .with_function(function_id),
        );
        bindings.push(PendingNativeTrustIrBinding {
            obligation_index,
            verifier_suite,
            proof_obligation_id,
        });
    }

    // The public inventory this planner just built is the whole proof inventory
    // the module carries across the sealing boundary, and it is claims-only.
    // A certificate reaching the module here would be pre-discharge: authority
    // asserted before any verifier ran, inside the very artifact whose digest
    // authorizes the request. Refuse the function rather than ship the claim —
    // fail-closed costs a compatibility-lane fallback, the alternative is a
    // module that says `Discharged` on nobody's evidence.
    if !module.proof_certificates.is_empty() {
        return Err(format!(
            "native TrustIr module for `{}` carries {} pre-discharge proof certificate(s); the \
             compiler mints proof CLAIMS only",
            func.def_path,
            module.proof_certificates.len(),
        ));
    }

    Ok(bindings)
}

/// Replace the MIR compatibility bridge's private proof inventory before
/// binding the compiler's public verifier obligations.
///
/// The bridge obligations are useful while lowering: in particular,
/// [`synthesize_native_panic_freedom_to_verifier_api_obligations`] reads the
/// bridge's whole-function panic obligation immediately before this boundary.
/// They are not, however, independent public proof units. Retaining them while
/// appending `bundle.obligations` creates duplicate/hidden native requests and
/// leaves the bridge rows without the exact `public_obligation_id` required by
/// replay and result reconciliation. It can also let an old numeric `ProofId`
/// reference accidentally bind a newly-created public row.
///
/// From this point onward the verifier-api bundle is the sole proof inventory.
/// Drop every side table and back-reference tied to the bridge-local IDs, while
/// preserving semantic instruction/function annotations (`NoOverflow`,
/// `NoPanic`, `Wrapping`, and so on) and the lowered executable IR itself.
fn reset_native_trust_ir_proof_inventory_to_public_bundle(module: &mut trust_ir::Module) {
    module.proof_obligations.clear();
    module.proof_certificates.clear();
    module.obligation_diagnostics.clear();

    for function in &mut module.functions {
        if let Some(summary) = &mut function.summary {
            // `proved` is proof authority even though it carries no numeric
            // `ProofId`; it cannot outlive the inventory that established it.
            summary.proved = false;
        }
        function
            .proofs
            .retain(|annotation| !matches!(annotation, trust_ir::ProofAnnotation::ProofRef(_)));
        for block in &mut function.blocks {
            for node in &mut block.body {
                node.proofs.retain(|annotation| {
                    !matches!(annotation, trust_ir::ProofAnnotation::ProofRef(_))
                });
                node.proof_context = None;
            }
        }
    }
}

/// What the planner learns about a trust-vc-routed obligation before the native
/// module is sealed. Deliberately WITHOUT a proof-bearing variant.
///
/// Two independent constraints make pre-discharge unrepresentable here, and both
/// are load-bearing rather than incidental:
///
/// * Under the sealed-authority reconciliation the native bundle admits proof
///   only from REPLAYED evidence. trust-vc's release-admissible artifact is an
///   opaque Alethe `SmtProof` no in-process validator can replay, so a
///   *successful* import would fail-close the whole bundle
///   (`TrustVcCertificateNotDischarged`) — importing evidence here is not merely
///   unused, it is strictly worse than declining.
/// * The only proof term Trust actually mints that a consumer could re-check is
///   the clean-kernel `CleanCic` certificate, and it is produced by the router
///   AFTER this module is frozen into its digest/lineage/replay identity. It
///   therefore ships on the transport report row, which is re-derivable and
///   content-addressed, not in the module the router was handed.
///
/// Keeping the enum proof-free makes "this seam cannot grant proof authority" a
/// property of the type rather than of three runtime assertions. Reopening it
/// means designing the re-mint: a module rebuilt after discharge, with a fresh
/// identity, whose every certificate the consumer independently kernel-rechecks
/// before it may shorten a request.
enum TrustVcNativeTrustIrCertificateImport {
    Unavailable {
        status: &'static str,
        reason: String,
    },
    // Trust: trust-vc refuted the obligation with a genuine counterexample (e.g.
    // `s[i % 9]` OOB at `i = 8`). Unlike `Unavailable` (a coverage gap → Unknown),
    // a refutation must drive the obligation to `Failed` under `-full`.
    //
    // Kept, unlike the deleted proof-bearing variant, because it points the other
    // way: this classifier declines to SOLVE (solving here would run outside the
    // router's per-function deadline), so it mints no refutation today, but the
    // consumer that turns the marker into `Failed`
    // (`full_verification_legacy_result_for_obligation`) is live and covered.
    // A carrier whose only effect is to fail an obligation closed cannot become a
    // false proof; removing it would delete the safety-direction half of the seam
    // while leaving the mapping it feeds.
    #[allow(dead_code)]
    Refuted {
        counterexample: Option<String>,
    },
    NotApplicable,
}

fn trust_vc_native_trust_ir_certificate_import(
    obligation: &trust_verifier_api::TrustObligation,
) -> TrustVcNativeTrustIrCertificateImport {
    // Trust: BoundsCheck is trust-vc-owned (it routes to the trust-vc suite in
    // native_trust_ir_route_for_api_obligation). Returning NotApplicable here
    // let bounds obligations into the native module as Pending WITHOUT a
    // certificate, and validate_trust_vc_request then failed the whole bundle
    // (MissingTrustVcEvidenceForObligation). With BoundsCheck matched, a
    // payload-less or unprovable obligation returns Unavailable instead —
    // annotated and EXCLUDED per-obligation, falling closed to the bridge
    // without poisoning the rest of the function.
    if !matches!(
        obligation.kind,
        trust_verifier_api::ObligationKind::MemorySafety
            | trust_verifier_api::ObligationKind::Ownership
            | trust_verifier_api::ObligationKind::BoundsCheck
    ) {
        return TrustVcNativeTrustIrCertificateImport::NotApplicable;
    }

    let has_proof_unit_metadata = obligation
        .metadata
        .iter()
        .any(|entry| entry.key == TRUST_VC_MIR_MEMORY_PROOF_UNIT_METADATA_KEY);
    if !has_proof_unit_metadata {
        return TrustVcNativeTrustIrCertificateImport::Unavailable {
            status: "unsupported",
            reason: format!(
                "trust-vc native TrustIr proof-certificate import unsupported: missing `{TRUST_VC_MIR_MEMORY_PROOF_UNIT_METADATA_KEY}` replayable proof-unit metadata"
            ),
        };
    }

    // Do not solve here. This compiler construction runs outside the router's
    // per-function deadline and would duplicate the same TrustVC work. Validate
    // the exact structured carrier only, then let the deadline-aware genuine
    // in-process adapter produce either proof or typed refutation evidence.
    match trust_vc_bridge::trust_vc_validate_structured_direct_mir_memory_obligation_metadata(
        obligation,
    ) {
        Ok(true) => TrustVcNativeTrustIrCertificateImport::Unavailable {
            status: "deferred",
            reason: trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_DEFERRED_REASON.to_string(),
        },
        Ok(false) => TrustVcNativeTrustIrCertificateImport::Unavailable {
            status: "unsupported",
            reason: format!(
                "trust-vc native TrustIr proof-certificate import unsupported: `{TRUST_VC_MIR_MEMORY_PROOF_UNIT_METADATA_KEY}` did not contain an exact structured proof unit"
            ),
        },
        Err(error) => {
            trace!(
                obligation_id = obligation.obligation_id.as_str(),
                reason = %error,
                "rejecting trust-vc MIR memory proof-unit transport before deadline-aware verification"
            );
            TrustVcNativeTrustIrCertificateImport::Unavailable {
                status: "rejected",
                reason: format!(
                    "trust-vc structured MIR-memory proof-unit transport rejected: {error}"
                ),
            }
        }
    }
}

/// Trust (sealed-authority reconciliation): bind each public planning row to
/// the exact fresh compiler VC that mir-extract minted it from. The shared
/// fresh-context matcher re-derives the function/display-crate context,
/// canonical id and kind, complete source span, formula schema/payload, source
/// and VC digests, required strength, and all verifier-specific metadata
/// families.
/// Merely copying `vc_index`, a description, and a source location is never
/// sufficient. This guarded-index family is not contract-derived, so any
/// contract id or source-contract link also declines. Multiplicity is part of
/// the authority boundary: zero or two matches both yield `None` and retain the
/// conservative TrustVC lane.
/// This planning-only exclusion is not a compiler-crate proof capability:
/// `kernel_certified` metadata cannot grant a verdict, and the later fresh-VC
/// snapshot separately authenticates the stable crate-instance envelope before
/// any result is re-keyed onto compiler VCs.
fn exact_native_planning_vc_indices(
    func: &trust_types::VerifiableFunction,
    bundle: &trust_verifier_api::TrustContractBundle,
    all_vcs: &[VerificationCondition],
) -> Vec<Option<usize>> {
    let (crate_name, path) = match &bundle.subject {
        trust_verifier_api::BundleSubject::Function { crate_name, path } => {
            (crate_name.as_str(), path.as_str())
        }
        _ => return vec![None; bundle.obligations.len()],
    };
    if crate_name.trim().is_empty() || path != func.def_path {
        return vec![None; bundle.obligations.len()];
    }
    const MAX_PLANNING_ROW_METADATA_ENTRIES: usize = 64;
    const MAX_PLANNING_ROW_METADATA_BYTES: usize = 256 * 1024;
    const MAX_PLANNING_CONTEXT_BYTES: usize = 16 * 1024;

    // Full fresh-identity reconstruction renders formulas and proof-unit
    // payloads. Gate it behind the certifier's cheap iterative shape/work
    // preflight so an unrelated giant VC can never enter those recursive
    // builders merely because it carries a public VC-origin row.
    let bounded_candidate_index = |obligation: &trust_verifier_api::TrustObligation| {
        if obligation.kind != trust_verifier_api::ObligationKind::BoundsCheck
            || obligation.contract_id.is_some()
            || obligation.metadata.len() > MAX_PLANNING_ROW_METADATA_ENTRIES
            || obligation.metadata.iter().any(|entry| {
                matches!(
                    entry.key.as_str(),
                    TRUST_VC_SOURCE_CONTRACT_INDEX_METADATA_KEY
                        | TRUST_CONTRACT_PREDICATE_DIGEST_METADATA_KEY
                        | TRUST_VC_SOURCE_CONTRACT_ROLE_METADATA_KEY
                )
            })
        {
            return None;
        }
        let metadata_bytes = obligation.metadata.iter().try_fold(0usize, |total, entry| {
            total.checked_add(entry.key.len())?.checked_add(entry.value.len())
        })?;
        if metadata_bytes > MAX_PLANNING_ROW_METADATA_BYTES {
            return None;
        }
        let mut contexts = obligation
            .metadata
            .iter()
            .filter(|entry| entry.key == trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY);
        let context_entry = contexts.next()?;
        if contexts.next().is_some() || context_entry.value.len() > MAX_PLANNING_CONTEXT_BYTES {
            return None;
        }
        let context =
            trust_verifier_api::ObligationContext::from_metadata_entry(context_entry).ok()??;
        if !context.has_current_schema()
            || !matches!(
                context.producer,
                trust_verifier_api::ObligationProducer::CompilerMirExtract
            )
        {
            return None;
        }
        let trust_verifier_api::ObligationOrigin::VerificationCondition { vc_index, .. } =
            context.origin
        else {
            return None;
        };
        let vc = all_vcs.get(vc_index)?;
        trust_certify::vc_fits_native_planning_certification_budget(vc).then_some(vc_index)
    };
    let bounded_candidates =
        bundle.obligations.iter().map(bounded_candidate_index).collect::<Vec<_>>();
    if bounded_candidates.iter().all(Option::is_none) {
        return bounded_candidates;
    }
    let source_digest = trust_mir_extract::verifier_source_digest(func);
    let candidate_indices = bundle
        .obligations
        .iter()
        .zip(bounded_candidates)
        .map(|(obligation, bounded_index)| {
            let bounded_index = bounded_index?;
            let exact_index =
                exact_fresh_vc_index_for_obligation_with_source_digest_and_crate_name(
                    func,
                    obligation,
                    all_vcs,
                    &source_digest,
                    Some(crate_name),
                )?;
            (exact_index == bounded_index).then_some(exact_index)
        })
        .collect::<Vec<_>>();
    let mut multiplicity = FxHashMap::default();
    for index in candidate_indices.iter().flatten() {
        *multiplicity.entry(*index).or_insert(0usize) += 1;
    }
    candidate_indices
        .into_iter()
        .map(|candidate| candidate.filter(|index| multiplicity.get(index) == Some(&1)))
        .collect()
}

/// Trust (sealed-authority reconciliation): mark a trust-vc-routed obligation
/// that the clean CIC kernel certified at planning time and that was therefore
/// EXCLUDED from the native module/trust-vc request. Mirrors the `Unavailable`
/// annotation shape (suite + transport status) so downstream transport
/// classifiers see one structured row; the distinct `kernel_certified` status
/// is deliberately outside the warning statuses (`unsupported`/`rejected`) —
/// the obligation is on its way to a kernel-certified `Proved`, not a gap —
/// and the `unsupported_reason` key is deliberately NOT set (reason-presence
/// classifiers, e.g. the benchmark unsupported-row detector, must not count a
/// kernel-certified row as a coverage gap).
fn annotate_kernel_certified_trust_vc_native_trust_ir_exclusion(
    obligation: &mut trust_verifier_api::TrustObligation,
) {
    set_obligation_metadata(
        obligation,
        trust_router::full_verification::TRUST_TRUST_IR_NATIVE_VERIFIER_SUITE_METADATA_KEY,
        "trust-vc".to_string(),
    );
    set_obligation_metadata(
        obligation,
        TRUST_TRUST_IR_NATIVE_TRANSPORT_STATUS_METADATA_KEY,
        "kernel_certified".to_string(),
    );
}

fn annotate_unsupported_trust_vc_native_trust_ir_import(
    obligation: &mut trust_verifier_api::TrustObligation,
    status: &'static str,
    reason: String,
) {
    // A compiler-deferred direct carrier intentionally has no native
    // request/proof identity: the row is excluded from the native TrustIR
    // request inventory and the router accepts the direct lane only when that
    // identity family is wholly absent. Unsupported/rejected native rows keep
    // the suite marker so they cannot masquerade as an identity-free carrier.
    if status != trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_TRANSPORT_STATUS_DEFERRED {
        set_obligation_metadata(
            obligation,
            trust_router::full_verification::TRUST_TRUST_IR_NATIVE_VERIFIER_SUITE_METADATA_KEY,
            "trust-vc".to_string(),
        );
    }
    set_obligation_metadata(
        obligation,
        TRUST_TRUST_IR_NATIVE_TRANSPORT_STATUS_METADATA_KEY,
        status.to_string(),
    );
    set_obligation_metadata(
        obligation,
        TRUST_TRUST_IR_NATIVE_UNSUPPORTED_REASON_METADATA_KEY,
        reason,
    );
}

fn annotate_trust_mc_typed_chc_lowering_status(
    obligation: &mut trust_verifier_api::TrustObligation,
) {
    let lowering_for_debug = trust_mc_typed_chc_lowering_for_obligation(obligation);
    if env_flag_enabled("TRUST_NATIVE_DEBUG") {
        let summary = match &lowering_for_debug {
            TrustMcTypedChcLowering::Supported(_) => "SUPPORTED".to_string(),
            TrustMcTypedChcLowering::Unsupported(reason) => format!("UNSUPPORTED: {reason}"),
        };
        eprintln!(
            "[NATIVE_TRUSTMC_EMIT] obl={} kind={:?} typed_chc_lowering={summary}",
            obligation.obligation_id, obligation.kind
        );
    }
    match lowering_for_debug {
        TrustMcTypedChcLowering::Supported(_) => {
            set_obligation_metadata(
                obligation,
                TRUST_MC_TYPED_CHC_LOWERING_STATUS_METADATA_KEY,
                "supported".to_string(),
            );
        }
        TrustMcTypedChcLowering::Unsupported(reason) => {
            set_obligation_metadata(
                obligation,
                TRUST_MC_TYPED_CHC_LOWERING_STATUS_METADATA_KEY,
                "unsupported".to_string(),
            );
            set_obligation_metadata(
                obligation,
                TRUST_MC_TYPED_CHC_UNSUPPORTED_REASON_METADATA_KEY,
                reason.clone(),
            );
            set_obligation_metadata(
                obligation,
                TRUST_TRUST_IR_NATIVE_TRANSPORT_STATUS_METADATA_KEY,
                "unsupported".to_string(),
            );
            set_obligation_metadata(
                obligation,
                TRUST_TRUST_IR_NATIVE_UNSUPPORTED_REASON_METADATA_KEY,
                reason,
            );
        }
    }
}

fn trust_vc_native_trust_ir_proof_unit_metadata_overrides(
    import: &trust_vc_bridge::TrustVcNativeTrustIrImportedProofArtifact,
) -> NativeTrustIrProofUnitMetadataOverrides {
    NativeTrustIrProofUnitMetadataOverrides {
        assertion_id: Some(import.assertion_id.clone()),
        trust_ir_module_digest: Some(import.trust_ir_module_digest.clone()),
        request_digest: Some(import.request_digest.clone()),
        compiler_facts_digest: Some(import.compiler_facts_digest.clone()),
        obligation_source_digest: Some(import.obligation_source_digest.clone()),
        replay_engine: Some(import.replay_engine.clone()),
        replay_invocation: Some(import.replay_invocation.clone()),
        replay_transcript_digest: Some(import.replay_transcript_digest.clone()),
        artifact_fingerprint: Some(import.artifact_fingerprint.clone()),
    }
}

fn set_obligation_metadata(
    obligation: &mut trust_verifier_api::TrustObligation,
    key: &str,
    value: String,
) {
    if let Some(entry) = obligation.metadata.iter_mut().find(|entry| entry.key == key) {
        entry.value = value;
    } else {
        obligation.metadata.push(trust_verifier_api::MetadataEntry { key: key.to_string(), value });
    }
}

fn extend_missing_obligation_metadata(
    metadata: &mut Vec<trust_verifier_api::MetadataEntry>,
    entries: Vec<trust_verifier_api::MetadataEntry>,
) {
    for entry in entries {
        if !metadata.iter().any(|existing| existing.key == entry.key) {
            metadata.push(entry);
        }
    }
}

/// E4/E5 become TrustMC-owned only for the complete, current compiler-authored
/// typed-VC envelope consumed by the TrustMC adapter. A payload-key presence
/// check is insufficient: partial, duplicated, stale-schema, non-Bool, or
/// non-compiler context metadata must retain the legacy TrustWP route.
fn native_trust_ir_has_current_typed_body_aware_e4_e5_envelope(
    obligation: &trust_verifier_api::TrustObligation,
) -> bool {
    if !matches!(
        obligation.kind,
        trust_verifier_api::ObligationKind::LoopInvariant
            | trust_verifier_api::ObligationKind::Termination
    ) {
        return false;
    }

    let Some(schema) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SCHEMA_METADATA_KEY)
    else {
        return false;
    };
    if schema != trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION {
        return false;
    }

    let Some(payload) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
    else {
        return false;
    };
    let Ok(predicate) =
        trust_types::json_depth::from_str_deep::<trust_verifier_api::TrustSpecPredicate>(payload)
    else {
        return false;
    };
    if !predicate.has_current_schema()
        || predicate.root_sort != trust_verifier_api::TrustSpecSort::Bool
        || predicate.root.sort != trust_verifier_api::TrustSpecSort::Bool
        || predicate.validate().is_err()
    {
        return false;
    }

    let Some(encoded_context) = unique_api_obligation_metadata_value(
        obligation,
        trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY,
    ) else {
        return false;
    };
    let Ok(context) = trust_types::json_depth::from_str_deep::<trust_verifier_api::ObligationContext>(
        encoded_context,
    ) else {
        return false;
    };
    context.has_current_schema()
        && matches!(&context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
        && matches!(
            &context.origin,
            trust_verifier_api::ObligationOrigin::VerificationCondition {
                formula_schema: Some(formula_schema),
                ..
            } if formula_schema == trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION
        )
}

fn native_trust_ir_route_for_api_obligation(
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<(&'static str, trust_ir::ObligationKind)> {
    match &obligation.kind {
        // Trust (P1.2 precedent, extended to preconditions): a body-aware
        // call-site precondition VC (`vc:<fn>:precondition:<i>`, origin
        // `VerificationCondition`, `contract_id: None`) carries a typed
        // `TRUST_VC_FORMULA_PAYLOAD` encoding the violation over the body
        // relation — the same closed CHC error-reachability query shape as the
        // P1.2 postcondition arm below. trust-wp's native pure replay is a
        // constant folder with zero assumptions that cannot consume the body
        // facts (guards, consts, min/saturating), so these landed Unknown.
        // Route the payload-carrying VC to trust-mc's typed-CHC runner. A
        // Precondition WITHOUT a typed payload — the def-site `#[requires]`
        // marker (contract_id Some, origin Contract, never carries the payload;
        // see contract_bundle_to_verifier_api) or any claim-based obligation —
        // keeps trust-wp's deductive route unchanged (fail-closed status quo).
        trust_verifier_api::ObligationKind::Precondition => {
            if api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
                .is_some()
            {
                Some(("trust-mc", trust_ir::ObligationKind::PanicFreedom))
            } else {
                Some(("trust-wp", trust_ir::ObligationKind::Precondition))
            }
        }
        // Trust (P1.2): a body-aware `#[ensures]` VC (`vc:<fn>:postcondition:<i>`,
        // origin `VerificationCondition`) carries a typed `TRUST_VC_FORMULA_PAYLOAD`
        // encoding `¬postcond ∧ body_defs` — the return slot `_0` pinned to its
        // computed value. That is a closed CHC-reachability query: route it to
        // trust-mc's typed-CHC/PDR runner, which discharges the analogous
        // arithmetic goals over the SAME formula pipeline. trust-wp's native pure
        // replay is a constant-folder that reconstructs only the BARE contract
        // predicate (havoc'd `_0`) and so always returned Unknown. A postcondition
        // WITHOUT a typed VC formula payload (a claim-based obligation) keeps
        // trust-wp's deductive route unchanged. The redundant def-site `#[ensures]`
        // marker is excluded upstream in `contract_bundle_to_verifier_api`, so the
        // authoritative body-aware VC is the postcondition obligation that reaches
        // here for a normal `#[ensures]`.
        trust_verifier_api::ObligationKind::Postcondition => {
            if api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
                .is_some()
            {
                Some(("trust-mc", trust_ir::ObligationKind::PanicFreedom))
            } else {
                Some(("trust-wp", trust_ir::ObligationKind::Postcondition))
            }
        }
        trust_verifier_api::ObligationKind::LoopInvariant => {
            if native_trust_ir_has_current_typed_body_aware_e4_e5_envelope(obligation) {
                // E4 rows are already closed violation formulas (entry or
                // consecution). Their proof is UNSAT of that formula, so use
                // the typed CHC/PDR kernel rather than trust-wp's authored-loop
                // marker lane, which intentionally has no native loop replay.
                Some(("trust-mc", trust_ir::ObligationKind::PanicFreedom))
            } else {
                Some(("trust-wp", trust_ir::ObligationKind::LoopInvariant))
            }
        }
        trust_verifier_api::ObligationKind::Refinement => {
            Some(("trust-wp", trust_ir::ObligationKind::RefinementType))
        }
        trust_verifier_api::ObligationKind::Termination => {
            if native_trust_ir_has_current_typed_body_aware_e4_e5_envelope(obligation) {
                // E5's non-negative/strict-decrease violation is likewise a
                // closed reachability query over the symbolic loop transition.
                Some(("trust-mc", trust_ir::ObligationKind::PanicFreedom))
            } else {
                Some(("trust-wp", trust_ir::ObligationKind::TranslationValidation))
            }
        }
        trust_verifier_api::ObligationKind::ArithmeticSafety
        | trust_verifier_api::ObligationKind::Assertion => {
            Some(("trust-mc", trust_ir::ObligationKind::PanicFreedom))
        }
        trust_verifier_api::ObligationKind::Invariant
        | trust_verifier_api::ObligationKind::Protocol => {
            Some(("trust-mc", trust_ir::ObligationKind::TranslationValidation))
        }
        trust_verifier_api::ObligationKind::Custom { namespace, .. }
            if namespace == trust_verifier_api::TRUST_VC_HARDENED_OBLIGATION_NAMESPACE =>
        {
            Some(("trust-mc", trust_ir::ObligationKind::TranslationValidation))
        }
        // trust-vc owns MIR memory/ownership obligations. The public verifier
        // bundle carries any direct MIR memory proof unit payload; the native
        // TrustIr binding preserves the trust-vc suite/request identity used by the
        // full verifier and proof transport.
        kind @ (trust_verifier_api::ObligationKind::MemorySafety
        | trust_verifier_api::ObligationKind::Ownership
        | trust_verifier_api::ObligationKind::BoundsCheck) => {
            trust_vc_bridge::trust_vc_native_trust_ir_kind_for_public_obligation(kind)
                .map(|native_kind| ("trust-vc", native_kind))
        }
        // Trust: ty (temporal) is deliberately EXEMPT from the typed TrustIr
        // native-bundle machinery (`PrimaryEngine::Ty.requires_trust_ir_native_bundle()`
        // is false): its model transport is the `trust.ty.temporal_model`
        // obligation metadata (see trust-mir-extract::ty_temporal_model_metadata),
        // which NativeTyEngine consumes directly. Emitting a "ty" binding here
        // is a trap — `trust_ir::NativeVerificationRequest` has no Ty variant and
        // the bridge never creates ty requests, so the binding annotation fails
        // with "no ty request for proof obligation N" and takes the WHOLE
        // function's native bundle down with it (every obligation, not just the
        // temporal one). Route None so the native bundle stays a three-suite
        // record and the temporal obligation flows through the public bundle.
        trust_verifier_api::ObligationKind::TemporalSafety
        | trust_verifier_api::ObligationKind::Liveness => None,
        trust_verifier_api::ObligationKind::Custom { .. } => None,
        _ => None,
    }
}

fn native_trust_ir_obligation_source_formula(
    obligation: &trust_verifier_api::TrustObligation,
) -> trust_ir::ProofFormula {
    let source_id = obligation
        .contract_id
        .as_deref()
        .or(obligation.proof_item_id.as_deref())
        .unwrap_or(&obligation.obligation_id);
    let assertion_id = format!("trust-assertion:{source_id}");
    let span = serde_json::json!({
        "file": obligation.source.file.clone().unwrap_or_default(),
        "line_start": obligation.source.line.unwrap_or_default(),
        "col_start": obligation.source.column.unwrap_or_default(),
        "line_end": obligation.source.end_line.unwrap_or_else(|| obligation.source.line.unwrap_or_default()),
        "col_end": obligation.source.end_column.unwrap_or_else(|| obligation.source.column.unwrap_or_default()),
    });
    let payload = serde_json::json!({
        "source_id": source_id,
        "assertion_id": assertion_id,
        "native_assertion_id": trust_types::stable_u32_id(assertion_id.as_bytes()),
        "span": span,
        "public_obligation_id": obligation.obligation_id,
    });
    trust_ir::ProofFormula {
        schema: trust_ir_bridge::TRUST_OBLIGATION_SOURCE_SCHEMA.to_string(),
        payload: payload.to_string(),
        smtlib: None,
        sort: None,
    }
}

fn populate_native_trust_ir_proof_formulas(
    module: &mut trust_ir::Module,
    bundle: &trust_verifier_api::TrustContractBundle,
    bindings: &[PendingNativeTrustIrBinding],
) -> Result<(), String> {
    for binding in bindings {
        let Some(obligation) = bundle.obligations.get(binding.obligation_index) else {
            return Err(format!(
                "native TrustIr binding referenced missing public obligation index {}",
                binding.obligation_index
            ));
        };
        let Some(formula) = native_trust_ir_proof_formula_for_api_obligation(
            binding.verifier_suite,
            &bundle.contracts,
            obligation,
        )?
        else {
            continue;
        };
        replace_native_trust_ir_proof_formula(
            module,
            binding.verifier_suite,
            binding.proof_obligation_id,
            formula,
        )?;
    }
    Ok(())
}

fn native_trust_ir_proof_formula_for_api_obligation(
    verifier_suite: &str,
    contracts: &[trust_verifier_api::TrustContract],
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<trust_ir::ProofFormula>, String> {
    if verifier_suite.eq_ignore_ascii_case("trust-wp") {
        return trust_wp_trust_ir_proof_formula_for_api_obligation(contracts, obligation);
    }
    // Trust: populate the canonical public formula unconditionally for the
    // trust-mc suite. Gating on a Supported typed-CHC lowering left every
    // Unsupported-lowering obligation carrying only the source-only envelope,
    // which the trust-bmc exact-match binding gate then rejected as "formula
    // does not exactly match canonical public formula metadata" — a spurious
    // mismatch diagnostic on a fail-closed row. The canonical metadata is
    // stamped by trust-mir-extract regardless of lowering support, so the
    // native obligation must carry it regardless too.
    if verifier_suite.eq_ignore_ascii_case("trust-mc") {
        return Ok(trust_ir_proof_formula_from_api_obligation_metadata(obligation));
    }
    Ok(None)
}

// Trust: the compiler routes obligations using hyphenated suite labels
// ("trust-mc"/"trust-wp"/"trust-vc"), but `trust_ir::NativeVerifierSuite`'s
// `Display` emits the underscore family form ("trust_mc"). `eq_ignore_ascii_case`
// does not fold `-`/`_`, so a naive comparison silently skips every native
// request and reports a missing replay atom. Compare ignoring case and any
// non-alphanumeric separators so request matching is robust across the boundary.
fn native_trust_ir_suite_label_matches(request_suite: &str, label: &str) -> bool {
    fn normalize(value: &str) -> String {
        value
            .chars()
            .filter(char::is_ascii_alphanumeric)
            .map(|ch| ch.to_ascii_lowercase())
            .collect()
    }
    normalize(request_suite) == normalize(label)
}

fn native_verifier_suite_canonical_label(suite: trust_ir::NativeVerifierSuite) -> String {
    suite.to_string().replace('_', "-")
}

fn replace_native_trust_ir_proof_formula(
    module: &mut trust_ir::Module,
    verifier_suite: &str,
    proof_obligation_id: trust_ir::ProofId,
    formula: trust_ir::ProofFormula,
) -> Result<(), String> {
    let obligation = module
        .proof_obligations
        .iter_mut()
        .find(|obligation| obligation.id == proof_obligation_id)
        .ok_or_else(|| {
            format!(
                "typed TrustIr module has no {verifier_suite} proof obligation {} to receive its final public claim",
                proof_obligation_id.index()
            )
        })?;
    obligation.formula = Some(formula);
    Ok(())
}

fn trust_ir_proof_formula_from_api_obligation_metadata(
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<trust_ir::ProofFormula> {
    let schema = api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SCHEMA_METADATA_KEY)?;
    let payload = api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)?;
    let smtlib = api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SMTLIB_METADATA_KEY)
        .map(str::to_string);
    let sort = api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SORT_METADATA_KEY)
        .map(str::to_string);
    Some(trust_ir::ProofFormula {
        schema: schema.to_string(),
        payload: payload.to_string(),
        smtlib,
        sort,
    })
}

fn trust_wp_trust_ir_proof_formula_for_api_obligation(
    contracts: &[trust_verifier_api::TrustContract],
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<trust_ir::ProofFormula>, String> {
    let Some(claim) = trust_wp_public_typed_proof_claim(contracts, obligation)? else {
        return Ok(None);
    };
    Ok(Some(trust_wp_trust_ir_proof_formula_from_claim(claim)))
}

fn trust_wp_trust_ir_proof_formula_from_claim(
    claim: TrustWpProofContextClaim,
) -> trust_ir::ProofFormula {
    match claim.format {
        TrustWpProofContextClaimFormat::TrustWpPureExprV1 => {
            trust_ir::ProofFormula::new(TRUST_WP_PURE_EXPR_SCHEMA_VERSION, claim.payload)
        }
        TrustWpProofContextClaimFormat::TrustFormulaV1 => {
            trust_ir::ProofFormula::new(TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION, claim.payload)
        }
        TrustWpProofContextClaimFormat::SmtLib2 => {
            trust_ir::ProofFormula::smtlib2(claim.payload, "Bool")
        }
        TrustWpProofContextClaimFormat::Other(schema) => {
            trust_ir::ProofFormula::new(schema, claim.payload)
        }
    }
}

fn trust_mc_typed_chc_contract_for_native_trust_ir_obligation(
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    request: &trust_ir::NativeVerificationRequest,
    proof_obligation_id: trust_ir::ProofId,
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<trust_verifier_api::TrustContract>, String> {
    let trust_ir::NativeVerificationRequest::TrustMc(request) = request else {
        return Err(
            "cannot build trust-mc typed CHC input from a non-trust-mc TrustIr request".to_string()
        );
    };
    let (chc_constraint, unsupported_reason) =
        match trust_mc_typed_chc_lowering_for_obligation(obligation) {
            TrustMcTypedChcLowering::Supported(chc_constraint) => (chc_constraint, None),
            TrustMcTypedChcLowering::Unsupported(reason) => (
                TrustMcTypedChcConstraint {
                    vars: Vec::new(),
                    constraint: serde_json::json!({ "kind": "bool_const", "value": false }),
                },
                Some(reason),
            ),
        };
    let native_obligation_id =
        trust_mc_native_trust_ir_obligation_id(request.id.index(), proof_obligation_id.index());
    let contract_id = format!("contract:trust-mc-typed-chc:{native_obligation_id}");
    let function_name = native_trust_ir_bundle
        .module
        .function_by_id(request.function)
        .map(|function| function.name.clone())
        .unwrap_or_else(|| format!("trust_ir-function-{}", request.function.index()));
    // Trust: routing shares the verifier-api's exact synthetic identity. A
    // public metadata-key lookalike must take the semantic lowering path (and
    // bundle validation rejects it), never the structural/vacuous default CHC.
    let is_default_trust_mc_obligation = obligation.is_default_admission();
    // Trust (diagnostic): typed-CHC routing attribution, opt-in via
    // TRUST_DIAG_CHC_ROUTE=1 — names, per obligation, whether the STRUCTURAL
    // default-function CHC or the SEMANTIC constraint lowering will back the
    // typed-CHC contract, and any unsupported reason. The structural CHC
    // carries no instruction semantics, so misrouting a semantic obligation
    // onto it is a vacuous proof; this print makes that routing observable.
    if std::env::var_os("TRUST_DIAG_CHC_ROUTE").is_some() {
        eprintln!(
            "TRUST_DIAG chc-route fn={function_name} obligation={} kind={:?} default={} unsupported={:?}",
            obligation.obligation_id,
            obligation.kind,
            is_default_trust_mc_obligation,
            unsupported_reason,
        );
        if !is_default_trust_mc_obligation {
            eprintln!(
                "TRUST_DIAG chc-vars {}",
                serde_json::to_string(&chc_constraint.vars).unwrap_or_default()
            );
            eprintln!(
                "TRUST_DIAG chc-constraint {}",
                serde_json::to_string(&chc_constraint.constraint).unwrap_or_default()
            );
        }
    }
    let routed_to_structural_chc = trust_mc_routes_to_structural_default_function_chc(
        obligation,
        unsupported_reason.is_none(),
    );
    // Trust (data-flow CFG-CHC, ENV-GATED / WIP — `TRUST_MC_DATAFLOW_CHC`):
    // redirect per-statement ARITHMETIC-safety obligations to the enriched
    // whole-function CFG-CHC in `ArithmeticSafetyOnly` mode. Proving the
    // function's overflow CHC error-unreachable SOUNDLY discharges the specific
    // overflow obligation (proving-more is sound; PDR-unknown stays unproved →
    // never a false SAFE). Gated to LOOPY functions (a CFG back-edge), so a
    // straight-line safety obligation keeps its single-formula path and cannot
    // regress to UNKNOWN on an unrelated overflow. Bounds-check obligations are
    // NOT redirected — the CHC has no bounds violation edge, so they stay on the
    // single-formula path. The encoder's own coverage gate
    // (`function_overflow_surface_fully_modeled`) fails closed to `Ok(None)` when
    // the overflow surface is not fully modeled, so a redirected obligation can
    // only be PROVED when its overflow is genuinely captured.
    //
    // The env gate defaults OFF, so with no opt-in this whole block is inert and
    // the emitted CHC is byte-identical to the structural encoding above.
    let redirect_safety_to_dataflow = trust_mc_dataflow_chc_enabled()
        && matches!(obligation.kind, trust_verifier_api::ObligationKind::ArithmeticSafety)
        && native_trust_ir_bundle
            .module
            .function_by_id(request.function)
            .is_some_and(function_has_back_edge);
    // Structural mode preserves the whole-function structural encoding's error
    // edges; ArithmeticSafetyOnly is used only for a redirected arithmetic
    // obligation.
    let error_mode = if routed_to_structural_chc {
        ChcErrorMode::Structural
    } else {
        ChcErrorMode::ArithmeticSafetyOnly
    };
    // The enriched whole-function CFG-CHC backs the structurally-routed
    // obligations OR a loop-carried arithmetic obligation.
    let dataflow_eligible =
        (trust_mc_dataflow_chc_enabled() && routed_to_structural_chc) || redirect_safety_to_dataflow;
    let enriched = if dataflow_eligible {
        trust_mc_dataflow_function_chc_from_trust_ir(native_trust_ir_bundle, request, error_mode)?
    } else {
        None
    };
    // True iff we used the enriched CHC but NOT via the standard structural path
    // — i.e. we redirected an arithmetic-safety obligation. Used below to suppress
    // the single-formula "unsupported" placeholder marking (we now have a real CHC).
    let redirected_to_dataflow = enriched.is_some() && !routed_to_structural_chc;
    let (relations, rules, enriched_vars) = match enriched {
        Some((relations, rules, vars)) => (relations, rules, Some(vars)),
        None if routed_to_structural_chc => {
            let (relations, rules) =
                trust_mc_default_function_chc_from_trust_ir(native_trust_ir_bundle, request)?;
            (relations, rules, None)
        }
        None => (
            serde_json::json!([
                { "name": "error" }
            ]),
            serde_json::json!([
                {
                    "head": { "name": "error" },
                    "body": {
                        "constraints": [chc_constraint.constraint],
                    },
                }
            ]),
            None,
        ),
    };
    let mut value = serde_json::json!({
        "schema_version": TRUST_MC_TYPED_CHC_OBLIGATION_SCHEMA,
        "obligation_id": native_obligation_id,
        "origin": "mir_derived",
        "function_name": function_name,
        "query": { "target": "error" },
        "vars": enriched_vars.unwrap_or_else(|| chc_constraint.vars.clone()),
        "relations": relations,
        "rules": rules,
        "native_metadata": trust_mc_native_typed_chc_metadata_json(
            native_trust_ir_bundle,
            request,
            proof_obligation_id,
        ),
    });
    // Only stamp the router_placeholder/unsupported marker when we FELL BACK to
    // the vacuous placeholder. A whole-function panic-freedom aggregate whose
    // per-VC lowering is (by design) unsupported is now ROUTED to the real
    // structural whole-CFG reachability CHC (see `trust_mc_routes_to_structural_
    // default_function_chc`); its `value` carries a genuine proof input, so
    // stamping it unsupported would make the transport wrongly refuse the real
    // reachability proof and leave it runtime-checked forever. The same holds for
    // an arithmetic-safety obligation REDIRECTED to the env-gated data-flow CHC:
    // it too now carries a genuine MIR-derived proof input, not a placeholder.
    if let Some(reason) = unsupported_reason
        .as_ref()
        .filter(|_| !routed_to_structural_chc && !redirected_to_dataflow)
    {
        if let serde_json::Value::Object(object) = &mut value {
            object.insert("origin".to_string(), serde_json::json!("router_placeholder"));
            object.insert(
                "unsupported".to_string(),
                serde_json::json!({
                    "status": "unsupported",
                    "reason": reason,
                }),
            );
            object.insert(
                "trust_native_admission".to_string(),
                serde_json::json!({
                    "status": "unsupported_semantics",
                    "unsupported_semantics_status": "unsupported",
                    "detail": reason,
                }),
            );
        }
    }
    let source_digest = api_obligation_metadata_value(obligation, TRUST_SOURCE_DIGEST_METADATA_KEY)
        .map(str::to_string)
        .unwrap_or_else(|| trust_mc_fallback_obligation_digest("source", obligation));
    let vc_digest = api_obligation_metadata_value(obligation, TRUST_VC_DIGEST_METADATA_KEY)
        .map(str::to_string)
        .unwrap_or_else(|| trust_mc_fallback_obligation_digest("vc", obligation));
    let synthetic_digest = trust_mc_synthetic_typed_chc_digest(&value)?;
    let binding = trust_mc_typed_chc_binding_json(
        obligation,
        &contract_id,
        &native_obligation_id,
        &source_digest,
        &vc_digest,
        &synthetic_digest,
    );
    let binding_metadata = serde_json::to_string(&binding).map_err(|error| {
        format!(
            "failed to serialize trust-mc typed CHC binding metadata for `{native_obligation_id}`: {error}"
        )
    })?;
    let binding_entries = trust_mc_typed_chc_binding_metadata_entries(
        &source_digest,
        &vc_digest,
        &synthetic_digest,
        binding_metadata,
    );

    Ok(Some(trust_verifier_api::TrustContract {
        contract_id,
        kind: trust_verifier_api::ContractKind::Asserts,
        predicate: trust_verifier_api::ContractPredicate::MathIr {
            schema: TRUST_MC_TYPED_CHC_OBLIGATION_SCHEMA.to_string(),
            value,
        },
        source: obligation.source.clone(),
        metadata: {
            let mut metadata = vec![trust_verifier_api::MetadataEntry {
                key: "trust-trust-mc.typed-chc-obligation.source".to_string(),
                value: "compiler-native-trust-ir-trust-spec-vc".to_string(),
            }];
            metadata.extend(binding_entries);
            metadata
        },
    }))
}

fn trust_mc_routes_to_structural_default_function_chc(
    obligation: &trust_verifier_api::TrustObligation,
    lowering_supported: bool,
) -> bool {
    // The default-admission obligation routes to the structural whole-CFG
    // reachability CHC when its per-VC lowering succeeded.
    //
    // The COUNTED whole-function panic-freedom AGGREGATE (id
    // `vc:<fn>:assertion:panic-freedom:0`, carrying
    // `TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY`) has NO per-VC violation
    // predicate BY DESIGN — it asserts "no error-flagged block (`Inst::Unreachable`
    // / indirect-call / dialect-op / unknown terminator) is CFG-reachable", a
    // whole-CFG reachability query, not a single `Assert(cond)`. So its per-VC
    // lowering is EXPECTED-unsupported (`lowering_supported == false`); route it to
    // the SAME sound structural CHC regardless.
    //
    // SOUNDNESS: `trust_mc_default_function_chc_from_trust_ir` derives `error` ONLY
    // from `Inst::Unreachable`, `CallIndirect`, `DialectOp`, no-terminator, and any
    // unhandled terminator — it does NOT flag `Inst::Assert` (guarded arithmetic/
    // bounds/drop panics) or direct `Inst::Call` (may-panic). So proving this CHC
    // means only that no UNGUARDED/bare panic site is reachable; every GUARDED panic
    // keeps its own per-site obligation (ArithmeticSafety / BoundsCheck / PanicFreedom /
    // may-panic-call), which the strict lane still requires independently. The
    // aggregate is a lightweight net over the bare-panic class, never a substitute
    // for the per-site gate — so this can only move `runtime_checked → proved` for a
    // function whose bare-panic blocks are genuinely CFG-unreachable, never mask a
    // reachable panic or an unproved per-site obligation.
    (lowering_supported && obligation.is_default_admission())
        || obligation_has_panic_freedom_marker(obligation)
}

/// Whether `obligation` is the whole-function panic-freedom aggregate (carries
/// [`TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY`]).
fn obligation_has_panic_freedom_marker(obligation: &trust_verifier_api::TrustObligation) -> bool {
    api_obligation_metadata_value(obligation, TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY)
        .is_some()
}

fn trust_mc_default_function_chc_from_trust_ir(
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    request: &trust_ir::TrustMcNativeRequest,
) -> Result<(serde_json::Value, serde_json::Value), String> {
    let function =
        native_trust_ir_bundle.module.function_by_id(request.function).ok_or_else(|| {
            format!(
                "default trust-mc function admission cannot find TrustIr function {}",
                request.function.index()
            )
        })?;
    if function.blocks.is_empty() {
        return Err(format!(
            "default trust-mc function admission for `{}` has no typed TrustIr blocks",
            function.name
        ));
    }

    let mut relations = Vec::with_capacity(function.blocks.len() + 1);
    relations.push(serde_json::json!({ "name": "error" }));
    for block in &function.blocks {
        relations.push(serde_json::json!({
            "name": trust_mc_default_block_relation(block.id),
        }));
    }

    let mut rules = vec![serde_json::json!({
        "head": { "name": trust_mc_default_block_relation(function.entry) },
        "body": { "constraints": [] },
    })];

    for block in &function.blocks {
        let source_relation = trust_mc_default_block_relation(block.id);
        let mut emitted_error_rule = false;
        let Some(terminator) = block.terminator() else {
            rules.push(trust_mc_default_error_rule(
                &source_relation,
                true,
                format!("typed TrustIr block {} has no terminator", block.id.index()),
            ));
            continue;
        };
        match &terminator.inst {
            trust_ir::Inst::Br { target, .. } => {
                rules.push(trust_mc_default_transition_rule(&source_relation, *target));
            }
            trust_ir::Inst::CondBr { then_target, else_target, .. } => {
                rules.push(trust_mc_default_transition_rule(&source_relation, *then_target));
                rules.push(trust_mc_default_transition_rule(&source_relation, *else_target));
            }
            trust_ir::Inst::Switch { default, cases, exhaustive_enum_unreachable, .. } => {
                // When the TyCtxt extraction check (`mark_exhaustive_enum_unreachable_switches`)
                // certified an exhaustive enum-discriminant switch whose otherwise arm is a
                // compiler-`Unreachable` block AND the explicit cases equal the enum's FULL
                // discriminant tag set, the default arm is genuinely infeasible: a valid enum
                // value's discriminant is always one of the cases. Do NOT emit the default
                // transition, so the default's `unreachable` terminator never reaches the
                // `error` relation in this structural reachability CHC — the obligation proves.
                // Sound: the flag is never set for a partial/non-exhaustive match or a plain-int
                // `unreachable_unchecked` (those keep the default transition and fail closed),
                // guarded by the enum_partial_unreachable / partial_int_unreachable mutants.
                if !*exhaustive_enum_unreachable {
                    rules.push(trust_mc_default_transition_rule(&source_relation, *default));
                }
                for case in cases {
                    rules.push(trust_mc_default_transition_rule(&source_relation, case.target));
                }
            }
            trust_ir::Inst::Return { .. } => {}
            trust_ir::Inst::Unreachable => {
                rules.push(trust_mc_default_error_rule(
                    &source_relation,
                    true,
                    format!(
                        "typed TrustIr block {} reaches an unreachable terminator",
                        block.id.index()
                    ),
                ));
                emitted_error_rule = true;
            }
            // Trust: `CoroSuspend` is a return-like terminator (trust-ir#coroutines).
            // It macro-expands to `GEP(frame, state_slot)` + `Store(next_state)` +
            // `Return(value)`, so in this structural reachability CHC it carries the
            // frame store (admitted, like any `Store`) and then returns — exactly like
            // `Inst::Return`, with NO in-function successors. Emit no transition rule.
            trust_ir::Inst::CoroSuspend { .. } => {}
            // Trust: `Invoke` is a direct call (`callee: FuncId`) with TWO control-flow
            // successors — `normal_dest` and `unwind_dest` — the Itanium/LLVM `invoke`.
            // Treat the callee effect exactly like `Inst::Call` (admitted; not in the
            // fail-closed admission set), then carry reachability along BOTH edges so the
            // structural CHC propagates to the normal continuation and to the landing-pad
            // block. Omitting either edge would under-approximate reachability.
            trust_ir::Inst::Invoke { normal_dest, unwind_dest, .. } => {
                rules.push(trust_mc_default_transition_rule(&source_relation, *normal_dest));
                rules.push(trust_mc_default_transition_rule(&source_relation, *unwind_dest));
            }
            // Trust: `Resume` re-raises the in-flight exception via `_Unwind_Resume(exn)`,
            // which does not return. It is a divergent TERMINATOR with NO in-function
            // successors (no postcondition flows to any successor), so — like `Return` —
            // it emits no transition rule and does not itself reach the `error` relation.
            trust_ir::Inst::Resume { .. } => {}
            _ => {
                rules.push(trust_mc_default_error_rule(
                    &source_relation,
                    true,
                    format!(
                        "typed TrustIr block {} terminates with non-terminator instruction {:?}",
                        block.id.index(),
                        terminator.inst
                    ),
                ));
                emitted_error_rule = true;
            }
        }

        for instruction in block.instructions() {
            if trust_mc_default_instruction_requires_fail_closed_admission(instruction) {
                rules.push(trust_mc_default_error_rule(
                    &source_relation,
                    true,
                    format!(
                        "typed TrustIr block {} contains unsupported native trust-mc admission instruction {:?}",
                        block.id.index(),
                        instruction.inst
                    ),
                ));
                emitted_error_rule = true;
            }
        }

        if !emitted_error_rule {
            rules.push(trust_mc_default_error_rule(
                &source_relation,
                false,
                format!(
                    "typed TrustIr block {} has no reachable native trust-mc admission error",
                    block.id.index()
                ),
            ));
        }
    }

    Ok((serde_json::Value::Array(relations), serde_json::Value::Array(rules)))
}

fn trust_mc_default_block_relation(block: trust_ir::BlockId) -> String {
    format!("bb{}", block.index())
}

fn trust_mc_default_transition_rule(
    source_relation: &str,
    target: trust_ir::BlockId,
) -> serde_json::Value {
    serde_json::json!({
        "head": { "name": trust_mc_default_block_relation(target) },
        "body": {
            "relation": { "name": source_relation, "args": [] },
            "constraints": [],
        },
    })
}

fn trust_mc_default_error_rule(
    source_relation: &str,
    reachable: bool,
    reason: String,
) -> serde_json::Value {
    serde_json::json!({
        "head": { "name": "error" },
        "body": {
            "relation": { "name": source_relation, "args": [] },
            "constraints": [
                {
                    "kind": "bool_const",
                    "value": reachable,
                    "reason": reason,
                }
            ],
        },
    })
}

fn trust_mc_default_instruction_requires_fail_closed_admission(
    instruction: &trust_ir::InstrNode,
) -> bool {
    matches!(&instruction.inst, trust_ir::Inst::CallIndirect { .. })
        || matches!(
            &instruction.inst,
            trust_ir::Inst::DialectOp(op)
                if instruction.results.len() != 1
                    || !trust_ir::dialect::trust_rust::is_thread_local_addr(op)
        )
}

// ---------------------------------------------------------------------------
// Trust (data-flow CFG-CHC encoder — ENV-GATED, WIP): data-flow enrichment of
// the structural CFG-CHC safety encoder above.
//
// The default encoder above emits a PURELY STRUCTURAL forward-reachability CHC:
// nullary block relations, an unconstrained entry fact, nullary transitions
// (branch conditions dropped), and per-block `error` edges. It is a total-havoc
// over-approximation — sound, but too weak to discharge loop-carried arithmetic.
//
// This enriched encoder threads SSA data flow into the SAME reachability CHC so
// PDR/Spacer can synthesize the invariants (e.g. `off <= len`) needed to prove
// `error` unreachable (= SAFE). It models:
//   * block relations parameterized by their integer/bool params (`arg_sorts`),
//   * the entry fact with those params left FREE (full input havoc),
//   * a straight-line fold of `BinOp{Add,Sub,Mul}` / `Const::Int` / `Copy` /
//     `ICmp` / `Overflow` into Bool-sorted equality constraints,
//   * EVERY terminator kind the structural encoder handles, so a function is
//     enriched whenever the structural encoder would accept it: `Br` / `CondBr` /
//     `Switch` / `Invoke` transitions that THREAD block args and carry the block
//     fold (plus, for `CondBr`, the branch guard `cond` / `¬cond`); `Return` /
//     `CoroSuspend` / `Resume` as no-successor terminators; and `Unreachable` —
//     the checked-arithmetic panic sink — as a REACHABLE `error` edge (the
//     obligation discharger: the enriched incoming guard lets PDR prove that edge
//     dead). Call return values (`Invoke` results, `Call`/unmodeled body insts)
//     are HAVOC'd — declared where used, never constrained (sound),
//   * every structural `error` edge preserved verbatim (with canonical args).
//
// GATING. The whole lane is opt-in via `TRUST_MC_DATAFLOW_CHC` and defaults OFF,
// so the shipped default corpus is byte-identical to the structural encoder
// unless a caller explicitly asks for enrichment. This is deliberate: the
// encoder is WIP and low-yield; do not enable it without validation.
//
// Soundness discipline (this is a reachability proof — `error` unreachable ⇒
// SAFE, so we must OVER-approximate the reachable set and never emit a false
// SAFE):
//   * Only emit a transition constraint ENTAILED by the real semantics; havoc
//     (emit nothing) is always sound. Entry params stay free.
//   * Integers are modeled as mathematical `int` (not `bit_vec`) so LIA
//     invariants synthesize; a value's var carries its NON-NEGATIVE magnitude
//     for unsigned types, under which unsigned compares equal integer compares
//     on all real states.
//   * The `Overflow` bit is modeled per width: signed `i8..i64` as
//     `sum ∉ [MIN,MAX]`; UNSIGNED `u8..u64` as `sum > 2^W-1` (add/mul) or
//     `sum < 0` (sub). 128-bit is NOT modeled (its wrap point exceeds `i128`),
//     and neither are the POINTER-WIDTH `Isize`/`Usize` (trust-ir v25 carries
//     them faithfully, so their wrap point is TARGET-dependent and a fixed
//     64-bit bound could MISS a real 32-bit overflow) — all of them are havoced
//     and gated out.
//   * UNSIGNED >= 0 DISCIPLINE (false-proof-critical): the unsigned `> 2^W-1`
//     test is faithful in `int` only if every unsigned operand carries its type
//     invariant `v >= 0` (a modeled-negative unsigned var could make an overflow
//     test spuriously false and MISS a real overflow). We emit `0 <= v <= 2^W-1`
//     for every FREE unsigned var — the entry (function-parameter) block's
//     params — where it removes only NON-REAL model states (SOUND). We do NOT
//     attach it to a fold-defined value (e.g. an unsigned subtraction result):
//     conjoining `>= 0` with its defining equality would exclude REAL wrap
//     states. Fold-defined values inherit non-negativity from their operands
//     (sum of non-negatives is non-negative); a genuinely-wrapping unsigned sub
//     feeding an overflow is the one residual gap (checked-mode subs are
//     `SubOverflow` with their own edge). Signed vars get NO `>= 0` (they can be
//     negative).
//   * ANY uncertainty (a missing terminator, an SSA edge arity mismatch, or a
//     future/unknown terminator kind) → `Ok(None)`, i.e. fall back to the
//     untouched structural encoder. Purely additive.
// ---------------------------------------------------------------------------

/// Runtime gate for the data-flow-enriched CFG-CHC encoder. Reads the
/// `TRUST_MC_DATAFLOW_CHC` environment variable (present ⇒ enabled) so the
/// frozen driver can toggle enrichment without a recompile. Defaults OFF, which
/// is what keeps the default verification lane byte-identical to the structural
/// encoder.
fn trust_mc_dataflow_chc_enabled() -> bool {
    std::env::var_os("TRUST_MC_DATAFLOW_CHC").is_some()
}

/// Debug gate: when `TRUST_MC_DATAFLOW_CHC_DEBUG` is set, the enriched encoder
/// prints one `[DATAFLOW-FIRED]` / `[DATAFLOW-FALLBACK]` line per function so a
/// rebuild can confirm at runtime whether enrichment actually engaged.
fn trust_mc_dataflow_chc_debug_enabled() -> bool {
    std::env::var_os("TRUST_MC_DATAFLOW_CHC_DEBUG").is_some()
}

/// Which family of `error` edges the enriched CHC emits. Relations and
/// transitions are identical across modes; ONLY the `error` edges differ.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum ChcErrorMode {
    /// Whole-function structural reachability — the default_function encoding:
    /// `Unreachable`→error, fail-closed-admission→error, and the `reachable:false`
    /// placeholder. Preserves the exact byte-shape the default obligations use.
    Structural,
    /// Only DIRECT arithmetic-overflow violations reach `error` — for a redirected
    /// arithmetic-safety obligation. Per modeled `Overflow` we emit
    /// `error :- bbB(args), fold, (lhs op rhs is out of range)`; NO structural
    /// edges are emitted (`Unreachable` / `Return` / calls / closures become pure
    /// havoc'd sinks with no `error` edge). Proving `error` unreachable then proves
    /// EXACTLY "no modeled arithmetic overflow occurs" — what the obligation
    /// asserts — undisturbed by unrelated panics / absent callees / closures.
    /// SOUND: dropping the other structural edges is dropping OTHER obligations'
    /// error routes (each proved separately); we never drop an overflow edge, and
    /// an over-approximated reachable set with a faithful violation edge cannot
    /// miss a real overflow.
    ArithmeticSafetyOnly,
}

/// Successor block ids of a block (empty for a return-like / divergent / missing
/// terminator). Shared by the loop detector and any CFG walk.
fn chc_block_successors(block: &trust_ir::Block) -> Vec<trust_ir::BlockId> {
    let Some(terminator) = block.terminator() else {
        return Vec::new();
    };
    match &terminator.inst {
        trust_ir::Inst::Br { target, .. } => vec![*target],
        trust_ir::Inst::CondBr { then_target, else_target, .. } => {
            vec![*then_target, *else_target]
        }
        trust_ir::Inst::Switch { default, cases, .. } => {
            let mut successors = vec![*default];
            successors.extend(cases.iter().map(|case| case.target));
            successors
        }
        trust_ir::Inst::Invoke { normal_dest, unwind_dest, .. } => {
            vec![*normal_dest, *unwind_dest]
        }
        _ => Vec::new(),
    }
}

/// Whether the function's CFG contains a back-edge (a loop), via textbook
/// 3-colour DFS (white/gray/black): an edge into a gray (on-path) node is a
/// back-edge. Used to gate the safety-obligation redirect below so only
/// loop-carried arithmetic is routed to the whole-function CFG-CHC — a
/// straight-line safety obligation keeps its single-formula proof path.
///
/// The DFS carries its own explicit stack rather than recursing: this runs
/// inside a compiler pass over arbitrary user CFGs, where a deep chain of blocks
/// would overflow the native stack.
fn function_has_back_edge(function: &trust_ir::Function) -> bool {
    const WHITE: u8 = 0;
    const GRAY: u8 = 1;
    const BLACK: u8 = 2;
    let successors_of = |block_id: trust_ir::BlockId| -> Vec<trust_ir::BlockId> {
        function.block(block_id).map(chc_block_successors).unwrap_or_default()
    };
    let mut color: FxHashMap<u32, u8> = FxHashMap::default();
    for root in &function.blocks {
        if color.get(&root.id.index()).copied().unwrap_or(WHITE) != WHITE {
            continue;
        }
        color.insert(root.id.index(), GRAY);
        // (block, its successors, index of the next successor to visit)
        let mut stack: Vec<(trust_ir::BlockId, Vec<trust_ir::BlockId>, usize)> =
            vec![(root.id, successors_of(root.id), 0)];
        while let Some((block_id, successors, cursor)) = stack.pop() {
            if cursor >= successors.len() {
                color.insert(block_id.index(), BLACK);
                continue;
            }
            let successor = successors[cursor];
            stack.push((block_id, successors, cursor + 1));
            match color.get(&successor.index()).copied().unwrap_or(WHITE) {
                // gray successor → back-edge; white → descend; black → done.
                GRAY => return true,
                WHITE => {
                    color.insert(successor.index(), GRAY);
                    stack.push((successor, successors_of(successor), 0));
                }
                _ => {}
            }
        }
    }
    false
}

/// SOUNDNESS gate for `ArithmeticSafetyOnly` mode. The whole-function CHC
/// conflates every arithmetic-safety obligation into one `error` query but only
/// models the `Overflow` widths [`chc_overflow_width_modeled`] accepts. If the
/// function contains an arithmetic-safety op we DON'T model — a 128-bit or
/// pointer-width `Overflow` (wrap not expressible as a fixed bound in `int`), or
/// an integer `UDiv`/`SDiv`/`URem`/`SRem` (div/rem-by-zero) — proving `error`
/// unreachable would NOT cover that op, so discharging its obligation from this
/// CHC would be a FALSE SAFE. Conservative: any such op ⇒ the surface is not
/// fully modeled ⇒ the encoder falls back to the single-formula path for this
/// function's safety obligations.
///
/// NOTE the standing assumption: arithmetic_safety obligations arise from CHECKED
/// arithmetic (`Overflow` insts) + div/rem, as in trust's verified configuration.
/// A plain `BinOp{Add,Sub,Mul}` that could be an UNCHECKED (release-mode) overflow
/// obligation is NOT caught here — flagged for the corpus to be checked-mode, and
/// one of the reasons this lane stays env-gated OFF.
fn function_overflow_surface_fully_modeled(function: &trust_ir::Function) -> bool {
    function.blocks.iter().all(|block| {
        block.body.iter().all(|node| match &node.inst {
            // Signed i8..i64 AND unsigned u8..u64 overflow are modeled; 128-bit
            // and pointer-width (`Isize`/`Usize`) `Overflow` are not.
            trust_ir::Inst::Overflow { ty, .. } => chc_overflow_width_modeled(ty),
            // Integer div/rem-by-zero is still unmodeled (float div is not an
            // arithmetic-safety violation).
            trust_ir::Inst::BinOp { op, .. } => !matches!(
                op,
                trust_ir::BinOp::UDiv
                    | trust_ir::BinOp::SDiv
                    | trust_ir::BinOp::URem
                    | trust_ir::BinOp::SRem
            ),
            _ => true,
        })
    })
}

/// Stable CHC variable name for an SSA value (`v{index}`).
fn chc_value_var_name(value: trust_ir::ValueId) -> String {
    format!("v{}", value.index())
}

/// Scalar CHC sort JSON for a `trust_ir::Ty`, or `None` for non-scalar types
/// (pointers, floats, aggregates) which are dropped from block relations and
/// havoced. `Bool` → bool sort; any integer → mathematical `int` (deliberately
/// NOT `bit_vec`, which would force the `bv_*` op family and block LIA invariant
/// synthesis).
fn chc_scalar_sort_json(ty: &trust_ir::Ty) -> Option<serde_json::Value> {
    if matches!(ty, trust_ir::Ty::Bool) {
        Some(serde_json::json!({ "kind": "bool" }))
    } else if ty.is_integer() {
        Some(serde_json::json!({ "kind": "int" }))
    } else {
        None
    }
}

/// A `{kind:var}` expression referencing an SSA value at the given sort.
fn chc_var_expr(value: trust_ir::ValueId, sort: &serde_json::Value) -> serde_json::Value {
    serde_json::json!({ "kind": "var", "name": chc_value_var_name(value), "sort": sort })
}

/// An `{kind:int_const}` expression. The value is encoded as a decimal STRING so
/// the full `i128` range round-trips (the reader parses `as_str` → `i128`).
fn chc_int_const(value: i128) -> serde_json::Value {
    serde_json::json!({ "kind": "int_const", "value": value.to_string() })
}

/// A `{kind:binary}` expression. `op` must be one of the reader's snake_case
/// binary ops (`add`/`sub`/`mul`/`eq`/`ne`/`lt`/`le`/`gt`/`ge`/`and`/`or`/…).
fn chc_binary(op: &str, lhs: serde_json::Value, rhs: serde_json::Value) -> serde_json::Value {
    serde_json::json!({ "kind": "binary", "op": op, "lhs": lhs, "rhs": rhs })
}

/// Declare a value's top-level `vars` entry once (keyed by SSA index so a value
/// threaded through several blocks is declared exactly once, with a consistent
/// sort — every referenced var must appear in `vars` or ingestion rejects it).
fn chc_declare_var(
    var_decls: &mut BTreeMap<u32, serde_json::Value>,
    value: trust_ir::ValueId,
    sort: &serde_json::Value,
) {
    var_decls
        .entry(value.index())
        .or_insert_with(|| serde_json::json!({ "name": chc_value_var_name(value), "sort": sort }));
}

/// The surviving `(ValueId, sort)` params of a block, in declaration order. This
/// is the single source of truth for a block relation's arity/sorts: it is
/// reused for the relation declaration's `arg_sorts`, every head into the block,
/// and every body premise out of the block, so the reader's strict positional
/// arity+sort match never diverges.
fn chc_block_relation_params(
    block: &trust_ir::Block,
) -> Vec<(trust_ir::ValueId, serde_json::Value)> {
    block
        .params
        .iter()
        .filter_map(|(value, ty)| chc_scalar_sort_json(ty).map(|sort| (*value, sort)))
        .collect()
}

/// Map an integer `BinOp` to its CHC op string. Only `Add`/`Sub`/`Mul` are
/// modeled; every other op (div/rem/bitwise/shift) returns `None` and is havoced
/// (sound over-approximation).
fn chc_map_int_binop(op: trust_ir::BinOp) -> Option<&'static str> {
    match op {
        trust_ir::BinOp::Add => Some("add"),
        trust_ir::BinOp::Sub => Some("sub"),
        trust_ir::BinOp::Mul => Some("mul"),
        _ => None,
    }
}

/// Map an `ICmpOp` to its CHC (mathematical-integer) comparison op. Signed and
/// unsigned compares both map to the integer relation: a value's var carries its
/// non-negative magnitude, under which unsigned compare == integer compare on
/// every real state, so both are sound. The ICmp RESULT is always Bool.
fn chc_map_icmp(op: trust_ir::ICmpOp) -> &'static str {
    use trust_ir::ICmpOp;
    match op {
        ICmpOp::Eq => "eq",
        ICmpOp::Ne => "ne",
        ICmpOp::Ult | ICmpOp::Slt => "lt",
        ICmpOp::Ule | ICmpOp::Sle => "le",
        ICmpOp::Ugt | ICmpOp::Sgt => "gt",
        ICmpOp::Uge | ICmpOp::Sge => "ge",
    }
}

/// Exact inclusive `(min, max)` range of a FIXED-WIDTH SIGNED integer type, for
/// the overflow bit. Returns `None` for unsigned, 128-bit and pointer-width
/// (`Isize`) types: an unbounded-`int` model cannot express 128-bit wrap, and
/// `Isize`'s width is TARGET-dependent (trust-ir v25 carries `isize` faithfully
/// instead of respelling it `I64`), so pinning a 64-bit bound could miss a real
/// 32-bit overflow. Both are havoced (fail-closed) rather than modeled
/// inexactly.
fn chc_signed_overflow_bounds(ty: &trust_ir::Ty) -> Option<(i128, i128)> {
    match ty {
        trust_ir::Ty::I8 => Some((i8::MIN as i128, i8::MAX as i128)),
        trust_ir::Ty::I16 => Some((i16::MIN as i128, i16::MAX as i128)),
        trust_ir::Ty::I32 => Some((i32::MIN as i128, i32::MAX as i128)),
        trust_ir::Ty::I64 => Some((i64::MIN as i128, i64::MAX as i128)),
        _ => None,
    }
}

/// Inclusive maximum `2^W - 1` of a FIXED-WIDTH UNSIGNED integer type.
/// `u64::MAX` (18446744073709551615) fits in `i128`; `u128` does NOT (`2^128 - 1`
/// overflows `i128`) and `Usize` is target-width, so both return `None` and stay
/// gated out / havoced (see [`chc_signed_overflow_bounds`]).
fn chc_unsigned_overflow_max(ty: &trust_ir::Ty) -> Option<i128> {
    match ty {
        trust_ir::Ty::U8 => Some(u8::MAX as i128),
        trust_ir::Ty::U16 => Some(u16::MAX as i128),
        trust_ir::Ty::U32 => Some(u32::MAX as i128),
        trust_ir::Ty::U64 => Some(u64::MAX as i128),
        _ => None,
    }
}

/// Is `ty` an integer width whose overflow this encoder models (signed `i8..i64`
/// or unsigned `u8..u64`)? 128-bit and pointer-width are NOT modeled.
fn chc_overflow_width_modeled(ty: &trust_ir::Ty) -> bool {
    chc_signed_overflow_bounds(ty).is_some() || chc_unsigned_overflow_max(ty).is_some()
}

/// The overflow-safety VIOLATION predicate for a signed OR unsigned `Overflow`,
/// as a Bool expr over the unbounded-`int` result `sum = lhs op rhs`. Returns
/// `None` for widths we do not model (128-bit, pointer-width), which are havoced
/// + gated out.
///
///  * SIGNED `iW`: `sum > iW::MAX ∨ sum < iW::MIN`.
///  * UNSIGNED add/mul (`uW`): `sum > uW::MAX` (the true wrap point, `2^W-1`).
///    SOUND in `int` PROVIDED every unsigned operand carries its type invariant
///    `>= 0` — which is why free unsigned vars get a `>= 0` fact.
///  * UNSIGNED sub (`uW`): underflow `sum < 0` (i.e. `lhs < rhs`).
fn chc_overflow_violation(
    op: trust_ir::OverflowOp,
    ty: &trust_ir::Ty,
    sum: &serde_json::Value,
) -> Option<serde_json::Value> {
    if let Some((min, max)) = chc_signed_overflow_bounds(ty) {
        return Some(chc_binary(
            "or",
            chc_binary("gt", sum.clone(), chc_int_const(max)),
            chc_binary("lt", sum.clone(), chc_int_const(min)),
        ));
    }
    let unsigned_max = chc_unsigned_overflow_max(ty)?;
    Some(match op {
        // `a + b` / `a * b` overflow above `2^W - 1`.
        trust_ir::OverflowOp::AddOverflow | trust_ir::OverflowOp::MulOverflow => {
            chc_binary("gt", sum.clone(), chc_int_const(unsigned_max))
        }
        // `a - b` underflows below 0 (unsigned).
        trust_ir::OverflowOp::SubOverflow => chc_binary("lt", sum.clone(), chc_int_const(0)),
    })
}

/// Type-invariant range facts `[v >= 0, v <= 2^W - 1]` for an UNSIGNED value of a
/// modeled width, else empty. These are emitted ONLY for FREE unsigned vars
/// (entry params) — where the var is unconstrained and the facts merely remove
/// the NON-REAL negative / oversized model states (SOUND). They must NOT be
/// attached to a fold-defined value (e.g. an unsigned subtraction result), where
/// conjoining `>= 0` with its defining equality would exclude REAL wrap states —
/// see the module soundness note.
fn chc_unsigned_range_facts(
    value: trust_ir::ValueId,
    ty: &trust_ir::Ty,
    var_decls: &mut BTreeMap<u32, serde_json::Value>,
) -> Vec<serde_json::Value> {
    let Some(max) = chc_unsigned_overflow_max(ty) else {
        return Vec::new();
    };
    let int = serde_json::json!({ "kind": "int" });
    chc_declare_var(var_decls, value, &int);
    vec![
        chc_binary("ge", chc_var_expr(value, &int), chc_int_const(0)),
        chc_binary("le", chc_var_expr(value, &int), chc_int_const(max)),
    ]
}

/// Straight-line fold of a block body (everything before the terminator).
/// Returns `(constraints, overflow_violations)`: `constraints` are the
/// Bool-sorted equalities carried on the block's outgoing transitions;
/// `overflow_violations` are the per-`Overflow` out-of-range Bool predicates used
/// by `ArithmeticSafetyOnly` mode to build DIRECT `error` edges (unused by
/// `Structural` mode). Every referenced value is declared. Unmodeled
/// instructions are HAVOCed (emit nothing) — a sound over-approximation.
fn chc_fold_block_body(
    block: &trust_ir::Block,
    var_decls: &mut BTreeMap<u32, serde_json::Value>,
) -> (Vec<serde_json::Value>, Vec<serde_json::Value>) {
    let int = serde_json::json!({ "kind": "int" });
    let boolean = serde_json::json!({ "kind": "bool" });
    let mut constraints = Vec::new();
    let mut overflow_violations = Vec::new();
    // `block.instructions()` / `block.body` INCLUDE the terminator node; the
    // straight-line fold must skip it.
    for node in block.body.iter().filter(|node| !node.is_terminator()) {
        match &node.inst {
            trust_ir::Inst::BinOp { op, ty, lhs, rhs } if ty.is_integer() => {
                let Some(mapped) = chc_map_int_binop(*op) else { continue };
                let Some(dest) = node.results.first() else { continue };
                chc_declare_var(var_decls, *dest, &int);
                chc_declare_var(var_decls, *lhs, &int);
                chc_declare_var(var_decls, *rhs, &int);
                constraints.push(chc_binary(
                    "eq",
                    chc_var_expr(*dest, &int),
                    chc_binary(mapped, chc_var_expr(*lhs, &int), chc_var_expr(*rhs, &int)),
                ));
            }
            trust_ir::Inst::Overflow { op, ty, lhs, rhs } => {
                // results[0] = wrapped value, results[1] = overflow bit (Bool).
                // Model signed `i8..i64` AND unsigned `u8..u64` (the unsigned wrap
                // point `2^W-1` fits in `i128`). 128-bit and pointer-width are NOT
                // modeled, so havoc the whole instruction (and gate it out).
                // SOUNDNESS for unsigned: the `> 2^W-1` test is faithful only if the
                // operands carry their `>= 0` type invariant — that is enforced for
                // FREE unsigned vars (entry params) elsewhere.
                if !chc_overflow_width_modeled(ty) {
                    continue;
                }
                let Some(value) = node.results.first() else { continue };
                let overflow_bit = node.results.get(1);
                chc_declare_var(var_decls, *value, &int);
                chc_declare_var(var_decls, *lhs, &int);
                chc_declare_var(var_decls, *rhs, &int);
                let op_string = match op {
                    trust_ir::OverflowOp::AddOverflow => "add",
                    trust_ir::OverflowOp::SubOverflow => "sub",
                    trust_ir::OverflowOp::MulOverflow => "mul",
                };
                let sum =
                    chc_binary(op_string, chc_var_expr(*lhs, &int), chc_var_expr(*rhs, &int));
                // On the ¬overflow branch this equality is exact; on the overflow
                // branch the guard (`overflow_bit` true) routes control to the panic
                // split, so the unbounded value is never used to conclude SAFE.
                constraints.push(chc_binary("eq", chc_var_expr(*value, &int), sum.clone()));
                // The overflow-safety VIOLATION predicate (signed range test, or the
                // unsigned `> 2^W-1` / `< 0` wrap test). Carried for the
                // `ArithmeticSafetyOnly` direct `error` edge, and also (when present)
                // defining the overflow-bit result.
                let Some(out_of_range) = chc_overflow_violation(*op, ty, &sum) else { continue };
                if let Some(overflow_bit) = overflow_bit {
                    chc_declare_var(var_decls, *overflow_bit, &boolean);
                    constraints.push(chc_binary(
                        "eq",
                        chc_var_expr(*overflow_bit, &boolean),
                        out_of_range.clone(),
                    ));
                }
                overflow_violations.push(out_of_range);
            }
            trust_ir::Inst::Const { ty, value } if ty.is_integer() => {
                if let trust_ir::Constant::Int(literal) = value {
                    let Some(dest) = node.results.first() else { continue };
                    chc_declare_var(var_decls, *dest, &int);
                    constraints
                        .push(chc_binary("eq", chc_var_expr(*dest, &int), chc_int_const(*literal)));
                }
            }
            trust_ir::Inst::Copy { ty, operand } if ty.is_integer() => {
                let Some(dest) = node.results.first() else { continue };
                chc_declare_var(var_decls, *dest, &int);
                chc_declare_var(var_decls, *operand, &int);
                constraints.push(chc_binary(
                    "eq",
                    chc_var_expr(*dest, &int),
                    chc_var_expr(*operand, &int),
                ));
            }
            trust_ir::Inst::ICmp { op, ty, lhs, rhs } if ty.is_integer() => {
                let mapped = chc_map_icmp(*op);
                let Some(dest) = node.results.first() else { continue };
                // Result is Bool even though `ty` names the OPERAND type.
                chc_declare_var(var_decls, *dest, &boolean);
                chc_declare_var(var_decls, *lhs, &int);
                chc_declare_var(var_decls, *rhs, &int);
                constraints.push(chc_binary(
                    "eq",
                    chc_var_expr(*dest, &boolean),
                    chc_binary(mapped, chc_var_expr(*lhs, &int), chc_var_expr(*rhs, &int)),
                ));
            }
            // Everything else — including every `Call` result: havoc (emit
            // nothing). Sound over-approximation.
            _ => {}
        }
    }
    (constraints, overflow_violations)
}

/// Build one enriched transition rule `bb(target params) :- bb(source params),
/// body_constraints`, threading the edge's block args into the target head and
/// declaring every referenced value. Returns `None` (⇒ abort enrichment, fall
/// back to structural) on an SSA arity mismatch between the edge args and the
/// target block params.
fn chc_transition_rule(
    source: &trust_ir::Block,
    target: &trust_ir::Block,
    edge_args: &[trust_ir::ValueId],
    body_constraints: Vec<serde_json::Value>,
    var_decls: &mut BTreeMap<u32, serde_json::Value>,
) -> Option<serde_json::Value> {
    if edge_args.len() != target.params.len() {
        return None;
    }
    // Body premise: the source block's canonical params.
    let source_params = chc_block_relation_params(source);
    for (value, sort) in &source_params {
        chc_declare_var(var_decls, *value, sort);
    }
    let source_args: Vec<_> =
        source_params.iter().map(|(value, sort)| chc_var_expr(*value, sort)).collect();
    // Head: for each surviving target param position, thread the edge actual
    // (same sort by SSA well-typedness).
    let mut head_args = Vec::new();
    for (position, (_param, param_ty)) in target.params.iter().enumerate() {
        if let Some(sort) = chc_scalar_sort_json(param_ty) {
            let actual = edge_args[position];
            chc_declare_var(var_decls, actual, &sort);
            head_args.push(chc_var_expr(actual, &sort));
        }
    }
    Some(serde_json::json!({
        "head": { "name": trust_mc_default_block_relation(target.id), "args": head_args },
        "body": {
            "relation": { "name": trust_mc_default_block_relation(source.id), "args": source_args },
            "constraints": body_constraints,
        },
    }))
}

/// Build one structural `error` edge `error :- bb(source params), [bool_const]`
/// with the block's canonical args (so it matches the enriched relation arity).
/// This mirrors [`trust_mc_default_error_rule`] exactly, preserving every
/// structural error edge in the enriched path (and keeping the non-vacuity gate
/// satisfied — every `error` rule retains a relation premise).
fn chc_error_rule(
    source: &trust_ir::Block,
    reachable: bool,
    reason: String,
    var_decls: &mut BTreeMap<u32, serde_json::Value>,
) -> serde_json::Value {
    let params = chc_block_relation_params(source);
    for (value, sort) in &params {
        chc_declare_var(var_decls, *value, sort);
    }
    let args: Vec<_> = params.iter().map(|(value, sort)| chc_var_expr(*value, sort)).collect();
    serde_json::json!({
        "head": { "name": "error" },
        "body": {
            "relation": { "name": trust_mc_default_block_relation(source.id), "args": args },
            "constraints": [
                {
                    "kind": "bool_const",
                    "value": reachable,
                    "reason": reason,
                }
            ],
        },
    })
}

/// Build one DIRECT arithmetic-overflow `error` edge for `ArithmeticSafetyOnly`
/// mode: `error :- bbB(source params), [fold..., violation]`. The block fold is
/// conjoined so the violation's `lhs`/`rhs` are tied to the block params (a bare
/// violation over free vars would be trivially satisfiable and prove nothing);
/// `violation` is the out-of-range predicate. This is the genuine
/// overflow-safety property — it is the ONLY error route in this mode.
fn chc_overflow_error_rule(
    source: &trust_ir::Block,
    fold: &[serde_json::Value],
    violation: &serde_json::Value,
    var_decls: &mut BTreeMap<u32, serde_json::Value>,
) -> serde_json::Value {
    let params = chc_block_relation_params(source);
    for (value, sort) in &params {
        chc_declare_var(var_decls, *value, sort);
    }
    let args: Vec<_> = params.iter().map(|(value, sort)| chc_var_expr(*value, sort)).collect();
    let mut constraints = fold.to_vec();
    constraints.push(violation.clone());
    serde_json::json!({
        "head": { "name": "error" },
        "body": {
            "relation": { "name": trust_mc_default_block_relation(source.id), "args": args },
            "constraints": constraints,
        },
    })
}

/// Data-flow-enriched parallel of [`trust_mc_default_function_chc_from_trust_ir`].
///
/// Returns `Ok(Some((relations, rules, vars)))` when the function is fully in
/// scope and every block could be framed faithfully; returns `Ok(None)`
/// (fail-closed hatch) to request the untouched structural fallback; returns
/// `Err` only for the same hard errors the structural encoder reports (missing
/// function / no blocks). NEVER emits a false SAFE — see the module comment above
/// for the soundness discipline.
fn trust_mc_dataflow_function_chc_from_trust_ir(
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    request: &trust_ir::TrustMcNativeRequest,
    error_mode: ChcErrorMode,
) -> Result<Option<(serde_json::Value, serde_json::Value, Vec<serde_json::Value>)>, String> {
    let function =
        native_trust_ir_bundle.module.function_by_id(request.function).ok_or_else(|| {
            format!(
                "data-flow trust-mc function admission cannot find TrustIr function {}",
                request.function.index()
            )
        })?;
    trust_mc_dataflow_chc_for_function(function, error_mode)
}

/// The `Function`-level core of the data-flow encoder, split out from the
/// bundle/request resolution above so it is unit-testable against a hand-built
/// `trust_ir::Function`. This wrapper adds the runtime
/// `TRUST_MC_DATAFLOW_CHC_DEBUG` firing trace around the pure encoder.
fn trust_mc_dataflow_chc_for_function(
    function: &trust_ir::Function,
    error_mode: ChcErrorMode,
) -> Result<Option<(serde_json::Value, serde_json::Value, Vec<serde_json::Value>)>, String> {
    let outcome = trust_mc_dataflow_chc_for_function_impl(function, error_mode)?;
    if trust_mc_dataflow_chc_debug_enabled() {
        match &outcome {
            Some((relations, rules, _)) => eprintln!(
                "[DATAFLOW-FIRED] fn={} mode={error_mode:?} relations={} rules={}",
                function.name,
                relations.as_array().map_or(0, |array| array.len()),
                rules.as_array().map_or(0, |array| array.len()),
            ),
            None => eprintln!(
                "[DATAFLOW-FALLBACK] fn={} mode={error_mode:?} reason=out-of-scope \
                 (missing-terminator / edge-arity-mismatch / unmodeled-terminator / \
                 unmodeled-arithmetic / no-overflow-edge)",
                function.name,
            ),
        }
    }
    Ok(outcome)
}

/// The pure `Function`-level encoder (no I/O). Same contract: `Ok(Some(..))` when
/// fully enriched, `Ok(None)` to request the structural fallback, `Err` only on a
/// function with no blocks / an unresolvable entry. `error_mode` selects which
/// `error` edges are emitted (see [`ChcErrorMode`]).
fn trust_mc_dataflow_chc_for_function_impl(
    function: &trust_ir::Function,
    error_mode: ChcErrorMode,
) -> Result<Option<(serde_json::Value, serde_json::Value, Vec<serde_json::Value>)>, String> {
    if function.blocks.is_empty() {
        return Err(format!(
            "data-flow trust-mc function admission for `{}` has no typed TrustIr blocks",
            function.name
        ));
    }

    // Fail-closed pre-check: a block with no terminator is malformed IR — fall
    // back to the structural encoder for the whole function. Every real terminator
    // kind IS modeled below (mirroring the structural encoder exactly), so a
    // function is enriched whenever the structural encoder would accept it. The
    // only other fallbacks are an SSA edge arity mismatch (`chc_transition_rule`
    // returns `None`) and any future/unknown terminator kind (the `_` arm).
    for block in &function.blocks {
        if block.terminator().is_none() {
            return Ok(None);
        }
    }

    // ArithmeticSafetyOnly soundness gate: if the function has an arithmetic-safety
    // op we do NOT model as an `error` edge, the whole-function overflow CHC would
    // miss it and could falsely discharge that op's obligation — fall back instead.
    if error_mode == ChcErrorMode::ArithmeticSafetyOnly
        && !function_overflow_surface_fully_modeled(function)
    {
        return Ok(None);
    }

    let bool_sort = serde_json::json!({ "kind": "bool" });
    let mut var_decls: BTreeMap<u32, serde_json::Value> =
        BTreeMap::new();
    // Set when an `ArithmeticSafetyOnly` overflow `error` edge is emitted; if none
    // are, the CHC would prove `error` unreachable vacuously (a false SAFE), so we
    // fall back below.
    let mut any_overflow_error = false;

    // Relations: `error` + one relation per block carrying its canonical
    // (int/bool) param projection as `arg_sorts`.
    let mut relations = Vec::with_capacity(function.blocks.len() + 1);
    relations.push(serde_json::json!({ "name": "error" }));
    for block in &function.blocks {
        let arg_sorts: Vec<_> =
            chc_block_relation_params(block).into_iter().map(|(_, sort)| sort).collect();
        relations.push(serde_json::json!({
            "name": trust_mc_default_block_relation(block.id),
            "arg_sorts": arg_sorts,
        }));
    }

    let mut rules: Vec<serde_json::Value> = Vec::new();

    // Entry fact: `bbEntry(params) :- (empty body)` — all params FREE (full input
    // havoc). Constraining them would under-approximate the input space.
    {
        let entry_block = function.block(function.entry).ok_or_else(|| {
            format!(
                "data-flow trust-mc function admission for `{}` cannot resolve entry block {}",
                function.name,
                function.entry.index()
            )
        })?;
        let entry_params = chc_block_relation_params(entry_block);
        for (value, sort) in &entry_params {
            chc_declare_var(&mut var_decls, *value, sort);
        }
        let entry_args: Vec<_> =
            entry_params.iter().map(|(value, sort)| chc_var_expr(*value, sort)).collect();
        // In ArithmeticSafetyOnly mode, constrain each unsigned ENTRY param (a
        // genuinely-free function input) with its type invariant `0 <= p <= 2^W-1`.
        // SOUND: it removes only NON-REAL negative/oversized model states of a free
        // var, and it is what lets PDR bound an unsigned accumulator. Omitted in
        // Structural mode so the default_function encoding keeps its exact shape.
        let mut entry_constraints: Vec<serde_json::Value> = Vec::new();
        if error_mode == ChcErrorMode::ArithmeticSafetyOnly {
            for (value, ty) in &entry_block.params {
                entry_constraints.extend(chc_unsigned_range_facts(*value, ty, &mut var_decls));
            }
        }
        rules.push(serde_json::json!({
            "head": { "name": trust_mc_default_block_relation(function.entry), "args": entry_args },
            "body": { "constraints": entry_constraints },
        }));
    }

    for block in &function.blocks {
        // Terminator presence was validated by the pre-check above.
        let Some(terminator) = block.terminator() else {
            return Ok(None);
        };
        // `fold` (kept owned for the ArithmeticSafetyOnly error edges below) is
        // CLONED into every outgoing transition; `overflow_violations` are the
        // per-`Overflow` out-of-range predicates for the direct overflow edges.
        let (fold, overflow_violations) = chc_fold_block_body(block, &mut var_decls);

        // Tracks whether this block already routes to `error` (Structural mode
        // only), so the `reachable:false` placeholder is emitted only when it does
        // not. Set by the `Unreachable` arm and the fail-closed-instruction scan.
        let mut emitted_error_rule = false;
        match &terminator.inst {
            trust_ir::Inst::Br { target, args } => {
                let Some(target_block) = function.block(*target) else {
                    return Ok(None);
                };
                let Some(rule) =
                    chc_transition_rule(block, target_block, args, fold.clone(), &mut var_decls)
                else {
                    return Ok(None);
                };
                rules.push(rule);
            }
            trust_ir::Inst::CondBr { cond, then_target, then_args, else_target, else_args } => {
                chc_declare_var(&mut var_decls, *cond, &bool_sort);
                let (Some(then_block), Some(else_block)) =
                    (function.block(*then_target), function.block(*else_target))
                else {
                    return Ok(None);
                };
                // then-edge: guard `cond` holds.
                let mut then_constraints = fold.clone();
                then_constraints.push(chc_var_expr(*cond, &bool_sort));
                let Some(then_rule) = chc_transition_rule(
                    block,
                    then_block,
                    then_args,
                    then_constraints,
                    &mut var_decls,
                ) else {
                    return Ok(None);
                };
                rules.push(then_rule);
                // else-edge: guard `¬cond`.
                let mut else_constraints = fold.clone();
                else_constraints.push(serde_json::json!({
                    "kind": "unary",
                    "op": "not",
                    "expr": chc_var_expr(*cond, &bool_sort),
                }));
                let Some(else_rule) = chc_transition_rule(
                    block,
                    else_block,
                    else_args,
                    else_constraints,
                    &mut var_decls,
                ) else {
                    return Ok(None);
                };
                rules.push(else_rule);
            }
            // No in-function successor — like the structural encoder, emit no
            // transition rule. (`fold` is discarded; its only role was to build
            // transition constraints.)
            trust_ir::Inst::Return { .. } => {}
            // The panic sink. In `Structural` mode, model it EXACTLY as the
            // structural encoder does — a REACHABLE `error` edge with the block's
            // canonical data-flow args (weakens toward true → never a false SAFE).
            // In `ArithmeticSafetyOnly` mode it is a PURE SINK (no error edge): an
            // unrelated panic must NOT make `error` reachable, or it would block the
            // overflow proof — that panic is a DIFFERENT obligation, proved apart.
            trust_ir::Inst::Unreachable => {
                if error_mode == ChcErrorMode::Structural {
                    rules.push(chc_error_rule(
                        block,
                        true,
                        format!(
                            "typed TrustIr block {} reaches an unreachable terminator",
                            block.id.index()
                        ),
                        &mut var_decls,
                    ));
                    emitted_error_rule = true;
                }
            }
            // Multi-way branch. Mirror the structural encoder: an edge to
            // `default` (unless the TyCtxt-vetted exhaustive-enum flag certifies it
            // dead — the one edge-drop precedent, matched exactly) and one to every
            // case target. NO per-case discriminant guard is added — an unguarded
            // edge is a sound over-approximation (precision, not soundness). Each
            // edge threads its own block args + the block fold.
            trust_ir::Inst::Switch {
                default,
                default_args,
                cases,
                exhaustive_enum_unreachable,
                ..
            } => {
                if !*exhaustive_enum_unreachable {
                    let Some(default_block) = function.block(*default) else {
                        return Ok(None);
                    };
                    let Some(rule) = chc_transition_rule(
                        block,
                        default_block,
                        default_args,
                        fold.clone(),
                        &mut var_decls,
                    ) else {
                        return Ok(None);
                    };
                    rules.push(rule);
                }
                for case in cases {
                    let Some(case_block) = function.block(case.target) else {
                        return Ok(None);
                    };
                    let Some(rule) = chc_transition_rule(
                        block,
                        case_block,
                        &case.args,
                        fold.clone(),
                        &mut var_decls,
                    ) else {
                        return Ok(None);
                    };
                    rules.push(rule);
                }
            }
            // Call with two successors (Itanium/LLVM `invoke`). Mirror the
            // structural encoder: carry reachability along BOTH edges. The callee's
            // return value bound on the normal edge is HAVOC'd — a fresh
            // unconstrained SSA value. The unwind edge carries no block args: the
            // landing pad receives the exception via its `LandingPad` instruction,
            // not via block params.
            trust_ir::Inst::Invoke { normal_dest, normal_args, unwind_dest, .. } => {
                let Some(normal_block) = function.block(*normal_dest) else {
                    return Ok(None);
                };
                let Some(normal_rule) = chc_transition_rule(
                    block,
                    normal_block,
                    normal_args,
                    fold.clone(),
                    &mut var_decls,
                ) else {
                    return Ok(None);
                };
                rules.push(normal_rule);
                let Some(unwind_block) = function.block(*unwind_dest) else {
                    return Ok(None);
                };
                let Some(unwind_rule) =
                    chc_transition_rule(block, unwind_block, &[], fold.clone(), &mut var_decls)
                else {
                    return Ok(None);
                };
                rules.push(unwind_rule);
            }
            // Return-like / divergent terminators with NO in-function successor —
            // mirror the structural encoder (no transition rule). `CoroSuspend`
            // saves its resume state and returns to the resumer; `Resume` re-raises
            // the in-flight exception to the unwinder. The `reachable:false`
            // placeholder below fires for these blocks, exactly as for `Return`.
            trust_ir::Inst::CoroSuspend { .. } | trust_ir::Inst::Resume { .. } => {}
            // Any future/unknown terminator kind → fall back to the untouched
            // structural encoder for the whole function (sound: never a false SAFE).
            _ => return Ok(None),
        }

        match error_mode {
            // Structural: preserve every structural `error` edge, with canonical
            // block args so the relation-app arity matches the relation declaration
            // — fail-closed-admission edges + the reachable:false placeholder. (The
            // `Unreachable`→error edge was emitted above.)
            ChcErrorMode::Structural => {
                for instruction in block.instructions() {
                    if trust_mc_default_instruction_requires_fail_closed_admission(instruction) {
                        rules.push(chc_error_rule(
                            block,
                            true,
                            format!(
                                "typed TrustIr block {} contains unsupported native trust-mc admission instruction {:?}",
                                block.id.index(),
                                instruction.inst
                            ),
                            &mut var_decls,
                        ));
                        emitted_error_rule = true;
                    }
                }
                if !emitted_error_rule {
                    rules.push(chc_error_rule(
                        block,
                        false,
                        format!(
                            "typed TrustIr block {} has no reachable native trust-mc admission error",
                            block.id.index()
                        ),
                        &mut var_decls,
                    ));
                }
            }
            // ArithmeticSafetyOnly: the ONLY `error` edges are the direct
            // arithmetic-overflow violations from this block's fold. No
            // Unreachable/admission/placeholder edges — unrelated panics/closures
            // are pure havoc'd transitions. The block fold is conjoined so the
            // violation is tied to the block params.
            ChcErrorMode::ArithmeticSafetyOnly => {
                for violation in &overflow_violations {
                    rules.push(chc_overflow_error_rule(block, &fold, violation, &mut var_decls));
                    any_overflow_error = true;
                }
            }
        }
    }

    // A vacuous ArithmeticSafetyOnly CHC (no overflow `error` edge at all) would
    // prove `error` unreachable trivially — a false SAFE for whatever obligation
    // was redirected. Fall back to the single-formula path instead.
    if error_mode == ChcErrorMode::ArithmeticSafetyOnly && !any_overflow_error {
        return Ok(None);
    }

    let vars: Vec<serde_json::Value> = var_decls.into_values().collect();
    Ok(Some((serde_json::Value::Array(relations), serde_json::Value::Array(rules), vars)))
}

fn trust_mc_public_typed_chc_contract_for_obligation(
    native_function_name: &str,
    func: &trust_types::VerifiableFunction,
    expected_crate_name: Option<&str>,
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<trust_verifier_api::TrustContract>, String> {
    if obligation.is_default_admission()
        || obligation_is_synthesized_whole_function_panic_freedom(
            func,
            expected_crate_name,
            obligation,
        )
    {
        return Ok(None);
    }
    let TrustMcTypedChcLowering::Supported(chc_constraint) =
        trust_mc_typed_chc_lowering_for_obligation(obligation)
    else {
        return Ok(None);
    };
    let contract_id = format!(
        "contract:trust-mc-typed-chc-public:{}",
        domain_length_bound_sha256_hex(
            "trustc.trust-mc-public-contract-id.v1",
            obligation.obligation_id.as_bytes(),
        )
    );
    let value = serde_json::json!({
        "schema_version": TRUST_MC_TYPED_CHC_OBLIGATION_SCHEMA,
        "obligation_id": obligation.obligation_id,
        "origin": "mir_derived",
        "function_name": native_function_name,
        "query": { "target": "error" },
        "vars": chc_constraint.vars,
        "relations": [{ "name": "error" }],
        "rules": [{
            "head": { "name": "error" },
            "body": { "constraints": [chc_constraint.constraint] },
        }],
    });
    Ok(Some(trust_verifier_api::TrustContract {
        contract_id,
        kind: trust_verifier_api::ContractKind::Asserts,
        predicate: trust_verifier_api::ContractPredicate::MathIr {
            schema: TRUST_MC_TYPED_CHC_OBLIGATION_SCHEMA.to_string(),
            value,
        },
        source: obligation.source.clone(),
        metadata: vec![trust_verifier_api::MetadataEntry {
            key: "trust-trust-mc.typed-chc-obligation.source".to_string(),
            value: "compiler-public-trust-spec-vc".to_string(),
        }],
    }))
}

fn obligation_is_synthesized_whole_function_panic_freedom(
    func: &trust_types::VerifiableFunction,
    expected_crate_name: Option<&str>,
    obligation: &trust_verifier_api::TrustObligation,
) -> bool {
    let expected_obligation_id = format!(
        "vc:{}:assertion:panic-freedom:0",
        trust_types::canonical_artifact_id_component(&func.def_path)
    );
    let Ok(expected_source_digest) = compiler_function_source_digest_hex(func) else {
        return false;
    };
    let Ok(expected_vc_digest) = default_trust_mc_function_obligation_digest(
        func,
        &format!("panic-freedom:{}", func.def_path),
    ) else {
        return false;
    };
    let mut metadata_keys = FxHashSet::default();
    if obligation.metadata.iter().any(|entry| {
        !metadata_keys.insert(entry.key.as_str())
            || !matches!(
                entry.key.as_str(),
                trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY
                    | TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY
                    | "trust.vc.kind"
                    | TRUST_SOURCE_DIGEST_METADATA_KEY
                    | TRUST_VC_DIGEST_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_LOWERING_STATUS_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_UNSUPPORTED_REASON_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_SYNTHETIC_CONTRACT_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_SOURCE_DIGEST_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_VC_DIGEST_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_SYNTHETIC_DIGEST_METADATA_KEY
                    | TRUST_MC_TYPED_CHC_BINDING_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_TRANSPORT_STATUS_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_UNSUPPORTED_REASON_METADATA_KEY
                    | trust_router::full_verification::TRUST_TRUST_IR_NATIVE_VERIFIER_SUITE_METADATA_KEY
                    | trust_router::full_verification::TRUST_TRUST_IR_NATIVE_REQUEST_ID_METADATA_KEY
                    | trust_router::full_verification::TRUST_TRUST_IR_NATIVE_PROOF_OBLIGATION_ID_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_PROOF_UNIT_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_ASSERTION_ID_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_TRUST_IR_MODULE_DIGEST_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_REQUEST_DIGEST_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_COMPILER_FACTS_DIGEST_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_OBLIGATION_SOURCE_DIGEST_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_REPLAY_ENGINE_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_REPLAY_INVOCATION_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_REPLAY_TRANSCRIPT_DIGEST_METADATA_KEY
                    | TRUST_TRUST_IR_NATIVE_ARTIFACT_FINGERPRINT_METADATA_KEY
            )
    }) {
        return false;
    }
    if obligation.obligation_id != expected_obligation_id
        || obligation.kind != trust_verifier_api::ObligationKind::Assertion
        || obligation.contract_id.is_some()
        || obligation.proof_item_id.is_some()
        || obligation.source != source_location_from_trust_span(&func.span)
        || obligation.required_strength.is_some()
        || !obligation.summary_facts.is_empty()
        || unique_api_obligation_metadata_value(
            obligation,
            TRUST_MC_PANIC_FREEDOM_OBLIGATION_METADATA_KEY,
        ) != Some("enabled")
        || unique_api_obligation_metadata_value(obligation, "trust.vc.kind")
            != Some("panic_freedom")
        || unique_api_obligation_metadata_value(obligation, TRUST_SOURCE_DIGEST_METADATA_KEY)
            != Some(expected_source_digest.as_str())
        || unique_api_obligation_metadata_value(obligation, TRUST_VC_DIGEST_METADATA_KEY)
            != Some(expected_vc_digest.as_str())
    {
        return false;
    }

    let mut contexts = obligation
        .metadata
        .iter()
        .filter(|entry| entry.key == trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY);
    let Some(context_entry) = contexts.next() else {
        return false;
    };
    if contexts.next().is_some() {
        return false;
    }
    let Ok(Some(context)) =
        trust_verifier_api::ObligationContext::from_metadata_entry(context_entry)
    else {
        return false;
    };
    if !context.has_current_schema()
        || !matches!(context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
    {
        return false;
    }
    let Some(function) = context.function.as_ref() else { return false };
    if function.crate_name.trim().is_empty()
        || function.path != func.def_path
        || expected_crate_name.is_some_and(|expected| function.crate_name != expected)
    {
        return false;
    }
    matches!(
        context.origin,
        trust_verifier_api::ObligationOrigin::VerificationCondition {
            ref vc_kind,
            vc_index: 0,
            formula_schema: None,
        } if vc_kind == "panic_freedom"
    )
}

fn unique_api_obligation_metadata_value<'a>(
    obligation: &'a trust_verifier_api::TrustObligation,
    key: &str,
) -> Option<&'a str> {
    let mut values = obligation
        .metadata
        .iter()
        .filter(|entry| entry.key == key)
        .map(|entry| entry.value.as_str());
    let value = values.next()?;
    values.next().is_none().then_some(value)
}

fn api_obligation_metadata_value<'a>(
    obligation: &'a trust_verifier_api::TrustObligation,
    key: &str,
) -> Option<&'a str> {
    obligation.metadata.iter().find(|entry| entry.key == key).map(|entry| entry.value.as_str())
}

fn finalize_trust_mc_public_semantic_contracts(
    native_function_name: &str,
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    bindings: &[PendingNativeTrustIrBinding],
) -> Result<(), String> {
    let expected_crate_name = match &bundle.subject {
        trust_verifier_api::BundleSubject::Function { crate_name, path }
            if !crate_name.trim().is_empty() && path == &func.def_path =>
        {
            Some(crate_name.clone())
        }
        _ => None,
    };
    let mut derived_contracts = Vec::new();
    for binding in
        bindings.iter().filter(|binding| binding.verifier_suite.eq_ignore_ascii_case("trust-mc"))
    {
        let obligation = bundle.obligations.get(binding.obligation_index).ok_or_else(|| {
            format!(
                "native TrustIr binding referenced missing public obligation index {}",
                binding.obligation_index
            )
        })?;
        let Some(derived_contract) = trust_mc_public_typed_chc_contract_for_obligation(
            native_function_name,
            func,
            expected_crate_name.as_deref(),
            obligation,
        )?
        else {
            continue;
        };
        if let Some(existing) = bundle
            .contracts
            .iter()
            .chain(derived_contracts.iter())
            .find(|contract| contract.contract_id == derived_contract.contract_id)
        {
            if existing != &derived_contract {
                return Err(format!(
                    "compiler-derived trust-mc public contract identity `{}` collides with different contents",
                    derived_contract.contract_id
                ));
            }
        } else {
            derived_contracts.push(derived_contract.clone());
        }

        let obligation = bundle
            .obligations
            .get_mut(binding.obligation_index)
            .expect("validated native binding index changed while finalizing contracts");
        let original_contract_id =
            obligation.contract_id.replace(derived_contract.contract_id.clone());
        if let Some(original_contract_id) = original_contract_id
            && original_contract_id != derived_contract.contract_id
        {
            set_obligation_metadata(
                obligation,
                TRUST_MC_TYPED_CHC_ORIGINAL_CONTRACT_METADATA_KEY,
                original_contract_id,
            );
        }
    }
    bundle.contracts.extend(derived_contracts);
    bundle.validate().map_err(|error| {
        format!("compiler-derived trust-mc public semantic contract finalization failed: {error}")
    })
}

fn finalize_trust_wp_public_semantic_contracts(
    bundle: &mut trust_verifier_api::TrustContractBundle,
    bindings: &[PendingNativeTrustIrBinding],
) -> Result<(), String> {
    let mut derived_contracts = Vec::new();
    for binding in
        bindings.iter().filter(|binding| binding.verifier_suite.eq_ignore_ascii_case("trust-wp"))
    {
        let obligation = bundle.obligations.get(binding.obligation_index).ok_or_else(|| {
            format!(
                "native TrustIr binding referenced missing public obligation index {}",
                binding.obligation_index
            )
        })?;
        let Some(derived_contract) = trust_wp_typed_contract_for_public_obligation(obligation)?
        else {
            // A pre-existing typed contract remains the public claim. No
            // compiler-derived contract is needed when there is no supported
            // metadata predicate to materialize.
            continue;
        };
        let derived_claim = trust_wp_public_typed_proof_claim_from_contract_predicate(
            &derived_contract.contract_id,
            &obligation.obligation_id,
            &derived_contract.predicate,
        )?
        .ok_or_else(|| {
            format!(
                "compiler-derived trust-wp contract `{}` for obligation `{}` did not contain a supported typed claim",
                derived_contract.contract_id, obligation.obligation_id
            )
        })?;
        if let Some(existing_claim) =
            trust_wp_public_typed_proof_claim(&bundle.contracts, obligation)?
            && existing_claim != derived_claim
        {
            return Err(format!(
                "public trust-wp contract and compiler typed-formula metadata disagree for obligation `{}`",
                obligation.obligation_id
            ));
        }
        if let Some(existing) = bundle
            .contracts
            .iter()
            .chain(derived_contracts.iter())
            .find(|contract| contract.contract_id == derived_contract.contract_id)
        {
            if existing != &derived_contract {
                return Err(format!(
                    "compiler-derived trust-wp contract identity `{}` collides with different public contract contents",
                    derived_contract.contract_id
                ));
            }
        } else {
            derived_contracts.push(derived_contract.clone());
        }

        let obligation = bundle
            .obligations
            .get_mut(binding.obligation_index)
            .expect("validated native binding index changed while finalizing contracts");
        let original_contract_id =
            obligation.contract_id.replace(derived_contract.contract_id.clone());
        if let Some(original_contract_id) = original_contract_id
            && original_contract_id != derived_contract.contract_id
        {
            set_obligation_metadata(
                obligation,
                TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY,
                original_contract_id,
            );
        }
        set_obligation_metadata(
            obligation,
            TRUST_WP_TYPED_FORMULA_SYNTHETIC_CONTRACT_METADATA_KEY,
            derived_contract.contract_id,
        );
    }
    bundle.contracts.extend(derived_contracts);
    bundle.validate().map_err(|error| {
        format!("compiler-derived trust-wp public semantic contract finalization failed: {error}")
    })
}

fn trust_wp_typed_contract_for_public_obligation(
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<trust_verifier_api::TrustContract>, String> {
    let Some(predicate) = trust_wp_typed_contract_predicate_from_obligation_metadata(obligation)?
    else {
        return Ok(None);
    };
    let contract_id = format!(
        "contract:trust-wp-typed-formula:{}",
        trust_types::stable_sha256_hex(
            format!("trustc.trust-wp.public-typed-contract.v1\0{}", obligation.obligation_id)
                .as_bytes(),
        )
    );
    Ok(Some(trust_verifier_api::TrustContract {
        contract_id,
        kind: trust_wp_contract_kind_for_obligation(&obligation.kind),
        predicate,
        source: obligation.source.clone(),
        metadata: vec![trust_verifier_api::MetadataEntry {
            key: TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY.to_string(),
            value: TRUST_WP_TYPED_FORMULA_SOURCE_COMPILER_VC_VALUE.to_string(),
        }],
    }))
}

fn trust_wp_typed_contract_predicate_from_obligation_metadata(
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<trust_verifier_api::ContractPredicate>, String> {
    let Some(schema) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SCHEMA_METADATA_KEY)
    else {
        return Ok(None);
    };
    if !trust_wp_supported_public_proof_schema(schema) {
        return Ok(None);
    }
    let Some(payload) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
    else {
        return Err(format!(
            "cannot build trust-wp typed formula contract for obligation `{}` without `{TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY}` metadata",
            obligation.obligation_id
        ));
    };
    // Trust (R1 corpus): preserve bounded deep parsing while rejecting
    // duplicate proof-JSON keys before deriving a compiler contract.
    let value = trust_types::trust_formula_v1::parse_unique_proof_json_payload(payload).map_err(
        |error| {
            format!(
                "cannot build trust-wp typed formula contract from malformed JSON payload on obligation `{}`: {error}",
                obligation.obligation_id
            )
        },
    )?;
    // Trust (#29): a metadata predicate that cannot materialize a typed claim
    // (`Ok(None)` — e.g. the amendment-1 arithmetic refusal, an out-of-i64
    // literal, or any node outside the replay fragment) must not derive a
    // compiler contract at all: deriving one and then failing to produce its
    // claim aborted the whole native bundle at the finalize seam, demoting
    // EVERY obligation of the function. Returning `None` here keeps the
    // demotion per-obligation — exactly the fail-closed shape an unlowerable
    // contract-linked predicate takes today.
    if trust_wp_public_typed_proof_claim_from_schema_value(schema, &value)?.is_none() {
        return Ok(None);
    }
    Ok(Some(trust_verifier_api::ContractPredicate::CanonicalJson {
        schema: schema.to_string(),
        value: canonical_json_value(&value),
    }))
}

fn trust_wp_contract_kind_for_obligation(
    kind: &trust_verifier_api::ObligationKind,
) -> trust_verifier_api::ContractKind {
    match kind {
        trust_verifier_api::ObligationKind::Precondition => {
            trust_verifier_api::ContractKind::Requires
        }
        trust_verifier_api::ObligationKind::Postcondition => {
            trust_verifier_api::ContractKind::Ensures
        }
        trust_verifier_api::ObligationKind::LoopInvariant => {
            trust_verifier_api::ContractKind::LoopInvariant
        }
        trust_verifier_api::ObligationKind::Refinement => {
            trust_verifier_api::ContractKind::Refinement
        }
        _ => trust_verifier_api::ContractKind::Asserts,
    }
}

// Trust (#23 Slice 1): body-bound trust-wp public claims for uncited `ensures`.
//
// Blueprint of record: docs/design-notes/2026-07-17-trust-wp-lowering-blueprint.md.
//
// An original mir-extract Ensures contract reaches the trust-wp deductive lane
// as a typed `trust.spec-predicate.v1` predicate; without a body binding the
// sibling verifier sees the bare predicate over a havoc'd `result` and fails
// closed (Unsupported). This finalize step derives, PRE-DIGEST, a compiler
// contract whose predicate is the sibling's `trust_wp.trust-formula.v1`
// let-envelope: `result` let-bound to the function's exact defining expression
// recovered from the typed trust-ir body by the fail-closed bridge walker
// (`trust_ir_bridge::trust_wp_claim`). The digest index, proof-source
// population, module ProofFormula, and replay atom all run AFTER this step, so
// public contract == module formula == replay atom by construction.
//
// FAIL-CLOSED: every guard miss silently skips the obligation, leaving today's
// Unsupported path byte-identical. The ONLY error exits are internal invariant
// breaks (dangling binding index, contract-identity collision, bundle
// validation). The full guard enumeration (blueprint amendments 1-4 + 7):
//   * trust-wp suite binding; obligation kind Postcondition with a
//     contract-linked, mir-extract-produced `ObligationOrigin::Contract`
//     context naming that same Ensures contract;
//   * the original public contract and obligation core must match an
//     independently rebuilt contract-only reference, and their dense source
//     index must resolve in the raw compiler `CompilerContractBundle`; a
//     duplicate/stale/malformed typed candidate never falls back to parsing;
//   * amendment 2 (provenance-tight): neither the obligation nor the contract
//     carries a synthetic typed-formula key or ANY typed-formula source key —
//     only ORIGINAL mir-extract Ensures rows body-bind;
//   * amendment 3: ZERO `ContractKind::Requires` rows in the public bundle,
//     independent compiler reference, AND raw compiler inventory, INCLUDING
//     unsupported ones (deleting public transport cannot bypass the guard);
//   * amendment 1: the predicate must lower through the bridge's v1 fragment
//     (comparisons + boolean connectives; ALL arithmetic refuses — machine
//     arithmetic over unbounded Int is a confirmed false-proof vector) and the
//     refutation-shaped-root belt;
//   * amendment 4: every MIR local index is globally unique; the defining
//     expression's entry-param index maps through the dense arg-local space;
//     named args are unique; each variable resolves to the exact arg name and
//     int/bool type. Compiler-typed `Inferred` variables additionally require
//     exact proposition digest/source-domain agreement. `_0` may normalize to
//     `result` only with an exact return type and no source arg named `_0`;
//   * amendment 7: no spec variable named `result`; int/bool result sort only,
//     and it must equal the defining expression, return local, and declared
//     function return sorts.
fn finalize_trust_wp_body_bound_public_claims(
    module: &trust_ir::Module,
    function_id: trust_ir::FuncId,
    func: &trust_types::VerifiableFunction,
    bundle: &mut trust_verifier_api::TrustContractBundle,
    compiler_contract_reference: Option<&trust_verifier_api::TrustContractBundle>,
    compiler_contracts: Option<&trust_types::CompilerContractBundle>,
    bindings: &[PendingNativeTrustIrBinding],
) -> Result<Vec<PendingCompilerBodyBoundClaim>, String> {
    // The public verifier bundle is transport, not authority. Body-bound
    // claims are available only when this construction path carries an
    // independently rebuilt contract-only reference derived directly from the
    // compiler query. Compatibility callers without that private reference
    // keep the ordinary unsupported path.
    let Some(compiler_contract_reference) = compiler_contract_reference else {
        return Ok(Vec::new());
    };
    let Some(compiler_contracts) = compiler_contracts else {
        return Ok(Vec::new());
    };
    if compiler_contract_reference.validate().is_err() {
        return Ok(Vec::new());
    }
    let mut derived_contracts: Vec<trust_verifier_api::TrustContract> = Vec::new();
    let mut pending_claims = Vec::new();
    for binding in
        bindings.iter().filter(|binding| binding.verifier_suite.eq_ignore_ascii_case("trust-wp"))
    {
        let obligation = bundle.obligations.get(binding.obligation_index).ok_or_else(|| {
            format!(
                "native TrustIr binding referenced missing public obligation index {}",
                binding.obligation_index
            )
        })?;
        // A binding index and public ID must each identify exactly one row.
        // Even if an upstream bundle validator grows more permissive, an
        // ambiguous carrier must never select which semantics get body-bound.
        if bindings
            .iter()
            .filter(|candidate| candidate.obligation_index == binding.obligation_index)
            .count()
            != 1
            || bundle
                .obligations
                .iter()
                .filter(|candidate| candidate.obligation_id == obligation.obligation_id)
                .count()
                != 1
        {
            continue;
        }
        let Some(derived_contract) = trust_wp_body_bound_contract_for_obligation(
            module,
            function_id,
            func,
            &bundle.contracts,
            obligation,
            compiler_contract_reference,
            compiler_contracts,
        ) else {
            // Guard miss: the obligation keeps today's fail-closed path.
            continue;
        };
        if let Some(existing) = bundle
            .contracts
            .iter()
            .chain(derived_contracts.iter())
            .find(|contract| contract.contract_id == derived_contract.contract_id)
        {
            if existing != &derived_contract {
                return Err(format!(
                    "compiler-derived trust-wp body-bound contract identity `{}` collides with different public contract contents",
                    derived_contract.contract_id
                ));
            }
        } else {
            derived_contracts.push(derived_contract.clone());
        }

        let obligation = bundle
            .obligations
            .get_mut(binding.obligation_index)
            .expect("validated native binding index changed while finalizing contracts");
        let original_contract_id =
            obligation.contract_id.replace(derived_contract.contract_id.clone());
        if let Some(original_contract_id) = original_contract_id
            && original_contract_id != derived_contract.contract_id
        {
            set_obligation_metadata(
                obligation,
                TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY,
                original_contract_id,
            );
        }
        set_obligation_metadata(
            obligation,
            TRUST_WP_TYPED_FORMULA_SYNTHETIC_CONTRACT_METADATA_KEY,
            derived_contract.contract_id.clone(),
        );
        pending_claims.push(PendingCompilerBodyBoundClaim {
            obligation_index: binding.obligation_index,
            proof_obligation_id: binding.proof_obligation_id,
            derived_contract,
        });
    }
    bundle.contracts.extend(derived_contracts);
    bundle.validate().map_err(|error| {
        format!("compiler-derived trust-wp body-bound public claim finalization failed: {error}")
    })?;
    Ok(pending_claims)
}

/// Turn guarded finalizer witnesses into exact compiler-private carriers only
/// after the public semantic digest, final native formula, source map, request,
/// and transport annotations all agree. No public metadata-only lookalike can
/// enter this function without a `PendingCompilerBodyBoundClaim` minted by the
/// finalizer above.
fn seal_compiler_finalized_body_bound_carriers(
    bundle: &trust_verifier_api::TrustContractBundle,
    native_bundle: &trust_ir_bridge::NativeVerificationBundle,
    pending_claims: &[PendingCompilerBodyBoundClaim],
    semantic_digests: &trust_verifier_api::CanonicalObligationSemanticDigestIndex,
) -> Result<Vec<CompilerFinalizedBodyBoundCarrier>, String> {
    if pending_claims.is_empty() {
        return Ok(Vec::new());
    }
    native_bundle.validate().map_err(|errors| {
        format!(
            "cannot seal compiler-finalized body-bound Trust-WP claims against an invalid native bundle: {}",
            errors.into_iter().map(|error| format!("{error:?}")).collect::<Vec<_>>().join("; ")
        )
    })?;

    let body_source_digest = native_bundle.source_digest().ok_or_else(|| {
        "body-bound Trust-WP authority requires an exact Rust MIR body/source digest".to_string()
    })?;
    let trust_ir_module_digest = native_bundle.trust_ir_module_digest;
    let compiler_facts_digest = native_bundle.compiler_facts.stable_digest();
    let native_bundle_digest = native_bundle.stable_digest();
    let mut seen_obligation_indices = FxHashSet::default();
    let mut seen_proof_ids = FxHashSet::default();
    let mut sealed = Vec::with_capacity(pending_claims.len());

    for pending in pending_claims {
        if !seen_obligation_indices.insert(pending.obligation_index)
            || !seen_proof_ids.insert(pending.proof_obligation_id)
        {
            return Err(
                "body-bound Trust-WP finalizer produced an ambiguous private claim inventory"
                    .to_string(),
            );
        }
        let obligation = bundle.obligations.get(pending.obligation_index).ok_or_else(|| {
            format!(
                "body-bound Trust-WP private claim referenced missing public obligation index {}",
                pending.obligation_index
            )
        })?;
        if obligation.kind != trust_verifier_api::ObligationKind::Postcondition
            || obligation.contract_id.as_deref()
                != Some(pending.derived_contract.contract_id.as_str())
            || exactly_one_metadata_value(
                &obligation.metadata,
                TRUST_WP_TYPED_FORMULA_SYNTHETIC_CONTRACT_METADATA_KEY,
            ) != Some(pending.derived_contract.contract_id.as_str())
            || exactly_one_metadata_value(
                &obligation.metadata,
                TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY,
            )
            .is_none_or(str::is_empty)
            || obligation
                .metadata
                .iter()
                .any(|entry| entry.key == TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY)
        {
            return Err(format!(
                "body-bound Trust-WP public obligation `{}` lost its exact compiler-finalized provenance",
                obligation.obligation_id
            ));
        }

        let mut matching_contracts = bundle
            .contracts
            .iter()
            .filter(|contract| contract.contract_id == pending.derived_contract.contract_id);
        let contract = matching_contracts.next().ok_or_else(|| {
            format!(
                "body-bound Trust-WP public obligation `{}` lost its derived contract",
                obligation.obligation_id
            )
        })?;
        if matching_contracts.next().is_some()
            || contract != &pending.derived_contract
            || exactly_one_metadata_value(
                &contract.metadata,
                TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY,
            ) != Some(TRUST_WP_TYPED_FORMULA_SOURCE_BODY_BOUND_VALUE)
        {
            return Err(format!(
                "body-bound Trust-WP derived contract for `{}` is ambiguous or changed",
                obligation.obligation_id
            ));
        }

        let public_semantic_digest = semantic_digests
            .get(&obligation.obligation_id)
            .ok_or_else(|| {
                format!(
                    "body-bound Trust-WP semantic digest index omitted `{}`",
                    obligation.obligation_id
                )
            })?
            .to_string();
        if bundle.canonical_obligation_semantic_digest_sha256(obligation).as_deref()
            != Ok(public_semantic_digest.as_str())
        {
            return Err(format!(
                "body-bound Trust-WP semantic digest changed for `{}` while sealing authority",
                obligation.obligation_id
            ));
        }
        let public_digest =
            trust_ir_sha256_digest_from_hex(&public_semantic_digest, &obligation.obligation_id)?;

        let mut proof_obligations = native_bundle
            .module
            .proof_obligations
            .iter()
            .filter(|candidate| candidate.id == pending.proof_obligation_id);
        let proof_obligation = proof_obligations.next().ok_or_else(|| {
            format!(
                "body-bound Trust-WP native proof inventory omitted proof {}",
                pending.proof_obligation_id.index()
            )
        })?;
        if proof_obligations.next().is_some()
            || proof_obligation
                .source
                .as_ref()
                .and_then(|source| source.public.as_ref())
                .is_none_or(|public| {
                    public.obligation_id != obligation.obligation_id
                        || public.semantic_digest != public_digest
                })
        {
            return Err(format!(
                "body-bound Trust-WP proof {} lost its exact public source identity",
                pending.proof_obligation_id.index()
            ));
        }
        let expected_formula =
            trust_wp_trust_ir_proof_formula_for_api_obligation(&bundle.contracts, obligation)?
                .ok_or_else(|| {
                    format!(
                        "body-bound Trust-WP public claim `{}` has no final native proof formula",
                        obligation.obligation_id
                    )
                })?;
        if proof_obligation.formula.as_ref() != Some(&expected_formula) {
            return Err(format!(
                "body-bound Trust-WP native proof formula changed for `{}`",
                obligation.obligation_id
            ));
        }

        let mut requests = native_bundle.requests.iter().filter(|request| {
            matches!(request, trust_ir::NativeVerificationRequest::TrustWp(_))
                && request
                    .obligations()
                    .iter()
                    .filter(|id| **id == pending.proof_obligation_id)
                    .count()
                    == 1
        });
        let request = requests.next().ok_or_else(|| {
            format!(
                "body-bound Trust-WP proof {} has no exact native request",
                pending.proof_obligation_id.index()
            )
        })?;
        if requests.next().is_some() {
            return Err(format!(
                "body-bound Trust-WP proof {} is claimed by multiple native requests",
                pending.proof_obligation_id.index()
            ));
        }

        let mut sources = native_bundle
            .compiler_facts
            .obligation_sources
            .iter()
            .filter(|source| source.obligation == pending.proof_obligation_id);
        let source = sources.next().ok_or_else(|| {
            format!(
                "body-bound Trust-WP proof {} has no compiler source row",
                pending.proof_obligation_id.index()
            )
        })?;
        if sources.next().is_some() || source.public_obligation_id != obligation.obligation_id {
            return Err(format!(
                "body-bound Trust-WP proof {} has an ambiguous or mismatched compiler source row",
                pending.proof_obligation_id.index()
            ));
        }
        let obligation_source_digest = native_json_digest(
            "trust.trust_ir.native.obligation-source.digest.v1",
            &native_compiler_fact_source_json(source),
        )?;

        let exact_metadata = [
            (
                trust_router::full_verification::TRUST_TRUST_IR_NATIVE_VERIFIER_SUITE_METADATA_KEY,
                "trust-wp".to_string(),
            ),
            (
                trust_router::full_verification::TRUST_TRUST_IR_NATIVE_REQUEST_ID_METADATA_KEY,
                request.id().index().to_string(),
            ),
            (
                trust_router::full_verification::TRUST_TRUST_IR_NATIVE_PROOF_OBLIGATION_ID_METADATA_KEY,
                pending.proof_obligation_id.index().to_string(),
            ),
            (
                TRUST_TRUST_IR_NATIVE_TRUST_IR_MODULE_DIGEST_METADATA_KEY,
                native_artifact_digest_hex(trust_ir_module_digest),
            ),
            (
                TRUST_TRUST_IR_NATIVE_REQUEST_DIGEST_METADATA_KEY,
                native_artifact_digest_hex(request.stable_digest()),
            ),
            (
                TRUST_TRUST_IR_NATIVE_COMPILER_FACTS_DIGEST_METADATA_KEY,
                native_artifact_digest_hex(compiler_facts_digest),
            ),
            (
                TRUST_TRUST_IR_NATIVE_OBLIGATION_SOURCE_DIGEST_METADATA_KEY,
                obligation_source_digest.clone(),
            ),
        ];
        if exact_metadata.iter().any(|(key, expected)| {
            exactly_one_metadata_value(&obligation.metadata, key) != Some(expected.as_str())
        }) {
            return Err(format!(
                "body-bound Trust-WP transport identities changed for `{}`",
                obligation.obligation_id
            ));
        }

        sealed.push(CompilerFinalizedBodyBoundCarrier {
            canonical_obligation: obligation.clone(),
            canonical_contract: contract.clone(),
            public_semantic_digest,
            native_request: request.clone(),
            native_proof_obligation: proof_obligation.clone(),
            native_obligation_source: source.clone(),
            native_bundle_digest,
            trust_ir_module_digest,
            compiler_facts_digest,
            body_source_digest,
            obligation_source_digest,
        });
    }
    Ok(sealed)
}

/// Map a MIR-model type to the sibling claim sort it may soundly carry in the
/// body-bound v1 fragment. Unbounded `Int` is sound for this fragment because
/// the defining equation is exact (copy/const only, no arithmetic anywhere)
/// and machine-integer states embed into Int valuations (blueprint
/// `claim_shape`). Everything non-int/bool fails closed.
fn trust_wp_body_bound_sort_for_ty(ty: &trust_types::Ty) -> Option<&'static str> {
    match ty {
        trust_types::Ty::Bool => Some("bool"),
        trust_types::Ty::Int { .. } | trust_types::Ty::PtrSizedInt { .. } => Some("int"),
        _ => None,
    }
}

/// Check the compiler proposition's source-domain sidecar against the exact
/// MIR local type. Typed propositions may not collapse distinct machine widths
/// or signedness merely because the public predicate surface uses logical Int.
fn trust_wp_body_bound_domain_matches_ty(
    domain: trust_types::CompilerContractValueDomain,
    ty: &trust_types::Ty,
) -> bool {
    match (domain, ty) {
        (trust_types::CompilerContractValueDomain::Bool, trust_types::Ty::Bool) => true,
        (
            trust_types::CompilerContractValueDomain::MachineInt { width, signed },
            trust_types::Ty::Int { width: actual_width, signed: actual_signed },
        ) => width == *actual_width && signed == *actual_signed,
        (
            trust_types::CompilerContractValueDomain::PointerSizedInt { width, signed },
            trust_types::Ty::PtrSizedInt { signed: actual_signed },
        ) => width == 64 && signed == *actual_signed,
        _ => false,
    }
}

/// Match the immutable compiler-query obligation against its mutable public
/// counterpart while allowing only the three certified-monitor transport
/// fields stamped after extraction. Every other field, including metadata
/// order and cardinality, remains byte-for-byte equal to the reference.
fn compiler_body_bound_reference_obligation_matches(
    reference: &trust_verifier_api::TrustObligation,
    current: &trust_verifier_api::TrustObligation,
) -> bool {
    obligation_matches_monitor_reference(current, reference)
}

/// Match an original compiler contract while permitting only the three
/// certified-monitor transport fields on the mutable public copy.
fn compiler_body_bound_reference_contract_matches(
    reference: &trust_verifier_api::TrustContract,
    current: &trust_verifier_api::TrustContract,
) -> bool {
    contract_matches_monitor_reference(current, reference)
}

/// Build the body-bound derived contract for one trust-wp Postcondition
/// obligation, or `None` when ANY guard misses (fail-closed skip; see
/// [`finalize_trust_wp_body_bound_public_claims`] for the enumeration).
fn trust_wp_body_bound_contract_for_obligation(
    module: &trust_ir::Module,
    function_id: trust_ir::FuncId,
    func: &trust_types::VerifiableFunction,
    contracts: &[trust_verifier_api::TrustContract],
    obligation: &trust_verifier_api::TrustObligation,
    compiler_contract_reference: &trust_verifier_api::TrustContractBundle,
    compiler_contracts: &trust_types::CompilerContractBundle,
) -> Option<trust_verifier_api::TrustContract> {
    use trust_ir_bridge::trust_wp_claim::{
        ClaimVariable, DefiningExpr, body_bound_trust_formula_envelope,
        reject_refutation_shaped_root, spec_predicate_to_sibling_json,
        trust_wp_result_defining_expr,
    };

    if obligation.kind != trust_verifier_api::ObligationKind::Postcondition {
        return None;
    }
    let contract_id = obligation.contract_id.as_ref()?;
    let mut linked_contracts =
        contracts.iter().filter(|contract| &contract.contract_id == contract_id);
    let contract = linked_contracts.next()?;
    if linked_contracts.next().is_some() {
        return None;
    }
    if contract.kind != trust_verifier_api::ContractKind::Ensures {
        return None;
    }

    // Authenticate the original row against a contract-only verifier bundle
    // independently rebuilt from the compiler's `CompilerContractBundle`.
    // The mutable public bundle cannot authenticate itself merely by carrying
    // plausible typed-proposition metadata.
    let mut reference_obligations = compiler_contract_reference
        .obligations
        .iter()
        .filter(|candidate| candidate.obligation_id == obligation.obligation_id);
    let reference_obligation = reference_obligations.next()?;
    if reference_obligations.next().is_some()
        || !compiler_body_bound_reference_obligation_matches(reference_obligation, obligation)
    {
        return None;
    }
    let reference_contract_id = reference_obligation.contract_id.as_ref()?;
    if reference_contract_id != contract_id {
        return None;
    }
    let mut reference_contracts = compiler_contract_reference
        .contracts
        .iter()
        .filter(|candidate| &candidate.contract_id == reference_contract_id);
    let reference_contract = reference_contracts.next()?;
    if reference_contracts.next().is_some()
        || !compiler_body_bound_reference_contract_matches(reference_contract, contract)
    {
        return None;
    }

    // Amendment 2 — provenance-tight: only ORIGINAL mir-extract contracts.
    let synthetic_metadata = |metadata: &[trust_verifier_api::MetadataEntry]| {
        metadata.iter().any(|entry| {
            entry.key == TRUST_WP_TYPED_FORMULA_SYNTHETIC_CONTRACT_METADATA_KEY
                || entry.key == TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY
                // The source key itself is compiler-owned provenance. Do not
                // accept an unknown value (or let duplicate source/synthetic
                // keys select by insertion order) as evidence of originality.
                || entry.key == TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY
        })
    };
    if synthetic_metadata(&obligation.metadata) || synthetic_metadata(&contract.metadata) {
        return None;
    }
    // The obligation itself must be the mir-extract contract marker for this
    // exact Ensures contract (unique current-schema context, producer
    // CompilerMirExtract, origin Contract{Ensures} naming the linked row).
    let mut contexts = obligation
        .metadata
        .iter()
        .filter(|entry| entry.key == trust_verifier_api::OBLIGATION_CONTEXT_METADATA_KEY);
    let context_entry = contexts.next()?;
    if contexts.next().is_some() {
        return None;
    }
    let context =
        trust_verifier_api::ObligationContext::from_metadata_entry(context_entry).ok()??;
    if !context.has_current_schema()
        || !matches!(context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
    {
        return None;
    }
    let source_contract_index = match &context.origin {
        trust_verifier_api::ObligationOrigin::Contract {
            contract_id: origin_contract_id,
            contract_kind: trust_verifier_api::ContractKind::Ensures,
            contract_index,
            ..
        } if origin_contract_id == contract_id => *contract_index,
        _ => return None,
    };
    let compiler_contract = compiler_contracts.contracts.get(source_contract_index)?;
    if compiler_contract.kind != trust_types::ContractKind::Ensures {
        return None;
    }
    let has_typed_proposition_candidate = compiler_contracts
        .typed_propositions
        .iter()
        .any(|proposition| proposition.source_contract_index == source_contract_index);
    let compiler_typed_proposition_record =
        compiler_contracts.typed_proposition(source_contract_index, compiler_contract);
    // A duplicate, stale-body, stale-kind, malformed-formula, or incomplete
    // domain record must not disappear into the source-parser compatibility
    // fallback. Once the compiler query supplies any typed candidate for this
    // index, only its unique exact proposition is authoritative.
    if has_typed_proposition_candidate && compiler_typed_proposition_record.is_none() {
        return None;
    }

    // Amendment 3 — requires detection over `bundle.contracts`, INCLUDING
    // `ContractPredicate::Unsupported` rows.
    if contracts.iter().any(|contract| contract.kind == trust_verifier_api::ContractKind::Requires)
        || compiler_contract_reference
            .contracts
            .iter()
            .any(|contract| contract.kind == trust_verifier_api::ContractKind::Requires)
        || compiler_contracts
            .contracts
            .iter()
            .any(|contract| contract.kind == trust_types::ContractKind::Requires)
    {
        return None;
    }

    // The linked predicate must be the typed mir-extract spec predicate.
    let trust_verifier_api::ContractPredicate::TrustIr { schema, value } = &contract.predicate
    else {
        return None;
    };
    if schema != trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION {
        return None;
    }
    let predicate =
        serde_json::from_value::<trust_verifier_api::TrustSpecPredicate>(value.clone()).ok()?;
    if !predicate.has_current_schema()
        || predicate.root_sort != trust_verifier_api::TrustSpecSort::Bool
        || predicate.root.sort != trust_verifier_api::TrustSpecSort::Bool
    {
        return None;
    }

    // The exact defining expression of the function's return value, recovered
    // fail-closed from the typed trust-ir body (single entry block, copy/const
    // chains only).
    let defining = trust_wp_result_defining_expr(module, function_id).ok()?;

    // Amendment 4 — pinned index-space translation: the bridge lowers arg
    // locals `1..=arg_count` (in order) to entry params `0..arg_count`, so
    // `EntryParam(k)` names arg local `k + 1`. Require the arg-local space to
    // be DENSE (every index present) so a skew fails closed instead of
    // misbinding.
    let arg_count = func.body.arg_count;
    let mut local_by_index = FxHashMap::default();
    for local in &func.body.locals {
        if local_by_index.insert(local.index, local).is_some() {
            return None;
        }
    }
    let mut arg_locals = Vec::with_capacity(arg_count);
    let mut arg_names = FxHashSet::default();
    for index in 1..=arg_count {
        let local = *local_by_index.get(&index)?;
        if let Some(name) = local.name.as_deref()
            && !arg_names.insert(name)
        {
            return None;
        }
        arg_locals.push(local);
    }
    let return_local = *local_by_index.get(&0)?;
    if return_local.ty != func.body.return_ty
        // Production rustc extraction leaves the return place unnamed; the
        // compatibility model names it `_0`. Any other name is not the
        // compiler return spelling authenticated by this lane.
        || return_local.name.as_deref().is_some_and(|name| name != "_0")
    {
        return None;
    }

    // Compiler-owned typed propositions use formula-local names (`_0`, `x`,
    // ...) and therefore arrive with `Inferred` origins rather than the source
    // parser's explicit `Result`/`Local` origins. Admit that representation
    // only when the original compiler contract and obligation carry the same
    // unique typed-proposition digest and the contract records the exact
    // `typed_proposition` lowering. Names are then resolved against the dense
    // compiler-held MIR local table below; public inferred names alone are not
    // sufficient.
    let typed_proposition_digest = exactly_one_metadata_value(
        &reference_contract.metadata,
        TRUST_CONTRACT_TYPED_PROPOSITION_DIGEST_METADATA_KEY,
    );
    let compiler_typed_proposition_digest = compiler_typed_proposition_record.map(|proposition| {
        trust_types::typed_contract_proposition_digest(
            &proposition.formula,
            &proposition.variable_domains,
        )
    });
    let compiler_typed_proposition = compiler_typed_proposition_digest.as_deref()
        == typed_proposition_digest
        && exactly_one_metadata_value(&reference_contract.metadata, "trust.contract.lowering")
            == Some("typed_proposition")
        && typed_proposition_digest.is_some_and(|digest| {
            exactly_one_metadata_value(
                &reference_obligation.metadata,
                TRUST_CONTRACT_TYPED_PROPOSITION_DIGEST_METADATA_KEY,
            ) == Some(digest)
                && exactly_one_metadata_value(
                    &contract.metadata,
                    TRUST_CONTRACT_TYPED_PROPOSITION_DIGEST_METADATA_KEY,
                ) == Some(digest)
                && exactly_one_metadata_value(
                    &obligation.metadata,
                    TRUST_CONTRACT_TYPED_PROPOSITION_DIGEST_METADATA_KEY,
                ) == Some(digest)
                && digest.strip_prefix("sha256:").is_some_and(canonical_sha256_hex_segment)
        });

    // Amendment 4 + 7 — every spec variable must be a NAMED arg local with a
    // matching recorded name and an int/bool sort agreeing with its Rust type;
    // no variable may be named `result`; duplicates fail closed.
    let mut claim_variables: Vec<ClaimVariable> = Vec::with_capacity(predicate.variables.len());
    let mut inferred_result_alias: Option<(String, trust_verifier_api::TrustSpecSort)> = None;
    for variable in &predicate.variables {
        if variable.name.trim().is_empty() || variable.name == "result" {
            return None;
        }
        let index = match &variable.origin {
            trust_verifier_api::TrustSpecVariableOrigin::Local { index } => *index,
            trust_verifier_api::TrustSpecVariableOrigin::Inferred
                if compiler_typed_proposition && variable.name == "_0" =>
            {
                // `_0` is rustc's typed-proposition spelling for the return
                // place, but is also a legal source argument identifier. Do
                // not normalize it unless the compiler-held MIR local table
                // makes that spelling unambiguous and both return type
                // carriers agree with the proposition sort.
                if arg_locals.iter().any(|local| local.name.as_deref() == Some("_0")) {
                    return None;
                }
                let sort = match variable.sort {
                    trust_verifier_api::TrustSpecSort::Int => "int",
                    trust_verifier_api::TrustSpecSort::Bool => "bool",
                    trust_verifier_api::TrustSpecSort::BitVec { .. }
                    | trust_verifier_api::TrustSpecSort::Array { .. }
                    | trust_verifier_api::TrustSpecSort::Float { .. } => return None,
                };
                if trust_wp_body_bound_sort_for_ty(&return_local.ty) != Some(sort)
                    || trust_wp_body_bound_sort_for_ty(&func.body.return_ty) != Some(sort)
                {
                    return None;
                }
                let return_domain = compiler_typed_proposition_record?
                    .variable_domains
                    .iter()
                    .find(|domain| domain.name == variable.name)?;
                if !trust_wp_body_bound_domain_matches_ty(return_domain.domain, &return_local.ty)
                    || !trust_wp_body_bound_domain_matches_ty(
                        return_domain.domain,
                        &func.body.return_ty,
                    )
                {
                    return None;
                }
                if inferred_result_alias.replace((variable.name.clone(), variable.sort)).is_some() {
                    return None;
                }
                continue;
            }
            trust_verifier_api::TrustSpecVariableOrigin::Inferred if compiler_typed_proposition => {
                let mut matching = arg_locals
                    .iter()
                    .filter(|local| local.name.as_deref() == Some(variable.name.as_str()));
                let local = *matching.next()?;
                if matching.next().is_some() {
                    return None;
                }
                local.index
            }
            trust_verifier_api::TrustSpecVariableOrigin::Inferred
            | trust_verifier_api::TrustSpecVariableOrigin::Quantified => return None,
            _ => return None,
        };
        if index == 0 || index > arg_count {
            return None;
        }
        let local = arg_locals[index - 1];
        if local.name.as_deref() != Some(variable.name.as_str()) {
            return None;
        }
        if let Some(proposition) = compiler_typed_proposition_record {
            let domain =
                proposition.variable_domains.iter().find(|domain| domain.name == variable.name)?;
            if !trust_wp_body_bound_domain_matches_ty(domain.domain, &local.ty) {
                return None;
            }
        }
        let sort = match variable.sort {
            trust_verifier_api::TrustSpecSort::Int => "int",
            trust_verifier_api::TrustSpecSort::Bool => "bool",
            trust_verifier_api::TrustSpecSort::BitVec { .. }
            | trust_verifier_api::TrustSpecSort::Array { .. }
            | trust_verifier_api::TrustSpecSort::Float { .. } => return None,
        };
        if trust_wp_body_bound_sort_for_ty(&local.ty) != Some(sort) {
            return None;
        }
        if claim_variables.iter().any(|existing| existing.name == variable.name) {
            return None;
        }
        claim_variables.push(ClaimVariable { name: variable.name.clone(), sort });
    }

    // Render the defining expression; for `EntryParam(k)` resolve the arg
    // local's recorded name and sort (amendment 5's i64 range check already
    // ran inside the walker for constants).
    let (defining_value, defining_sort, defining_param) = match &defining {
        DefiningExpr::EntryParam(position) => {
            if *position >= arg_count {
                return None;
            }
            let local = arg_locals[*position];
            let name = local.name.as_deref()?;
            if name == "result" {
                return None;
            }
            let sort = trust_wp_body_bound_sort_for_ty(&local.ty)?;
            (serde_json::json!({ "var": name }), sort, Some((name.to_string(), sort)))
        }
        DefiningExpr::IntConst(value) => (serde_json::json!({ "int": value }), "int", None),
        DefiningExpr::BoolConst(value) => (serde_json::json!({ "bool": value }), "bool", None),
    };
    // A param referenced by the defining expression but absent from the
    // ensures variables is appended (with its type-derived sort); if declared,
    // the sorts must agree.
    if let Some((name, sort)) = defining_param {
        if let Some(existing) = claim_variables.iter().find(|variable| variable.name == name) {
            if existing.sort != sort {
                return None;
            }
        } else {
            claim_variables.push(ClaimVariable { name, sort });
        }
    }

    // Amendment 1 — translate the canonical typed predicate through the
    // bridge's v1 fragment (ALL arithmetic refuses) and the
    // refutation-shaped-root belt. The bridge owns validation and lowering;
    // passing the whole typed predicate keeps this seam in lockstep with its
    // declaration/sort checks.
    let mut body = spec_predicate_to_sibling_json(&predicate).ok()?;
    reject_refutation_shaped_root(&body).ok()?;
    let mut result_sort_typed = None;
    collect_body_bound_result_sort(&predicate.root, &mut result_sort_typed).ok()?;
    let result_sort_typed = match (result_sort_typed, inferred_result_alias) {
        (Some(sort), None) => sort,
        (None, Some((alias, sort))) => {
            if rewrite_body_bound_result_alias(&mut body, &alias) == 0 {
                return None;
            }
            sort
        }
        // Two distinct return carriers, or none, are ambiguous/non-body-bound.
        (Some(_), Some(_)) | (None, None) => return None,
    };
    // Amendment 7 — the ensures must constrain `result` with a consistent
    // int/bool sort, and it must equal the defining expression's sort.
    let result_sort = match result_sort_typed {
        trust_verifier_api::TrustSpecSort::Int => "int",
        trust_verifier_api::TrustSpecSort::Bool => "bool",
        trust_verifier_api::TrustSpecSort::BitVec { .. }
        | trust_verifier_api::TrustSpecSort::Array { .. }
        | trust_verifier_api::TrustSpecSort::Float { .. } => return None,
    };
    if result_sort != defining_sort
        || trust_wp_body_bound_sort_for_ty(&return_local.ty) != Some(result_sort)
        || trust_wp_body_bound_sort_for_ty(&func.body.return_ty) != Some(result_sort)
    {
        return None;
    }
    let mut envelope =
        body_bound_trust_formula_envelope(&claim_variables, &body, result_sort, &defining_value)
            .ok()?;
    // Schema respelling: the bridge stamps the sibling-repo hyphenated tag
    // (`trust-wp.…`), but every Trust-side decoder (`canonical_trust_formula_payload`
    // here and in the trust-wp adapter) pins the canonical trust-types
    // UNDERSCORE spelling, and the sibling decoder folds `_`/`-` on decode —
    // so the underscore spelling is the one identity every hop accepts.
    envelope["schema"] = serde_json::json!(TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION);
    let envelope = canonical_json_value(&envelope);
    // Defensive: the downstream claim decoders (`trust_wp_public_typed_proof_claim`,
    // the adapter passthrough) hard-error on an undecodable claim; verify here
    // so a malformed envelope becomes a fail-closed skip, never a build error.
    canonical_trust_formula_payload(&envelope).ok()?;

    let derived_contract_id = format!(
        "contract:trust-wp-body-bound:{}",
        trust_types::stable_sha256_hex(
            format!("trustc.trust-wp.body-bound-ensures-contract.v1\0{}", obligation.obligation_id)
                .as_bytes(),
        )
    );
    Some(trust_verifier_api::TrustContract {
        contract_id: derived_contract_id,
        kind: trust_verifier_api::ContractKind::Ensures,
        predicate: trust_verifier_api::ContractPredicate::CanonicalJson {
            schema: TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION.to_string(),
            value: envelope,
        },
        source: contract.source.clone(),
        metadata: vec![trust_verifier_api::MetadataEntry {
            key: TRUST_WP_TYPED_FORMULA_SOURCE_METADATA_KEY.to_string(),
            value: TRUST_WP_TYPED_FORMULA_SOURCE_BODY_BOUND_VALUE.to_string(),
        }],
    })
}

/// Rewrite the compiler-owned typed-proposition spelling of the return local
/// into the sibling formula's reserved `result` variable. Only exact
/// single-key variable nodes are rewritten; object keys, string literals, and
/// larger objects cannot be confused for a variable occurrence. The caller
/// admits this normalization only behind matching compiler proposition
/// digests and requires at least one rewritten occurrence.
fn rewrite_body_bound_result_alias(value: &mut serde_json::Value, alias: &str) -> usize {
    match value {
        serde_json::Value::Object(map)
            if map.len() == 1
                && map.get("var").and_then(serde_json::Value::as_str) == Some(alias) =>
        {
            map.insert("var".to_string(), serde_json::Value::String("result".to_string()));
            1
        }
        serde_json::Value::Object(map) => {
            map.values_mut().map(|value| rewrite_body_bound_result_alias(value, alias)).sum()
        }
        serde_json::Value::Array(values) => {
            values.iter_mut().map(|value| rewrite_body_bound_result_alias(value, alias)).sum()
        }
        _ => 0,
    }
}

/// Collect the sort of every `result` occurrence after the bridge has accepted
/// the typed predicate's narrow v1 fragment. Keeping this as a second,
/// compiler-checked walk makes the let-envelope fail closed when `result` is
/// absent or inconsistently sorted without maintaining a second JSON decoder.
fn collect_body_bound_result_sort(
    expr: &trust_verifier_api::TrustSpecExpr,
    result_sort: &mut Option<trust_verifier_api::TrustSpecSort>,
) -> Result<(), String> {
    match &expr.kind {
        trust_verifier_api::TrustSpecExprKind::Result => {
            if let Some(existing) = result_sort {
                if *existing != expr.sort {
                    return Err("spec predicate uses `result` with inconsistent sorts".to_string());
                }
            } else {
                *result_sort = Some(expr.sort);
            }
        }
        trust_verifier_api::TrustSpecExprKind::Unary { expr: inner, .. } => {
            collect_body_bound_result_sort(inner, result_sort)?;
        }
        trust_verifier_api::TrustSpecExprKind::Binary { lhs, rhs, .. } => {
            collect_body_bound_result_sort(lhs, result_sort)?;
            collect_body_bound_result_sort(rhs, result_sort)?;
        }
        trust_verifier_api::TrustSpecExprKind::BoolLiteral { .. }
        | trust_verifier_api::TrustSpecExprKind::IntLiteral { .. }
        | trust_verifier_api::TrustSpecExprKind::Variable { .. } => {}
        // Defense in depth: the typed bridge has already rejected these.
        _ => return Err("spec node outside the body-bound v1 fragment".to_string()),
    }
    Ok(())
}

fn native_trust_ir_proof_unit_id(
    verifier_suite: &str,
    request_id: u32,
    proof_obligation_id: u32,
) -> String {
    format!(
        "trust_ir-native-{}-request-{request_id}-proof-{proof_obligation_id}",
        verifier_suite.to_ascii_lowercase()
    )
}

#[derive(Debug, Clone, Default)]
struct NativeTrustIrProofUnitMetadataOverrides {
    assertion_id: Option<String>,
    trust_ir_module_digest: Option<String>,
    request_digest: Option<String>,
    compiler_facts_digest: Option<String>,
    obligation_source_digest: Option<String>,
    replay_engine: Option<String>,
    replay_invocation: Option<String>,
    replay_transcript_digest: Option<String>,
    artifact_fingerprint: Option<String>,
}

fn native_trust_ir_proof_unit_metadata_entries(
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    request: &trust_ir::NativeVerificationRequest,
    proof_obligation_id: trust_ir::ProofId,
    overrides: Option<&NativeTrustIrProofUnitMetadataOverrides>,
) -> Result<Vec<trust_verifier_api::MetadataEntry>, String> {
    let verifier_suite = native_verifier_suite_canonical_label(request.verifier_suite());
    let request_id = request.id().index();
    let proof_unit_id =
        native_trust_ir_proof_unit_id(&verifier_suite, request_id, proof_obligation_id.index());
    let source = native_trust_ir_bundle
        .compiler_facts
        .obligation_sources
        .iter()
        .find(|source| source.obligation == proof_obligation_id)
        .ok_or_else(|| {
            format!(
                "typed TrustIr NativeVerificationBundle has no compiler-fact obligation source for proof obligation {}",
                proof_obligation_id.index()
            )
        })?;
    let assertion_id = overrides
        .and_then(|overrides| overrides.assertion_id.clone())
        .or_else(|| source.assertion_id.map(|id| id.index().to_string()));
    let obligation_source = native_compiler_fact_source_json(source);
    let obligation_source_digest =
        overrides.and_then(|overrides| overrides.obligation_source_digest.clone()).map_or_else(
            || {
                native_json_digest(
                    "trust.trust_ir.native.obligation-source.digest.v1",
                    &obligation_source,
                )
            },
            |value| Ok(value),
        )?;
    let trust_ir_module_digest =
        overrides.and_then(|overrides| overrides.trust_ir_module_digest.clone()).unwrap_or_else(
            || native_artifact_digest_hex(native_trust_ir_bundle.trust_ir_module_digest),
        );
    let request_digest = overrides
        .and_then(|overrides| overrides.request_digest.clone())
        .unwrap_or_else(|| native_artifact_digest_hex(request.stable_digest()));
    let compiler_facts_digest =
        overrides.and_then(|overrides| overrides.compiler_facts_digest.clone()).unwrap_or_else(
            || native_artifact_digest_hex(native_trust_ir_bundle.compiler_facts.stable_digest()),
        );
    let replay_identity = request.provenance().replay_identity();
    let replay_engine = overrides
        .and_then(|overrides| overrides.replay_engine.clone())
        .or_else(|| replay_identity.map(|replay| replay.engine.clone()));
    let replay_invocation = overrides
        .and_then(|overrides| overrides.replay_invocation.clone())
        .or_else(|| replay_identity.map(|replay| replay.invocation.clone()));
    let replay_transcript_digest =
        overrides.and_then(|overrides| overrides.replay_transcript_digest.clone()).or_else(|| {
            replay_identity
                .and_then(|replay| replay.transcript_digest)
                .map(native_artifact_digest_hex)
        });
    let replay_context = native_replay_context_json(request.provenance().replay_context());
    let replay_context_digest =
        native_json_digest("trust.trust_ir.native.replay-context.digest.v1", &replay_context)?;

    let mut proof_unit = serde_json::json!({
        "schema_version": TRUST_TRUST_IR_NATIVE_PROOF_UNIT_SCHEMA,
        "native_id": proof_unit_id,
        "verifier_suite": verifier_suite,
        "request_id": request_id,
        "proof_obligation_id": proof_obligation_id.index(),
        "public_obligation_id": source.public_obligation_id,
        "trust_ir_module_digest": {
            "algorithm": "sha256",
            "value": trust_ir_module_digest.clone(),
        },
        "request_digest": {
            "algorithm": "sha256",
            "value": request_digest.clone(),
        },
        "compiler_facts_digest": {
            "algorithm": "sha256",
            "value": compiler_facts_digest.clone(),
        },
        "obligation_source_digest": {
            "algorithm": "sha256",
            "value": obligation_source_digest.clone(),
        },
        "obligation_source": obligation_source,
        "assertion_id": assertion_id.clone(),
        "replay": {
            "engine": replay_engine.clone(),
            "invocation": replay_invocation.clone(),
            "transcript_digest": replay_transcript_digest.as_ref().map(|digest| serde_json::json!({
                "algorithm": "sha256",
                "value": digest,
            })),
            "context_digest": {
                "algorithm": "sha256",
                "value": replay_context_digest,
            },
        },
        "proof_status": "pending_native_evidence",
    });
    let artifact_fingerprint =
        overrides.and_then(|overrides| overrides.artifact_fingerprint.clone()).map_or_else(
            || {
                native_json_digest(
                    "trust.trust_ir.native.proof-unit-artifact.digest.v1",
                    &proof_unit,
                )
            },
            |value| Ok(value),
        )?;
    if let serde_json::Value::Object(object) = &mut proof_unit {
        object.insert(
            "artifact_fingerprint".to_string(),
            serde_json::json!({
                "algorithm": "sha256",
                "value": artifact_fingerprint.clone(),
            }),
        );
    }
    let proof_unit_metadata =
        serde_json::to_string(&canonical_json_value(&proof_unit)).map_err(|error| {
            format!("failed to serialize native TrustIr proof-unit metadata: {error}")
        })?;

    let mut entries = vec![
        trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_PROOF_UNIT_METADATA_KEY.to_string(),
            value: proof_unit_metadata,
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_TRUST_IR_MODULE_DIGEST_METADATA_KEY.to_string(),
            value: trust_ir_module_digest,
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_REQUEST_DIGEST_METADATA_KEY.to_string(),
            value: request_digest,
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_COMPILER_FACTS_DIGEST_METADATA_KEY.to_string(),
            value: compiler_facts_digest,
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_OBLIGATION_SOURCE_DIGEST_METADATA_KEY.to_string(),
            value: obligation_source_digest,
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_ARTIFACT_FINGERPRINT_METADATA_KEY.to_string(),
            value: artifact_fingerprint,
        },
    ];
    if let Some(assertion_id) = assertion_id {
        entries.push(trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_ASSERTION_ID_METADATA_KEY.to_string(),
            value: assertion_id,
        });
    }
    if let Some(replay_engine) = replay_engine {
        entries.push(trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_REPLAY_ENGINE_METADATA_KEY.to_string(),
            value: replay_engine,
        });
    }
    if let Some(replay_invocation) = replay_invocation {
        entries.push(trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_REPLAY_INVOCATION_METADATA_KEY.to_string(),
            value: replay_invocation,
        });
    }
    if let Some(replay_transcript_digest) = replay_transcript_digest {
        entries.push(trust_verifier_api::MetadataEntry {
            key: TRUST_TRUST_IR_NATIVE_REPLAY_TRANSCRIPT_DIGEST_METADATA_KEY.to_string(),
            value: replay_transcript_digest,
        });
    }
    Ok(entries)
}

fn native_compiler_fact_source_json(
    source: &trust_ir::NativeObligationSource,
) -> serde_json::Value {
    serde_json::json!({
        "proof_obligation_id": source.obligation.index(),
        "public_obligation_id": source.public_obligation_id,
        "function_id": source.function.map(|id| id.index()),
        "assertion_id": source.assertion_id.map(|id| id.index()),
        "span": source.span.map(native_source_span_json),
        "cause": native_obligation_cause_name(source.cause),
        "monomorphization_id": source.monomorphization.map(|id| id.index()),
        "fact_refs": source.facts.iter().map(native_compiler_fact_ref_json).collect::<Vec<_>>(),
    })
}

fn native_json_digest(schema: &str, value: &serde_json::Value) -> Result<String, String> {
    let canonical = canonical_json_value(value);
    let bytes = serde_json::to_vec(&canonical)
        .map_err(|error| format!("failed to serialize native TrustIr metadata digest: {error}"))?;
    let mut material = schema.as_bytes().to_vec();
    material.push(0);
    material.extend(bytes);
    Ok(trust_types::stable_sha256_hex(&material))
}

struct TrustMcTypedChcConstraint {
    vars: Vec<serde_json::Value>,
    constraint: serde_json::Value,
}

enum TrustMcTypedChcLowering {
    Supported(TrustMcTypedChcConstraint),
    Unsupported(String),
}

fn trust_mc_fallback_obligation_digest(
    label: &str,
    obligation: &trust_verifier_api::TrustObligation,
) -> String {
    let material = serde_json::json!({
        "schema": "trustc.trust-mc-fallback-obligation-digest.v1",
        "label": label,
        "obligation": obligation,
    });
    let bytes = serde_json::to_vec(&canonical_json_value(&material))
        .unwrap_or_else(|_| material.to_string().into_bytes());
    trust_types::stable_sha256_hex(&bytes)
}

fn trust_mc_typed_chc_binding_json(
    obligation: &trust_verifier_api::TrustObligation,
    contract_id: &str,
    native_obligation_id: &str,
    source_digest: &str,
    vc_digest: &str,
    synthetic_digest: &str,
) -> serde_json::Value {
    serde_json::json!({
        "schema_version": TRUST_MC_TYPED_CHC_BINDING_SCHEMA,
        "typed_chc_schema": TRUST_MC_TYPED_CHC_OBLIGATION_SCHEMA,
        "public_obligation_id": obligation.obligation_id,
        "native_obligation_id": native_obligation_id,
        "synthetic_contract_id": contract_id,
        "source_digest": {
            "algorithm": "sha256",
            "value": source_digest,
        },
        "vc_digest": {
            "algorithm": "sha256",
            "value": vc_digest,
        },
        "synthetic_chc_digest": {
            "algorithm": "sha256",
            "value": synthetic_digest,
        },
    })
}

fn trust_mc_typed_chc_binding_metadata_entries(
    source_digest: &str,
    vc_digest: &str,
    synthetic_digest: &str,
    binding_metadata: String,
) -> Vec<trust_verifier_api::MetadataEntry> {
    vec![
        trust_verifier_api::MetadataEntry {
            key: TRUST_MC_TYPED_CHC_SOURCE_DIGEST_METADATA_KEY.to_string(),
            value: source_digest.to_string(),
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_MC_TYPED_CHC_VC_DIGEST_METADATA_KEY.to_string(),
            value: vc_digest.to_string(),
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_MC_TYPED_CHC_SYNTHETIC_DIGEST_METADATA_KEY.to_string(),
            value: synthetic_digest.to_string(),
        },
        trust_verifier_api::MetadataEntry {
            key: TRUST_MC_TYPED_CHC_BINDING_METADATA_KEY.to_string(),
            value: binding_metadata,
        },
    ]
}

fn trust_mc_synthetic_typed_chc_digest(value: &serde_json::Value) -> Result<String, String> {
    let canonical = canonical_json_value(value);
    let bytes = serde_json::to_vec(&canonical).map_err(|error| {
        format!("failed to serialize synthetic trust-mc typed CHC input: {error}")
    })?;
    let mut material = b"trust-mc.typed-chc-obligation.digest.v1\0".to_vec();
    material.extend(bytes);
    Ok(trust_types::stable_sha256_hex(&material))
}

fn canonical_json_value(value: &serde_json::Value) -> serde_json::Value {
    match value {
        serde_json::Value::Array(values) => {
            serde_json::Value::Array(values.iter().map(canonical_json_value).collect())
        }
        serde_json::Value::Object(map) => {
            let mut entries: Vec<_> = map.iter().collect();
            entries.sort_by(|(left, _), (right, _)| left.cmp(right));
            let mut canonical = serde_json::Map::new();
            for (key, value) in entries {
                canonical.insert(key.clone(), canonical_json_value(value));
            }
            serde_json::Value::Object(canonical)
        }
        _ => value.clone(),
    }
}

#[cfg(test)]
fn trust_mc_typed_chc_constraint_for_obligation(
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<TrustMcTypedChcConstraint>, String> {
    Ok(match trust_mc_typed_chc_lowering_for_obligation(obligation) {
        TrustMcTypedChcLowering::Supported(constraint) => Some(constraint),
        TrustMcTypedChcLowering::Unsupported(_) => None,
    })
}

fn trust_mc_typed_chc_lowering_for_obligation(
    obligation: &trust_verifier_api::TrustObligation,
) -> TrustMcTypedChcLowering {
    if !trust_mc_can_emit_direct_typed_chc_input(obligation) {
        return TrustMcTypedChcLowering::Unsupported(format!(
            "trust-mc typed CHC lowering is not configured for {:?} obligations",
            obligation.kind
        ));
    }
    let Some(schema) =
        api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SCHEMA_METADATA_KEY)
    else {
        return TrustMcTypedChcLowering::Unsupported(format!(
            "missing `{TRUST_VC_FORMULA_SCHEMA_METADATA_KEY}` typed formula schema metadata"
        ));
    };
    if schema != trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION {
        return TrustMcTypedChcLowering::Unsupported(format!(
            "unsupported trust-mc typed CHC formula schema `{schema}`, expected `{}`",
            trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION
        ));
    }
    let Some(payload) = obligation
        .metadata
        .iter()
        .find(|entry| entry.key == TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
        .map(|entry| entry.value.as_str())
    else {
        return TrustMcTypedChcLowering::Unsupported(format!(
            "missing `{TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY}` typed formula payload metadata"
        ));
    };
    // Trust (R1 corpus): `from_str_deep` — dense loop-unrolled functions emit
    // legitimately >128-deep predicate trees; the plain parse failed with
    // "recursion limit exceeded", marked the lowering unsupported, and the
    // obligation fell through to trust-mc with no typed input (cascade noise
    // instead of a real solve). The bounded big-stack fallback recovers those;
    // past-bound payloads keep this honest Unsupported arm.
    let predicate: trust_verifier_api::TrustSpecPredicate =
        match trust_types::json_depth::from_str_deep(payload) {
            Ok(predicate) => predicate,
            Err(err) => {
                return TrustMcTypedChcLowering::Unsupported(format!(
                    "malformed TrustSpecPredicate metadata on obligation `{}`: {err}",
                    obligation.obligation_id
                ));
            }
        };
    if !predicate.has_current_schema() {
        return TrustMcTypedChcLowering::Unsupported(format!(
            "unsupported TrustSpecPredicate schema `{}`, expected `{}`",
            predicate.schema_version,
            trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION
        ));
    }
    if let Err(reason) = predicate.validate() {
        return TrustMcTypedChcLowering::Unsupported(format!(
            "invalid TrustSpecPredicate metadata on obligation `{}`: {reason}",
            obligation.obligation_id
        ));
    }
    if predicate.root_sort != trust_verifier_api::TrustSpecSort::Bool
        || predicate.root.sort != trust_verifier_api::TrustSpecSort::Bool
    {
        return TrustMcTypedChcLowering::Unsupported(
            "TrustSpecPredicate root must be a typed boolean predicate".to_string(),
        );
    }
    let constraint = match trust_mc_typed_chc_expr_from_trust_spec(&predicate.root) {
        Ok(constraint) => constraint,
        Err(reason) => return TrustMcTypedChcLowering::Unsupported(reason),
    };
    if trust_mc_typed_chc_expr_is_bool_true(&constraint) {
        return TrustMcTypedChcLowering::Unsupported(
            "TrustSpecPredicate lowered to boolean true; no trust-mc CHC error condition was emitted"
                .to_string(),
        );
    }
    let vars = match predicate
        .variables
        .iter()
        .map(trust_mc_typed_chc_var_from_trust_spec)
        .collect::<Result<Vec<_>, _>>()
    {
        Ok(vars) => vars,
        Err(reason) => return TrustMcTypedChcLowering::Unsupported(reason),
    };
    TrustMcTypedChcLowering::Supported(TrustMcTypedChcConstraint { vars, constraint })
}

fn trust_mc_can_emit_direct_typed_chc_input(
    obligation: &trust_verifier_api::TrustObligation,
) -> bool {
    // Trust (P1.2 — postconditions via trust-mc CHC/PDR): a body-aware
    // `#[ensures]` VC (`vc:<fn>:postcondition:<i>`, origin `VerificationCondition`)
    // carries a typed `TrustSpecPredicate` payload of `¬postcond ∧ body_defs`
    // (the return slot `_0` pinned to its computed value; see
    // `generate_v2_contract_vcs_impl`). That is a standard CHC error-reachability
    // query: UNSAT ⇒ the postcondition is proved, SAT ⇒ refuted with a
    // counterexample. trust-wp's NATIVE pure replay is a constant-folder that
    // cannot consume the body relation (it returns "symbolic or unsupported
    // operands"), so postconditions used to land Unknown. trust-mc's typed-CHC
    // runner already discharges the analogous arithmetic goals over the same
    // formula pipeline; admit Postcondition here so it runs. SOUNDNESS: only a
    // Postcondition obligation that actually carries the typed formula payload
    // reaches a CHC (the lowering returns Unsupported otherwise), and a trust-mc
    // PdrInvariant/ChcValidity proof is a real unbounded proof — never a bounded
    // guess.
    // Trust (P1.2 precedent, extended): Precondition is admitted for the same
    // reason as Postcondition — a call-site precondition VC carries the same
    // typed `TrustSpecPredicate` violation payload over the body relation, and
    // only a payload-carrying obligation reaches a CHC (the lowering returns
    // Unsupported otherwise). See the Precondition arm in
    // `native_trust_ir_route_for_api_obligation`.
    matches!(
        obligation.kind,
        trust_verifier_api::ObligationKind::ArithmeticSafety
            | trust_verifier_api::ObligationKind::Assertion
            | trust_verifier_api::ObligationKind::Postcondition
            | trust_verifier_api::ObligationKind::Precondition
            | trust_verifier_api::ObligationKind::LoopInvariant
            | trust_verifier_api::ObligationKind::Termination
    ) || matches!(
        &obligation.kind,
        trust_verifier_api::ObligationKind::Custom { namespace, .. }
            if namespace == trust_verifier_api::TRUST_VC_HARDENED_OBLIGATION_NAMESPACE
    )
}

fn trust_mc_typed_chc_var_from_trust_spec(
    variable: &trust_verifier_api::TrustSpecVariable,
) -> Result<serde_json::Value, String> {
    if variable.name.trim().is_empty() {
        return Err("TrustSpecPredicate variable name is empty".to_string());
    }
    Ok(serde_json::json!({
        "name": variable.name,
        "sort": trust_mc_typed_chc_sort_from_trust_spec(variable.sort),
    }))
}

fn trust_mc_typed_chc_expr_from_trust_spec(
    expr: &trust_verifier_api::TrustSpecExpr,
) -> Result<serde_json::Value, String> {
    use trust_verifier_api::{
        TrustSpecBinaryOp, TrustSpecBvBinaryOp, TrustSpecBvUnaryOp, TrustSpecExprKind,
        TrustSpecSort, TrustSpecUnaryOp,
    };

    match &expr.kind {
        TrustSpecExprKind::BoolLiteral { value } => {
            trust_mc_require_trust_spec_sort(expr, TrustSpecSort::Bool, "bool literal")?;
            Ok(serde_json::json!({ "kind": "bool_const", "value": value }))
        }
        TrustSpecExprKind::IntLiteral { value } => {
            trust_mc_require_trust_spec_sort(expr, TrustSpecSort::Int, "int literal")?;
            Ok(serde_json::json!({ "kind": "int_const", "value": value }))
        }
        TrustSpecExprKind::Variable { name } => {
            if name.trim().is_empty() {
                return Err("TrustSpecPredicate variable reference has an empty name".to_string());
            }
            Ok(serde_json::json!({
                "kind": "var",
                "name": name,
                "sort": trust_mc_typed_chc_sort_from_trust_spec(expr.sort),
            }))
        }
        TrustSpecExprKind::Unary { op, expr: inner } => {
            let op = match op {
                TrustSpecUnaryOp::Not => "not",
                TrustSpecUnaryOp::Neg => "neg",
                _ => {
                    return Err(
                        "TrustSpecPredicate unary operator is outside trust-mc typed CHC int/bool fragment"
                            .to_string(),
                    );
                }
            };
            Ok(serde_json::json!({
                "kind": "unary",
                "op": op,
                "expr": trust_mc_typed_chc_expr_from_trust_spec(inner)?,
            }))
        }
        TrustSpecExprKind::Binary { op, lhs, rhs } => {
            let op = match op {
                TrustSpecBinaryOp::Add => "add",
                TrustSpecBinaryOp::Sub => "sub",
                TrustSpecBinaryOp::Mul => "mul",
                TrustSpecBinaryOp::Div => "div",
                TrustSpecBinaryOp::Mod => "mod",
                TrustSpecBinaryOp::Eq => "eq",
                TrustSpecBinaryOp::Ne => "ne",
                TrustSpecBinaryOp::Lt => "lt",
                TrustSpecBinaryOp::Le => "le",
                TrustSpecBinaryOp::Gt => "gt",
                TrustSpecBinaryOp::Ge => "ge",
                TrustSpecBinaryOp::And => "and",
                TrustSpecBinaryOp::Or => "or",
                TrustSpecBinaryOp::Implies => "implies",
                _ => {
                    return Err(
                        "TrustSpecPredicate binary operator is outside trust-mc typed CHC int/bool fragment"
                            .to_string(),
                    );
                }
            };
            Ok(serde_json::json!({
                "kind": "binary",
                "op": op,
                "lhs": trust_mc_typed_chc_expr_from_trust_spec(lhs)?,
                "rhs": trust_mc_typed_chc_expr_from_trust_spec(rhs)?,
            }))
        }
        TrustSpecExprKind::BitVecLiteral { value, width } => {
            trust_mc_require_trust_spec_sort(
                expr,
                TrustSpecSort::BitVec { width: *width },
                "bit-vector literal",
            )?;
            Ok(serde_json::json!({
                "kind": "bit_vec_const",
                "value": value,
                "width": width,
            }))
        }
        TrustSpecExprKind::BvUnary { op, expr: inner, .. } => {
            let inner = trust_mc_typed_chc_expr_from_trust_spec(inner)?;
            match op {
                TrustSpecBvUnaryOp::Not => Ok(serde_json::json!({
                    "kind": "unary",
                    "op": "bv_not",
                    "expr": inner,
                })),
                TrustSpecBvUnaryOp::SignExt { extend_by } => Ok(serde_json::json!({
                    "kind": "unary",
                    "op": "bv_sign_ext",
                    "extend_by": extend_by,
                    "expr": inner,
                })),
                TrustSpecBvUnaryOp::Extract { high, low } => Ok(serde_json::json!({
                    "kind": "unary",
                    "op": "bv_extract",
                    "high": high,
                    "low": low,
                    "expr": inner,
                })),
                _ => Err(
                    "TrustSpecPredicate bit-vector unary operator is outside trust-mc typed CHC fragment"
                        .to_string(),
                ),
            }
        }
        TrustSpecExprKind::BvBinary { op, lhs, rhs, .. } => {
            let op = match op {
                TrustSpecBvBinaryOp::Add => "bv_add",
                TrustSpecBvBinaryOp::Sub => "bv_sub",
                TrustSpecBvBinaryOp::Mul => "bv_mul",
                TrustSpecBvBinaryOp::Udiv => "bv_udiv",
                TrustSpecBvBinaryOp::Urem => "bv_urem",
                TrustSpecBvBinaryOp::And => "bv_and",
                TrustSpecBvBinaryOp::Or => "bv_or",
                TrustSpecBvBinaryOp::Xor => "bv_xor",
                TrustSpecBvBinaryOp::Shl => "bv_shl",
                TrustSpecBvBinaryOp::Lshr => "bv_lshr",
                TrustSpecBvBinaryOp::Ashr => "bv_ashr",
                TrustSpecBvBinaryOp::Ult => "bv_ult",
                TrustSpecBvBinaryOp::Ule => "bv_ule",
                TrustSpecBvBinaryOp::Ugt => "bv_ugt",
                TrustSpecBvBinaryOp::Uge => "bv_uge",
                TrustSpecBvBinaryOp::Slt => "bv_slt",
                TrustSpecBvBinaryOp::Sle => "bv_sle",
                _ => {
                    return Err(
                        "TrustSpecPredicate bit-vector binary operator is outside trust-mc typed CHC fragment"
                            .to_string(),
                    );
                }
            };
            Ok(serde_json::json!({
                "kind": "binary",
                "op": op,
                "lhs": trust_mc_typed_chc_expr_from_trust_spec(lhs)?,
                "rhs": trust_mc_typed_chc_expr_from_trust_spec(rhs)?,
            }))
        }
        TrustSpecExprKind::BvFromInt { expr: inner, width } => Ok(serde_json::json!({
            "kind": "unary",
            "op": "int_to_bv",
            "width": width,
            "expr": trust_mc_typed_chc_expr_from_trust_spec(inner)?,
        })),
        // BV→Int carries only `signed`; the operand width is intrinsic to the
        // operand's own bit-vector sort (ay's bv2int derives it), so — matching
        // the reference `ay_bridge` lowering which ignores `Formula::BvToInt`'s
        // width — we do not emit it (and the reader rejects a stray `width`).
        TrustSpecExprKind::IntFromBv { expr: inner, signed, width: _ } => {
            Ok(serde_json::json!({
                "kind": "unary",
                "op": "bv_to_int",
                "signed": signed,
                "expr": trust_mc_typed_chc_expr_from_trust_spec(inner)?,
            }))
        }
        TrustSpecExprKind::Index { base, index } => Ok(serde_json::json!({
            "kind": "select",
            "array": trust_mc_typed_chc_expr_from_trust_spec(base)?,
            "index": trust_mc_typed_chc_expr_from_trust_spec(index)?,
        })),
        TrustSpecExprKind::Result
        | TrustSpecExprKind::Old { .. }
        | TrustSpecExprKind::Field { .. }
        | TrustSpecExprKind::Quantifier { .. } => {
            Err("TrustSpecPredicate node is outside trust-mc typed CHC native int/bool VC fragment"
                .to_string())
        }
        _ => Err(
            "TrustSpecPredicate future node is outside trust-mc typed CHC native int/bool VC fragment"
                .to_string(),
        ),
    }
}

fn trust_mc_require_trust_spec_sort(
    expr: &trust_verifier_api::TrustSpecExpr,
    expected: trust_verifier_api::TrustSpecSort,
    context: &str,
) -> Result<(), String> {
    if expr.sort == expected {
        Ok(())
    } else {
        Err(format!(
            "TrustSpecPredicate {context} has sort {:?}, expected {:?}",
            expr.sort, expected
        ))
    }
}

fn trust_mc_typed_chc_sort_from_trust_spec(
    sort: trust_verifier_api::TrustSpecSort,
) -> serde_json::Value {
    match sort {
        trust_verifier_api::TrustSpecSort::Bool => serde_json::json!({ "kind": "bool" }),
        trust_verifier_api::TrustSpecSort::Int => serde_json::json!({ "kind": "int" }),
        trust_verifier_api::TrustSpecSort::BitVec { width } => {
            serde_json::json!({ "kind": "bit_vec", "width": width })
        }
        trust_verifier_api::TrustSpecSort::Array { element } => serde_json::json!({
            "kind": "array",
            "index": { "kind": "int" },
            "element": trust_mc_typed_chc_scalar_sort_from_trust_spec(element),
        }),
        // Trust: transport the TRUE sort. trust-mc's typed CHC lowering is
        // exact-or-reject — an unmodeled sort kind is a hard decline (Unknown),
        // never a mistyped encoding — so emitting the honest float shape here
        // fails closed at the solver boundary instead of lying upstream.
        trust_verifier_api::TrustSpecSort::Float { eb, sb } => {
            serde_json::json!({ "kind": "float", "eb": eb, "sb": sb })
        }
    }
}

fn trust_mc_typed_chc_scalar_sort_from_trust_spec(
    sort: trust_verifier_api::TrustSpecScalarSort,
) -> serde_json::Value {
    match sort {
        trust_verifier_api::TrustSpecScalarSort::Bool => {
            serde_json::json!({ "kind": "bool" })
        }
        trust_verifier_api::TrustSpecScalarSort::Int => {
            serde_json::json!({ "kind": "int" })
        }
        trust_verifier_api::TrustSpecScalarSort::BitVec { width } => {
            serde_json::json!({ "kind": "bit_vec", "width": width })
        }
    }
}

fn trust_mc_typed_chc_expr_is_bool_true(expr: &serde_json::Value) -> bool {
    expr.get("kind").and_then(serde_json::Value::as_str) == Some("bool_const")
        && expr.get("value").and_then(serde_json::Value::as_bool) == Some(true)
}

fn trust_mc_native_trust_ir_obligation_id(request_id: u32, proof_obligation_id: u32) -> String {
    // Trust: the native id MUST use the underscore "trust_mc" spelling so the
    // typed-CHC binding's `native_obligation_id` matches what the native runner
    // emits (trust-mc-trust-bmc native_bundle.rs builds
    // `trust_ir-native-trust_mc-request-…`) and what the trust-bmc adapter
    // expects (`native_trust_ir_expected_trust_mc_obligation_id`). A hyphenated
    // "trust-mc" here fails the binding-identity check
    // (verifier_api.rs:validate_trust_mc_typed_chc_binding_identity), which
    // silently downgrades an already-proved native CHC/PDR obligation to
    // Unsupported and hands it to the ay bridge. The hyphenated display spelling
    // belongs only to the canonical *report* id (`native_trust_ir_proof_unit_id`).
    format!("trust_ir-native-trust_mc-request-{request_id}-proof-{proof_obligation_id}")
}

fn trust_mc_native_typed_chc_metadata_json(
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    request: &trust_ir::TrustMcNativeRequest,
    proof_obligation_id: trust_ir::ProofId,
) -> serde_json::Value {
    let (adapter_input, source_digest) = match native_trust_ir_bundle.input {
        trust_ir::NativeAdapterInput::RustMir { body_digest } => {
            ("rust-mir", Some(native_artifact_digest_json(body_digest)))
        }
        trust_ir::NativeAdapterInput::TrustIrModule => ("trust_ir-module", None),
    };

    serde_json::json!({
        "schema_version": 3,
        "producer": native_bundle_producer_name(native_trust_ir_bundle.producer),
        "adapter_input": adapter_input,
        "source_digest": source_digest,
        "trust_ir_module_digest": native_artifact_digest_json(native_trust_ir_bundle.trust_ir_module_digest),
        "lineage_manifest_digest": native_artifact_digest_json(native_trust_ir_bundle.lineage.stable_digest()),
        "native_request_id": request.id.index(),
        "verification_mode": trust_mc_verification_mode_name(request.mode),
        "function_id": request.function.index(),
        "proof_obligation_ids": [proof_obligation_id.index()],
        "lineage_root_ids": request.lineage_roots.iter().map(|id| id.index()).collect::<Vec<_>>(),
        "compiler_facts_digest": native_artifact_digest_json(native_trust_ir_bundle.compiler_facts.stable_digest()),
        "compiler_fact_counts": native_compiler_fact_counts_json(&native_trust_ir_bundle.compiler_facts),
        "compiler_fact_sources": native_compiler_fact_sources_json(
            &native_trust_ir_bundle.compiler_facts,
            proof_obligation_id,
        ),
        "replay_identity": request.provenance.replay_identity().and_then(native_replay_identity_json),
        "replay_context": native_replay_context_json(request.provenance.replay_context()),
    })
}

fn native_artifact_digest_json(digest: trust_ir::ProofDigest) -> serde_json::Value {
    serde_json::json!({
        "algorithm": digest.algorithm.to_string(),
        "value": native_artifact_digest_hex(digest),
    })
}

fn native_artifact_digest_hex(digest: trust_ir::ProofDigest) -> String {
    digest.bytes.iter().map(|byte| format!("{byte:02x}")).collect::<String>()
}

fn native_bundle_producer_name(producer: trust_ir::NativeBundleProducer) -> &'static str {
    match producer {
        trust_ir::NativeBundleProducer::TRust => "Trust",
        trust_ir::NativeBundleProducer::TSwift => "tSwift",
        trust_ir::NativeBundleProducer::TC => "tC",
        trust_ir::NativeBundleProducer::TrustIr => "TrustIr",
    }
}

fn trust_mc_verification_mode_name(mode: trust_ir::TrustMcVerificationMode) -> &'static str {
    match mode {
        trust_ir::TrustMcVerificationMode::BoundedModelCheck => "bmc",
        trust_ir::TrustMcVerificationMode::Chc => "chc",
        trust_ir::TrustMcVerificationMode::Pdr => "pdr",
    }
}

fn native_compiler_fact_counts_json(facts: &trust_ir::NativeCompilerFacts) -> serde_json::Value {
    serde_json::json!({
        "adt_layouts": facts.adt_layouts.len(),
        "fat_pointers": facts.fat_pointers.len(),
        "trait_object_metadata": facts.trait_object_metadata.len(),
        "pointer_offsets": facts.pointer_offsets.len(),
        "casts": facts.casts.len(),
        "monomorphizations": facts.monomorphizations.len(),
        "obligation_sources": facts.obligation_sources.len(),
    })
}

fn native_compiler_fact_sources_json(
    facts: &trust_ir::NativeCompilerFacts,
    proof_obligation_id: trust_ir::ProofId,
) -> Vec<serde_json::Value> {
    facts
        .obligation_sources
        .iter()
        .filter(|source| source.obligation == proof_obligation_id)
        .map(|source| {
            serde_json::json!({
                "proof_obligation_id": source.obligation.index(),
                "function_id": source.function.map(|id| id.index()),
                "span": source.span.map(native_source_span_json),
                "cause": native_obligation_cause_name(source.cause),
                "monomorphization_id": source.monomorphization.map(|id| id.index()),
                "fact_refs": source.facts.iter().map(native_compiler_fact_ref_json).collect::<Vec<_>>(),
            })
        })
        .collect()
}

fn native_compiler_fact_ref_json(fact: &trust_ir::NativeCompilerFactRef) -> serde_json::Value {
    let (kind, id) = match *fact {
        trust_ir::NativeCompilerFactRef::AdtLayout(id) => ("AdtLayout", id.index()),
        trust_ir::NativeCompilerFactRef::FatPointer(id) => ("FatPointer", id.index()),
        trust_ir::NativeCompilerFactRef::Cast(id) => ("Cast", id.index()),
        trust_ir::NativeCompilerFactRef::Monomorphization(id) => ("Monomorphization", id.index()),
        trust_ir::NativeCompilerFactRef::TraitObjectMetadata(id) => {
            ("TraitObjectMetadata", id.index())
        }
        trust_ir::NativeCompilerFactRef::PointerOffset(id) => ("PointerOffset", id.index()),
    };
    serde_json::json!({ "kind": kind, "id": id })
}

fn native_source_span_json(span: trust_ir::SourceSpan) -> serde_json::Value {
    serde_json::json!({ "file": span.file, "line": span.line, "col": span.col })
}

fn native_obligation_cause_name(cause: trust_ir::NativeObligationCause) -> &'static str {
    match cause {
        trust_ir::NativeObligationCause::Precondition => "Precondition",
        trust_ir::NativeObligationCause::Postcondition => "Postcondition",
        trust_ir::NativeObligationCause::Assert => "Assert",
        trust_ir::NativeObligationCause::BoundsCheck => "BoundsCheck",
        trust_ir::NativeObligationCause::OverflowCheck => "OverflowCheck",
        trust_ir::NativeObligationCause::LayoutCheck => "LayoutCheck",
        trust_ir::NativeObligationCause::CastCheck => "CastCheck",
        trust_ir::NativeObligationCause::BorrowCheck => "BorrowCheck",
        trust_ir::NativeObligationCause::Translation => "Translation",
        trust_ir::NativeObligationCause::Panic => "Panic",
        trust_ir::NativeObligationCause::PointerOffset => "PointerOffset",
        trust_ir::NativeObligationCause::Other => "Other",
        trust_ir::NativeObligationCause::Temporal => "Temporal",
    }
}

fn native_replay_identity_json(
    replay: &trust_ir::ProofReplayIdentity,
) -> Option<serde_json::Value> {
    Some(serde_json::json!({
        "engine": replay.engine.clone(),
        "invocation": replay.invocation.clone(),
        "transcript_digest": native_artifact_digest_json(replay.transcript_digest?),
    }))
}

fn native_replay_context_json(context: &trust_ir::NativeReplayContext) -> serde_json::Value {
    serde_json::json!({
        "atoms": context.atoms.iter().map(native_replay_atom_json).collect::<Vec<_>>(),
        "unsupported_modes": context.unsupported_modes.iter().map(native_unsupported_mode_json).collect::<Vec<_>>(),
    })
}

fn native_replay_atom_json(atom: &trust_ir::NativeReplayAtom) -> serde_json::Value {
    serde_json::json!({
        "atom_id": atom.id.index(),
        "kind": native_replay_atom_kind_name(atom.kind),
        "formula_schema": atom.formula.schema.clone(),
        "payload_digest": native_artifact_digest_json(atom.payload_digest),
        "proof_obligation_id": atom.obligation.map(|id| id.index()),
        "assertion_id": atom.assertion_id.map(|id| id.index()),
        "span": atom.span.map(native_source_span_json),
    })
}

fn native_replay_atom_kind_name(kind: trust_ir::NativeReplayAtomKind) -> &'static str {
    match kind {
        trust_ir::NativeReplayAtomKind::Assumption => "Assumption",
        trust_ir::NativeReplayAtomKind::Assertion => "Assertion",
    }
}

fn native_unsupported_mode_json(mode: &trust_ir::NativeUnsupportedMode) -> serde_json::Value {
    serde_json::json!({
        "reason": native_unsupported_mode_reason_name(mode.reason),
        "detail": mode.detail.clone(),
    })
}

fn native_unsupported_mode_reason_name(
    reason: trust_ir::NativeUnsupportedModeReason,
) -> &'static str {
    match reason {
        trust_ir::NativeUnsupportedModeReason::UnsupportedVerifierMode => {
            "unsupported-verifier-mode"
        }
        trust_ir::NativeUnsupportedModeReason::UnsupportedFormulaSchema => {
            "unsupported-formula-schema"
        }
        trust_ir::NativeUnsupportedModeReason::UnsupportedCompilerFact => {
            "unsupported-compiler-fact"
        }
        trust_ir::NativeUnsupportedModeReason::MissingSourceSpan => "missing-source-span",
        trust_ir::NativeUnsupportedModeReason::MissingReplayTranscript => {
            "missing-replay-transcript"
        }
        trust_ir::NativeUnsupportedModeReason::Other => "other",
    }
}

fn annotate_verifier_api_obligations_with_native_trust_ir(
    bundle: &mut trust_verifier_api::TrustContractBundle,
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    bindings: &[PendingNativeTrustIrBinding],
) -> Result<(), String> {
    let mut trust_mc_typed_contracts = Vec::new();
    let trust_vc_imports = if bindings
        .iter()
        .any(|binding| binding.verifier_suite.eq_ignore_ascii_case("trust-vc"))
    {
        Some(
            trust_vc_bridge::trust_vc_native_trust_ir_imported_proof_artifacts_from_bundle(
                native_trust_ir_bundle,
            )
            .map_err(|error| {
                format!(
                    "failed to derive trust-vc native TrustIr proof-certificate metadata from compiler bundle: {error}"
                )
            })?,
        )
    } else {
        None
    };
    let trust_vc_import_index = if let Some(imports) = trust_vc_imports.as_ref() {
        let mut index = FxHashMap::default();
        for import in imports {
            let key = (import.request_id, import.trust_ir_obligation_id);
            if index.insert(key, import).is_some() {
                return Err(format!(
                    "ambiguous trust-vc native TrustIr proof-certificate imports for request {} proof obligation {}",
                    key.0, key.1
                ));
            }
        }
        Some(index)
    } else {
        None
    };
    for binding in bindings {
        let request = native_trust_ir_bundle
            .requests
            .iter()
            .find(|request| {
                native_trust_ir_suite_label_matches(
                    &request.verifier_suite().to_string(),
                    binding.verifier_suite,
                ) && request.obligations().contains(&binding.proof_obligation_id)
            })
            .ok_or_else(|| {
                format!(
                    "typed TrustIr NativeVerificationBundle has no {} request for proof obligation {}",
                    binding.verifier_suite,
                    binding.proof_obligation_id.index()
                )
        })?;
        let trust_vc_import = if binding.verifier_suite.eq_ignore_ascii_case("trust-vc") {
            let imports = trust_vc_import_index.as_ref().ok_or_else(|| {
                "missing trust-vc native TrustIr proof-certificate import metadata".to_string()
            })?;
            Some(
                imports
                    .get(&(request.id().index(), binding.proof_obligation_id.index()))
                    .copied()
                    .ok_or_else(|| {
                        format!(
                            "trust-vc native TrustIr proof-certificate import missing request {} proof obligation {}",
                            request.id().index(),
                            binding.proof_obligation_id.index()
                        )
                    })?,
            )
        } else {
            None
        };
        let trust_vc_proof_unit_overrides =
            trust_vc_import.map(trust_vc_native_trust_ir_proof_unit_metadata_overrides);

        let trust_wp_metadata = if binding.verifier_suite.eq_ignore_ascii_case("trust-wp") {
            let obligation = bundle.obligations.get(binding.obligation_index).ok_or_else(|| {
                format!(
                    "native TrustIr binding referenced missing public obligation index {}",
                    binding.obligation_index
                )
            })?;
            let mut metadata =
                trust_router::full_verification::trust_wp_native_replay_metadata_entries_for_request(
                    native_trust_ir_bundle,
                    request,
                    binding.proof_obligation_id,
                )?;
            if let Some(proof_context) = trust_wp_typed_pure_expr_proof_context_metadata_entry(
                &bundle.contracts,
                obligation,
                native_trust_ir_bundle,
                request,
                binding.proof_obligation_id,
            )? {
                metadata.retain(|entry| {
                    entry.key
                        != trust_router::full_verification::TRUST_TRUST_WP_PROOF_CONTEXT_METADATA_KEY
                });
                metadata.push(proof_context);
            }
            metadata
        } else {
            Vec::new()
        };

        let obligation = bundle.obligations.get_mut(binding.obligation_index).ok_or_else(|| {
            format!(
                "native TrustIr binding referenced missing public obligation index {}",
                binding.obligation_index
            )
        })?;

        obligation.metadata.extend([
            trust_verifier_api::MetadataEntry {
                key: trust_router::full_verification::TRUST_TRUST_IR_NATIVE_VERIFIER_SUITE_METADATA_KEY
                    .to_string(),
                value: binding.verifier_suite.to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: trust_router::full_verification::TRUST_TRUST_IR_NATIVE_REQUEST_ID_METADATA_KEY
                    .to_string(),
                value: request.id().index().to_string(),
            },
            trust_verifier_api::MetadataEntry {
                key: trust_router::full_verification::TRUST_TRUST_IR_NATIVE_PROOF_OBLIGATION_ID_METADATA_KEY
                    .to_string(),
                value: binding.proof_obligation_id.index().to_string(),
            },
        ]);
        if binding.verifier_suite.eq_ignore_ascii_case("trust-wp")
            || binding.verifier_suite.eq_ignore_ascii_case("trust-mc")
            || binding.verifier_suite.eq_ignore_ascii_case("trust-vc")
        {
            obligation.metadata.extend(native_trust_ir_proof_unit_metadata_entries(
                native_trust_ir_bundle,
                request,
                binding.proof_obligation_id,
                trust_vc_proof_unit_overrides.as_ref(),
            )?);
        }
        obligation.metadata.extend(trust_wp_metadata);
        if let Some(import) = trust_vc_import {
            extend_missing_obligation_metadata(
                &mut obligation.metadata,
                trust_vc_bridge::trust_vc_native_trust_ir_import_metadata_entries(import),
            );
        }
        if binding.verifier_suite.eq_ignore_ascii_case("trust-mc") {
            if let Some(contract) = trust_mc_typed_chc_contract_for_native_trust_ir_obligation(
                native_trust_ir_bundle,
                request,
                binding.proof_obligation_id,
                obligation,
            )? {
                // This derived CHC is likewise transport input. Never replace
                // a public contract identity after the native module has
                // committed the public claim.
                obligation.metadata.push(trust_verifier_api::MetadataEntry {
                    key: TRUST_MC_TYPED_CHC_SYNTHETIC_CONTRACT_METADATA_KEY.to_string(),
                    value: contract.contract_id.clone(),
                });
                obligation.metadata.extend(
                    contract
                        .metadata
                        .iter()
                        .filter(|entry| {
                            matches!(
                                entry.key.as_str(),
                                TRUST_MC_TYPED_CHC_SOURCE_DIGEST_METADATA_KEY
                                    | TRUST_MC_TYPED_CHC_VC_DIGEST_METADATA_KEY
                                    | TRUST_MC_TYPED_CHC_SYNTHETIC_DIGEST_METADATA_KEY
                                    | TRUST_MC_TYPED_CHC_BINDING_METADATA_KEY
                            )
                        })
                        .cloned(),
                );
                trust_mc_typed_contracts.push(contract);
            }
        }
    }

    bundle.contracts.extend(trust_mc_typed_contracts);
    Ok(())
}

fn trust_wp_typed_pure_expr_proof_context_metadata_entry(
    contracts: &[trust_verifier_api::TrustContract],
    obligation: &trust_verifier_api::TrustObligation,
    native_trust_ir_bundle: &trust_ir_bridge::NativeVerificationBundle,
    request: &trust_ir::NativeVerificationRequest,
    proof_obligation_id: trust_ir::ProofId,
) -> Result<Option<trust_verifier_api::MetadataEntry>, String> {
    let Some(assertion_claim) = trust_wp_public_typed_proof_claim(contracts, obligation)? else {
        return Ok(None);
    };
    let trust_ir::NativeVerificationRequest::TrustWp(request) = request else {
        return Err(
            "cannot build trust-wp proof-context metadata from a non-trust-wp request".into()
        );
    };
    if !request.obligations.contains(&proof_obligation_id) {
        return Err(format!(
            "trust-wp request {} does not contain TrustIr proof obligation {}",
            request.id.index(),
            proof_obligation_id.index()
        ));
    }
    let source =
        native_trust_ir_bundle.obligation_source(proof_obligation_id).ok_or_else(|| {
            format!(
                "trust-wp proof obligation {} is missing typed TrustIr obligation-source metadata",
                proof_obligation_id.index()
            )
        })?;
    let expected_span = source.span.ok_or_else(|| {
        format!(
            "trust-wp proof obligation {} is missing typed TrustIr source-span metadata",
            proof_obligation_id.index()
        )
    })?;
    let expected_assertion = source.assertion_id.ok_or_else(|| {
        format!(
            "trust-wp proof obligation {} is missing typed TrustIr assertion metadata",
            proof_obligation_id.index()
        )
    })?;

    let mut replay_atoms = request.provenance.replay_context.atoms.iter().collect::<Vec<_>>();
    replay_atoms.sort_by_key(|atom| atom.id);

    let mut next_index = 0;
    let mut assumptions = Vec::new();
    for atom in replay_atoms.iter().copied().filter(|atom| {
        trust_wp_replay_atom_applies_to_obligation(atom, proof_obligation_id)
            && atom.kind == trust_ir::NativeReplayAtomKind::Assumption
    }) {
        assumptions.push(trust_wp_replay_atom_json(atom, next_index, "assumption", None)?);
        next_index += 1;
    }

    let mut assertions = Vec::new();
    for atom in replay_atoms.iter().copied().filter(|atom| {
        atom.obligation == Some(proof_obligation_id)
            && atom.kind == trust_ir::NativeReplayAtomKind::Assertion
    }) {
        if atom.assertion_id != Some(expected_assertion) {
            return Err(format!(
                "trust-wp proof-context atom {} for request {} obligation {} has assertion {:?}, expected {}",
                atom.id.index(),
                request.id.index(),
                proof_obligation_id.index(),
                atom.assertion_id,
                expected_assertion.index()
            ));
        }
        if atom.span != Some(expected_span) {
            return Err(format!(
                "trust-wp proof-context atom {} for request {} obligation {} has span {:?}, expected {:?}",
                atom.id.index(),
                request.id.index(),
                proof_obligation_id.index(),
                atom.span,
                expected_span
            ));
        }
        assertions.push(trust_wp_replay_atom_json(
            atom,
            next_index,
            "assertion",
            Some(&assertion_claim),
        )?);
        next_index += 1;
    }

    if assertions.is_empty() {
        return Err(format!(
            "trust-wp request {} has no assertion proof-context atom bound to TrustIr proof obligation {}",
            request.id.index(),
            proof_obligation_id.index()
        ));
    }

    Ok(Some(trust_verifier_api::MetadataEntry {
        key: trust_router::full_verification::TRUST_TRUST_WP_PROOF_CONTEXT_METADATA_KEY.to_string(),
        value: serde_json::json!({
            "assumptions": assumptions,
            "assertions": assertions,
        })
        .to_string(),
    }))
}

fn trust_wp_replay_atom_applies_to_obligation(
    atom: &trust_ir::NativeReplayAtom,
    proof_obligation_id: trust_ir::ProofId,
) -> bool {
    atom.obligation.map_or(true, |obligation| obligation == proof_obligation_id)
}

fn trust_wp_replay_atom_json(
    atom: &trust_ir::NativeReplayAtom,
    index: u32,
    role: &'static str,
    claim_override: Option<&TrustWpProofContextClaim>,
) -> Result<serde_json::Value, String> {
    let claim = match claim_override {
        Some(claim) => claim.clone(),
        None => trust_wp_proof_claim_from_trust_ir_formula(&atom.formula)?,
    };
    let mut object = serde_json::Map::new();
    object.insert("index".to_string(), serde_json::json!(index));
    object.insert("role".to_string(), serde_json::json!(role));
    object.insert("claim".to_string(), claim.to_json());
    object.insert("native_replay_atom_id".to_string(), serde_json::json!(atom.id.index()));
    if let Some(obligation) = atom.obligation {
        object.insert("native_obligation_id".to_string(), serde_json::json!(obligation.index()));
    }
    if let Some(assertion_id) = atom.assertion_id {
        object.insert("native_assertion_id".to_string(), serde_json::json!(assertion_id.index()));
    }
    if let Some(span) = atom.span {
        object.insert(
            "native_span".to_string(),
            serde_json::json!({
                "file_id": span.file,
                "line": span.line,
                "column": span.col,
            }),
        );
    }
    Ok(serde_json::Value::Object(object))
}

const TRUST_WP_PURE_EXPR_SCHEMA_VERSION: &str = "TrustWpPureExprV1";
// Must equal the canonical trust-types tag the trust-wp acceptor expects
// (`trust_wp.trust-formula.v1`, underscore). A divergent literal here (the old
// `trust-wp.trust-formula.v1`, hyphen) made trust-wp reject every native
// formula payload. Reference the canonical const so it can never drift again.
const TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION: &str =
    trust_types::trust_formula_v1::TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION;
const TRUST_TYPES_FORMULA_SCHEMA_VERSION: &str = "trust-types.Formula@1";

#[derive(Debug, Clone, PartialEq, Eq)]
struct TrustWpProofContextClaim {
    format: TrustWpProofContextClaimFormat,
    payload: String,
}

impl TrustWpProofContextClaim {
    fn to_json(&self) -> serde_json::Value {
        let format = match &self.format {
            TrustWpProofContextClaimFormat::TrustWpPureExprV1 => {
                serde_json::json!("trust_wp_pure_expr_v1")
            }
            TrustWpProofContextClaimFormat::TrustFormulaV1 => serde_json::json!("trust_formula_v1"),
            TrustWpProofContextClaimFormat::SmtLib2 => serde_json::json!("smtlib2"),
            TrustWpProofContextClaimFormat::Other(schema) => {
                serde_json::json!({ "other": schema })
            }
        };
        serde_json::json!({
            "format": format,
            "payload": self.payload,
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
enum TrustWpProofContextClaimFormat {
    TrustWpPureExprV1,
    TrustFormulaV1,
    SmtLib2,
    Other(String),
}

fn trust_wp_public_typed_proof_claim(
    contracts: &[trust_verifier_api::TrustContract],
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<TrustWpProofContextClaim>, String> {
    if let Some(contract_id) = obligation.contract_id.as_ref() {
        let Some(contract) = contracts.iter().find(|contract| &contract.contract_id == contract_id)
        else {
            return Err(format!(
                "trust-wp proof-context metadata could not find contract `{contract_id}` for obligation `{}`",
                obligation.obligation_id
            ));
        };

        if let Some(claim) = trust_wp_public_typed_proof_claim_from_contract_predicate(
            contract_id,
            &obligation.obligation_id,
            &contract.predicate,
        )? {
            return Ok(Some(claim));
        }
    }

    trust_wp_public_typed_proof_claim_from_obligation_metadata(obligation)
}

fn trust_wp_public_typed_proof_claim_from_contract_predicate(
    contract_id: &str,
    obligation_id: &str,
    predicate: &trust_verifier_api::ContractPredicate,
) -> Result<Option<TrustWpProofContextClaim>, String> {
    match predicate {
        trust_verifier_api::ContractPredicate::CanonicalJson { schema, value }
        | trust_verifier_api::ContractPredicate::TrustIr { schema, value }
            if schema == TRUST_WP_PURE_EXPR_SCHEMA_VERSION =>
        {
            let (payload, sort) = trust_wp_pure_expr_stable_text(value)?;
            if sort != TrustWpPureExprSort::Bool {
                return Err(format!(
                    "TrustWpPureExprV1 contract `{contract_id}` for obligation `{obligation_id}` is not boolean"
                ));
            }
            Ok(Some(TrustWpProofContextClaim {
                format: TrustWpProofContextClaimFormat::TrustWpPureExprV1,
                payload,
            }))
        }
        trust_verifier_api::ContractPredicate::CanonicalJson { schema, value }
        | trust_verifier_api::ContractPredicate::TrustIr { schema, value }
            if schema == "PureExpr" =>
        {
            let Some(payload) = value.as_str().filter(|payload| !payload.trim().is_empty()) else {
                return Err(format!(
                    "PureExpr contract `{contract_id}` for obligation `{obligation_id}` must be a non-empty string payload"
                ));
            };
            trust_types::trust_formula_v1::reject_trust_wp_pure_expr_v1_text_arithmetic(payload)?;
            Ok(Some(TrustWpProofContextClaim {
                format: TrustWpProofContextClaimFormat::TrustWpPureExprV1,
                payload: payload.to_string(),
            }))
        }
        trust_verifier_api::ContractPredicate::CanonicalJson { schema, value }
        | trust_verifier_api::ContractPredicate::TrustIr { schema, value }
            if schema == TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION =>
        {
            Ok(Some(TrustWpProofContextClaim {
                format: TrustWpProofContextClaimFormat::TrustFormulaV1,
                payload: canonical_trust_formula_payload(value)?,
            }))
        }
        // Trust #1003: raw symbolic `trust-types.Formula@1` postcondition
        // predicate. Lower into the trust-wp.trust-formula.v1 envelope; fail
        // closed (Unsupported) for constructs outside the native int/bool
        // replay fragment so no proof is fabricated from an unlowered predicate.
        trust_verifier_api::ContractPredicate::CanonicalJson { schema, value }
        | trust_verifier_api::ContractPredicate::TrustIr { schema, value }
            if schema == TRUST_TYPES_FORMULA_SCHEMA_VERSION =>
        {
            match trust_types_formula_payload(value) {
                Ok(payload) => Ok(Some(TrustWpProofContextClaim {
                    format: TrustWpProofContextClaimFormat::TrustFormulaV1,
                    payload,
                })),
                Err(e) => {
                    debug!(
                        "trust-wp `trust-types.Formula@1` lowering unsupported for contract `{contract_id}` obligation `{obligation_id}`: {e}"
                    );
                    Ok(None)
                }
            }
        }
        trust_verifier_api::ContractPredicate::CanonicalJson { schema, value }
        | trust_verifier_api::ContractPredicate::TrustIr { schema, value }
            if schema == trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION =>
        {
            let predicate =
                serde_json::from_value::<trust_verifier_api::TrustSpecPredicate>(value.clone())
                    .map_err(|err| {
                        format!(
                            "invalid typed TrustSpecPredicate contract `{contract_id}` for obligation `{obligation_id}`: {err}"
                        )
                    })?;
            match trust_spec_predicate_to_trust_formula_payload(&predicate) {
                Ok(payload) => Ok(Some(TrustWpProofContextClaim {
                    format: TrustWpProofContextClaimFormat::TrustFormulaV1,
                    payload,
                })),
                Err(e) => {
                    debug!(
                        "trust-wp translation unsupported for contract `{contract_id}` obligation `{obligation_id}`: {e}"
                    );
                    Ok(None)
                }
            }
        }
        _ => Ok(None),
    }
}

fn trust_wp_public_typed_proof_claim_from_obligation_metadata(
    obligation: &trust_verifier_api::TrustObligation,
) -> Result<Option<TrustWpProofContextClaim>, String> {
    let Some(schema) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_SCHEMA_METADATA_KEY)
    else {
        return Ok(None);
    };
    if !trust_wp_supported_public_proof_schema(schema) {
        return Ok(None);
    }
    let Some(payload) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
    else {
        return Err(format!(
            "trust-wp proof-context metadata for obligation `{}` has typed schema `{schema}` but no `{TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY}` payload",
            obligation.obligation_id
        ));
    };
    // Trust (R1 corpus): the shared proof-JSON parser preserves the bounded
    // deep fallback while rejecting duplicate keys before schema decoding.
    let value = trust_types::trust_formula_v1::parse_unique_proof_json_payload(payload).map_err(
        |err| {
            format!(
                "trust-wp proof-context metadata for obligation `{}` has invalid JSON `{TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY}` payload: {err}",
                obligation.obligation_id
            )
        },
    )?;
    trust_wp_public_typed_proof_claim_from_schema_value(schema, &value)
}

fn trust_wp_supported_public_proof_schema(schema: &str) -> bool {
    schema == TRUST_WP_PURE_EXPR_SCHEMA_VERSION
        || schema == TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION
        // Trust #1003: raw symbolic `trust-types.Formula@1` predicates are now
        // lowered into the `trust-wp.trust-formula.v1` envelope and routed to
        // trust-wp, so they are a supported proof schema.
        || schema == TRUST_TYPES_FORMULA_SCHEMA_VERSION
        || schema == trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION
}

fn trust_wp_public_typed_proof_claim_from_schema_value(
    schema: &str,
    value: &serde_json::Value,
) -> Result<Option<TrustWpProofContextClaim>, String> {
    if schema == TRUST_WP_PURE_EXPR_SCHEMA_VERSION {
        let (payload, sort) = trust_wp_pure_expr_stable_text(value)?;
        if sort != TrustWpPureExprSort::Bool {
            return Err("TrustWpPureExprV1 proof-context payload is not boolean".to_string());
        }
        return Ok(Some(TrustWpProofContextClaim {
            format: TrustWpProofContextClaimFormat::TrustWpPureExprV1,
            payload,
        }));
    }
    if schema == TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION {
        return Ok(Some(TrustWpProofContextClaim {
            format: TrustWpProofContextClaimFormat::TrustFormulaV1,
            payload: canonical_trust_formula_payload(value)?,
        }));
    }
    if schema == trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION {
        let predicate =
            serde_json::from_value::<trust_verifier_api::TrustSpecPredicate>(value.clone())
                .map_err(|err| format!("invalid typed TrustSpecPredicate proof payload: {err}"))?;
        match trust_spec_predicate_to_trust_formula_payload(&predicate) {
            Ok(payload) => {
                return Ok(Some(TrustWpProofContextClaim {
                    format: TrustWpProofContextClaimFormat::TrustFormulaV1,
                    payload,
                }));
            }
            Err(e) => {
                debug!("trust-wp translation unsupported: {e}");
                return Ok(None);
            }
        }
    }
    // Trust #1003: raw symbolic `trust-types.Formula@1` postcondition predicate.
    // Lower into the trust-wp.trust-formula.v1 envelope; fail closed (Unsupported)
    // for any construct outside trust-wp's native int/bool replay fragment.
    if schema == TRUST_TYPES_FORMULA_SCHEMA_VERSION {
        match trust_types_formula_payload(value) {
            Ok(payload) => {
                return Ok(Some(TrustWpProofContextClaim {
                    format: TrustWpProofContextClaimFormat::TrustFormulaV1,
                    payload,
                }));
            }
            Err(e) => {
                debug!("trust-wp `trust-types.Formula@1` lowering unsupported: {e}");
                return Ok(None);
            }
        }
    }
    Err(format!("unsupported trust-wp proof-context schema `{schema}`"))
}

fn trust_wp_proof_claim_from_trust_ir_formula(
    formula: &trust_ir::ProofFormula,
) -> Result<TrustWpProofContextClaim, String> {
    // Trust #1003: a raw symbolic `trust-types.Formula@1` payload is a
    // serde-serialized `trust_types::Formula`, NOT a `trust-wp.trust-formula.v1`
    // envelope. Lower it into the envelope before handing it to native replay,
    // otherwise trust-wp's decoder would reject the bare Formula JSON. Fail
    // closed for constructs outside the native int/bool replay fragment.
    if formula.schema.as_str() == TRUST_TYPES_FORMULA_SCHEMA_VERSION {
        if formula.payload.trim().is_empty() {
            return Err(format!(
                "trust-wp proof-context replay atom formula schema `{TRUST_TYPES_FORMULA_SCHEMA_VERSION}` has an empty payload"
            ));
        }
        let value =
            trust_types::trust_formula_v1::parse_unique_proof_json_payload(&formula.payload)
                .map_err(|err| {
                    format!("invalid `{TRUST_TYPES_FORMULA_SCHEMA_VERSION}` JSON payload: {err}")
                })?;
        let payload = trust_types_formula_payload(&value)?;
        return Ok(TrustWpProofContextClaim {
            format: TrustWpProofContextClaimFormat::TrustFormulaV1,
            payload,
        });
    }
    let (format, payload) = match formula.schema.as_str() {
        TRUST_WP_PURE_EXPR_SCHEMA_VERSION => {
            let payload = if formula.payload.trim_start().starts_with('{') {
                let value = trust_types::trust_formula_v1::parse_unique_proof_json_payload(
                    &formula.payload,
                )
                .map_err(|err| format!("invalid TrustWpPureExprV1 JSON payload: {err}"))?;
                let (payload, sort) = trust_wp_pure_expr_stable_text(&value)?;
                if sort != TrustWpPureExprSort::Bool {
                    return Err("TrustWpPureExprV1 proof-context replay atom is not boolean".into());
                }
                payload
            } else {
                trust_types::trust_formula_v1::reject_trust_wp_pure_expr_v1_text_arithmetic(
                    &formula.payload,
                )?;
                formula.payload.clone()
            };
            (TrustWpProofContextClaimFormat::TrustWpPureExprV1, payload)
        }
        "PureExpr" => {
            trust_types::trust_formula_v1::reject_trust_wp_pure_expr_v1_text_arithmetic(
                &formula.payload,
            )?;
            (TrustWpProofContextClaimFormat::TrustWpPureExprV1, formula.payload.clone())
        }
        TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION => (
            TrustWpProofContextClaimFormat::TrustFormulaV1,
            trust_types::trust_formula_v1::parse_arithmetic_free_trust_formula_v1_payload(
                &formula.payload,
            )?,
        ),
        "smtlib2" => (
            TrustWpProofContextClaimFormat::SmtLib2,
            formula.smtlib.clone().unwrap_or_else(|| formula.payload.clone()),
        ),
        other => {
            (TrustWpProofContextClaimFormat::Other(other.to_string()), formula.payload.clone())
        }
    };
    if payload.trim().is_empty() {
        return Err(format!(
            "trust-wp proof-context replay atom formula schema `{}` has an empty payload",
            formula.schema
        ));
    }
    Ok(TrustWpProofContextClaim { format, payload })
}

fn canonical_trust_formula_payload(value: &serde_json::Value) -> Result<String, String> {
    trust_types::trust_formula_v1::canonical_arithmetic_free_trust_formula_v1_payload(value)
}

// Trust #1003: Lower a raw symbolic `trust-types.Formula@1` payload (a
// serde-serialized `trust_types::Formula`) into the `trust-wp.trust-formula.v1`
// claim envelope that trust-wp's native replay decoder accepts. This is the
// compiler-side counterpart of the trust-wp bridge's
// `trust_types_formula_value_to_trust_formula_payload`. The lowering is
// fail-closed: it accepts the arithmetic-free comparison/boolean fragment and
// rejects arithmetic, bitvectors, arrays, conditionals, quantifiers, and
// out-of-`i64` literals. In particular, machine arithmetic is never laundered
// into the sibling's unbounded-Int prover.
fn trust_types_formula_payload(value: &serde_json::Value) -> Result<String, String> {
    let formula = serde_json::from_value::<trust_types::Formula>(value.clone()).map_err(|err| {
        format!("invalid typed `{TRUST_TYPES_FORMULA_SCHEMA_VERSION}` Formula payload: {err}")
    })?;
    trust_types::trust_formula_v1::formula_to_trust_formula_v1_envelope(&formula)
}

fn trust_spec_predicate_to_trust_formula_payload(
    predicate: &trust_verifier_api::TrustSpecPredicate,
) -> Result<String, String> {
    if !predicate.has_current_schema() {
        return Err(format!(
            "unsupported TrustSpecPredicate schema `{}`, expected `{}`",
            predicate.schema_version,
            trust_verifier_api::TRUST_SPEC_PREDICATE_SCHEMA_VERSION
        ));
    }
    if predicate.root_sort != trust_verifier_api::TrustSpecSort::Bool
        || predicate.root.sort != trust_verifier_api::TrustSpecSort::Bool
    {
        return Err("TrustSpecPredicate root must be a typed boolean predicate".to_string());
    }
    predicate.validate()?;
    if predicate
        .variables
        .iter()
        .any(|variable| matches!(variable.sort, trust_verifier_api::TrustSpecSort::Array { .. }))
    {
        return Err(
            "TrustSpecPredicate arrays are outside trust-wp TrustFormulaV1 scalar replay fragment"
                .to_string(),
        );
    }
    validate_trust_spec_div_mod_defined(&predicate.root)?;

    let mut result_sort = None;
    let body = trust_spec_expr_to_trust_formula_body(&predicate.root, &mut result_sort)?;
    let mut variables = Vec::with_capacity(predicate.variables.len());
    for variable in &predicate.variables {
        if variable.name.trim().is_empty() {
            return Err("TrustSpecPredicate variable name is empty".to_string());
        }
        variables.push(serde_json::json!({
            "name": variable.name.as_str(),
            "sort": trust_spec_sort_label(variable.sort),
        }));
    }

    let mut payload = serde_json::Map::new();
    payload.insert("schema".to_string(), serde_json::json!(TRUST_WP_TRUST_FORMULA_SCHEMA_VERSION));
    payload.insert("variables".to_string(), serde_json::Value::Array(variables));
    if let Some(sort) = result_sort {
        payload.insert(
            "result".to_string(),
            serde_json::json!({
                "name": "result",
                "sort": trust_spec_sort_label(sort),
            }),
        );
    }
    payload.insert("body".to_string(), body);

    canonical_trust_formula_payload(&serde_json::Value::Object(payload)).map_err(|err| {
        format!("could not canonicalize TrustSpecPredicate as TrustFormulaV1: {err}")
    })
}

fn trust_spec_expr_to_trust_formula_body(
    expr: &trust_verifier_api::TrustSpecExpr,
    result_sort: &mut Option<trust_verifier_api::TrustSpecSort>,
) -> Result<serde_json::Value, String> {
    match &expr.kind {
        trust_verifier_api::TrustSpecExprKind::BoolLiteral { value } => {
            require_trust_spec_sort(expr, trust_verifier_api::TrustSpecSort::Bool, "bool literal")?;
            Ok(serde_json::json!({ "bool": value }))
        }
        trust_verifier_api::TrustSpecExprKind::IntLiteral { value } => {
            require_trust_spec_sort(expr, trust_verifier_api::TrustSpecSort::Int, "int literal")?;
            let parsed = value.parse::<i64>().map_err(|err| {
                format!("TrustSpecPredicate integer literal `{value}` is outside i64: {err}")
            })?;
            Ok(serde_json::json!({ "int": parsed }))
        }
        trust_verifier_api::TrustSpecExprKind::Variable { name } => {
            if name.trim().is_empty() {
                return Err("TrustSpecPredicate variable reference has an empty name".to_string());
            }
            Ok(serde_json::json!({ "var": name }))
        }
        trust_verifier_api::TrustSpecExprKind::Result => {
            if let Some(existing) = result_sort {
                if *existing != expr.sort {
                    return Err("TrustSpecPredicate uses result with inconsistent sorts".to_string());
                }
            } else {
                *result_sort = Some(expr.sort);
            }
            Ok(serde_json::json!({ "result": true }))
        }
        trust_verifier_api::TrustSpecExprKind::Unary { op, expr: inner } => {
            match op {
                trust_verifier_api::TrustSpecUnaryOp::Not => {
                    require_trust_spec_sort(
                        expr,
                        trust_verifier_api::TrustSpecSort::Bool,
                        "not expression",
                    )?;
                    require_trust_spec_sort(
                        inner,
                        trust_verifier_api::TrustSpecSort::Bool,
                        "not operand",
                    )?;
                }
                // Trust (#29): `Neg` is arithmetic — refuse it in the bare-claim
                // lane for the same amendment-1 reason as the binary arithmetic
                // refusal below.
                trust_verifier_api::TrustSpecUnaryOp::Neg => {
                    return Err(trust_spec_bare_claim_arithmetic_refusal("neg"));
                }
                _ => {
                    return Err(
                        "TrustSpecPredicate future unary operator is outside trust-wp TrustFormulaV1 native int/bool replay fragment"
                            .to_string(),
                    );
                }
            }
            Ok(serde_json::json!({
                "op": trust_spec_unary_op_label(*op)?,
                "expr": trust_spec_expr_to_trust_formula_body(inner, result_sort)?,
            }))
        }
        trust_verifier_api::TrustSpecExprKind::Binary { op, lhs, rhs } => {
            // Trust (#29, defense-in-depth): refuse machine arithmetic in the
            // BARE (non-body-bound) trust-wp claim lane. Lowering a
            // machine-integer `ensures` predicate into unbounded-Int
            // arithmetic is a confirmed false-proof vector: the sibling's
            // linear-int rule proves free-variable Int tautologies such as
            // `ensures result + 1 > result`, which is FALSE at `u64::MAX`
            // under Rust's wrapping machine semantics (before this gate the
            // native trust-wp lane reported that claim "verified ...
            // NativeTrustWpBundleVerifier"; only the sealed-authority gate
            // held the final verdict at UNKNOWN — a single-gate defense).
            // Mirror the body-bound lane's v1 fragment (blueprint
            // docs/design-notes/2026-07-17-trust-wp-lowering-blueprint.md,
            // amendment 1; `trust_ir_bridge::trust_wp_claim::
            // spec_predicate_to_sibling_json`): comparisons + boolean
            // connectives + literals/vars/result ONLY — no
            // Add/Sub/Mul/Div/Mod/Neg anywhere in the predicate. Fail-closed:
            // the callers demote the obligation exactly as an unlowerable
            // predicate does today (native-lane Unsupported, never Proved).
            if matches!(
                op,
                trust_verifier_api::TrustSpecBinaryOp::Add
                    | trust_verifier_api::TrustSpecBinaryOp::Sub
                    | trust_verifier_api::TrustSpecBinaryOp::Mul
                    | trust_verifier_api::TrustSpecBinaryOp::Div
                    | trust_verifier_api::TrustSpecBinaryOp::Mod
            ) {
                return Err(trust_spec_bare_claim_arithmetic_refusal(
                    trust_spec_binary_op_label(*op)?,
                ));
            }
            validate_trust_spec_binary(*op, expr, lhs, rhs)?;
            Ok(serde_json::json!({
                "op": trust_spec_binary_op_label(*op)?,
                "lhs": trust_spec_expr_to_trust_formula_body(lhs, result_sort)?,
                "rhs": trust_spec_expr_to_trust_formula_body(rhs, result_sort)?,
            }))
        }
        trust_verifier_api::TrustSpecExprKind::Old { expr: inner } => Ok(serde_json::json!({
            "old": trust_spec_expr_to_trust_formula_body(inner, result_sort)?,
        })),
        trust_verifier_api::TrustSpecExprKind::Field { .. }
        | trust_verifier_api::TrustSpecExprKind::Index { .. }
        | trust_verifier_api::TrustSpecExprKind::Quantifier { .. } => Err(
            "TrustSpecPredicate node is outside trust-wp TrustFormulaV1 native int/bool replay fragment"
                .to_string(),
        ),
        _ => Err(
            "TrustSpecPredicate future node is outside trust-wp TrustFormulaV1 native int/bool replay fragment"
                .to_string(),
        ),
    }
}

// Trust (#29): amendment-1 arithmetic refusal for the bare trust-wp claim
// lane. Kept as a single helper so the walker's unary (`Neg`) and binary
// (`Add`/`Sub`/`Mul`/`Div`/`Mod`) refusals stay message-identical with the
// adapter's copy of this lowering (crates/trust-wp/src/verifier_api.rs).
fn trust_spec_bare_claim_arithmetic_refusal(op: &str) -> String {
    format!(
        "TrustSpecPredicate arithmetic operator `{op}` is outside the trust-wp TrustFormulaV1 bare-claim fragment: machine arithmetic modeled over unbounded Int is a false-proof vector (`ensures result + 1 > result` is Int-provable but false at u64::MAX); see 2026-07-17 trust-wp lowering blueprint amendment 1"
    )
}

fn validate_trust_spec_div_mod_defined(
    expr: &trust_verifier_api::TrustSpecExpr,
) -> Result<(), String> {
    validate_trust_spec_expr_div_mod_defined(expr, &[])
}

fn validate_trust_spec_expr_div_mod_defined(
    expr: &trust_verifier_api::TrustSpecExpr,
    assumptions: &[trust_verifier_api::TrustSpecExpr],
) -> Result<(), String> {
    match &expr.kind {
        trust_verifier_api::TrustSpecExprKind::Binary {
            op: trust_verifier_api::TrustSpecBinaryOp::And,
            lhs,
            rhs,
        } => {
            let mut scoped = assumptions.to_vec();
            collect_trust_spec_definedness_facts(expr, &mut scoped);
            validate_trust_spec_expr_div_mod_defined(lhs, &scoped)?;
            validate_trust_spec_expr_div_mod_defined(rhs, &scoped)
        }
        trust_verifier_api::TrustSpecExprKind::Binary {
            op: trust_verifier_api::TrustSpecBinaryOp::Implies,
            lhs,
            rhs,
        } => {
            let mut scoped = assumptions.to_vec();
            collect_trust_spec_definedness_facts(lhs, &mut scoped);
            validate_trust_spec_expr_div_mod_defined(lhs, &scoped)?;
            validate_trust_spec_expr_div_mod_defined(rhs, &scoped)
        }
        trust_verifier_api::TrustSpecExprKind::Binary {
            op:
                op @ (trust_verifier_api::TrustSpecBinaryOp::Div
                | trust_verifier_api::TrustSpecBinaryOp::Mod),
            lhs,
            rhs,
        } => {
            validate_trust_spec_expr_div_mod_defined(lhs, assumptions)?;
            validate_trust_spec_expr_div_mod_defined(rhs, assumptions)?;
            if trust_spec_expr_known_nonzero(rhs, assumptions) {
                Ok(())
            } else {
                Err(format!(
                    "TrustSpecPredicate {:?} divisor must be syntactically nonzero or guarded by a nonzero assumption for trust-wp TrustFormulaV1 native replay",
                    op
                ))
            }
        }
        trust_verifier_api::TrustSpecExprKind::Binary { lhs, rhs, .. } => {
            validate_trust_spec_expr_div_mod_defined(lhs, assumptions)?;
            validate_trust_spec_expr_div_mod_defined(rhs, assumptions)
        }
        trust_verifier_api::TrustSpecExprKind::Unary { expr: inner, .. }
        | trust_verifier_api::TrustSpecExprKind::Old { expr: inner } => {
            validate_trust_spec_expr_div_mod_defined(inner, assumptions)
        }
        trust_verifier_api::TrustSpecExprKind::Field { base, .. } => {
            validate_trust_spec_expr_div_mod_defined(base, assumptions)
        }
        trust_verifier_api::TrustSpecExprKind::Index { base, index } => {
            validate_trust_spec_expr_div_mod_defined(base, assumptions)?;
            validate_trust_spec_expr_div_mod_defined(index, assumptions)
        }
        trust_verifier_api::TrustSpecExprKind::Quantifier { body, .. } => {
            validate_trust_spec_expr_div_mod_defined(body, assumptions)
        }
        trust_verifier_api::TrustSpecExprKind::BoolLiteral { .. }
        | trust_verifier_api::TrustSpecExprKind::IntLiteral { .. }
        | trust_verifier_api::TrustSpecExprKind::Variable { .. }
        | trust_verifier_api::TrustSpecExprKind::Result => Ok(()),
        _ => Ok(()),
    }
}

fn collect_trust_spec_definedness_facts(
    expr: &trust_verifier_api::TrustSpecExpr,
    facts: &mut Vec<trust_verifier_api::TrustSpecExpr>,
) {
    match &expr.kind {
        trust_verifier_api::TrustSpecExprKind::Binary {
            op: trust_verifier_api::TrustSpecBinaryOp::And,
            lhs,
            rhs,
        } => {
            collect_trust_spec_definedness_facts(lhs, facts);
            collect_trust_spec_definedness_facts(rhs, facts);
        }
        trust_verifier_api::TrustSpecExprKind::Binary { op, .. }
            if trust_spec_is_definedness_fact_operator(*op) =>
        {
            if !trust_spec_contains_div_mod(expr) {
                facts.push(expr.clone());
            }
        }
        _ => {}
    }
}

fn trust_spec_is_definedness_fact_operator(op: trust_verifier_api::TrustSpecBinaryOp) -> bool {
    matches!(
        op,
        trust_verifier_api::TrustSpecBinaryOp::Eq
            | trust_verifier_api::TrustSpecBinaryOp::Ne
            | trust_verifier_api::TrustSpecBinaryOp::Lt
            | trust_verifier_api::TrustSpecBinaryOp::Le
            | trust_verifier_api::TrustSpecBinaryOp::Gt
            | trust_verifier_api::TrustSpecBinaryOp::Ge
    )
}

fn trust_spec_expr_known_nonzero(
    expr: &trust_verifier_api::TrustSpecExpr,
    assumptions: &[trust_verifier_api::TrustSpecExpr],
) -> bool {
    trust_spec_constant_int(expr).is_some_and(|value| value != 0)
        || assumptions
            .iter()
            .any(|assumption| trust_spec_assumption_proves_nonzero(assumption, expr))
}

fn trust_spec_assumption_proves_nonzero(
    assumption: &trust_verifier_api::TrustSpecExpr,
    target: &trust_verifier_api::TrustSpecExpr,
) -> bool {
    let trust_verifier_api::TrustSpecExprKind::Binary { op, lhs, rhs } = &assumption.kind else {
        return false;
    };
    match op {
        trust_verifier_api::TrustSpecBinaryOp::Ne => {
            (lhs.as_ref() == target && trust_spec_is_int_zero(rhs))
                || (rhs.as_ref() == target && trust_spec_is_int_zero(lhs))
        }
        trust_verifier_api::TrustSpecBinaryOp::Gt | trust_verifier_api::TrustSpecBinaryOp::Lt => {
            (lhs.as_ref() == target && trust_spec_is_int_zero(rhs))
                || (trust_spec_is_int_zero(lhs) && rhs.as_ref() == target)
        }
        _ => false,
    }
}

fn trust_spec_contains_div_mod(expr: &trust_verifier_api::TrustSpecExpr) -> bool {
    match &expr.kind {
        trust_verifier_api::TrustSpecExprKind::Binary {
            op:
                trust_verifier_api::TrustSpecBinaryOp::Div | trust_verifier_api::TrustSpecBinaryOp::Mod,
            ..
        } => true,
        trust_verifier_api::TrustSpecExprKind::Binary { lhs, rhs, .. } => {
            trust_spec_contains_div_mod(lhs) || trust_spec_contains_div_mod(rhs)
        }
        trust_verifier_api::TrustSpecExprKind::Unary { expr: inner, .. }
        | trust_verifier_api::TrustSpecExprKind::Old { expr: inner } => {
            trust_spec_contains_div_mod(inner)
        }
        trust_verifier_api::TrustSpecExprKind::Field { base, .. } => {
            trust_spec_contains_div_mod(base)
        }
        trust_verifier_api::TrustSpecExprKind::Index { base, index } => {
            trust_spec_contains_div_mod(base) || trust_spec_contains_div_mod(index)
        }
        trust_verifier_api::TrustSpecExprKind::Quantifier { body, .. } => {
            trust_spec_contains_div_mod(body)
        }
        trust_verifier_api::TrustSpecExprKind::BoolLiteral { .. }
        | trust_verifier_api::TrustSpecExprKind::IntLiteral { .. }
        | trust_verifier_api::TrustSpecExprKind::Variable { .. }
        | trust_verifier_api::TrustSpecExprKind::Result => false,
        _ => false,
    }
}

fn trust_spec_is_int_zero(expr: &trust_verifier_api::TrustSpecExpr) -> bool {
    trust_spec_constant_int(expr) == Some(0)
}

fn trust_spec_constant_int(expr: &trust_verifier_api::TrustSpecExpr) -> Option<i64> {
    match &expr.kind {
        trust_verifier_api::TrustSpecExprKind::IntLiteral { value } => value.parse::<i64>().ok(),
        _ => None,
    }
}

fn require_trust_spec_sort(
    expr: &trust_verifier_api::TrustSpecExpr,
    expected: trust_verifier_api::TrustSpecSort,
    context: &str,
) -> Result<(), String> {
    if expr.sort == expected {
        Ok(())
    } else {
        Err(format!(
            "TrustSpecPredicate {context} has sort {:?}, expected {:?}",
            expr.sort, expected
        ))
    }
}

fn validate_trust_spec_binary(
    op: trust_verifier_api::TrustSpecBinaryOp,
    expr: &trust_verifier_api::TrustSpecExpr,
    lhs: &trust_verifier_api::TrustSpecExpr,
    rhs: &trust_verifier_api::TrustSpecExpr,
) -> Result<(), String> {
    require_trust_spec_sort(expr, op.result_sort(), "binary expression")?;
    match op {
        trust_verifier_api::TrustSpecBinaryOp::Add
        | trust_verifier_api::TrustSpecBinaryOp::Sub
        | trust_verifier_api::TrustSpecBinaryOp::Mul
        | trust_verifier_api::TrustSpecBinaryOp::Div
        | trust_verifier_api::TrustSpecBinaryOp::Mod => {
            require_trust_spec_sort(
                lhs,
                trust_verifier_api::TrustSpecSort::Int,
                "arithmetic lhs",
            )?;
            require_trust_spec_sort(
                rhs,
                trust_verifier_api::TrustSpecSort::Int,
                "arithmetic rhs",
            )
        }
        trust_verifier_api::TrustSpecBinaryOp::Eq
        | trust_verifier_api::TrustSpecBinaryOp::Ne => {
            if lhs.sort == rhs.sort {
                require_trust_spec_sort(
                    expr,
                    trust_verifier_api::TrustSpecSort::Bool,
                    "comparison expression",
                )
            } else {
                Err(format!(
                    "TrustSpecPredicate equality compares incompatible sorts {:?} and {:?}",
                    lhs.sort, rhs.sort
                ))
            }
        }
        trust_verifier_api::TrustSpecBinaryOp::Lt
        | trust_verifier_api::TrustSpecBinaryOp::Le
        | trust_verifier_api::TrustSpecBinaryOp::Gt
        | trust_verifier_api::TrustSpecBinaryOp::Ge => {
            require_trust_spec_sort(
                lhs,
                trust_verifier_api::TrustSpecSort::Int,
                "comparison lhs",
            )?;
            require_trust_spec_sort(
                rhs,
                trust_verifier_api::TrustSpecSort::Int,
                "comparison rhs",
            )?;
            require_trust_spec_sort(
                expr,
                trust_verifier_api::TrustSpecSort::Bool,
                "comparison expression",
            )
        }
        trust_verifier_api::TrustSpecBinaryOp::And
        | trust_verifier_api::TrustSpecBinaryOp::Or
        | trust_verifier_api::TrustSpecBinaryOp::Implies => {
            require_trust_spec_sort(
                lhs,
                trust_verifier_api::TrustSpecSort::Bool,
                "boolean lhs",
            )?;
            require_trust_spec_sort(
                rhs,
                trust_verifier_api::TrustSpecSort::Bool,
                "boolean rhs",
            )?;
            require_trust_spec_sort(
                expr,
                trust_verifier_api::TrustSpecSort::Bool,
                "boolean expression",
            )
        }
        _ => Err(
            "TrustSpecPredicate future binary operator is outside trust-wp TrustFormulaV1 native int/bool replay fragment"
                .to_string(),
        ),
    }
}

fn trust_spec_sort_label(sort: trust_verifier_api::TrustSpecSort) -> &'static str {
    match sort {
        trust_verifier_api::TrustSpecSort::Bool => "bool",
        trust_verifier_api::TrustSpecSort::Int => "int",
        trust_verifier_api::TrustSpecSort::BitVec { .. } => "bit_vec",
        trust_verifier_api::TrustSpecSort::Array { .. } => "array",
        // trust-wp's scalar TrustFormulaV1 fragment rejects float-sorted
        // predicates up front; this label only names the sort in that
        // fail-closed diagnostic.
        trust_verifier_api::TrustSpecSort::Float { .. } => "float",
    }
}

fn trust_spec_unary_op_label(
    op: trust_verifier_api::TrustSpecUnaryOp,
) -> Result<&'static str, String> {
    match op {
        trust_verifier_api::TrustSpecUnaryOp::Not => Ok("not"),
        trust_verifier_api::TrustSpecUnaryOp::Neg => Ok("neg"),
        _ => Err(
            "TrustSpecPredicate future unary operator is outside trust-wp TrustFormulaV1 native int/bool replay fragment"
                .to_string(),
        ),
    }
}

fn trust_spec_binary_op_label(
    op: trust_verifier_api::TrustSpecBinaryOp,
) -> Result<&'static str, String> {
    match op {
        trust_verifier_api::TrustSpecBinaryOp::Add => Ok("add"),
        trust_verifier_api::TrustSpecBinaryOp::Sub => Ok("sub"),
        trust_verifier_api::TrustSpecBinaryOp::Mul => Ok("mul"),
        trust_verifier_api::TrustSpecBinaryOp::Div => Ok("div"),
        trust_verifier_api::TrustSpecBinaryOp::Mod => Ok("mod"),
        trust_verifier_api::TrustSpecBinaryOp::Eq => Ok("eq"),
        trust_verifier_api::TrustSpecBinaryOp::Ne => Ok("ne"),
        trust_verifier_api::TrustSpecBinaryOp::Lt => Ok("lt"),
        trust_verifier_api::TrustSpecBinaryOp::Le => Ok("le"),
        trust_verifier_api::TrustSpecBinaryOp::Gt => Ok("gt"),
        trust_verifier_api::TrustSpecBinaryOp::Ge => Ok("ge"),
        trust_verifier_api::TrustSpecBinaryOp::And => Ok("and"),
        trust_verifier_api::TrustSpecBinaryOp::Or => Ok("or"),
        trust_verifier_api::TrustSpecBinaryOp::Implies => Ok("implies"),
        _ => Err(
            "TrustSpecPredicate future binary operator is outside trust-wp TrustFormulaV1 native int/bool replay fragment"
                .to_string(),
        ),
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum TrustWpPureExprSort {
    Bool,
    Int,
}

fn trust_wp_pure_expr_stable_text(
    value: &serde_json::Value,
) -> Result<(String, TrustWpPureExprSort), String> {
    trust_wp_pure_expr_stable_text_with_sorts(value, &mut BTreeMap::new())
}

fn trust_wp_pure_expr_stable_text_with_sorts(
    value: &serde_json::Value,
    variable_sorts: &mut BTreeMap<String, TrustWpPureExprSort>,
) -> Result<(String, TrustWpPureExprSort), String> {
    let object = value
        .as_object()
        .ok_or_else(|| "TrustWpPureExprV1 payload must be a JSON object".to_string())?;
    let kind = object
        .get("kind")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "TrustWpPureExprV1 payload is missing string field `kind`".to_string())?;
    match kind {
        "bool" => {
            reject_trust_wp_pure_expr_unknown_fields(object, &["kind", "value"])?;
            let value =
                object.get("value").and_then(serde_json::Value::as_bool).ok_or_else(|| {
                    "TrustWpPureExprV1 bool node is missing boolean `value`".to_string()
                })?;
            Ok((value.to_string(), TrustWpPureExprSort::Bool))
        }
        "int" => {
            reject_trust_wp_pure_expr_unknown_fields(object, &["kind", "value"])?;
            let value = object
                .get("value")
                .and_then(serde_json::Value::as_i64)
                .ok_or_else(|| "TrustWpPureExprV1 int node is missing i64 `value`".to_string())?;
            Ok((value.to_string(), TrustWpPureExprSort::Int))
        }
        "var" => {
            reject_trust_wp_pure_expr_unknown_fields(object, &["kind", "name", "sort"])?;
            let name = object
                .get("name")
                .and_then(serde_json::Value::as_str)
                .ok_or_else(|| "TrustWpPureExprV1 var node is missing string `name`".to_string())?;
            if !trust_wp_pure_var_name_lexes_as_identifier(name) {
                return Err(format!(
                    "TrustWpPureExprV1 var name `{name}` is outside the stable-text identifier fragment"
                ));
            }
            let sort = match object.get("sort").and_then(serde_json::Value::as_str) {
                Some("int") => TrustWpPureExprSort::Int,
                Some("bool") => TrustWpPureExprSort::Bool,
                other => {
                    return Err(format!(
                        "TrustWpPureExprV1 var node has unsupported sort {other:?}; expected `int` or `bool`"
                    ));
                }
            };
            if let Some(previous) = variable_sorts.insert(name.to_string(), sort)
                && previous != sort
            {
                return Err(format!(
                    "TrustWpPureExprV1 variable `{name}` has conflicting sorts `{previous:?}` and `{sort:?}`; one untyped stable-text name cannot preserve both"
                ));
            }
            Ok((name.to_string(), sort))
        }
        "not" => {
            reject_trust_wp_pure_expr_unknown_fields(object, &["kind", "expr"])?;
            let (expr, sort) = trust_wp_pure_expr_stable_text_with_sorts(
                required_json_field(object, "expr")?,
                variable_sorts,
            )?;
            if sort != TrustWpPureExprSort::Bool {
                return Err("TrustWpPureExprV1 not operand must be boolean".to_string());
            }
            Ok((format!("(! {expr})"), TrustWpPureExprSort::Bool))
        }
        "binary" => {
            reject_trust_wp_pure_expr_unknown_fields(object, &["kind", "op", "lhs", "rhs"])?;
            let op = object.get("op").and_then(serde_json::Value::as_str).ok_or_else(|| {
                "TrustWpPureExprV1 binary node is missing string `op`".to_string()
            })?;
            let lhs_value = required_json_field(object, "lhs")?;
            let rhs_value = required_json_field(object, "rhs")?;
            let (mut lhs, lhs_sort) =
                trust_wp_pure_expr_stable_text_with_sorts(lhs_value, variable_sorts)?;
            let (mut rhs, rhs_sort) =
                trust_wp_pure_expr_stable_text_with_sorts(rhs_value, variable_sorts)?;
            let (op_text, sort) = trust_wp_pure_binary_op(op, lhs_sort, rhs_sort)?;
            // Stable text has no declarations and parses bare `flag == ready`
            // as Int equality. Preserve the typed Bool operands explicitly so
            // public JSON, module formula, and assertion formula normalize to
            // one idempotent AST. Other Bool uses keep their compact canonical
            // spelling; the adapter performs full wire expansion only at the
            // final sibling boundary.
            let direct_bool_var = |value: &serde_json::Value| {
                value.get("kind").and_then(serde_json::Value::as_str) == Some("var")
                    && value.get("sort").and_then(serde_json::Value::as_str) == Some("bool")
            };
            if matches!(op, "eq" | "ne") && direct_bool_var(lhs_value) && direct_bool_var(rhs_value)
            {
                lhs = format!("({lhs} == true)");
                rhs = format!("({rhs} == true)");
            }
            Ok((format!("({lhs} {op_text} {rhs})"), sort))
        }
        other => Err(format!("unsupported TrustWpPureExprV1 node kind `{other}`")),
    }
}

fn reject_trust_wp_pure_expr_unknown_fields(
    object: &serde_json::Map<String, serde_json::Value>,
    allowed: &[&str],
) -> Result<(), String> {
    if let Some(field) = object.keys().find(|field| !allowed.contains(&field.as_str())) {
        return Err(format!("TrustWpPureExprV1 node contains unsupported field `{field}`"));
    }
    Ok(())
}

fn required_json_field<'a>(
    object: &'a serde_json::Map<String, serde_json::Value>,
    field: &str,
) -> Result<&'a serde_json::Value, String> {
    object.get(field).ok_or_else(|| format!("TrustWpPureExprV1 node is missing `{field}`"))
}

/// Shared exact opaque base-identifier policy for trust-wp stable text:
/// `[A-Za-z_][A-Za-z0-9_]*`, excluding the downstream parser's keyword set.
/// Wider spellings can become postfix syntax, fail to lex, or be interpreted as
/// a keyword, so the compiler encoder fails closed on them.
fn trust_wp_pure_var_name_lexes_as_identifier(name: &str) -> bool {
    trust_types::trust_formula_v1::trust_wp_pure_expr_v1_opaque_identifier(name)
}

fn trust_wp_pure_binary_op(
    op: &str,
    lhs: TrustWpPureExprSort,
    rhs: TrustWpPureExprSort,
) -> Result<(&'static str, TrustWpPureExprSort), String> {
    match op {
        // Trust (#29, blueprint amendment 1): this is a third bare-claim
        // lowering surface, distinct from both the TrustSpecPredicate walker
        // and trust-wp's decoder. `TrustWpPureExprV1` has no integer-domain
        // tag, so replaying machine `+`/`-` as unbounded Int can prove false
        // wrapping tautologies (`x + 1 > x` at `u64::MAX`). Refuse both the
        // canonical enum labels and stable-text aliases before serialization.
        "add" | "+" => Err(trust_wp_pure_bare_claim_arithmetic_refusal("add")),
        "sub" | "-" => Err(trust_wp_pure_bare_claim_arithmetic_refusal("sub")),
        "eq" if lhs == rhs => Ok(("==", TrustWpPureExprSort::Bool)),
        "ne" if lhs == rhs => Ok(("!=", TrustWpPureExprSort::Bool)),
        "lt" if lhs == TrustWpPureExprSort::Int && rhs == TrustWpPureExprSort::Int => {
            Ok(("<", TrustWpPureExprSort::Bool))
        }
        "le" if lhs == TrustWpPureExprSort::Int && rhs == TrustWpPureExprSort::Int => {
            Ok(("<=", TrustWpPureExprSort::Bool))
        }
        "gt" if lhs == TrustWpPureExprSort::Int && rhs == TrustWpPureExprSort::Int => {
            Ok((">", TrustWpPureExprSort::Bool))
        }
        "ge" if lhs == TrustWpPureExprSort::Int && rhs == TrustWpPureExprSort::Int => {
            Ok((">=", TrustWpPureExprSort::Bool))
        }
        "and" if lhs == TrustWpPureExprSort::Bool && rhs == TrustWpPureExprSort::Bool => {
            Ok(("&&", TrustWpPureExprSort::Bool))
        }
        "or" if lhs == TrustWpPureExprSort::Bool && rhs == TrustWpPureExprSort::Bool => {
            Ok(("||", TrustWpPureExprSort::Bool))
        }
        // "==>" is the spelling the trust-wp stable-text parser and the
        // first-party contract parser accept; the old "=>" died on replay.
        "implies" if lhs == TrustWpPureExprSort::Bool && rhs == TrustWpPureExprSort::Bool => {
            Ok(("==>", TrustWpPureExprSort::Bool))
        }
        other => Err(format!(
            "TrustWpPureExprV1 binary op `{other}` does not accept operand sorts {:?} and {:?}",
            lhs, rhs
        )),
    }
}

fn trust_wp_pure_bare_claim_arithmetic_refusal(op: &str) -> String {
    format!(
        "TrustWpPureExprV1 arithmetic operator `{op}` is outside the trust-wp stable-text bare-claim fragment: machine arithmetic modeled over unbounded Int is a false-proof vector (`x + 1 > x` is Int-provable but false at u64::MAX); see 2026-07-17 trust-wp lowering blueprint amendment 1"
    )
}

fn native_trust_ir_source_digest(
    func: &trust_types::VerifiableFunction,
) -> Result<trust_ir_bridge::ProofDigest, String> {
    // Trust: Sha256 (domain-separated) — NativeVerificationBundle validation
    // fail-closes on any non-cryptographic digest algorithm for identities
    // that participate in replay/authority selection.
    serde_json::to_vec(func)
        .map(|bytes| {
            trust_ir_bridge::ProofDigest::sha256_domain(
                "trustc.full-verification.rust-mir.v1",
                &bytes,
            )
        })
        .map_err(|error| {
            format!(
                "failed to serialize `{}` for typed TrustIr source digest: {error}",
                func.def_path
            )
        })
}

fn native_trust_ir_bundle_build_failure_result(
    bundle: &trust_verifier_api::TrustContractBundle,
    requested_obligations: &[trust_verifier_api::TrustObligation],
    context: &trust_router::VerifierExecutionContext,
    reason: &str,
) -> trust_router::VerificationRunResult {
    let manifest = trust_verifier_api::EngineManifest::new(
        "trust-full-verifier",
        trust_verifier_api::API_VERSION,
        trust_verifier_api::EngineKind::Composite,
    );
    let diagnostic = format!("{NATIVE_TRUST_IR_LOWERING_FAILED_MARKER}: {reason}");
    let evidence = requested_obligations
        .iter()
        .map(|obligation| trust_verifier_api::ObligationEvidence {
            evidence_id: format!(
                "trust-full-verifier:native-trust-ir-unavailable:{}",
                obligation.obligation_id
            ),
            obligation_id: obligation.obligation_id.clone(),
            engine: manifest.clone(),
            status: trust_verifier_api::EvidenceStatus::Unsupported,
            decline: None,
            proof_strength: None,
            artifacts: Vec::new(),
            counterexample: None,
            publication: trust_verifier_api::EvidencePublicationMetadata::default(),
            diagnostics: vec![diagnostic.clone()],
        })
        .collect::<Vec<_>>();
    let mut result = trust_router::VerificationRunResult::from_evidence(
        context.snapshot(),
        bundle,
        manifest,
        requested_obligations,
        evidence,
    );
    result.diagnostics.push(diagnostic);
    result
}

/// Build an O(1)-lookup index that contains only IDs occurring exactly once.
/// Duplicate IDs are ambiguity, not identity: remove them and keep them
/// excluded even if a third occurrence appears later.
fn unique_index_by_id<'a, T, F>(items: &'a [T], id: F) -> FxHashMap<&'a str, &'a T>
where
    F: Fn(&'a T) -> &'a str,
{
    unique_index_and_duplicates_by_id(items, id).0
}

fn unique_index_and_duplicates_by_id<'a, T, F>(
    items: &'a [T],
    id: F,
) -> (FxHashMap<&'a str, &'a T>, FxHashSet<&'a str>)
where
    F: Fn(&'a T) -> &'a str,
{
    let mut unique = FxHashMap::default();
    let mut duplicates = FxHashSet::default();
    for item in items {
        let key = id(item);
        if duplicates.contains(key) {
            continue;
        }
        if unique.insert(key, item).is_some() {
            unique.remove(key);
            duplicates.insert(key);
        }
    }
    (unique, duplicates)
}

fn unique_requested_obligations(
    run: &trust_verifier_api::VerificationRunResult,
) -> FxHashMap<&str, &trust_verifier_api::TrustObligation> {
    unique_index_by_id(&run.requested_obligations, |obligation| obligation.obligation_id.as_str())
}

/// Linear, deterministic join of every public identity needed by compiler
/// proof transport. All maps contain only unique IDs. A strict accepted
/// entry points at the one concrete evidence row selected by one accepted
/// manifest decision; duplicate IDs, multiple accepted decisions, hard
/// conflicting decisions, skipped rows, malformed native identity, and
/// cross-lineage native artifacts are excluded fail-closed.
struct FullVerificationEvidenceIndex<'a> {
    evidence_by_obligation_id: FxHashMap<&'a str, &'a trust_verifier_api::ObligationEvidence>,
    evidence_by_evidence_id: FxHashMap<&'a str, &'a trust_verifier_api::ObligationEvidence>,
    skipped_by_id: FxHashMap<&'a str, &'a trust_verifier_api::SkippedObligation>,
    requested_by_id: FxHashMap<&'a str, &'a trust_verifier_api::TrustObligation>,
    ambiguous_requested_ids: FxHashSet<&'a str>,
    strict_accepted_by_obligation_id:
        FxHashMap<&'a str, &'a trust_verifier_api::ObligationEvidence>,
}

fn manifest_decision_matches_exact_evidence(
    decision: &trust_verifier_api::ManifestEvidenceDecision,
    evidence: &trust_verifier_api::ObligationEvidence,
) -> bool {
    decision.evidence_id == evidence.evidence_id
        && decision.obligation_id == evidence.obligation_id
        && decision.engine == evidence.engine
        && decision.status == evidence.status
        && decision.proof_strength == evidence.proof_strength
        && decision.publication == evidence.publication
        && decision.counterexample == evidence.counterexample
        && decision.diagnostics == evidence.diagnostics
        && decision.artifacts == evidence.artifacts
}

fn canonical_sha256_hex_segment(value: &str) -> bool {
    value.len() == 64
        && value.bytes().all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
}

fn native_trust_vc_identity_family_is_wholly_absent(
    obligation: &trust_verifier_api::TrustObligation,
) -> bool {
    !obligation.metadata.iter().any(|entry| {
        entry.key.starts_with("trust.trust_ir.native.")
            && entry.key
                != trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_TRANSPORT_STATUS_METADATA_KEY
            && entry.key
                != trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_TRANSPORT_REASON_METADATA_KEY
    })
}

fn has_exact_direct_trust_vc_deferred_marker(
    obligation: &trust_verifier_api::TrustObligation,
) -> bool {
    let unique = |key: &str| {
        let mut matching = obligation.metadata.iter().filter(|entry| entry.key == key);
        let value = matching.next()?.value.as_str();
        matching.next().is_none().then_some(value)
    };
    native_trust_vc_identity_family_is_wholly_absent(obligation)
        && unique(trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_TRANSPORT_STATUS_METADATA_KEY)
            == Some(trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_TRANSPORT_STATUS_DEFERRED)
        && unique(trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_TRANSPORT_REASON_METADATA_KEY)
            == Some(trust_vc_bridge::TRUST_VC_DIRECT_MIR_MEMORY_DEFERRED_REASON)
}

fn evidence_has_exact_direct_trust_vc_lineage(
    obligation: &trust_verifier_api::TrustObligation,
    evidence: &trust_verifier_api::ObligationEvidence,
) -> bool {
    evidence.obligation_id == obligation.obligation_id
        && evidence.engine.name == "trust-full-verifier"
        && evidence.engine.kind == trust_verifier_api::EngineKind::Composite
        && evidence.engine.repository.is_none()
        && has_exact_direct_trust_vc_deferred_marker(obligation)
        && !evidence
            .artifacts
            .iter()
            .any(|artifact| artifact.uri.starts_with("trust_ir-native://verification-bundle/"))
        && trust_vc_bridge::trust_vc_direct_mir_memory_evidence_has_certificate_shape(evidence)
}

/// Require one coherent bundle -> request -> proof artifact lineage for the
/// exact native identity. Three individually well-shaped URIs with unrelated
/// digests are not a proof binding.
fn evidence_has_exact_native_trust_ir_artifact_lineage(
    obligation: &trust_verifier_api::TrustObligation,
    evidence: &trust_verifier_api::ObligationEvidence,
) -> bool {
    let Some((expected_suite, _)) = native_trust_ir_route_for_api_obligation(obligation) else {
        return true;
    };
    let identity = native_transport_identity(obligation);
    if native_trust_vc_identity_family_is_wholly_absent(obligation) {
        return expected_suite == "trust-vc"
            && evidence_has_exact_direct_trust_vc_lineage(obligation, evidence);
    }
    let (Some(declared_suite), Some(request_id), Some(proof_id)) =
        (identity.suite.as_deref(), identity.request_id.as_deref(), identity.proof_id.as_deref())
    else {
        return false;
    };
    if declared_suite != expected_suite
        || request_id.parse::<u32>().ok().map(|id| id.to_string()).as_deref() != Some(request_id)
        || proof_id.parse::<u32>().ok().map(|id| id.to_string()).as_deref() != Some(proof_id)
        || !native_identity_is_complete_and_canonical(&identity)
    {
        return false;
    }

    const PREFIX: &str = "trust_ir-native://verification-bundle/";
    let mut bundles = FxHashSet::default();
    let mut requests = FxHashSet::default();
    let mut proofs = Vec::new();
    for artifact in &evidence.artifacts {
        let Some(remainder) = artifact.uri.strip_prefix(PREFIX) else { continue };
        let segments = remainder.split('/').collect::<Vec<_>>();
        match segments.as_slice() {
            [bundle_digest]
                if artifact.kind == trust_verifier_api::EvidenceArtifactKind::EngineInput
                    && canonical_sha256_hex_segment(bundle_digest) =>
            {
                bundles.insert(*bundle_digest);
            }
            [bundle_digest, suite, "request", actual_request_id, request_digest]
                if artifact.kind == trust_verifier_api::EvidenceArtifactKind::EngineInput
                    && canonical_sha256_hex_segment(bundle_digest)
                    && *suite == expected_suite
                    && *actual_request_id == request_id
                    && canonical_sha256_hex_segment(request_digest) =>
            {
                requests.insert((*bundle_digest, *request_digest));
            }
            [
                bundle_digest,
                suite,
                "request",
                actual_request_id,
                request_digest,
                "proof",
                actual_proof_id,
                proof_digest,
            ] if artifact.kind
                == trust_verifier_api::EvidenceArtifactKind::NormalizedObligation
                && canonical_sha256_hex_segment(bundle_digest)
                && *suite == expected_suite
                && *actual_request_id == request_id
                && canonical_sha256_hex_segment(request_digest)
                && *actual_proof_id == proof_id
                && canonical_sha256_hex_segment(proof_digest) =>
            {
                proofs.push((*bundle_digest, *request_digest));
            }
            _ => {}
        }
    }
    proofs.iter().any(|lineage| bundles.contains(lineage.0) && requests.contains(lineage))
}

fn build_full_verification_evidence_index(
    run: &trust_verifier_api::VerificationRunResult,
) -> FullVerificationEvidenceIndex<'_> {
    let (requested_by_id, duplicate_requested_ids) =
        unique_index_and_duplicates_by_id(&run.requested_obligations, |obligation| {
            obligation.obligation_id.as_str()
        });
    let (evidence_by_evidence_id, duplicate_evidence_ids) =
        unique_index_and_duplicates_by_id(&run.evidence, |evidence| evidence.evidence_id.as_str());
    let (mut evidence_by_obligation_id, _) =
        unique_index_and_duplicates_by_id(&run.evidence, |evidence| {
            evidence.obligation_id.as_str()
        });
    let (skipped_by_id, duplicate_skipped_ids) =
        unique_index_and_duplicates_by_id(&run.skipped, |skipped| skipped.obligation_id.as_str());

    let manifest = run.to_manifest();
    let source_structurally_invalid = manifest.diagnostics.iter().any(|diagnostic| {
        diagnostic.starts_with("source verifier result failed structural validation:")
    });
    let mut hard_conflicts = FxHashSet::default();
    for decision in &manifest.rejected_evidence {
        if matches!(
            decision.status,
            trust_verifier_api::EvidenceStatus::Proved | trust_verifier_api::EvidenceStatus::Failed
        ) {
            hard_conflicts.insert(decision.obligation_id.as_str());
        }
    }

    let mut strict_accepted_by_obligation_id = FxHashMap::default();
    let mut ambiguous_accepted_ids = FxHashSet::default();
    if !source_structurally_invalid && manifest.summary.publication_conflicts == 0 {
        for decision in &manifest.accepted_evidence {
            if decision.disposition != trust_verifier_api::EvidenceDisposition::AcceptedProof
                || duplicate_evidence_ids.contains(decision.evidence_id.as_str())
                || duplicate_requested_ids.contains(decision.obligation_id.as_str())
                || duplicate_skipped_ids.contains(decision.obligation_id.as_str())
                || skipped_by_id.contains_key(decision.obligation_id.as_str())
                || hard_conflicts.contains(decision.obligation_id.as_str())
                || ambiguous_accepted_ids.contains(decision.obligation_id.as_str())
            {
                continue;
            }
            let Some(evidence) =
                evidence_by_evidence_id.get(decision.evidence_id.as_str()).copied()
            else {
                continue;
            };
            let Some(obligation) = requested_by_id.get(decision.obligation_id.as_str()).copied()
            else {
                continue;
            };
            if !manifest_decision_matches_exact_evidence(decision, evidence)
                || !evidence.is_unbounded_proof()
                || !evidence_has_exact_native_trust_ir_artifact_lineage(obligation, evidence)
            {
                continue;
            }
            let key = evidence.obligation_id.as_str();
            if strict_accepted_by_obligation_id.insert(key, evidence).is_some() {
                strict_accepted_by_obligation_id.remove(key);
                ambiguous_accepted_ids.insert(key);
            }
        }
    }

    // Legacy row conversion must use the accepted evidence selected by exact
    // decision ID, never an arbitrary first row. A unique diagnostic-only row
    // remains available when no accepted proof exists.
    for obligation in &run.requested_obligations {
        if let Some(evidence) =
            strict_accepted_by_obligation_id.get(obligation.obligation_id.as_str()).copied()
        {
            evidence_by_obligation_id.insert(obligation.obligation_id.as_str(), evidence);
        }
    }

    FullVerificationEvidenceIndex {
        evidence_by_obligation_id,
        evidence_by_evidence_id,
        skipped_by_id,
        requested_by_id,
        ambiguous_requested_ids: duplicate_requested_ids,
        strict_accepted_by_obligation_id,
    }
}

/// Stable positions of the exact conflict-free evidence rows selected by the
/// run manifest. Shared live-authority seals retain this compact index so each
/// compiler row can compare its complete accepted evidence in O(1), while the
/// heavier manifest/lineage reconstruction remains a once-per-seal check.
fn strict_accepted_evidence_positions(
    run: &trust_verifier_api::VerificationRunResult,
) -> FxHashMap<String, usize> {
    let index = build_full_verification_evidence_index(run);
    run.evidence
        .iter()
        .enumerate()
        .filter_map(|(position, evidence)| {
            index
                .strict_accepted_by_obligation_id
                .get(evidence.obligation_id.as_str())
                .is_some_and(|accepted| std::ptr::eq(*accepted, evidence))
                .then(|| (evidence.obligation_id.clone(), position))
        })
        .collect()
}

fn strict_accepted_obligation_ids_from_index(
    run: &trust_verifier_api::VerificationRunResult,
    index: &FullVerificationEvidenceIndex<'_>,
) -> FxHashSet<String> {
    run.requested_obligations
        .iter()
        .filter(|obligation| !obligation.is_default_admission())
        .filter(|obligation| {
            index.strict_accepted_by_obligation_id.contains_key(obligation.obligation_id.as_str())
        })
        .map(|obligation| obligation.obligation_id.clone())
        .collect()
}

#[cfg(test)]
fn index_run_result_obligations(
    result: &trust_verifier_api::VerificationRunResult,
) -> (
    FxHashMap<&str, &trust_verifier_api::ObligationEvidence>,
    FxHashMap<&str, &trust_verifier_api::SkippedObligation>,
) {
    let index = build_full_verification_evidence_index(result);
    (index.evidence_by_obligation_id, index.skipped_by_id)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
enum SourceClauseKind {
    Ensures,
    LoopInvariant,
    Decreases,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
enum SourceClauseRole {
    Postcondition,
    LoopInvariantInitiation,
    LoopInvariantConsecution,
    LoopDecreases,
    RecursionDecreases,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord, Hash)]
struct SourceClauseIdentity {
    index: usize,
    contract_id: String,
    predicate_digest: String,
    kind: SourceClauseKind,
}

fn exactly_one_metadata_value<'a>(
    metadata: &'a [trust_verifier_api::MetadataEntry],
    key: &str,
) -> Option<&'a str> {
    let mut values =
        metadata.iter().filter(|entry| entry.key == key).map(|entry| entry.value.as_str());
    let value = values.next()?;
    values.next().is_none().then_some(value)
}

fn metadata_has_exact_optional_value(
    metadata: &[trust_verifier_api::MetadataEntry],
    key: &str,
    expected: Option<&str>,
) -> bool {
    let mut values =
        metadata.iter().filter(|entry| entry.key == key).map(|entry| entry.value.as_str());
    match (expected, values.next(), values.next()) {
        (Some(expected), Some(actual), None) => actual == expected,
        (None, None, None) => true,
        _ => false,
    }
}

fn metadata_matches_exact_key_family(
    metadata: &[trust_verifier_api::MetadataEntry],
    expected: &[trust_verifier_api::MetadataEntry],
    keys: &[&str],
) -> bool {
    keys.iter().all(|key| {
        let actual = metadata
            .iter()
            .filter(|entry| entry.key == *key)
            .map(|entry| entry.value.as_str())
            .collect::<Vec<_>>();
        let expected = expected
            .iter()
            .filter(|entry| entry.key == *key)
            .map(|entry| entry.value.as_str())
            .collect::<Vec<_>>();
        actual == expected
    })
}

fn metadata_contains_summary_assumption(metadata: &[trust_verifier_api::MetadataEntry]) -> bool {
    metadata.iter().any(|entry| {
        entry.key == trust_verifier_api::SUMMARY_FACT_METADATA_KEY
            || entry.key == TRUST_WP_NATIVE_SUMMARY_FACT_METADATA_KEY
    })
}

fn bundle_metadata_invalid_for_fresh_rekey(metadata: &[trust_verifier_api::MetadataEntry]) -> bool {
    let mut seen = BTreeSet::new();
    for entry in metadata {
        if !seen.insert(entry.key.as_str()) {
            return true;
        }
        let valid = match entry.key.as_str() {
            TRUST_FULL_VERIFICATION_SOURCE_METADATA_KEY => {
                entry.value == TRUST_FULL_VERIFICATION_SOURCE_METADATA_VALUE
            }
            TRUST_SOURCE_DIGEST_METADATA_KEY => canonical_sha256_hex_segment(&entry.value),
            TRUST_COMPILER_STABLE_CRATE_ID_METADATA_KEY => {
                entry.value.len() == 16
                    && entry
                        .value
                        .bytes()
                        .all(|byte| byte.is_ascii_digit() || (b'a'..=b'f').contains(&byte))
            }
            TRUST_EXACT_LOOP_CONTRACT_VC_REPLACEMENTS_METADATA_KEY => {
                let mut previous = None;
                !entry.value.is_empty()
                    && entry.value.split(',').all(|part| {
                        let Ok(index) = part.parse::<usize>() else { return false };
                        let canonical = index.to_string() == part;
                        let ordered = previous.is_none_or(|prior| prior < index);
                        previous = Some(index);
                        canonical && ordered
                    })
            }
            TRUST_DEFINITION_SITE_PRECONDITIONS_EXCLUDED_METADATA_KEY => entry
                .value
                .parse::<usize>()
                .is_ok_and(|count| count > 0 && count.to_string() == entry.value),
            // Fresh compiler bundles have a closed producer-owned metadata
            // vocabulary. Unknown bundle keys are rejected rather than
            // blacklisted piecemeal: a future engine must not silently turn a
            // newly introduced proof-bearing key into an assumption.
            _ => false,
        };
        if !valid {
            return true;
        }
    }
    !seen.contains(TRUST_FULL_VERIFICATION_SOURCE_METADATA_KEY)
        || !seen.contains(TRUST_SOURCE_DIGEST_METADATA_KEY)
}

fn exactly_one_obligation_context(
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<trust_verifier_api::ObligationContext> {
    let mut contexts = Vec::new();
    for entry in &obligation.metadata {
        match trust_verifier_api::ObligationContext::from_metadata_entry(entry) {
            Ok(Some(context)) => contexts.push(context),
            Ok(None) => {}
            Err(_) => return None,
        }
    }
    (contexts.len() == 1).then(|| contexts.pop().expect("one context"))
}

/// Match a public obligation back to the exact compiler-owned VC from which
/// `trust-mir-extract` freshly built it. This helper intentionally does not
/// decide multiplicity: callers must additionally require that exactly one
/// bundle obligation matches the returned index.
#[cfg(test)]
fn exact_fresh_vc_index_for_obligation_without_multiplicity(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &[VerificationCondition],
) -> Option<usize> {
    let source_digest = trust_mir_extract::verifier_source_digest(func);
    exact_fresh_vc_index_for_obligation_with_source_digest(
        func,
        obligation,
        fresh_vcs,
        &source_digest,
    )
}

#[cfg(test)]
fn exact_fresh_vc_index_for_obligation_with_source_digest(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &[VerificationCondition],
    source_digest: &str,
) -> Option<usize> {
    exact_fresh_vc_index_for_obligation_with_source_digest_and_crate_name(
        func,
        obligation,
        fresh_vcs,
        source_digest,
        None,
    )
}

fn exact_fresh_vc_index_for_obligation_with_source_digest_and_crate_name(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &[VerificationCondition],
    source_digest: &str,
    exact_crate_name: Option<&str>,
) -> Option<usize> {
    if metadata_contains_summary_assumption(&obligation.metadata) {
        // trust-wp still consumes this legacy metadata carrier as a proof
        // assumption in addition to the structured `summary_facts` field.
        return None;
    }
    let context = exactly_one_obligation_context(obligation)?;
    if !context.has_current_schema()
        || !matches!(context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
    {
        return None;
    }
    let context_function = context.function.as_ref()?;
    let (vc_index, context_vc_kind, context_formula_schema) = match &context.origin {
        trust_verifier_api::ObligationOrigin::VerificationCondition {
            vc_kind,
            vc_index,
            formula_schema: Some(formula_schema),
            ..
        } => (*vc_index, vc_kind.as_str(), formula_schema.as_str()),
        _ => return None,
    };
    let vc = fresh_vcs.get(vc_index)?;
    let vc_function = vc.function.as_str();
    if vc_function != func.name && vc_function != func.def_path {
        return None;
    }
    if vc.location != source_span_from_api_location(&obligation.source) {
        return None;
    }

    let identity = match exact_crate_name {
        Some(crate_name) => {
            trust_mir_extract::verifier_vc_content_identity_with_source_digest_and_crate_name(
                func,
                vc_index,
                vc,
                source_digest,
                crate_name,
            )
        }
        #[allow(deprecated)]
        None => trust_mir_extract::verifier_vc_content_identity_with_source_digest(
            func,
            vc_index,
            vc,
            source_digest,
        ),
    };
    let temporal_serialize_error_key =
        format!("{}.serialize_error", trust_types::TY_TEMPORAL_MODEL_METADATA_KEY);
    if context_function != &identity.function
        || context_vc_kind != identity.vc_kind
        || obligation.obligation_id != identity.obligation_id
        || obligation.kind != identity.obligation_kind
        || obligation.description != identity.description
        || obligation.required_strength != identity.required_strength
        || obligation.proof_item_id.is_some()
        // Generated VC rows never carry summary assumptions. trust-wp consumes
        // this public field as proof context, so accepting an injected fact
        // would re-key evidence for an easier formula onto the fresh VC.
        || !obligation.summary_facts.is_empty()
    {
        return None;
    }
    if exactly_one_metadata_value(&obligation.metadata, TRUST_VC_DIGEST_METADATA_KEY)
        != Some(identity.digest.as_str())
    {
        return None;
    }
    let metadata_formula_schema =
        exactly_one_metadata_value(&obligation.metadata, TRUST_VC_FORMULA_SCHEMA_METADATA_KEY)?;
    if metadata_formula_schema != context_formula_schema
        || metadata_formula_schema != identity.formula_schema
    {
        return None;
    }
    if !metadata_has_exact_optional_value(
        &obligation.metadata,
        TRUST_VC_KIND_METADATA_KEY,
        Some(identity.vc_kind.as_str()),
    ) || !metadata_has_exact_optional_value(
        &obligation.metadata,
        TRUST_SOURCE_DIGEST_METADATA_KEY,
        Some(identity.source_digest.as_str()),
    ) || !metadata_has_exact_optional_value(
        &obligation.metadata,
        TRUST_VC_FORMULA_SORT_METADATA_KEY,
        Some(identity.formula_sort.as_str()),
    ) || !metadata_has_exact_optional_value(
        &obligation.metadata,
        TRUST_VC_FORMULA_SMTLIB_METADATA_KEY,
        Some(identity.formula_smtlib.as_str()),
    ) || !metadata_has_exact_optional_value(
        &obligation.metadata,
        TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY,
        identity.formula_payload.as_deref(),
    ) || !metadata_has_exact_optional_value(
        &obligation.metadata,
        TRUST_VC_FORMULA_PRUNED_METADATA_KEY,
        identity.formula_pruned.then_some("true"),
    ) || !metadata_matches_exact_key_family(
        &obligation.metadata,
        &identity.mir_memory_metadata,
        &[
            TRUST_VC_CONDITION_ORIGIN_METADATA_KEY,
            TRUST_VC_PROOF_OBLIGATION_METADATA_KEY,
            TRUST_VC_OWNERSHIP_CONTEXT_METADATA_KEY,
            TRUST_VC_MIR_MEMORY_PROOF_UNIT_SCHEMA_METADATA_KEY,
            TRUST_VC_MIR_MEMORY_PROOF_UNIT_METADATA_KEY,
            TRUST_VC_MIR_MEMORY_PROOF_UNIT_UNSUPPORTED_METADATA_KEY,
        ],
    ) || !metadata_matches_exact_key_family(
        &obligation.metadata,
        &identity.temporal_metadata,
        &[trust_types::TY_TEMPORAL_MODEL_METADATA_KEY, temporal_serialize_error_key.as_str()],
    ) || !metadata_matches_exact_key_family(
        &obligation.metadata,
        &identity.engine_formula_metadata,
        &[
            TRUST_VC_ENGINE_TRUST_MC_FORMULA_SCHEMA_METADATA_KEY,
            TRUST_VC_ENGINE_TRUST_WP_FORMULA_SCHEMA_METADATA_KEY,
            TRUST_VC_ENGINE_TRUST_VC_FORMULA_SCHEMA_METADATA_KEY,
        ],
    ) || !metadata_matches_exact_key_family(
        &obligation.metadata,
        &identity.hardened_metadata,
        &[
            TRUST_VC_HARDENED_CATEGORY_METADATA_KEY,
            TRUST_VC_HARDENED_FAMILY_METADATA_KEY,
            TRUST_VC_HARDENED_CALLEE_METADATA_KEY,
            TRUST_VC_HARDENED_DETAIL_METADATA_KEY,
        ],
    ) {
        return None;
    }
    Some(vc_index)
}

fn exact_fresh_vc_match_multiplicity(
    func: &trust_types::VerifiableFunction,
    bundle: &trust_verifier_api::TrustContractBundle,
    fresh_vcs: &[VerificationCondition],
    source_digest: &str,
    authority: &CompilerFunctionAuthority,
) -> FxHashMap<usize, usize> {
    let mut counts = FxHashMap::default();
    let expected_function = authority.function();
    if expected_function.crate_name.trim().is_empty()
        || expected_function.path != func.def_path
        || !authority.matches_bundle(bundle)
    {
        return counts;
    }
    if bundle_metadata_invalid_for_fresh_rekey(&bundle.metadata) {
        // A bundle-level legacy fact is visible to trust-wp for every row, so
        // no proof from this bundle may be re-keyed onto compiler-owned VCs.
        return counts;
    }
    for obligation in &bundle.obligations {
        if let Some(index) = exact_fresh_vc_index_for_obligation_with_source_digest_and_crate_name(
            func,
            obligation,
            fresh_vcs,
            source_digest,
            Some(&expected_function.crate_name),
        ) {
            *counts.entry(index).or_default() += 1;
        }
    }
    counts
}

#[cfg(test)]
fn exact_unique_fresh_vc_index_for_obligation(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &[VerificationCondition],
    match_multiplicity: &FxHashMap<usize, usize>,
    source_digest: &str,
) -> Option<usize> {
    let index = exact_fresh_vc_index_for_obligation_with_source_digest(
        func,
        obligation,
        fresh_vcs,
        source_digest,
    )?;
    (match_multiplicity.get(&index) == Some(&1)).then_some(index)
}

fn exact_unique_fresh_vc_index_for_obligation_and_crate_name(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &[VerificationCondition],
    match_multiplicity: &FxHashMap<usize, usize>,
    source_digest: &str,
    exact_crate_name: &str,
) -> Option<usize> {
    let index = exact_fresh_vc_index_for_obligation_with_source_digest_and_crate_name(
        func,
        obligation,
        fresh_vcs,
        source_digest,
        Some(exact_crate_name),
    )?;
    (match_multiplicity.get(&index) == Some(&1)).then_some(index)
}

#[cfg(test)]
fn exact_unique_fresh_vc_for_obligation<'a>(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &'a [VerificationCondition],
    match_multiplicity: &FxHashMap<usize, usize>,
    source_digest: &str,
) -> Option<&'a VerificationCondition> {
    exact_unique_fresh_vc_index_for_obligation(
        func,
        obligation,
        fresh_vcs,
        match_multiplicity,
        source_digest,
    )
    .and_then(|index| fresh_vcs.get(index))
}

#[derive(Debug, Clone)]
struct ExactFreshVcRekeyBinding {
    vc_index: usize,
    public_semantic_digest: String,
}

#[derive(Debug, Default)]
struct ExactFreshVcRekeySnapshot {
    by_obligation_id: BTreeMap<String, ExactFreshVcRekeyBinding>,
    bundle_metadata_digest: Option<String>,
    /// Exact compiler-owned VC carrier frozen at dispatch time. Public
    /// semantic digests bind the verifier request, but an index alone must not
    /// let a later compiler transform substitute a different VC at that index.
    /// Keep the collision-free canonical payloads rather than another digest;
    /// serialization failure makes the snapshot incomplete.
    canonical_fresh_vc_payloads: Option<Vec<String>>,
    /// Exact compiler-authored catalog inventory. Catalog-only assumption rows
    /// remain here even though they are deliberately absent from dispatch.
    catalog_obligations: Vec<trust_verifier_api::TrustObligation>,
    /// Exact compiler-dispatched proof-request inventory. This is a structural
    /// snapshot rather than a digest: a verifier response may not append,
    /// remove, reorder, or rewrite even an otherwise unrelated requested row
    /// and still participate in fresh-context re-keying.
    dispatched_obligations: Vec<trust_verifier_api::TrustObligation>,
    /// Exact compiler-owned execution context captured immediately before
    /// dispatch. A verifier response may be internally self-consistent after
    /// jointly rewriting its run id, invocation lane, limits, cancellation,
    /// or metadata, but it still cannot acquire fresh-context authority from
    /// a context the compiler did not dispatch.
    expected_execution_context: trust_verifier_api::VerifierExecutionSnapshot,
    /// Private classification frozen from the independent compiler contract
    /// reference before dispatch. It is deliberately carried beside the
    /// public catalog snapshot so legacy row mapping never re-derives an entry
    /// assumption from verifier-controlled obligation shape.
    definition_entry_markers: ExactDefinitionEntryMarkerSet,
    eligible_vc_indices: Vec<usize>,
    expected_vc_count: usize,
    complete: bool,
}

fn fresh_rekey_bundle_metadata_digest(
    metadata: &[trust_verifier_api::MetadataEntry],
) -> Option<String> {
    let mut bytes = b"trustc.fresh-vc.bundle-metadata.v1\0".to_vec();
    bytes.extend(serde_json::to_vec(metadata).ok()?);
    Some(trust_types::stable_sha256_hex(&bytes))
}

/// Capture the exact public proof claims for fresh VCs after all legitimate
/// compiler-side native-contract rewrites and before any verifier runs.
///
/// The verifier API's canonical semantic digest binds the full obligation and
/// its referenced synthetic/original contract or proof item while excluding
/// only explicitly non-semantic transport annotations. This private snapshot
/// prevents a self-consistent public contract re-point from proving an easier
/// claim and then re-keying that evidence onto the compiler-owned VC.
fn exact_fresh_vc_rekey_snapshot_with_dispatched_obligations(
    func: &trust_types::VerifiableFunction,
    compiler_contracts: &trust_types::CompilerContractBundle,
    bundle: &trust_verifier_api::TrustContractBundle,
    dispatched_obligations: &[trust_verifier_api::TrustObligation],
    fresh_vcs: &[VerificationCondition],
    definition_entry_markers: ExactDefinitionEntryMarkerSet,
    authority: &CompilerFunctionAuthority,
    expected_execution_context: trust_verifier_api::VerifierExecutionSnapshot,
) -> ExactFreshVcRekeySnapshot {
    let expected_function = authority.function();
    let eligible_vc_indices =
        trust_mir_extract::verifier_api_emitted_vc_indices(func, compiler_contracts, fresh_vcs);
    let canonical_fresh_vc_payloads =
        fresh_vcs.iter().map(canonical_exact_vc_payload).collect::<Option<Vec<_>>>();
    let mut snapshot = ExactFreshVcRekeySnapshot {
        expected_vc_count: eligible_vc_indices.len(),
        eligible_vc_indices,
        bundle_metadata_digest: fresh_rekey_bundle_metadata_digest(&bundle.metadata),
        canonical_fresh_vc_payloads,
        catalog_obligations: bundle.obligations.clone(),
        dispatched_obligations: dispatched_obligations.to_vec(),
        expected_execution_context,
        definition_entry_markers,
        ..ExactFreshVcRekeySnapshot::default()
    };
    if bundle.validate_requested_obligations(dispatched_obligations).is_err() {
        return snapshot;
    }
    if bundle_metadata_invalid_for_fresh_rekey(&bundle.metadata) {
        return snapshot;
    }
    if expected_function.crate_name.trim().is_empty()
        || expected_function.path != func.def_path
        || !authority.matches_bundle(bundle)
    {
        return snapshot;
    }
    let source_digest = trust_mir_extract::verifier_source_digest(func);
    let multiplicity =
        exact_fresh_vc_match_multiplicity(func, bundle, fresh_vcs, &source_digest, authority);
    let mut selected = Vec::new();
    let mut vc_indices = BTreeMap::new();
    for obligation in &bundle.obligations {
        let Some(vc_index) = exact_unique_fresh_vc_index_for_obligation_and_crate_name(
            func,
            obligation,
            fresh_vcs,
            &multiplicity,
            &source_digest,
            &expected_function.crate_name,
        ) else {
            continue;
        };
        selected.push(obligation.clone());
        if vc_indices.insert(obligation.obligation_id.clone(), vc_index).is_some() {
            return snapshot;
        }
    }
    let Ok(digests) = bundle.canonical_obligation_semantic_digest_index_sha256(&selected) else {
        return snapshot;
    };
    let mut by_obligation_id = BTreeMap::new();
    for (obligation_id, vc_index) in vc_indices {
        let Some(public_semantic_digest) = digests.get(&obligation_id).map(str::to_string) else {
            return snapshot;
        };
        by_obligation_id
            .insert(obligation_id, ExactFreshVcRekeyBinding { vc_index, public_semantic_digest });
    }
    let unique_vc_indices =
        by_obligation_id.values().map(|binding| binding.vc_index).collect::<BTreeSet<_>>();
    if by_obligation_id.len() != snapshot.expected_vc_count
        || unique_vc_indices.len() != snapshot.expected_vc_count
        || !snapshot.eligible_vc_indices.iter().all(|index| unique_vc_indices.contains(index))
        || snapshot.bundle_metadata_digest.is_none()
        || snapshot.canonical_fresh_vc_payloads.is_none()
    {
        return snapshot;
    }
    snapshot.by_obligation_id = by_obligation_id;
    snapshot.complete = true;
    snapshot
}

/// Snapshot helper for lanes that dispatch the complete public catalog.
/// Compiler full verification uses the explicit-subset variant above so an
/// exact definition-entry assumption can remain catalogued without becoming a
/// proof request.
#[cfg(test)]
fn exact_fresh_vc_rekey_snapshot(
    func: &trust_types::VerifiableFunction,
    compiler_contracts: &trust_types::CompilerContractBundle,
    bundle: &trust_verifier_api::TrustContractBundle,
    fresh_vcs: &[VerificationCondition],
    expected_execution_context: trust_verifier_api::VerifierExecutionSnapshot,
) -> ExactFreshVcRekeySnapshot {
    let expected_function = match &bundle.subject {
        trust_verifier_api::BundleSubject::Function { crate_name, path } => {
            trust_verifier_api::FunctionContext {
                crate_name: crate_name.clone(),
                path: path.clone(),
            }
        }
        _ => return ExactFreshVcRekeySnapshot::default(),
    };
    let authority = CompilerFunctionAuthority::compatibility_for_test(expected_function);
    exact_fresh_vc_rekey_snapshot_with_dispatched_obligations(
        func,
        compiler_contracts,
        bundle,
        &bundle.obligations,
        fresh_vcs,
        ExactDefinitionEntryMarkerSet::default(),
        &authority,
        expected_execution_context,
    )
}

#[cfg(test)]
fn exact_fresh_vc_rekey_snapshot_with_expected_function(
    func: &trust_types::VerifiableFunction,
    compiler_contracts: &trust_types::CompilerContractBundle,
    bundle: &trust_verifier_api::TrustContractBundle,
    fresh_vcs: &[VerificationCondition],
    expected_function: &trust_verifier_api::FunctionContext,
    expected_execution_context: trust_verifier_api::VerifierExecutionSnapshot,
) -> ExactFreshVcRekeySnapshot {
    let authority = CompilerFunctionAuthority::compatibility_for_test(expected_function.clone());
    exact_fresh_vc_rekey_snapshot_with_dispatched_obligations(
        func,
        compiler_contracts,
        bundle,
        &bundle.obligations,
        fresh_vcs,
        ExactDefinitionEntryMarkerSet::default(),
        &authority,
        expected_execution_context,
    )
}

fn current_fresh_vc_semantic_digests(
    bundle: &trust_verifier_api::TrustContractBundle,
    snapshot: &ExactFreshVcRekeySnapshot,
    requested_obligations: &[trust_verifier_api::TrustObligation],
) -> Option<trust_verifier_api::CanonicalObligationSemanticDigestIndex> {
    if !snapshot.complete
        || bundle_metadata_invalid_for_fresh_rekey(&bundle.metadata)
        || fresh_rekey_bundle_metadata_digest(&bundle.metadata).as_ref()
            != snapshot.bundle_metadata_digest.as_ref()
    {
        return None;
    }
    let obligations = requested_obligations
        .iter()
        .filter(|obligation| snapshot.by_obligation_id.contains_key(&obligation.obligation_id))
        .cloned()
        .collect::<Vec<_>>();
    if obligations.len() != snapshot.expected_vc_count {
        return None;
    }
    let digests = bundle.canonical_obligation_semantic_digest_index_sha256(&obligations).ok()?;
    if digests.len() != snapshot.expected_vc_count
        || snapshot.by_obligation_id.iter().any(|(obligation_id, binding)| {
            digests.get(obligation_id).map(str::to_string)
                != Some(binding.public_semantic_digest.clone())
        })
    {
        return None;
    }
    Some(digests)
}

fn exact_fresh_vc_rekey_run_is_complete(
    bundle: &trust_verifier_api::TrustContractBundle,
    run: &trust_verifier_api::VerificationRunResult,
    fresh_vcs: &[VerificationCondition],
    snapshot: &ExactFreshVcRekeySnapshot,
) -> bool {
    // The verifier response must be the canonical envelope for the exact
    // compiler-held bundle. Matching obligation rows alone cannot authorize a
    // response replayed from another bundle/subject, and stale public derived
    // fields cannot mint a compiler-private fresh-context capability.
    if run.bundle_id != bundle.bundle_id
        || run.subject != bundle.subject
        || run.context != snapshot.expected_execution_context
        || run.validate_derived_state().is_err()
        || bundle.obligations != snapshot.catalog_obligations
        || run.requested_obligations != snapshot.dispatched_obligations
        || fresh_vcs.iter().map(canonical_exact_vc_payload).collect::<Option<Vec<_>>>().as_ref()
            != snapshot.canonical_fresh_vc_payloads.as_ref()
    {
        return false;
    }
    // With no compiler-owned VCs there is no fresh authority to re-key. Keep
    // the legacy/public-only path independent of the producer-owned metadata
    // vocabulary used to seal an actual fresh batch.
    if fresh_vcs.is_empty() {
        return true;
    }
    snapshot.complete
        && snapshot.eligible_vc_indices.iter().all(|index| *index < fresh_vcs.len())
        && current_fresh_vc_semantic_digests(bundle, snapshot, &run.requested_obligations)
            .is_some_and(|digests| digests.len() == snapshot.expected_vc_count)
}

fn fresh_vc_rekey_integrity_failure_result() -> VerificationResult {
    VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("trust-fresh-vc-rekey-integrity"),
        time_ms: 0,
        reason: "fresh compiler VC inventory or semantic carrier changed across verifier dispatch"
            .to_string(),
    }
}

fn fresh_vc_rekey_integrity_failure_vc(
    func: &trust_types::VerifiableFunction,
) -> VerificationCondition {
    VerificationCondition {
        kind: VcKind::UnsupportedMir {
            kind: "fresh-vc-rekey-integrity".to_string(),
            detail: "public verifier inventory did not match the compiler-owned fresh VC batch"
                .to_string(),
        },
        function: trust_types::Symbol::intern(&func.name),
        location: func.span.clone(),
        // This is a violation formula. `true` deliberately prevents generic
        // UNSAT/structural promotion from erasing the integrity failure.
        formula: Formula::Bool(true),
        contract_metadata: None,
    }
}

fn exact_snapshot_fresh_vc_for_obligation<'a>(
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vcs: &'a [VerificationCondition],
    snapshot: &ExactFreshVcRekeySnapshot,
    current_digests: Option<&trust_verifier_api::CanonicalObligationSemanticDigestIndex>,
) -> Option<&'a VerificationCondition> {
    let binding = snapshot.by_obligation_id.get(&obligation.obligation_id)?;
    let current = current_digests?.get(&obligation.obligation_id)?;
    if current != binding.public_semantic_digest {
        return None;
    }
    let fresh_vc = fresh_vcs.get(binding.vc_index)?;
    let sealed_payload = snapshot.canonical_fresh_vc_payloads.as_ref()?.get(binding.vc_index)?;
    (canonical_exact_vc_payload(fresh_vc).as_ref() == Some(sealed_payload)).then_some(fresh_vc)
}

fn source_clause_kind_for_contract(
    contract: &trust_verifier_api::TrustContract,
) -> Option<SourceClauseKind> {
    match contract.kind {
        trust_verifier_api::ContractKind::Ensures => Some(SourceClauseKind::Ensures),
        trust_verifier_api::ContractKind::LoopInvariant => Some(SourceClauseKind::LoopInvariant),
        trust_verifier_api::ContractKind::Asserts => Some(SourceClauseKind::Decreases),
        _ => None,
    }
}

fn exactly_one_original_contract<'a>(
    bundle: &'a trust_verifier_api::TrustContractBundle,
    contract_id: &str,
) -> Option<&'a trust_verifier_api::TrustContract> {
    let mut contracts =
        bundle.contracts.iter().filter(|contract| contract.contract_id == contract_id);
    let contract = contracts.next()?;
    contracts.next().is_none().then_some(contract)
}

fn obligation_retains_original_contract_id(
    obligation: &trust_verifier_api::TrustObligation,
    expected: &str,
) -> bool {
    let originals: Vec<_> = obligation
        .metadata
        .iter()
        .filter(|entry| {
            entry.key == TRUST_MC_TYPED_CHC_ORIGINAL_CONTRACT_METADATA_KEY
                || entry.key == TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY
        })
        .map(|entry| entry.value.as_str())
        .collect();
    match (obligation.contract_id.as_deref() == Some(expected), originals.as_slice()) {
        (true, []) => true,
        (false, [original]) => *original == expected,
        _ => false,
    }
}

fn source_clause_identity_from_contract(
    bundle: &trust_verifier_api::TrustContractBundle,
    obligation: &trust_verifier_api::TrustObligation,
    index: usize,
    contract_id: &str,
) -> Option<SourceClauseIdentity> {
    if monitor_contract_source_index(contract_id) != Some(index)
        || !obligation_retains_original_contract_id(obligation, contract_id)
    {
        return None;
    }
    let contract = exactly_one_original_contract(bundle, contract_id)?;
    let kind = source_clause_kind_for_contract(contract)?;
    let contract_digest = exactly_one_metadata_value(
        &contract.metadata,
        TRUST_CONTRACT_PREDICATE_DIGEST_METADATA_KEY,
    )?;
    let obligation_digest = exactly_one_metadata_value(
        &obligation.metadata,
        TRUST_CONTRACT_PREDICATE_DIGEST_METADATA_KEY,
    )?;
    if contract_digest != obligation_digest || !canonical_sha256_hex_segment(contract_digest) {
        return None;
    }
    Some(SourceClauseIdentity {
        index,
        contract_id: contract_id.to_string(),
        predicate_digest: contract_digest.to_string(),
        kind,
    })
}

fn source_clause_marker_identity(
    bundle: &trust_verifier_api::TrustContractBundle,
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<SourceClauseIdentity> {
    let context = exactly_one_obligation_context(obligation)?;
    match context.origin {
        trust_verifier_api::ObligationOrigin::Contract {
            contract_id,
            contract_kind,
            contract_index,
            ..
        } => {
            let identity = source_clause_identity_from_contract(
                bundle,
                obligation,
                contract_index,
                &contract_id,
            )?;
            let kind_matches = matches!(
                (identity.kind, contract_kind, &obligation.kind),
                (
                    SourceClauseKind::Ensures,
                    trust_verifier_api::ContractKind::Ensures,
                    trust_verifier_api::ObligationKind::Postcondition,
                ) | (
                    SourceClauseKind::LoopInvariant,
                    trust_verifier_api::ContractKind::LoopInvariant,
                    trust_verifier_api::ObligationKind::LoopInvariant,
                ) | (
                    SourceClauseKind::Decreases,
                    trust_verifier_api::ContractKind::Asserts,
                    trust_verifier_api::ObligationKind::Termination,
                )
            );
            kind_matches.then_some(identity)
        }
        trust_verifier_api::ObligationOrigin::UnsupportedContract {
            contract_index,
            compiler_contract_kind,
            ..
        } => {
            let contract_id = obligation.contract_id.as_deref()?;
            let identity = source_clause_identity_from_contract(
                bundle,
                obligation,
                contract_index,
                contract_id,
            )?;
            let kind_matches = matches!(
                (identity.kind, compiler_contract_kind.as_str()),
                (SourceClauseKind::LoopInvariant, "loop_invariant")
                    | (SourceClauseKind::Decreases, "decreases")
            ) && matches!(
                &obligation.kind,
                trust_verifier_api::ObligationKind::Custom { namespace, name }
                    if namespace == trust_verifier_api::TRUST_CONTRACT_OBLIGATION_NAMESPACE
                        && name == "unsupported"
            );
            kind_matches.then_some(identity)
        }
        _ => None,
    }
}

fn source_clause_body_link(
    bundle: &trust_verifier_api::TrustContractBundle,
    obligation: &trust_verifier_api::TrustObligation,
    fresh_vc: &VerificationCondition,
) -> Option<(SourceClauseIdentity, SourceClauseRole)> {
    if !matches!(
        exactly_one_obligation_context(obligation)?.origin,
        trust_verifier_api::ObligationOrigin::VerificationCondition { .. }
    ) {
        return None;
    }
    let index_text = exactly_one_metadata_value(
        &obligation.metadata,
        TRUST_VC_SOURCE_CONTRACT_INDEX_METADATA_KEY,
    )?;
    let index = index_text.parse::<usize>().ok()?;
    if index.to_string() != index_text {
        return None;
    }
    let role = match exactly_one_metadata_value(
        &obligation.metadata,
        TRUST_VC_SOURCE_CONTRACT_ROLE_METADATA_KEY,
    )? {
        "postcondition" => SourceClauseRole::Postcondition,
        "loop_invariant_initiation" => SourceClauseRole::LoopInvariantInitiation,
        "loop_invariant_consecution" => SourceClauseRole::LoopInvariantConsecution,
        "loop_decreases" => SourceClauseRole::LoopDecreases,
        "recursion_decreases" => SourceClauseRole::RecursionDecreases,
        _ => return None,
    };
    let expected_source_index = fresh_vc.contract_metadata?.source_contract_index?;
    let expected_role = match &fresh_vc.kind {
        VcKind::Postcondition => SourceClauseRole::Postcondition,
        VcKind::LoopInvariantInitiation { .. } => SourceClauseRole::LoopInvariantInitiation,
        VcKind::LoopInvariantConsecution { .. } => SourceClauseRole::LoopInvariantConsecution,
        VcKind::NonTermination { context, .. } if context == "loop-decreases" => {
            SourceClauseRole::LoopDecreases
        }
        VcKind::NonTermination { context, .. } if context == "recursion" => {
            SourceClauseRole::RecursionDecreases
        }
        _ => return None,
    };
    if index != expected_source_index || role != expected_role {
        // The public source link may discharge an authored marker only when it
        // agrees with the compiler-owned fresh VC that was exactly re-keyed.
        // Re-pointing a solved row to another contract must not transfer proof.
        return None;
    }
    let contract_id = obligation
        .contract_id
        .as_deref()
        .filter(|id| monitor_contract_source_index(id) == Some(index))
        .or_else(|| {
            [
                TRUST_MC_TYPED_CHC_ORIGINAL_CONTRACT_METADATA_KEY,
                TRUST_WP_TYPED_FORMULA_ORIGINAL_CONTRACT_METADATA_KEY,
            ]
            .into_iter()
            .find_map(|key| exactly_one_metadata_value(&obligation.metadata, key))
        })?;
    let identity = source_clause_identity_from_contract(bundle, obligation, index, contract_id)?;
    let kind_matches = matches!(
        (identity.kind, role, &obligation.kind),
        (
            SourceClauseKind::Ensures,
            SourceClauseRole::Postcondition,
            trust_verifier_api::ObligationKind::Postcondition,
        ) | (
            SourceClauseKind::LoopInvariant,
            SourceClauseRole::LoopInvariantInitiation | SourceClauseRole::LoopInvariantConsecution,
            trust_verifier_api::ObligationKind::LoopInvariant,
        ) | (
            SourceClauseKind::Decreases,
            SourceClauseRole::LoopDecreases | SourceClauseRole::RecursionDecreases,
            trust_verifier_api::ObligationKind::Termination,
        )
    );
    kind_matches.then_some((identity, role))
}

fn source_clause_body_group_is_complete(
    identity: &SourceClauseIdentity,
    links: &[(usize, SourceClauseRole)],
) -> bool {
    match identity.kind {
        SourceClauseKind::Ensures => {
            !links.is_empty()
                && links.iter().all(|(_, role)| *role == SourceClauseRole::Postcondition)
        }
        SourceClauseKind::LoopInvariant => {
            links.len() == 2
                && links
                    .iter()
                    .filter(|(_, role)| *role == SourceClauseRole::LoopInvariantInitiation)
                    .count()
                    == 1
                && links
                    .iter()
                    .filter(|(_, role)| *role == SourceClauseRole::LoopInvariantConsecution)
                    .count()
                    == 1
        }
        SourceClauseKind::Decreases => {
            // Function-recursion decreases owns one row per fresh recursive
            // call site. Its source marker is removed only during verifier-api
            // bundle construction, after an exact fresh raw/production-variant
            // bijection. A marker that survives that gate must stay visible:
            // accepting merely a nonempty/count-only recursion group here
            // would re-open missing- and duplicate-call fail-open paths.
            links.len() == 1 && links[0].1 == SourceClauseRole::LoopDecreases
        }
    }
}

/// Reconstruct only the compiler-owned structural plan for each authored
/// source marker and its complete fresh body-VC group.
///
/// This phase intentionally does not inspect proof evidence or public result
/// labels. Those are transport facts, not proof capabilities. A later phase
/// resolves every body ID to its exact result row and requires a sealed private
/// authority for that row before it changes the marker from `Unknown`.
fn exact_source_clause_discharge_plans(
    bundle: &trust_verifier_api::TrustContractBundle,
    run: &trust_verifier_api::VerificationRunResult,
    fresh_vcs: &[VerificationCondition],
    fresh_vc_rekey_snapshot: &ExactFreshVcRekeySnapshot,
) -> BTreeMap<String, Vec<String>> {
    let current_digests = current_fresh_vc_semantic_digests(
        bundle,
        fresh_vc_rekey_snapshot,
        &run.requested_obligations,
    );
    let mut body_links: BTreeMap<SourceClauseIdentity, Vec<(String, SourceClauseRole)>> =
        BTreeMap::new();
    let mut markers: BTreeMap<SourceClauseIdentity, Vec<&trust_verifier_api::TrustObligation>> =
        BTreeMap::new();
    for obligation in &run.requested_obligations {
        if let Some(fresh_vc) = exact_snapshot_fresh_vc_for_obligation(
            obligation,
            fresh_vcs,
            fresh_vc_rekey_snapshot,
            current_digests.as_ref(),
        ) && let Some((identity, role)) = source_clause_body_link(bundle, obligation, fresh_vc)
        {
            body_links.entry(identity).or_default().push((obligation.obligation_id.clone(), role));
        }
        if let Some(identity) = source_clause_marker_identity(bundle, obligation) {
            markers.entry(identity).or_default().push(obligation);
        }
    }
    let mut plans = BTreeMap::new();
    for (identity, marker_rows) in markers {
        if marker_rows.len() != 1 {
            continue;
        }
        let Some(links) = body_links.get(&identity) else { continue };
        if !source_clause_body_group_is_complete(
            &identity,
            &links.iter().enumerate().map(|(index, (_, role))| (index, *role)).collect::<Vec<_>>(),
        ) {
            continue;
        }
        let mut body_ids = links
            .iter()
            .map(|(public_obligation_id, _)| public_obligation_id.clone())
            .collect::<Vec<_>>();
        body_ids.sort();
        let unique_body_ids = body_ids.iter().map(String::as_str).collect::<BTreeSet<_>>();
        if body_ids.is_empty()
            || unique_body_ids.len() != body_ids.len()
            || plans.insert(marker_rows[0].obligation_id.clone(), body_ids).is_some()
        {
            plans.remove(&marker_rows[0].obligation_id);
        }
    }
    plans
}

#[cfg(test)]
fn exact_source_clause_marker_ids(
    bundle: &trust_verifier_api::TrustContractBundle,
    run: &trust_verifier_api::VerificationRunResult,
    fresh_vcs: &[VerificationCondition],
    fresh_vc_rekey_snapshot: &ExactFreshVcRekeySnapshot,
) -> FxHashSet<String> {
    exact_source_clause_discharge_plans(bundle, run, fresh_vcs, fresh_vc_rekey_snapshot)
        .into_keys()
        .collect()
}

fn exact_source_clause_pending_result() -> VerificationResult {
    VerificationResult::Unknown {
        solver: trust_types::Symbol::intern("trust-exact-source-clause-discharge"),
        time_ms: 0,
        reason: "source-clause catalog marker awaits sealed private body authorities".to_string(),
    }
}

/// Reassert the phase-one source-marker boundary after generic result
/// promotions. Those passes operate on formula shape and must not turn the
/// marker's non-semantic `Bool(false)` catalog placeholder into proof credit.
fn keep_exact_source_clause_markers_pending(
    bundle: &trust_verifier_api::TrustContractBundle,
    results: &mut [(VerificationCondition, VerificationResult)],
    bindings: &[Option<ResultObligationBinding>],
) -> usize {
    if results.len() != bindings.len() {
        return 0;
    }
    let mut reset = 0;
    for (index, ((vc, result), binding)) in results.iter_mut().zip(bindings).enumerate() {
        let Some(binding) = binding.as_ref() else { continue };
        if matches!(
            &*result,
            VerificationResult::Proved { .. } | VerificationResult::Unknown { .. }
        ) && binding.matches_row(index, vc)
            && source_clause_marker_identity(bundle, &binding.canonical_obligation).is_some()
        {
            *result = exact_source_clause_pending_result();
            reset += 1;
        }
    }
    reset
}

/// Trust: WHOLE-FUNCTION PANIC-FREEDOM BY STRUCTURAL SUBSUMPTION — the
/// default-lane analogue of trust-mc's trivially-safe whole-function harness,
/// generalized from "the CHC has no error rule" to "every error rule
/// individually carries a private static proof".
///
/// The synthesized `assertion:panic-freedom:0` aggregate claims "no assertion,
/// `unreachable!`, or panic is reachable" for the WHOLE function. Its native
/// discharge (typed CHC/PDR) is blocked for every loop-bearing module by the
/// proof-grade admission whitelist, so a function whose every per-site VC the
/// formula lane PROVED (kernel-certified!) still failed strict verification —
/// the measured residual on ~19 `tests/trust-falsification/proved/` fixtures
/// (e.g. `foreach_range_safe`: "1 proved, 0 failed, 1 unknown" where the
/// unknown is exactly this aggregate).
///
/// SOUNDNESS — the aggregate is ENTAILED by the conjunction of the other rows
/// when all three hold:
///  (1) `native_bundle_built`: typed-TrustIr lowering COMPLETED, so the row
///      set enumerates every panic source (assert/panic sites, calls, drops).
///      An unlowerable construct either hard-aborts (never reaches here with
///      `Ok(Some)`) or folds into the aggregate's DESCRIPTION — excluded by
///      (2). The bridge's own discipline mints a fail-closed row for every
///      call it cannot prove total (absent-callee / expected-absent /
///      drop-glue markers), and such a row is never `proved`, so it blocks
///      (3).
///  (2) the aggregate still carries the CANONICAL description — a folded
///      extern-call / absent-callee / drop-glue gap replaces the text
///      (`extern_call_description`) and is NEVER subsumed;
///  (3) every OTHER row is `is_static_proof_for` under its own FINAL private
///      authority (this pass runs LAST in the authority phase). Assumption
///      bookkeeping (`DefinitionEntryAssumption`,
///      `AssumedTotalCalleeAssumption`) is not a static proof and blocks the
///      discharge. A `Failed`/`Timeout` row anywhere suppresses it entirely —
///      a refutation or a coverage gap is never papered over.
///
/// MUTANT ARGUMENT (the falsification gate's 148 buggy twins): a mutant with a
/// real panic mints a per-site row that is Failed/refuted (blocks via the
/// any-Failed bail) or Unknown (blocks (3)); a mutant panicking through an
/// absent callee mints the bridge's fail-closed assumption row (never proved —
/// blocks (3)) or folds into the aggregate description (blocks (2)); a mutant
/// whose construct cannot lower loses `native_bundle_built` (blocks (1)).
/// Havoc-modeled values only ever make premises HARDER to prove. So the flip
/// can never fire for a function with an unruled-out panic path.
fn apply_whole_function_panic_freedom_subsumption(
    sess: &Session,
    native_bundle_built: bool,
    results: &mut [(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) {
    let dbg = env_flag_enabled("TRUST_ASSERT_DEBUG");
    if !native_bundle_built || results.is_empty() {
        if dbg {
            eprintln!(
                "[PF_SUBSUME] bail: native_bundle_built={native_bundle_built} results={}",
                results.len()
            );
        }
        return;
    }
    if results.len() != proof_authorities.len() {
        if dbg {
            eprintln!(
                "[PF_SUBSUME] bail: len mismatch results={} authorities={}",
                results.len(),
                proof_authorities.len()
            );
        }
        return;
    }
    let canonical = trust_types::assumption::PANIC_FREEDOM_AGGREGATE_DESCRIPTION_PREFIX;
    let mut aggregates: Vec<usize> = Vec::new();
    for (index, (vc, result)) in results.iter().enumerate() {
        // A refuted or timed-out row ANYWHERE in the function suppresses the
        // whole discharge: a refutation is never overridden, and a timeout is
        // an unruled-out path, not a premise.
        if matches!(result, VerificationResult::Failed { .. } | VerificationResult::Timeout { .. })
        {
            if dbg {
                eprintln!("[PF_SUBSUME] bail: row {index} is Failed/Timeout kind={:?}", vc.kind);
            }
            return;
        }
        // The aggregate reaches this pipeline in one of TWO VC shapes:
        //  * the fresh synthesis `Assertion { message }` with the canonical
        //    text (`legacy_vc_from_api_obligation`'s recognized arm), or
        //  * the legacy placeholder `UnsupportedMir { kind:
        //    "FullVerification::Assertion", detail }` whose `detail` embeds the
        //    obligation description verbatim (canonical text first, then the
        //    `; metadata_keys=[…]` suffix) — the shape measured on
        //    foreach_range_safe.
        // In BOTH shapes a folded extern-call/absent-callee/drop-glue gap
        // REPLACES the leading description, so the canonical-prefix test is the
        // same exclusion in either spelling.
        let described = match &vc.kind {
            VcKind::Assertion { message } => message.as_str(),
            VcKind::UnsupportedMir { kind, detail } if kind == "FullVerification::Assertion" => {
                detail.as_str()
            }
            _ => continue,
        };
        if !described.starts_with(canonical) {
            continue;
        }
        if result.is_proved() && proof_authorities.get(index).and_then(Option::as_ref).is_some() {
            // Already discharged by a real engine WITH its own authority —
            // nothing to derive.
            continue;
        }
        // A Proved-but-AUTHORITYLESS aggregate (the native import path: the
        // opaque `panic_reachable` formula can earn neither a kernel cert nor
        // a revalidation receipt) still needs the subsumption token or the
        // native proof-authority validation rejects it. The mint below never
        // overwrites an existing authority and preserves an already-Proved
        // result.
        aggregates.push(index);
    }
    if aggregates.is_empty() {
        if dbg {
            eprintln!("[PF_SUBSUME] bail: no canonical aggregate among {} rows:", results.len());
            for (i, (vc, r)) in results.iter().enumerate() {
                eprintln!("[PF_SUBSUME]   row {i}: kind={:?} proved={} ", &vc.kind, r.is_proved());
            }
        }
        return;
    }
    // Every NON-aggregate row must be a real static proof under its own final
    // private authority (assumption bookkeeping is excluded by the predicate).
    let premises_hold = results.iter().enumerate().all(|(index, (vc, result))| {
        if aggregates.contains(&index) {
            return true;
        }
        result.is_proved()
            && proof_authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
                authority.is_static_proof_for(
                    index,
                    vc,
                    result,
                    result_bindings.get(index).and_then(Option::as_ref),
                )
            })
    });
    if !premises_hold {
        if dbg {
            for (index, (vc, result)) in results.iter().enumerate() {
                if aggregates.contains(&index) {
                    continue;
                }
                let ok = result.is_proved()
                    && proof_authorities.get(index).and_then(Option::as_ref).is_some_and(
                        |authority| {
                            authority.is_static_proof_for(
                                index,
                                vc,
                                result,
                                result_bindings.get(index).and_then(Option::as_ref),
                            )
                        },
                    );
                if !ok {
                    eprintln!(
                        "[PF_SUBSUME] premise FAILS: row {index} kind={:?} proved={} authority={}",
                        &vc.kind,
                        result.is_proved(),
                        proof_authorities
                            .get(index)
                            .and_then(Option::as_ref)
                            .map_or("none", |_| "some(non-static?)")
                    );
                }
            }
        }
        return;
    }
    for index in aggregates {
        // The aggregate is a native-requested obligation; a missing or
        // mismatched binding means this is not the exact bound row — bail
        // fail-closed rather than mint on a moved identity.
        let binding = result_bindings
            .get(index)
            .and_then(Option::as_ref)
            .cloned()
            .filter(|binding| binding.matches_row(index, &results[index].0));
        if binding.is_none() && !row_was_compiler_grounded(sess, index, &results[index].0) {
            // No binding AND no recorded compiler grounding: this row's public
            // identity is simply absent, not deliberately retired. Fail closed.
            if dbg {
                eprintln!(
                    "[PF_SUBSUME] bail: aggregate row {index} has no matching binding and was not compiler-grounded"
                );
            }
            continue;
        }
        let Some(row) = exact_result_row_identity(index, &results[index].0) else {
            if dbg {
                eprintln!("[PF_SUBSUME] bail: aggregate row {index} has no exact identity");
            }
            continue;
        };
        if !results[index].1.is_proved() {
            results[index].1 = VerificationResult::Proved {
                solver: trust_types::Symbol::intern("trust-structural-subsumption"),
                time_ms: 0,
                // A deductive conjunction over sound premises; the row's
                // REPORTED tier comes from `trust_disposition_for_authority`
                // (Trusted/Deductive), never from this label.
                strength: trust_types::ProofStrength::deductive(),
                proof_certificate: None,
                solver_warnings: None,
                native_proof_envelope: None,
            };
        }
        proof_authorities[index] =
            Some(ResultProofAuthority::WholeFunctionPanicFreedomSubsumption { row, binding });
        if env_flag_enabled("TRUST_ASSERT_DEBUG") {
            eprintln!(
                "[PANIC_FREEDOM_SUBSUMPTION] discharged aggregate row {index} for {}",
                results[index].0.function.as_str()
            );
        }
    }
}

/// Apply (or re-apply) exact source-clause derivations after the ordinary body
/// authorities have been minted.
///
/// Phase one keeps every recognized catalog marker `Unknown`; neither a public
/// `Proved` result nor accepted public evidence can change it. This phase first
/// revokes any old source authority, then requires every exact structural body
/// row to be `Proved` under a matching non-recursive private authority. Only
/// then are the marker result and its private authority installed together.
fn apply_exact_source_clause_discharges(
    bundle: &trust_verifier_api::TrustContractBundle,
    run: &trust_verifier_api::VerificationRunResult,
    fresh_vcs: &[VerificationCondition],
    fresh_vc_rekey_snapshot: &ExactFreshVcRekeySnapshot,
    results: &mut [(VerificationCondition, VerificationResult)],
    bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) -> usize {
    // Revoke source-derived tokens wherever they moved, not only from the
    // marker slot they were minted for. Independently normalize every exact
    // marker's synthetic Proved/Unknown result. This prevents a stale, missing,
    // or swapped authority from leaving an authoritative-looking result behind.
    for authority in proof_authorities.iter_mut() {
        if matches!(
            authority.as_ref(),
            Some(ResultProofAuthority::ExactSourceClauseDischarge { .. })
        ) {
            *authority = None;
        }
    }
    keep_exact_source_clause_markers_pending(bundle, results, bindings);
    if results.len() != bindings.len() || results.len() != proof_authorities.len() {
        return 0;
    }

    let plans =
        exact_source_clause_discharge_plans(bundle, run, fresh_vcs, fresh_vc_rekey_snapshot);
    let mut row_by_obligation_id = BTreeMap::new();
    let mut duplicate_ids = BTreeSet::new();
    for (index, binding) in bindings.iter().enumerate() {
        let Some(binding) = binding.as_ref() else { continue };
        if !results.get(index).is_some_and(|(vc, _)| binding.matches_row(index, vc)) {
            continue;
        }
        if duplicate_ids.contains(&binding.public_obligation_id) {
            continue;
        }
        if row_by_obligation_id.insert(binding.public_obligation_id.clone(), index).is_some() {
            row_by_obligation_id.remove(&binding.public_obligation_id);
            duplicate_ids.insert(binding.public_obligation_id.clone());
        }
    }

    let mut applied = 0;
    for (marker_id, body_ids) in plans {
        let Some(index) = row_by_obligation_id.get(&marker_id).copied() else { continue };
        let Some((marker_vc, marker_result)) = results.get(index) else { continue };
        if !matches!(
            marker_result,
            VerificationResult::Unknown { solver, .. }
                if solver.as_str() == "trust-exact-source-clause-discharge"
        ) || proof_authorities[index].is_some()
        {
            continue;
        }
        let Some(marker_binding) = bindings.get(index).and_then(Option::as_ref) else { continue };
        if marker_binding.public_obligation_id != marker_id
            || !marker_binding.matches_row(index, marker_vc)
        {
            continue;
        }
        let Some(row) = exact_result_row_identity(index, marker_vc) else { continue };
        // REFUTATION PROPAGATION (the dual of the all-proved discharge below):
        // the plan's structural body rows are derived FROM the marker's source
        // clause, so a genuine `Failed` on ANY of them refutes the clause's
        // conjunction — "awaits sealed private body authorities" would
        // misrepresent a clause no authority can ever discharge, and the
        // transport would double-report it (pending marker + failed body row).
        // `keep_exact_source_clause_markers_pending` deliberately resets only
        // `Proved | Unknown`, so an absorbed refutation survives re-assertion.
        // Adverse-verdict direction only: this can never mint proof credit, and
        // the body row must bind exactly (same identity discipline as the
        // proved path). No proof authority is installed — a refutation is not
        // proof credit.
        let refuted_body = body_ids.iter().find_map(|public_obligation_id| {
            let body_index = row_by_obligation_id.get(public_obligation_id).copied()?;
            if body_index == index {
                return None;
            }
            let (body_vc, body_result) = results.get(body_index)?;
            let body_binding = bindings.get(body_index)?.as_ref()?;
            if matches!(body_result, VerificationResult::Failed { .. })
                && body_binding.public_obligation_id == *public_obligation_id
                && body_binding.matches_row(body_index, body_vc)
            {
                return Some(body_index);
            }
            None
        });
        if let Some(body_index) = refuted_body {
            results[index].1 = results[body_index].1.clone();
            applied += 1;
            continue;
        }
        let Some(body_proofs) = body_ids
            .into_iter()
            .map(|public_obligation_id| {
                let body_index = row_by_obligation_id.get(&public_obligation_id).copied()?;
                if body_index == index {
                    return None;
                }
                let (body_vc, body_result) = results.get(body_index)?;
                let body_binding = bindings.get(body_index)?.as_ref()?;
                let body_authority = proof_authorities.get(body_index)?.as_ref()?;
                if !body_result.is_proved()
                    || body_binding.public_obligation_id != public_obligation_id
                    || !body_binding.matches_row(body_index, body_vc)
                    || !body_authority.is_exact_source_clause_body_proof_for(
                        body_index,
                        body_vc,
                        body_result,
                        Some(body_binding),
                    )
                {
                    return None;
                }
                Some(ExactSourceClauseBodyProofBinding {
                    public_obligation_id,
                    row: exact_result_row_identity(body_index, body_vc)?,
                })
            })
            .collect::<Option<Vec<_>>>()
        else {
            continue;
        };
        if body_proofs.is_empty() {
            continue;
        }
        let source_authority = ResultProofAuthority::ExactSourceClauseDischarge {
            row,
            binding: marker_binding.clone(),
            body_proofs,
        };
        results[index].1 = VerificationResult::Proved {
            solver: trust_types::Symbol::intern("trust-exact-source-clause-discharge"),
            time_ms: 0,
            strength: trust_types::ProofStrength::deductive(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        };
        proof_authorities[index] = Some(source_authority);
        applied += 1;
    }
    applied
}

/// Consume private receipts from the genuine Trust-WP dispatch for the narrow
/// compiler-finalized body-bound marker lane. This runs after ordinary exact
/// source-clause discharge so a Clean-kernel derivation, when available,
/// remains the stronger authority. Public labels, metadata, evidence, or a
/// manifest without the corresponding private receipt cannot enter this arm.
fn apply_body_bound_native_replay_receipts(
    bundle: &trust_verifier_api::TrustContractBundle,
    native_bundle: Option<&trust_ir_bridge::NativeVerificationBundle>,
    run: &trust_verifier_api::VerificationRunResult,
    receipts: &[BodyBoundNativeReplayReceipt],
    results: &mut [(VerificationCondition, VerificationResult)],
    bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &mut [Option<ResultProofAuthority>],
) -> usize {
    let Some(native_bundle) = native_bundle else { return 0 };
    if receipts.is_empty()
        || results.len() != bindings.len()
        || results.len() != proof_authorities.len()
    {
        return 0;
    }
    let receipt_ids = receipts
        .iter()
        .map(|receipt| receipt.live.returned_obligation.obligation_id.as_str())
        .collect::<Vec<_>>();
    if receipt_ids.iter().any(|id| receipt_ids.iter().filter(|other| *other == id).count() != 1) {
        return 0;
    }

    let mut applied = 0;
    for receipt in receipts {
        if !receipt.matches_current_carriers(bundle, native_bundle, run) {
            continue;
        }
        let mut matching_rows = bindings.iter().enumerate().filter_map(|(index, binding)| {
            binding.as_ref().and_then(|binding| {
                (binding.public_obligation_id == receipt.live.returned_obligation.obligation_id)
                    .then_some((index, binding))
            })
        });
        let Some((index, binding)) = matching_rows.next() else { continue };
        if matching_rows.next().is_some()
            || proof_authorities[index].is_some()
            || !binding.matches_row(index, &results[index].0)
            || !binding.matches_public_obligation(&receipt.live.returned_obligation)
            || !matches!(results[index].0.formula, Formula::Bool(false))
            || source_clause_marker_identity(bundle, &binding.canonical_obligation)
                .is_none_or(|identity| identity.kind != SourceClauseKind::Ensures)
            || matches!(results[index].1, VerificationResult::Failed { .. })
        {
            continue;
        }
        let Some(row) = exact_result_row_identity(index, &results[index].0) else { continue };
        // TCB closure step 1: try to take trust-wp out of this row's base by
        // re-deriving the sealed claim in the Clean kernel. Attempted BEFORE the
        // replay token is minted so the stronger authority wins when it exists;
        // a decline (unsupported claim shape, or no proof of a claim the kernel
        // cannot close) simply leaves the row on the existing `Trusted` lane.
        let (authority, solver) = match body_bound_kernel_certificate(receipt, &row) {
            Some(evidence) => (
                ResultProofAuthority::BodyBoundKernelCertified {
                    row,
                    binding: binding.clone(),
                    receipt: receipt.clone(),
                    evidence,
                },
                "trust-certify-body-bound-kernel-recheck",
            ),
            None => (
                ResultProofAuthority::BodyBoundNativeReplay {
                    row,
                    binding: binding.clone(),
                    receipt: receipt.clone(),
                    strength: TrustProofStrength::Deductive,
                },
                "trust-wp-body-bound-live-replay",
            ),
        };
        results[index].1 = VerificationResult::Proved {
            solver: trust_types::Symbol::intern(solver),
            time_ms: 0,
            strength: trust_types::ProofStrength::deductive(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        };
        proof_authorities[index] = Some(authority);
        applied += 1;
    }
    applied
}

/// Re-derive a sealed body-bound `ensures` claim in the Clean kernel.
///
/// The input is the `trust_wp.trust-formula.v1` envelope the compiler pinned
/// into this row's native proof obligation and re-compared at the sealing seam —
/// the proposition trust-wp was asked about, never its answer. `trust-certify`
/// reconstructs it as a CIC goal, proves it, and re-checks the term under a
/// zero-trust axiom closure; see `trust_certify::body_bound_ensures`.
///
/// The lineage is bound to this exact row: the public obligation id, the
/// carrier's semantic digest, and the row's canonical VC payload and index are
/// length-prefixed into an injective identity, so a certificate cannot be
/// transplanted onto another row or another claim.
fn body_bound_kernel_certificate(
    receipt: &BodyBoundNativeReplayReceipt,
    row: &ExactResultRowIdentity,
) -> Option<trust_ir::ProofEvidence> {
    let carrier = &receipt.live.carrier;
    let formula = carrier.native_proof_obligation.formula.as_ref()?;
    let mut identity = Vec::new();
    for field in [
        carrier.canonical_obligation.obligation_id.as_bytes(),
        carrier.public_semantic_digest.as_bytes(),
        row.canonical_vc.as_bytes(),
        &row.index.to_le_bytes(),
    ] {
        identity.extend_from_slice(&(field.len() as u64).to_le_bytes());
        identity.extend_from_slice(field);
    }
    match trust_certify::body_bound_ensures::certify_body_bound_ensures_claim(
        &formula.schema,
        &formula.payload,
        &identity,
    ) {
        Ok(evidence) => Some(evidence),
        Err(reason) => {
            debug!(
                "body-bound kernel re-check declined for `{}`: {reason}",
                carrier.canonical_obligation.obligation_id
            );
            None
        }
    }
}

fn full_verification_legacy_results_bound_with_fresh_vcs(
    func: &trust_types::VerifiableFunction,
    bundle: &trust_verifier_api::TrustContractBundle,
    result: &trust_verifier_api::VerificationRunResult,
    fresh_vcs: &[VerificationCondition],
    fresh_vc_rekey_snapshot: &ExactFreshVcRekeySnapshot,
) -> (Vec<(VerificationCondition, VerificationResult)>, Vec<Option<ResultObligationBinding>>) {
    if !exact_fresh_vc_rekey_run_is_complete(bundle, result, fresh_vcs, fresh_vc_rekey_snapshot) {
        // A missing, duplicated, malformed, or post-dispatch-mutated public VC
        // carrier invalidates the fresh batch as a whole. Keep every ordinary
        // public row plus every eligible compiler-owned VC as Unknown, while
        // `None` bindings prevent both native verdict import and the ay bridge
        // from reconstructing authority through formula/location coincidence.
        let mut failed = bundle
            .obligations
            .iter()
            .filter(|obligation| !obligation.is_default_admission())
            .map(|obligation| {
                (
                    legacy_vc_from_api_obligation(func, obligation),
                    fresh_vc_rekey_integrity_failure_result(),
                )
            })
            .collect::<Vec<_>>();
        failed.extend(
            fresh_vc_rekey_snapshot
                .eligible_vc_indices
                .iter()
                .filter_map(|index| fresh_vcs.get(*index).cloned())
                .map(|vc| (vc, fresh_vc_rekey_integrity_failure_result())),
        );
        // Preserve an explicit, non-promotable integrity row even when every
        // original fresh formula happens to be independently certifiable.
        failed.push((
            fresh_vc_rekey_integrity_failure_vc(func),
            fresh_vc_rekey_integrity_failure_result(),
        ));
        let bindings = vec![None; failed.len()];
        return (failed, bindings);
    }
    let full_index = build_full_verification_evidence_index(result);
    let strict_accepted_ids = strict_accepted_obligation_ids_from_index(result, &full_index);
    let current_fresh_vc_digests = current_fresh_vc_semantic_digests(
        bundle,
        fresh_vc_rekey_snapshot,
        &result.requested_obligations,
    );

    // Map each obligation to its exact legacy VC/result while retaining the
    // compiler-owned obligation long enough to mint its private binding.
    let mapped: Vec<(
        &trust_verifier_api::TrustObligation,
        VerificationCondition,
        VerificationResult,
        bool,
    )> = bundle
        .obligations
        .iter()
        .enumerate()
        // Trust: the synthetic trust-mc per-function admission is not a real
        // obligation — it anchors native-bundle construction but its "proof" is
        // vacuous by construction. Exclude it from the legacy results so it
        // never inflates trusted/total counts or makes an admission-only
        // function read as Verified. See trust_verifier_api::is_default_admission.
        .filter(|(_, obligation)| !obligation.is_default_admission())
        .map(|(bundle_index, obligation)| {
            // Interval analysis can discharge a VC before it reaches the v1
            // solver set, while the native full-verification bundle still
            // contains that row. Re-key such a result to the original formula
            // only through the fresh typed context + exact location + digest +
            // schema identity emitted for this very `all_vcs` slice. Duplicate
            // matches and every malformed/stale/out-of-range carrier retain the
            // legacy fail-closed formula; no proof label is consulted here.
            let vc = exact_snapshot_fresh_vc_for_obligation(
                obligation,
                fresh_vcs,
                fresh_vc_rekey_snapshot,
                current_fresh_vc_digests.as_ref(),
            )
            .cloned()
            .unwrap_or_else(|| legacy_vc_from_api_obligation(func, obligation));
            let definition_entry_assumption = fresh_vc_rekey_snapshot
                .definition_entry_markers
                .matches(bundle_index, bundle, obligation);
            // A source marker is a catalog identity, not the semantic body
            // proposition. Keep its legacy `Bool(false)` placeholder Unknown
            // through solver import, kernel certification, and authority mint;
            // the post-authority phase below is its only discharge path.
            let legacy_result = full_verification_legacy_result_for_obligation(
                obligation,
                &full_index.evidence_by_obligation_id,
                &full_index.skipped_by_id,
                &strict_accepted_ids,
                definition_entry_assumption,
                api_obligation_is_assumed_total_callee_marker(func, bundle, obligation),
            );
            let legacy_result = if source_clause_marker_identity(bundle, obligation).is_some()
                && matches!(
                    &legacy_result,
                    VerificationResult::Proved { .. } | VerificationResult::Unknown { .. }
                ) {
                exact_source_clause_pending_result()
            } else {
                // A concrete refutation or timeout is a fail-closed blocker,
                // not a generic promotion to normalize away.
                legacy_result
            };
            (obligation, vc, legacy_result, definition_entry_assumption)
        })
        .collect();

    let mut results = Vec::with_capacity(mapped.len());
    let mut bindings = Vec::with_capacity(mapped.len());
    for (index, (obligation, vc, result, definition_entry_assumption)) in
        mapped.into_iter().enumerate()
    {
        bindings.push(result_obligation_binding_with_compiler_assumptions(
            index,
            &vc,
            obligation,
            definition_entry_assumption,
            api_obligation_is_assumed_total_callee_marker(func, bundle, obligation),
        ));
        results.push((vc, result));
    }
    (results, bindings)
}

#[cfg(test)]
fn full_verification_legacy_results_bound(
    func: &trust_types::VerifiableFunction,
    bundle: &trust_verifier_api::TrustContractBundle,
    result: &trust_verifier_api::VerificationRunResult,
) -> (Vec<(VerificationCondition, VerificationResult)>, Vec<Option<ResultObligationBinding>>) {
    let snapshot = exact_fresh_vc_rekey_snapshot(
        func,
        &trust_types::CompilerContractBundle::default(),
        bundle,
        &[],
        result.context.clone(),
    );
    full_verification_legacy_results_bound_with_fresh_vcs(func, bundle, result, &[], &snapshot)
}

/// Trust (P1.2): the honest solver label minted for a def-site `#[requires]`
/// marker discharged as a modular ENTRY ASSUMPTION (see
/// `full_verification_legacy_result_for_obligation`). This label is produced
/// ONLY by that frozen-identity-gated arm — nothing deserialized (transport, cache,
/// annotations) ever re-enters the in-process `results` pairs — so every
/// verdict path in this file may treat a `Proved` carrying it as the
/// entry-assumption discharge without re-deriving the origin check.
const TRUST_ENTRY_ASSUMPTION_SOLVER: &str = "trust-entry-assumption";
/// Trust (failed-rekey symmetry): the honest solver label minted when a
/// VERIFIED refutation of one representation of a source obligation is
/// re-keyed onto the duplicate/marker row RESTATING the same predicate at the
/// same source span. Produced only by the in-process assertion-family duplicate
/// re-key; nothing deserialized ever re-enters the private result carrier. A
/// `Failed` can only strengthen fail-closed behavior, so this label carries
/// attribution, never proof authority.
const TRUST_REFUTE_REKEY_SOLVER: &str = "trust-refute-rekey";
/// Machine-stable transport kind for the same modular entry assumption. The
/// in-process result remains a private `Proved` bookkeeping discharge, but the
/// wire row must enter the assumption/unknown partition and never proof credit.
const TRUST_ENTRY_ASSUMPTION_TRANSPORT_KIND: &str = "assumption:requires";
const TRUST_ENTRY_ASSUMPTION_REASON: &str =
    "conditional definition-entry assumption; every caller must establish the requires contract";
const TRUST_ASSUMED_TOTAL_SOLVER: &str = "trust-assumed-total";
const TRUST_ASSUMED_TOTAL_REASON: &str = "user-audited #[trust::assume_total] callee: recorded assumption, NOT verified; the crate's proof is conditional on the audited wrapper's totality";
const TRUST_UNSUPPORTED_MIR_TRANSPORT_REASON: &str =
    "unsupported MIR obligations cannot carry proved or runtime-checked transport outcomes";

/// Whether an in-process result is the def-site `#[requires]` entry-assumption
/// discharge (a `Proved` minted by the frozen-identity-gated arm in
/// `full_verification_legacy_result_for_obligation`, never by a solver).
fn is_entry_assumption_discharge(result: &VerificationResult) -> bool {
    matches!(
        result,
        VerificationResult::Proved { solver, .. }
            if solver.as_str() == TRUST_ENTRY_ASSUMPTION_SOLVER
    )
}

fn is_assumed_total_discharge(result: &VerificationResult) -> bool {
    matches!(
        result,
        VerificationResult::Proved { solver, .. }
            if solver.as_str() == TRUST_ASSUMED_TOTAL_SOLVER
    )
}

fn api_obligation_is_assumed_total_callee_marker(
    func: &trust_types::VerifiableFunction,
    bundle: &trust_verifier_api::TrustContractBundle,
    obligation: &trust_verifier_api::TrustObligation,
) -> bool {
    let prefix = trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX;
    if !obligation.description.strip_prefix(prefix).is_some_and(|detail| !detail.trim().is_empty())
    {
        return false;
    }

    // The prefix is only a diagnostic label. Authority comes from recomputing
    // the exact compiler-owned whole-function panic carrier against the live
    // extracted function and bundle subject. This binds the canonical ID,
    // source, crate/path, source/VC digests, metadata allowlist/uniqueness, and
    // current CompilerMirExtract context; canonical-looking public strings are
    // insufficient.
    let expected_crate_name = match &bundle.subject {
        trust_verifier_api::BundleSubject::Function { crate_name, path }
            if !crate_name.trim().is_empty() && path == &func.def_path =>
        {
            crate_name.as_str()
        }
        _ => return false,
    };
    obligation_is_synthesized_whole_function_panic_freedom(
        func,
        Some(expected_crate_name),
        obligation,
    )
}

/// Apply the phase-A vacuity gate, exempting only private capabilities minted
/// for a definition-entry assumption, an exact source-clause/body discharge,
/// the direct TrustVC lane's exact live Ownership certificate, or S3's affine
/// exact-direct E4/E5 receipt. Catalog rows can have a constant legacy
/// placeholder; exact Ownership and E4/E5 violation formulas can also
/// legitimately normalize to false after their private same-solve receipts
/// proved the complete structured carriers. In each case authority lives
/// outside the public formula label. Solver/backend names are public
/// attribution strings and can never authorize an exemption.
fn apply_vacuity_gate_with_authority(
    index: usize,
    vc: &VerificationCondition,
    result: VerificationResult,
    binding: Option<&ResultObligationBinding>,
    authority: Option<&ResultProofAuthority>,
) -> VerificationResult {
    // Trust: E9 §5d — an EnsuresCitationDischarge authority is exempt for the
    // same reason the definition-entry assumption is: its semantics are carried
    // by the authority itself (a kernel-certified proof of the ensures CLAUSE,
    // row-bound by the conjunction pairing), not by this row's formula
    // representation — which for the duplicate whole-signature-span entry is
    // the legacy bookkeeping placeholder the vacuity gate would (correctly,
    // for solver proofs) downgrade.
    if authority.is_some_and(|authority| {
        authority.is_definition_entry_assumption_for(index, vc, binding)
            || authority.is_assumed_total_callee_assumption_for(index, vc, binding)
            || authority.is_exact_source_clause_discharge_for(index, vc, binding)
            || authority.is_ensures_citation_discharge_for(index, vc, binding)
            || authority.is_body_bound_lane_authority_for(index, vc, binding)
            || authority.is_direct_trust_vc_live_for(index, vc, &result, binding)
            || authority.is_fresh_exact_direct_chc_pdr_for(index, vc, &result, binding)
    }) {
        result
    } else {
        trust_router::constant_folder::apply_vacuity_gate(vc, result)
    }
}

/// A def-site `#[requires]` marker: an obligation whose typed context origin is
/// `Contract { contract_kind: Requires }`. This is the function's OWN entry
/// assumption (built in `contract_bundle_to_verifier_api`), NOT a call-site
/// precondition VC (origin `VerificationCondition`). The two share a
/// `contract_id`, so origin is the only sound discriminator — see the caller.
fn is_definition_site_requires_marker(obligation: &trust_verifier_api::TrustObligation) -> bool {
    if !matches!(&obligation.kind, trust_verifier_api::ObligationKind::Precondition) {
        return false;
    }
    let Some(context) = exactly_one_obligation_context(obligation) else {
        return false;
    };
    if !context.has_current_schema()
        || !matches!(context.producer, trust_verifier_api::ObligationProducer::CompilerMirExtract)
    {
        return false;
    }
    let trust_verifier_api::ObligationOrigin::Contract {
        contract_id,
        contract_kind: trust_verifier_api::ContractKind::Requires,
        ..
    } = context.origin
    else {
        return false;
    };
    obligation.contract_id.as_deref() == Some(contract_id.as_str())
}

fn full_verification_legacy_result_for_obligation(
    obligation: &trust_verifier_api::TrustObligation,
    evidence_by_id: &FxHashMap<&str, &trust_verifier_api::ObligationEvidence>,
    skipped_by_id: &FxHashMap<&str, &trust_verifier_api::SkippedObligation>,
    strict_accepted_ids: &FxHashSet<String>,
    definition_entry_assumption: bool,
    assumed_total_callee_assumption: bool,
) -> VerificationResult {
    // Trust (P1.2 — def-site `#[requires]` is an ENTRY ASSUMPTION, not a proof
    // obligation): a function is entitled to ASSUME its own precondition; the
    // obligation to establish it is transferred to each CALL SITE (where a
    // `contract_id: None` call-site precondition VC is generated and DOES get
    // proved/refuted — see `native_contract_vc_kind` and the caller-side
    // reclassify at the vcgen path). The def-site marker itself is bookkeeping:
    // routing it to trust-wp's native pure replay (which correctly returns
    // Unsupported on a free symbolic comparison like `a <= 1000`, since you
    // genuinely cannot PROVE `a <= 1000` for an arbitrary `a`) dragged EVERY
    // contracted function to `unknown` -> Inconclusive -> gate fail. The default
    // (vcgen) lane already discharges this trivially (a `Bool(false)` violation is
    // UNSAT -> Proved); this makes the native/full lane consistent.
    //
    // SOUNDNESS: scoped to the def-site marker ONLY, whose exact full row and
    // referenced contract were frozen against the independent compiler-owned
    // contract-only reconstruction before dispatch. Its obligation-context
    // ORIGIN is `Contract { contract_kind: Requires }`, but that public shape
    // is only a reject-only prerequisite, never authority. This distinction is
    // essential because a CALL-SITE precondition VC carries the SAME
    // `contract_id` (it references the callee's contract, e.g.
    // `trust-contract:add:requires:0`) but has origin `VerificationCondition`
    // — so a `contract_id`-based check would WRONGLY discharge the caller's
    // obligation and let a violated call slip through. Gating on the frozen
    // exact identity discharges the callee's entry assumption while leaving
    // every caller-side precondition VC to be genuinely proved/refuted. Postconditions,
    // invariants, and refinements have a different `contract_kind` and are
    // excluded — those the body must genuinely prove. A vacuous
    // `#[requires(false)]` is contained by modular semantics: the body verifies
    // vacuously, but every CALL must prove `false` at the call site and fails
    // closed. The in-process attribution label is `trust-entry-assumption`;
    // transport maps this private bookkeeping discharge to the explicit
    // `assumption:requires`/`skipped` non-proof row.
    if definition_entry_assumption {
        return VerificationResult::Proved {
            solver: trust_types::Symbol::intern(TRUST_ENTRY_ASSUMPTION_SOLVER),
            time_ms: 0,
            strength: trust_types::ProofStrength::deductive(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        };
    }
    // The bridge emits this marker only for a caller-side callee explicitly
    // marked `#[trust::assume_total]`. Its synthetic may-panic encoding is
    // refutable by construction, so classify the row as recorded assumption
    // before importing native refutation evidence.
    if assumed_total_callee_assumption {
        return VerificationResult::Proved {
            solver: trust_types::Symbol::intern(TRUST_ASSUMED_TOTAL_SOLVER),
            time_ms: 0,
            strength: trust_types::ProofStrength::deductive(),
            proof_certificate: None,
            solver_warnings: None,
            native_proof_envelope: None,
        };
    }
    // Trust: SOUNDNESS-CRITICAL. trust-vc's direct-MIR-memory verifier refuted
    // this obligation with a genuine counterexample (negated VC formula SAT over
    // a total/faithful lowering). The native evidence import recorded the
    // refutation on the obligation via `TRUST_VC_REFUTED_METADATA_KEY` (it could
    // not be expressed as a positive proof certificate). Map it to `Failed` so it
    // fails closed under `-full` rather than surviving as Unknown. Both this
    // marker and the pruning marker must be unique: duplicate metadata is not an
    // authority source and cannot be resolved by insertion order.
    //
    // A violation-pruned payload is different. Dropping conjuncts produces a
    // weaker formula P with more models (`original => P`). P being UNSAT still
    // proves the original UNSAT, but a model of P need not satisfy the dropped
    // hypotheses. Therefore a direct TrustVC refutation of P is Unknown for the
    // original obligation, exactly like a generic pruned Failed result below.
    let violation_pruned =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PRUNED_METADATA_KEY)
            == Some("true");
    if unique_api_obligation_metadata_value(obligation, TRUST_VC_REFUTED_METADATA_KEY).is_some() {
        if violation_pruned {
            return VerificationResult::Unknown {
                solver: trust_types::Symbol::intern("trust-vc"),
                time_ms: 0,
                reason: "direct trust-vc counterexample is to a weaker violation-pruned sub-conjunction; it does not establish the original violation is reachable".to_string(),
            };
        }
        return VerificationResult::Failed {
            solver: trust_types::Symbol::intern("trust-vc"),
            time_ms: 0,
            counterexample: None,
        };
    }
    if let Some(evidence) = evidence_by_id.get(obligation.obligation_id.as_str()).copied() {
        let legacy = legacy_result_from_api_evidence(evidence);
        // A VIOLATION-PRUNED payload P is a WEAKER sub-conjunction of the real
        // violation (`original => P`) because un-lowerable hypothesis conjuncts
        // were dropped. Proving P UNSAT proves the original UNSAT, but a model of
        // P need not satisfy the dropped hypotheses. Downgrade only for one exact
        // canonical pruning marker; malformed or duplicate metadata cannot erase
        // an otherwise authoritative Failed result.
        if matches!(legacy, VerificationResult::Failed { .. }) && violation_pruned {
            return VerificationResult::Unknown {
                solver: trust_types::Symbol::intern(&evidence.engine.name),
                time_ms: 0,
                reason: "native full verifier counterexample is to a weaker violation-pruned sub-conjunction; it does not establish the original violation is reachable".to_string(),
            };
        }
        if matches!(legacy, VerificationResult::Proved { .. })
            && !strict_accepted_ids.contains(obligation.obligation_id.as_str())
        {
            return VerificationResult::Unknown {
                solver: trust_types::Symbol::intern(&evidence.engine.name),
                time_ms: 0,
                reason: "native full verifier proof evidence was not accepted by the compiler's strict full-verification policy".to_string(),
            };
        }
        legacy
    } else if let Some(skipped) = skipped_by_id.get(obligation.obligation_id.as_str()).copied() {
        VerificationResult::Unknown {
            solver: trust_types::Symbol::intern("trust-full-verifier"),
            time_ms: 0,
            reason: format!("native full verifier skipped obligation: {:?}", skipped.reason),
        }
    } else {
        VerificationResult::Unknown {
            solver: trust_types::Symbol::intern("trust-full-verifier"),
            time_ms: 0,
            reason: "native full verifier returned no evidence".to_string(),
        }
    }
}

fn legacy_vc_from_api_obligation(
    func: &trust_types::VerifiableFunction,
    obligation: &trust_verifier_api::TrustObligation,
) -> VerificationCondition {
    // Trust: a whole-function panic-freedom obligation
    // (`synthesize_native_panic_freedom_to_verifier_api_obligations`) has no v1
    // vcgen VC to re-key its native proof onto — vcgen deliberately skips panic
    // VCs — so it would otherwise fall through to a placeholder `UnsupportedMir`
    // VC with a `Bool(false)` formula that the phase-A vacuity gate rejects
    // (constant-false goal), downgrading the real native PdrInvariant proof to
    // Unknown. Give it a real `Assertion` kind and a SYMBOLIC violation formula
    // — `panic_reachable`, a bare boolean variable that does NOT constant-fold —
    // so the vacuity gate passes and the native CHC/PDR proof is counted. The
    // real proof is the native solve; this formula is the v1-accounting
    // representation of the obligation "no panic is reachable" (violation:
    // `panic_reachable` is SAT).
    if obligation_is_synthesized_whole_function_panic_freedom(func, None, obligation) {
        return VerificationCondition {
            kind: VcKind::Assertion { message: obligation.description.clone() },
            function: trust_types::Symbol::intern(&func.def_path),
            location: source_span_from_api_location(&obligation.source),
            formula: Formula::Var(
                format!("panic_reachable:{}", obligation.obligation_id),
                trust_types::Sort::Bool,
            ),
            contract_metadata: None,
        };
    }
    let kind = native_contract_vc_kind(obligation)
        .or_else(|| hardened_vc_from_api_obligation(obligation))
        .unwrap_or_else(|| {
            let (kind, detail) = legacy_unsupported_kind_detail(obligation);
            VcKind::UnsupportedMir { kind, detail }
        });
    // Trust (W3.7/F4): a hardened DESIGN MANDATE — an opaque OS/process obligation
    // (e.g. the `_print` process-semantics rule) whose violation formula is the
    // tautology `Bool(true)`, a discharge target that can NEVER be proved UNSAT — must
    // KEEP that `Bool(true)` formula here so the transport constructor's design-mandate
    // bit (`hardened_category().is_some() && matches!(formula, Bool(true))`) survives
    // the full-lane reconstruction. Without this the formula falls through to the
    // `Bool(false)` placeholder below (`reconstruct_obligation_violation_formula` maps
    // every `Bool(_)` payload to `None`), silently DROPPING the mandate bit — so the
    // row is miscounted as a genuine unknown instead of an inventory mandate, and
    // hello's process-semantics row loses its `design_mandate:true`. SOUND: this ONLY
    // sets the bit; the obligation's OUTCOME still comes from the native hardened
    // evidence (opaque → Unsupported/Unknown), never from re-solving `Bool(true)`, so
    // no refutation is introduced (the vacuity gate touches only Proved results, and a
    // `Bool(true)` violation is not vacuously-UNSAT so a Proved mandate would NOT be
    // downgraded — but the opaque hardened stub returns no Proved evidence, so the row
    // stays the same non-failed outcome as before, now correctly bucketed as a mandate).
    if kind.hardened_category().is_some() && hardened_obligation_is_design_mandate(obligation) {
        return VerificationCondition {
            kind,
            function: trust_types::Symbol::intern(&func.def_path),
            location: source_span_from_api_location(&obligation.source),
            formula: Formula::Bool(true),
            contract_metadata: None,
        };
    }
    // Trust (#35): reconstruct this obligation's REAL violation formula from its
    // own `trust.vc.formula.payload` metadata. The bridge re-keys solver-set VCs
    // onto their native results BY LOCATION, but a VC that vcgen *discharged*
    // (constant-folded out of the solver set — e.g. a constant shift-amount or
    // cast-range check, `a >> 2` / `x as u32`) has no solver-set entry, so it
    // falls through to the `Formula::Bool(false)` placeholder below, which the
    // phase-A vacuity gate rejects (constant-false goal) — silently downgrading
    // the genuine native PdrInvariant proof to Unknown. Recovering the obligation's
    // own formula here lets the in-process kernel INDEPENDENTLY certify the closed
    // contradiction (`Or([2<0, 2>=32])` → Certified) and, for non-closed shapes,
    // lets the native proof count as Trusted instead of vanishing. Precise by
    // construction: the payload is THIS obligation's violation, not a heuristic
    // location match. Mirrors the panic-freedom symbolic-formula precedent above.
    let formula =
        reconstruct_obligation_violation_formula(obligation).unwrap_or(Formula::Bool(false));
    VerificationCondition {
        kind,
        function: trust_types::Symbol::intern(&func.def_path),
        location: source_span_from_api_location(&obligation.source),
        formula,
        contract_metadata: None,
    }
}

/// Trust (W3.7/F4): whether a hardened obligation is a DESIGN MANDATE — its original
/// violation formula is the tautology `Bool(true)`. The vcgen hardened rules build an
/// opaque OS/process obligation (`_print`, `stdout`, `setuid`, …) with a `Bool(true)`
/// violation (an always-"violated", never-dischargeable design mandate), while a
/// hardened MIR-assert carries a REAL assert-failure predicate. The `Bool(true)`
/// formula lowers to a `trust.vc.formula.payload` that decodes to `Formula::Bool(true)`
/// (`trust-mir-extract` `vc_formula_payload`), so we detect the mandate PRECISELY by
/// that payload — a real hardened assert decodes to a non-`Bool` predicate and returns
/// `false` (kept as a genuine discharge target). Fail-closed: an absent, duplicated,
/// or unparseable payload returns `false` (treated as a genuine obligation, never a
/// free mandate).
fn hardened_obligation_is_design_mandate(obligation: &trust_verifier_api::TrustObligation) -> bool {
    let Some(payload) =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)
    else {
        return false;
    };
    // Trust (R1 corpus): depth-tolerant parse — see `trust_types::json_depth`.
    let Some(predicate) =
        trust_types::json_depth::from_str_deep::<trust_verifier_api::TrustSpecPredicate>(payload)
            .ok()
    else {
        return false;
    };
    // Deserialization only establishes the JSON shape. The declaration table
    // and the sorts carried by every expression node are independent authority
    // inputs, so a malformed payload must not acquire design-mandate semantics.
    // Keep this fail-closed in lockstep with every other native predicate
    // consumer.
    if predicate.validate().is_err() {
        return false;
    }
    matches!(formula_from_trust_spec_expr(&predicate.root), Some(Formula::Bool(true)))
}

/// Recover an obligation's real `trust_types::Formula` violation from its
/// `trust.vc.formula.payload` metadata (a `trust.spec-predicate.v1`
/// `TrustSpecPredicate`), or `None` when the payload is absent/duplicated, not in
/// the supported bool/int/bitvector fragment, or a literal `Bool(_)` placeholder
/// (→ caller keeps the `Bool(false)` placeholder, preserving prior fail-closed
/// behavior). Quantifier / heap / variant nodes fail closed, so no proof is
/// fabricated from a shape the decoder cannot represent faithfully.
fn reconstruct_obligation_violation_formula(
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<Formula> {
    let payload =
        unique_api_obligation_metadata_value(obligation, TRUST_VC_FORMULA_PAYLOAD_METADATA_KEY)?;
    // Trust (R1 corpus): depth-tolerant parse — see `trust_types::json_depth`.
    let predicate =
        trust_types::json_depth::from_str_deep::<trust_verifier_api::TrustSpecPredicate>(payload)
            .ok()?;
    // `formula_from_trust_spec_expr` is deliberately a lossless decoder, not a
    // schema validator. Validate first so undeclared variables, forged node
    // sorts, duplicate declarations, and other structurally invalid metadata
    // cannot become a reconstructed native VC.
    predicate.validate().ok()?;
    // A violation is a proposition. Every compiler-produced payload is minted by
    // `trust_spec_predicate_from_formula`, which requires a Bool root, so a
    // non-Bool root is a malformed/foreign payload — fail closed rather than
    // reconstruct a non-propositional "violation" (defense-in-depth now that the
    // decoder also produces BitVec-sorted terms).
    if predicate.root.sort != trust_verifier_api::TrustSpecSort::Bool {
        return None;
    }
    let formula = formula_from_trust_spec_expr(&predicate.root)?;
    match formula {
        Formula::Bool(_) => None,
        other => Some(other),
    }
}

/// Decode a `TrustSpecExpr` (the stable compiler-lowered predicate IR) back into
/// a `trust_types::Formula`, covering the full bool/int/bitvector vocabulary of
/// the payload schema. The exact inverse of `trust-mir-extract`'s
/// `FormulaLowerer::lower_formula` on that encoder's image: every arm here
/// reverses the corresponding encoder arm node-for-node, so a decoded row keeps
/// the REAL violation formula the payload was minted from. Faithfulness is
/// load-bearing — the decoded formula is what the in-process kernel
/// independently re-certifies (`certify_all`) and what the phase-A vacuity gate
/// inspects before `build_result_proof_authorities` will mint ANY proof
/// authority — so any node this decoder cannot reverse EXACTLY returns `None`
/// and the caller keeps the fail-closed `Bool(false)` placeholder for that row
/// (quantifiers, `result`/`old`/field/index/variant nodes, `Ugt`/`Uge` — which
/// no `Formula` produces — and non-`i128` literals). Note the schema has NO
/// floating-point node kinds by construction (the encoder fails Fp* formulas
/// closed and FP hypotheses are violation-pruned before payload creation), so
/// float-VC payloads arrive here as their pure-BV witness residue and are fully
/// covered by the bitvector arms below.
///
/// Every bitvector arm cross-checks the payload's claimed sorts against the op's
/// width (the encoder always writes them consistently), so a payload whose sort
/// annotations disagree with its structure is malformed and fails closed rather
/// than decoding to an ill-sorted formula.
fn formula_from_trust_spec_expr(expr: &trust_verifier_api::TrustSpecExpr) -> Option<Formula> {
    use trust_verifier_api::{
        TrustSpecBinaryOp as Bin, TrustSpecBvBinaryOp as BvBin, TrustSpecBvUnaryOp as BvUn,
        TrustSpecExprKind as K, TrustSpecSort as SpecSort, TrustSpecUnaryOp as Un,
    };
    let bx = |f: Formula| Box::new(f);
    let rec = formula_from_trust_spec_expr;
    let bv = |width: u32| SpecSort::BitVec { width };
    Some(match &expr.kind {
        K::BoolLiteral { value } => Formula::Bool(*value),
        K::IntLiteral { value } => Formula::Int(value.parse::<i128>().ok()?),
        K::Variable { name } => Formula::Var(name.clone(), trust_sort_from_spec_sort(expr.sort)?),
        K::Unary { op, expr: inner } => match op {
            Un::Not => Formula::Not(bx(rec(inner)?)),
            Un::Neg => Formula::Neg(bx(rec(inner)?)),
            _ => return None,
        },
        K::Binary { op, lhs, rhs } => {
            let l = rec(lhs)?;
            let r = rec(rhs)?;
            match op {
                Bin::And => Formula::And(vec![l, r]),
                Bin::Or => Formula::Or(vec![l, r]),
                Bin::Implies => Formula::Implies(bx(l), bx(r)),
                Bin::Eq => Formula::Eq(bx(l), bx(r)),
                Bin::Ne => Formula::Not(bx(Formula::Eq(bx(l), bx(r)))),
                Bin::Lt => Formula::Lt(bx(l), bx(r)),
                Bin::Le => Formula::Le(bx(l), bx(r)),
                Bin::Gt => Formula::Gt(bx(l), bx(r)),
                Bin::Ge => Formula::Ge(bx(l), bx(r)),
                Bin::Add => Formula::Add(bx(l), bx(r)),
                Bin::Sub => Formula::Sub(bx(l), bx(r)),
                Bin::Mul => Formula::Mul(bx(l), bx(r)),
                Bin::Div => Formula::Div(bx(l), bx(r)),
                Bin::Mod => Formula::Rem(bx(l), bx(r)),
                _ => return None,
            }
        }
        // The encoder writes `Formula::BitVec { value: i128, width }` as
        // `value.to_string()`; `parse::<i128>` is its exact inverse (a decimal
        // magnitude outside i128 was never encoder-produced — fail closed).
        K::BitVecLiteral { value, width } => {
            if expr.sort != bv(*width) {
                return None;
            }
            Formula::BitVec { value: value.parse::<i128>().ok()?, width: *width }
        }
        K::BvUnary { op, expr: inner, width } => match op {
            // `bvnot`: operand and result share `width`.
            BvUn::Not => {
                if inner.sort != bv(*width) || expr.sort != bv(*width) {
                    return None;
                }
                Formula::BvNot(bx(rec(inner)?), *width)
            }
            // `sign_extend`: the encoder refuses `extend_by == 0` and stamps
            // `width = inner_width + extend_by`; reverse under the same rules.
            BvUn::SignExt { extend_by } => {
                let SpecSort::BitVec { width: inner_width } = inner.sort else {
                    return None;
                };
                if *extend_by == 0
                    || inner_width.checked_add(*extend_by) != Some(*width)
                    || expr.sort != bv(*width)
                {
                    return None;
                }
                Formula::BvSignExt(bx(rec(inner)?), *extend_by)
            }
            // `extract [high:low]`: the encoder enforces `low <= high <
            // inner_width` and stamps `width = high - low + 1`.
            BvUn::Extract { high, low } => {
                let SpecSort::BitVec { width: inner_width } = inner.sort else {
                    return None;
                };
                if *high < *low
                    || *high >= inner_width
                    || (*high - *low).checked_add(1) != Some(*width)
                    || expr.sort != bv(*width)
                {
                    return None;
                }
                Formula::BvExtract { inner: bx(rec(inner)?), high: *high, low: *low }
            }
            // `#[non_exhaustive]`: an unknown future op fails closed.
            _ => return None,
        },
        K::BvBinary { op, lhs, rhs, width } => {
            // Both operands carry the op width; the node carries the op's
            // result sort (`Bool` for comparisons, `BitVec(width)` otherwise).
            if lhs.sort != bv(*width)
                || rhs.sort != bv(*width)
                || expr.sort != op.result_sort(*width)
            {
                return None;
            }
            let l = bx(rec(lhs)?);
            let r = bx(rec(rhs)?);
            match op {
                BvBin::Add => Formula::BvAdd(l, r, *width),
                BvBin::Sub => Formula::BvSub(l, r, *width),
                BvBin::Mul => Formula::BvMul(l, r, *width),
                BvBin::Udiv => Formula::BvUDiv(l, r, *width),
                BvBin::Urem => Formula::BvURem(l, r, *width),
                BvBin::And => Formula::BvAnd(l, r, *width),
                BvBin::Or => Formula::BvOr(l, r, *width),
                BvBin::Xor => Formula::BvXor(l, r, *width),
                BvBin::Shl => Formula::BvShl(l, r, *width),
                BvBin::Lshr => Formula::BvLShr(l, r, *width),
                BvBin::Ashr => Formula::BvAShr(l, r, *width),
                BvBin::Ult => Formula::BvULt(l, r, *width),
                BvBin::Ule => Formula::BvULe(l, r, *width),
                BvBin::Slt => Formula::BvSLt(l, r, *width),
                BvBin::Sle => Formula::BvSLe(l, r, *width),
                // `Ugt`/`Uge` have no `Formula` counterpart (the encoder never
                // emits them), so a payload containing one is foreign — fail
                // closed rather than decode a formula the encoder could not
                // have produced. `#[non_exhaustive]` catch-all included.
                _ => return None,
            }
        }
        // `int2bv` / `bv2nat`-or-signed-value: mirror the encoder's expected
        // operand sorts exactly (`IntToBv`'s operand is `Int`; `BvToInt`'s is a
        // `width`-bit vector and its `signed` flag is threaded through — a
        // signed/unsigned mismatch silently corrupts the value).
        K::BvFromInt { expr: inner, width } => {
            if inner.sort != SpecSort::Int || expr.sort != bv(*width) {
                return None;
            }
            Formula::IntToBv(bx(rec(inner)?), *width)
        }
        K::IntFromBv { expr: inner, signed, width } => {
            if inner.sort != bv(*width) || expr.sort != SpecSort::Int {
                return None;
            }
            Formula::BvToInt(bx(rec(inner)?), *width, *signed)
        }
        // Outside the decodable fragment (quantifiers, result/old/field/index,
        // variant nodes) — fail closed.
        _ => return None,
    })
}

/// Map a `TrustSpecSort` to a `trust_types::Sort` for the decoded violation
/// fragment. Bitvector sorts map through faithfully to `Sort::BitVec(width)` —
/// a BV-payload row must keep its real `Var(_, BitVec(w))` leaves (the
/// float-overflow witnesses and machine integer checks are BV-sorted
/// end-to-end) so the reconstructed formula is non-vacuous and its
/// native/kernel proof can mint authority. Consumers stay fail-closed
/// downstream: the in-process kernel-certification lane
/// (`trust_certify::certify_vc`) is shape-gated — it discharges the unsigned
/// wide-BV no-overflow fragment (guarded add/sub, `(a/c)+(b/c)` midpoint) and
/// returns `None` for anything it cannot independently refute — and the
/// vacuity gate treats non-boolean atoms as opaque, so decoding the BV shape
/// can only expose MORE genuine kernel proofs, never fabricate one.
fn trust_sort_from_spec_sort(sort: trust_verifier_api::TrustSpecSort) -> Option<trust_types::Sort> {
    match sort {
        trust_verifier_api::TrustSpecSort::Bool => Some(trust_types::Sort::Bool),
        trust_verifier_api::TrustSpecSort::Int => Some(trust_types::Sort::Int),
        trust_verifier_api::TrustSpecSort::BitVec { width } => {
            Some(trust_types::Sort::BitVec(width))
        }
        trust_verifier_api::TrustSpecSort::Array { .. } => None,
        // Faithful decode (see the fn doc: decoding a shape can only expose
        // MORE genuine kernel proofs, never fabricate one): the typed float
        // sort maps 1:1 onto trust_types' IEEE Float sort.
        trust_verifier_api::TrustSpecSort::Float { eb, sb } => {
            Some(trust_types::Sort::Float { eb, sb })
        }
    }
}

fn hardened_vc_from_api_obligation(
    obligation: &trust_verifier_api::TrustObligation,
) -> Option<VcKind> {
    let custom_hardened_name = match &obligation.kind {
        trust_verifier_api::ObligationKind::Custom { namespace, name }
            if namespace == trust_verifier_api::TRUST_VC_HARDENED_OBLIGATION_NAMESPACE =>
        {
            Some(name.as_str())
        }
        _ => None,
    };
    let category_tag =
        api_obligation_metadata_value(obligation, TRUST_VC_HARDENED_CATEGORY_METADATA_KEY)
            .or(custom_hardened_name)?;
    let category = HardenedVcCategory::from_tag(category_tag)
        .unwrap_or_else(|| HardenedVcCategory::unknown_tag(category_tag));
    let callee = api_obligation_metadata_value(obligation, TRUST_VC_HARDENED_CALLEE_METADATA_KEY)
        .or(custom_hardened_name)
        .unwrap_or_default()
        .to_string();
    let mut detail =
        api_obligation_metadata_value(obligation, TRUST_VC_HARDENED_DETAIL_METADATA_KEY)
            .unwrap_or(&obligation.description)
            .to_string();
    if category.is_unknown() && !detail.contains(category.as_tag()) {
        detail = format!("unrecognized hardened category `{}`: {detail}", category.as_tag());
    }

    Some(VcKind::HardenedBoundary { category, callee, detail })
}

/// Trust (P1.2-C): map a first-class `Postcondition` contract obligation to the
/// native `VcKind::Postcondition` so it is accounted as a real postcondition VC
/// (re-keyed onto its trust-wp native proof by location) instead of falling
/// through to `UnsupportedMir { kind: "FullVerification::Postcondition" }` — which
/// made every `#[ensures]` survey as `unknown` regardless of the trust-wp result.
/// SOUND: only the obligation's *kind label* changes; the violation formula is
/// still reconstructed from the obligation's own payload (or the fail-closed
/// `Bool(false)` placeholder → vacuity gate → Unknown), so no proof is fabricated.
fn native_contract_vc_kind(obligation: &trust_verifier_api::TrustObligation) -> Option<VcKind> {
    match &obligation.kind {
        trust_verifier_api::ObligationKind::Postcondition => Some(VcKind::Postcondition),
        // Trust (#5-PRE-A): reconstruct a CALL-SITE PRECONDITION obligation with its real
        // `VcKind::Precondition` kind (not the `UnsupportedMir` fallthrough below).
        // Without this the full-lane legacy VC for `obligation:caller:precondition:0` was
        // re-labeled `VcKind::UnsupportedMir{FullVerification::Precondition}`, so (a) the
        // in-process ay backend could not `can_handle` it (its formula was never solved ->
        // permanent Unknown, even for an ESTABLISHED constant precondition), and (b) the
        // `build_proof_results` fail-closed reclassify (which keys on
        // `VcKind::Precondition`) never fired. Recovering the real kind lets the ay
        // re-solve decide the recovered violation formula — PROVE `!(5<10)` UNSAT for an
        // established precondition, REFUTE `i>=4` SAT for a violated one — and lets the
        // reclassify fail-close a genuinely-undischarged call-site precondition.
        //
        // CRITICAL SCOPING: this must apply ONLY to a CALL-SITE precondition (a call THIS
        // function makes, which it must discharge), NEVER to the callee's OWN
        // definition-site `#[requires]`, which is an ASSUMPTION the function is entitled to
        // make (it is discharged by ITS callers, `generate_callsite_precondition_vcs`), not
        // an obligation it must prove. The two are distinguished by `contract_id`: a
        // call-site precondition is emitted as a VC obligation with `contract_id: None`
        // (obligation id `vc:<fn>:precondition:<i>`, carrying `trust.vc.formula.payload`);
        // the def-site marker is built from the function's own `bundle.contracts` with
        // `contract_id: Some(..)` (origin `Contract`). Reconstructing the def-site marker
        // as a fail-closable Precondition would falsely fail EVERY contracted function on
        // its own entry assumption. So gate on `contract_id.is_none()`; a def-site marker
        // (`Some`) keeps the benign UnsupportedMir fallthrough (a non-fatal coverage gap,
        // exactly as before this change). The `callee` name is diagnostic only.
        trust_verifier_api::ObligationKind::Precondition if obligation.contract_id.is_none() => {
            Some(VcKind::Precondition { callee: obligation.description.clone() })
        }
        // Trust: reconstruct the temporal VcKind from the transported model
        // metadata (`trust.ty.temporal_model`, the exact VcKind the producer
        // emitted). Without this the temporal obligation's legacy VC falls
        // through to `UnsupportedMir`, so it displays under a neighboring
        // same-span obligation's label instead of `[temporal]` after the
        // bridge's location re-key, and the temporal-family re-key/bridge
        // exclusions (which key on the VcKind) can't recognize it. Recovering
        // the real kind makes the ty engine's verdict display and account as
        // temporal, and lets those exclusions self-apply.
        trust_verifier_api::ObligationKind::TemporalSafety
        | trust_verifier_api::ObligationKind::Liveness => {
            let value = api_obligation_metadata_value(
                obligation,
                trust_types::TY_TEMPORAL_MODEL_METADATA_KEY,
            )?;
            trust_types::TyTemporalModelPayload::from_metadata_value(value)
                .ok()
                .map(|payload| payload.vc_kind)
        }
        _ => None,
    }
}

fn legacy_unsupported_kind_detail(
    obligation: &trust_verifier_api::TrustObligation,
) -> (String, String) {
    let kind = match &obligation.kind {
        trust_verifier_api::ObligationKind::Custom { namespace, name } => {
            format!("FullVerification::{namespace}::{name}")
        }
        kind => format!("FullVerification::{kind:?}"),
    };

    let mut detail = obligation.description.clone();
    if let Some(contract_id) = &obligation.contract_id {
        detail.push_str(&format!("; contract_id={contract_id}"));
    }
    // Trust: obligation metadata can hold multi-KB SMT-LIB2 + JSON payloads. Emitting
    // those as part of the diagnostic message explodes compile logs (we saw 10GB+ during
    // stage 2). Surface just the metadata key names here; the full payload belongs in a
    // structured sidecar, tracked in Task #27.
    if !obligation.metadata.is_empty() {
        let keys = obligation
            .metadata
            .iter()
            .map(|entry| entry.key.as_str())
            .collect::<Vec<_>>()
            .join(",");
        detail.push_str(&format!("; metadata_keys=[{keys}]"));
    }

    (kind, detail)
}

fn source_span_from_api_location(location: &trust_verifier_api::SourceLocation) -> SourceSpan {
    SourceSpan {
        file: location.file.clone().unwrap_or_default(),
        line_start: location.line.unwrap_or_default(),
        col_start: location.column.unwrap_or_default(),
        line_end: location.end_line.unwrap_or_else(|| location.line.unwrap_or_default()),
        col_end: location.end_column.unwrap_or_else(|| location.column.unwrap_or_default()),
    }
}

fn legacy_result_from_api_evidence(
    evidence: &trust_verifier_api::ObligationEvidence,
) -> VerificationResult {
    match evidence.status {
        trust_verifier_api::EvidenceStatus::Proved => {
            if !evidence.is_unbounded_proof() {
                return VerificationResult::Unknown {
                    solver: trust_types::Symbol::intern(&evidence.engine.name),
                    time_ms: 0,
                    reason: format!(
                        "native full verifier proof evidence is not publication grade or lacks required artifacts: {:?}",
                        evidence.proof_strength
                    ),
                };
            }
            let Some(strength) = evidence.proof_strength.as_ref() else {
                return VerificationResult::Unknown {
                    solver: trust_types::Symbol::intern(&evidence.engine.name),
                    time_ms: 0,
                    reason: "native full verifier proved obligation without proof strength"
                        .to_string(),
                };
            };
            let Some(strength) = legacy_proof_strength(strength) else {
                return VerificationResult::Unknown {
                    solver: trust_types::Symbol::intern(&evidence.engine.name),
                    time_ms: 0,
                    reason: format!(
                        "native full verifier proof strength is not representable by compiler summary: {:?}",
                        strength
                    ),
                };
            };
            VerificationResult::Proved {
                solver: trust_types::Symbol::intern(&evidence.engine.name),
                time_ms: 0,
                strength,
                proof_certificate: None,
                solver_warnings: (!evidence.diagnostics.is_empty())
                    .then(|| evidence.diagnostics.clone()),
                native_proof_envelope: None,
            }
        }
        trust_verifier_api::EvidenceStatus::Failed => VerificationResult::Failed {
            solver: trust_types::Symbol::intern(&evidence.engine.name),
            time_ms: 0,
            counterexample: evidence
                .counterexample
                .as_ref()
                .map(legacy_counterexample_from_api_evidence),
        },
        // `ObligationEvidence` carries no duration, so this conversion has no
        // honest per-row number of its own: the `0` is a PLACEHOLDER, not a
        // measurement. The production full-verification path immediately
        // re-stamps every row whose evidence attributes the lapse to the
        // per-function wall-clock budget with the resolved
        // `-Ztrust-verify-function-budget-ms` value
        // (`stamp_function_budget_on_evidence_timeouts`), so the strict
        // classifier's "timed out after {N}ms" names the budget that actually
        // expired instead of claiming `0ms`. An engine-internal timeout (no
        // budget attribution in the evidence diagnostics) keeps the
        // placeholder — no duration exists anywhere on this path for it.
        trust_verifier_api::EvidenceStatus::Timeout => VerificationResult::Timeout {
            solver: trust_types::Symbol::intern(&evidence.engine.name),
            timeout_ms: 0,
        },
        trust_verifier_api::EvidenceStatus::Unknown
        | trust_verifier_api::EvidenceStatus::Canceled
        | trust_verifier_api::EvidenceStatus::Unsupported => VerificationResult::Unknown {
            solver: trust_types::Symbol::intern(&evidence.engine.name),
            time_ms: 0,
            reason: evidence_unknown_reason(evidence),
        },
        _ => VerificationResult::Unknown {
            solver: trust_types::Symbol::intern(&evidence.engine.name),
            time_ms: 0,
            reason: evidence_unknown_reason(evidence),
        },
    }
}

/// Trust ('0ms' timeout honesty): re-stamp the resolved per-function
/// wall-clock budget onto full-lane `Timeout` rows whose evidence attributes
/// the lapse to that budget.
///
/// `legacy_result_from_api_evidence` converts `EvidenceStatus::Timeout` to
/// `Timeout { timeout_ms: 0 }` because `ObligationEvidence` carries no
/// duration — and the strict classifier then reported a real budget lapse as
/// "timed out after 0ms". The timeout that actually fired for those rows is
/// the per-function budget (`-Ztrust-verify-function-budget-ms`, resolved by
/// `verify_fn_deadline` from the same tracked option read here). Every
/// budget-lapse producer stamps a "wall-clock budget" diagnostic on its
/// evidence (the trust-router engine acceptance sites and trust-bmc's
/// `budget_timeout_evidence`), which is the attribution gate used below.
///
/// Deliberately narrow (this is message honesty, not a verdict change):
/// - only `Timeout` rows still carrying the `0` placeholder are touched — a
///   real measured duration, should one ever appear, is never overwritten;
/// - rows whose evidence lacks the budget attribution keep the placeholder —
///   an engine-internal timeout's true duration is unknown at this seam and
///   stamping the function budget on it would be a fresh lie;
/// - a disabled budget (`0` = no deadline, so no budget-lapse evidence can
///   exist) stamps nothing.
fn stamp_function_budget_on_evidence_timeouts(
    function_budget_ms: u64,
    run: &trust_verifier_api::VerificationRunResult,
    result_bindings: &[Option<ResultObligationBinding>],
    results: &mut [(VerificationCondition, VerificationResult)],
) {
    if function_budget_ms == 0 {
        return;
    }
    let index = build_full_verification_evidence_index(run);
    for (row_index, (_, result)) in results.iter_mut().enumerate() {
        let VerificationResult::Timeout { timeout_ms, .. } = result else {
            continue;
        };
        if *timeout_ms != 0 {
            continue;
        }
        let Some(binding) = result_bindings.get(row_index).and_then(Option::as_ref) else {
            continue;
        };
        let attributed_to_budget = index
            .evidence_by_obligation_id
            .get(binding.public_obligation_id.as_str())
            .is_some_and(|evidence| {
                evidence.status == trust_verifier_api::EvidenceStatus::Timeout
                    && evidence
                        .diagnostics
                        .iter()
                        .any(|diagnostic| diagnostic.contains("wall-clock budget"))
            });
        if attributed_to_budget {
            *timeout_ms = function_budget_ms;
        }
    }
}

fn legacy_counterexample_from_api_evidence(
    counterexample: &trust_verifier_api::Counterexample,
) -> Counterexample {
    let assignments = counterexample
        .data
        .get("assignments")
        .and_then(serde_json::Value::as_array)
        .map(|assignments| {
            assignments
                .iter()
                .filter_map(legacy_counterexample_assignment_from_json)
                .collect::<Vec<_>>()
        })
        .filter(|assignments| !assignments.is_empty())
        .unwrap_or_else(|| {
            vec![("verified_counterexample".to_string(), CounterexampleValue::Bool(true))]
        });
    Counterexample::new(assignments)
}

fn legacy_counterexample_assignment_from_json(
    value: &serde_json::Value,
) -> Option<(String, CounterexampleValue)> {
    if let Some(items) = value.as_array() {
        let [name, raw_value] = items.as_slice() else { return None };
        return Some((
            name.as_str()?.to_string(),
            legacy_counterexample_value_from_json(raw_value)?,
        ));
    }

    let object = value.as_object()?;
    let name = object.get("name").and_then(serde_json::Value::as_str)?.to_string();
    let raw_value = object.get("value")?;
    Some((name, legacy_counterexample_value_from_json(raw_value)?))
}

fn legacy_counterexample_value_from_json(value: &serde_json::Value) -> Option<CounterexampleValue> {
    if let Some(value) = value.as_bool() {
        return Some(CounterexampleValue::Bool(value));
    }
    if let Some(value) = value.as_i64() {
        return Some(CounterexampleValue::Int(i128::from(value)));
    }
    if let Some(value) = value.as_u64() {
        return Some(CounterexampleValue::Uint(u128::from(value)));
    }
    if let Some(value) = value.as_f64() {
        return Some(CounterexampleValue::Float(value));
    }
    if let Some(value) = value.as_str() {
        if value.eq_ignore_ascii_case("true") {
            return Some(CounterexampleValue::Bool(true));
        }
        if value.eq_ignore_ascii_case("false") {
            return Some(CounterexampleValue::Bool(false));
        }
        if let Ok(parsed) = value.parse::<i128>() {
            return Some(CounterexampleValue::Int(parsed));
        }
    }
    None
}

fn evidence_unknown_reason(evidence: &trust_verifier_api::ObligationEvidence) -> String {
    if evidence.diagnostics.is_empty() {
        return format!("native full verifier evidence status: {:?}", evidence.status);
    }

    format!(
        "native full verifier evidence status: {:?}; {}",
        evidence.status,
        evidence.diagnostics.join("; ")
    )
}

fn legacy_proof_strength(strength: &trust_verifier_api::ProofStrength) -> Option<ProofStrength> {
    let legacy = match &strength.reasoning {
        trust_verifier_api::ReasoningKind::Smt => ProofStrength::smt_unsat(),
        trust_verifier_api::ReasoningKind::BoundedModelCheck { depth } => {
            ProofStrength::bounded(*depth)
        }
        trust_verifier_api::ReasoningKind::Inductive => ProofStrength::inductive(),
        trust_verifier_api::ReasoningKind::Deductive => ProofStrength::deductive(),
        trust_verifier_api::ReasoningKind::Constructive => ProofStrength::constructive(),
        trust_verifier_api::ReasoningKind::Pdr => ProofStrength::pdr(),
        trust_verifier_api::ReasoningKind::Chc => ProofStrength::chc_spacer(),
        trust_verifier_api::ReasoningKind::AbstractInterpretation => {
            ProofStrength::abstract_interpretation()
        }
        trust_verifier_api::ReasoningKind::OwnershipAnalysis => ProofStrength {
            reasoning: ReasoningKind::OwnershipAnalysis,
            assurance: trust_types::AssuranceLevel::Sound,
        },
        trust_verifier_api::ReasoningKind::ExplicitStateModel => ProofStrength {
            reasoning: ReasoningKind::ExplicitStateModel,
            assurance: trust_types::AssuranceLevel::Sound,
        },
        trust_verifier_api::ReasoningKind::TemporalModelCheck
        | trust_verifier_api::ReasoningKind::ProofCalculus => return None,
        _ => return None,
    };
    Some(legacy)
}

fn effective_max_level(
    sess: &Session,
    func: &trust_types::VerifiableFunction,
) -> trust_types::ProofLevel {
    let configured = match sess.opts.unstable_opts.trust_verify_level {
        0 => trust_types::ProofLevel::L0Safety,
        1 => trust_types::ProofLevel::L1Functional,
        _ => trust_types::ProofLevel::L2Domain,
    };

    if !func.contracts.is_empty()
        || !func.preconditions.is_empty()
        || !func.postconditions.is_empty()
    {
        configured.max(trust_types::ProofLevel::L1Functional)
    } else {
        configured
    }
}

/// Trust: Report verification results using rustc's diagnostic system.
///
/// Emits rich diagnostics with file/line numbers and code snippets via
/// `body.span`. All verification results are emitted as notes (informational)
/// so they never trigger -D warnings or break builds. Verification is additive.
///
/// Takes paired (VC, result) tuples from trust-router. In the future, results
/// will also flow through tcx.trust_proof_results() query and be consumed by
/// codegen (for check elision) and by trust-report (for JSON/HTML output).
/// Trust: maximum number of *distinct* non-proved reason strings listed in the
/// aggregated per-item verification summary. Without this cap (and the
/// deduplication that feeds it) a single generic item with ~10^5 obligations
/// emitted millions of identical span-notes — see the log-batching rewrite of
/// `report_results`.
const MAX_REPORTED_REASONS: usize = 5;

fn report_results(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
    certified: usize,
) {
    if results.is_empty() {
        return;
    }

    // Trust: print the header once per Session, including when a rustc_driver
    // process compiles multiple crates. The typed session cell synchronizes
    // parallel MIR workers without suppressing later invocations' headers.
    let print_header = tcx.sess.with_trust_compiler_state::<SessionReportState, _>(|state| {
        !std::mem::replace(&mut state.header_printed, true)
    });
    if print_header {
        let crate_name = tcx.crate_name(LOCAL_CRATE);
        eprintln!();
        eprintln!("=== Trust Verification Report ({crate_name}) ===");
        eprintln!();
    }

    // Trust: Use body.span for rich diagnostics — rustc will render file:line:col
    // and code snippets automatically.
    let func_span = body.span;

    // Trust #log-batching: aggregate per item. Previously this loop emitted one
    // rendered span-note *per obligation*; because each note re-renders
    // `body.span` (file/line + source snippet), a single generic item with ~10^5
    // obligations produced millions of log lines. We now tally outcomes and emit
    // a single summary note per item, with deduplicated reason strings (capped at
    // MAX_REPORTED_REASONS) so identical results collapse into one line + count.
    let mut proved = 0usize;
    let mut failed = 0usize;
    let mut unknown = 0usize;
    let mut timeout = 0usize;
    let mut runtime_checked = 0usize;
    let mut other = 0usize;
    let mut reasons: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();

    for (index, (vc, result)) in results.iter().enumerate() {
        let tag = format_vc_kind(&vc.kind);
        let binding = result_bindings.get(index).and_then(Option::as_ref);
        let authority = proof_authorities.get(index).and_then(Option::as_ref);
        match result {
            // A public `Proved` label is counted only when the exact private
            // authority binds this row, VC, and current obligation payload.
            // Per-obligation attribution is available through the structured
            // `-Z trust-verify-output=json` surface; there is no ambient
            // diagnostic environment-variable bypass.
            VerificationResult::Proved { solver, .. }
                if authority.is_some_and(|authority| {
                    authority.permits_static_proved_transport_for(index, vc, result, binding)
                }) =>
            {
                proved += 1;
                // This observability line is derived exclusively from the
                // already-accepted private authority variant. It neither
                // creates authority nor changes the result/evidence grade.
                // Keeping it in the ordinary report lets production UI tests
                // distinguish receipt consumption from a generic Proved
                // label or from public native attribution metadata.
                if matches!(authority, Some(ResultProofAuthority::BodyBoundNativeReplay { .. })) {
                    *reasons
                        .entry(format!(
                            "[{tag}] PROVED ({solver}): private compiler-finalized body-bound native replay receipt accepted"
                        ))
                        .or_insert(0) += 1;
                }
                // The certified sibling reports separately on purpose: the two
                // rows pass for different reasons, and a reader must be able to
                // tell a kernel-rechecked postcondition from one that rests on
                // the adapter's answer.
                if matches!(authority, Some(ResultProofAuthority::BodyBoundKernelCertified { .. }))
                {
                    *reasons
                        .entry(format!(
                            "[{tag}] PROVED ({solver}): body-bound ensures re-derived and kernel-checked by trust-certify"
                        ))
                        .or_insert(0) += 1;
                }
            }
            VerificationResult::Proved { .. }
                if authority.is_some_and(|authority| {
                    authority.is_definition_entry_assumption_for(index, vc, binding)
                }) =>
            {
                // Conditional bookkeeping is intentionally reported apart
                // from the generic static-proof arm. It has no proof strength,
                // cannot seed codegen or panic/dynamic summaries, and remains
                // valid only under the function's exact `requires` contract.
                proved += 1;
                *reasons.entry(format!("[{tag}] {TRUST_ENTRY_ASSUMPTION_REASON}")).or_insert(0) +=
                    1;
            }
            VerificationResult::Proved { solver, .. } => {
                // A public Proved label is not proof authority. Keep the human
                // diagnostic consistent with proof results and JSON transport:
                // missing/misaligned exact authority fails closed.
                if has_runtime_check(tcx.sess, &vc.kind) {
                    runtime_checked += 1;
                    *reasons
                        .entry(format!(
                            "[{tag}] runtime-checked: solver {solver} reported Proved without exact kernel/native proof authority"
                        ))
                        .or_insert(0) += 1;
                } else {
                    unknown += 1;
                    *reasons
                        .entry(format!(
                            "[{tag}] UNKNOWN ({solver}): Proved label lacked exact kernel/native proof authority"
                        ))
                        .or_insert(0) += 1;
                }
            }
            VerificationResult::Failed { solver, counterexample, .. } => {
                failed += 1;
                let cex = counterexample
                    .as_ref()
                    .map(|c| format!("; counterexample: {c}"))
                    .unwrap_or_default();
                *reasons.entry(format!("[{tag}] FAILED ({solver}){cex}")).or_insert(0) += 1;
            }
            VerificationResult::Unknown { solver, reason, .. } => {
                if has_runtime_check(tcx.sess, &vc.kind) {
                    runtime_checked += 1;
                    *reasons
                        .entry(format!("[{tag}] runtime-checked: {}", runtime_check_note(&vc.kind)))
                        .or_insert(0) += 1;
                } else {
                    unknown += 1;
                    *reasons.entry(format!("[{tag}] UNKNOWN ({solver}): {reason}")).or_insert(0) +=
                        1;
                }
            }
            VerificationResult::Timeout { solver, .. } => {
                if has_runtime_check(tcx.sess, &vc.kind) {
                    runtime_checked += 1;
                    *reasons
                        .entry(format!("[{tag}] runtime-checked: {}", runtime_check_note(&vc.kind)))
                        .or_insert(0) += 1;
                } else {
                    timeout += 1;
                    *reasons.entry(format!("[{tag}] TIMEOUT ({solver})")).or_insert(0) += 1;
                }
            }
            _ => {
                other += 1;
                *reasons
                    .entry(format!("[{tag}] unsupported verification result variant"))
                    .or_insert(0) += 1;
            }
        }
    }

    let mut summary = format!(
        "Trust verification: {proved} proved, {failed} failed, {unknown} unknown, \
         {timeout} timed out, {runtime_checked} runtime-checked",
    );
    if other > 0 {
        summary.push_str(&format!(", {other} other"));
    }
    summary.push_str(&format!(" out of {} obligation(s)", results.len()));

    // Trust: All results are notes — verification is additive and must NEVER
    // break builds.
    let mut diag = tcx.dcx().struct_span_note(func_span, summary);
    // Trust: surface clean's kernel-certified tier by default. A `Certified`
    // obligation was re-proved and RE-CHECKED by the clean CIC kernel with ZERO
    // trust in the SMT solver (the de Bruijn criterion), so the solver is outside
    // the trusted base. This is a strictly stronger guarantee than `proved`
    // (solver-trusted), so we report it explicitly when present. Runtime-check
    // elision remains disabled until this proof also carries exact MIR-Assert
    // identity.
    if certified > 0 {
        diag.note(format!(
            "of which {certified} kernel-certified by the clean CIC kernel \
             (zero-trust re-check; runtime-check elision requires exact MIR Assert identity)"
        ));
    }
    for (reason, count) in reasons.iter().take(MAX_REPORTED_REASONS) {
        if *count > 1 {
            diag.note(format!("{count}× {reason}"));
        } else {
            diag.note(reason.clone());
        }
    }
    if reasons.len() > MAX_REPORTED_REASONS {
        diag.note(format!(
            "… and {} more distinct reason(s) suppressed (log batching)",
            reasons.len() - MAX_REPORTED_REASONS,
        ));
    }
    diag.emit();
}

fn report_transport_results(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    results: &[TransportObligationResult],
    cached: u32,
) {
    if results.is_empty() {
        return;
    }
    let func_span = body.span;

    // Trust #log-batching: aggregate transport-obligation results into a single
    // per-item note (outcome counts + deduplicated reasons) instead of one
    // rendered span-note per obligation.
    let mut outcomes: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    let mut reasons: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    for result in results {
        let outcome = result.outcome.as_str().to_ascii_uppercase().replace('_', "-");
        *outcomes.entry(outcome).or_insert(0) += 1;
        if let Some(reason) = &result.reason {
            *reasons.entry(format!("[{}] {reason}", result.kind)).or_insert(0) += 1;
        }
    }

    let outcome_summary = outcomes
        .iter()
        .map(|(outcome, count)| format!("{count} {outcome}"))
        .collect::<Vec<_>>()
        .join(", ");
    let mut diag = tcx.dcx().struct_span_note(
        func_span,
        format!(
            "Trust transport verification: {outcome_summary} out of {} obligation(s)",
            results.len()
        ),
    );
    // Trust (verify-cache increment 4): surface cache-replayed obligations as an
    // honest distinct signal instead of leaving them buried in the conservative
    // `UNKNOWN` transport rows. This reads the authoritative `cached` summary
    // count — it does NOT relabel the cross-boundary transport rows, which stay
    // conservatively `unknown` by design (non-evidentiary fail-safe).
    if cached > 0 {
        diag.note(format!(
            "{cached} obligation(s) replayed from the verification cache: proved earlier by this \
             trustc on byte-identical inputs (sound-key hit) and unchanged since, so \
             re-verification was skipped this run (reported conservatively as `unknown` above)"
        ));
    }
    for (reason, count) in reasons.iter().take(MAX_REPORTED_REASONS) {
        if *count > 1 {
            diag.note(format!("{count}× {reason}"));
        } else {
            diag.note(reason.clone());
        }
    }
    if reasons.len() > MAX_REPORTED_REASONS {
        diag.note(format!(
            "… and {} more distinct reason(s) suppressed (log batching)",
            reasons.len() - MAX_REPORTED_REASONS,
        ));
    }
    diag.emit();
}

fn build_transport_results(
    sess: &Session,
    results: &[(VerificationCondition, VerificationResult)],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    // Trust (M-Pkg perf): precomputed per-obligation kernel certification
    // (`certify_all`), index-aligned with `results`. `None` falls back to
    // running `certify_vc` per obligation (used by unit tests that don't
    // precompute); production callers pass `Some(&cleancic)`.
    cleancic: Option<&[Option<trust_ir::ProofEvidence>]>,
) -> Vec<TransportObligationResult> {
    let target = verification_target_key(sess);
    build_transport_results_with_runtime_checks_for_target(
        sess.overflow_checks(),
        Some(&target),
        results,
        full_verification,
        cleancic,
    )
}

fn build_transport_results_bound(
    sess: &Session,
    results: &[(VerificationCondition, VerificationResult)],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    cleancic: &[Option<trust_ir::ProofEvidence>],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> Vec<TransportObligationResult> {
    let target = verification_target_key(sess);
    build_transport_results_with_runtime_checks_bound(
        sess.overflow_checks(),
        Some(&target),
        results,
        full_verification,
        cleancic,
        result_bindings,
        proof_authorities,
    )
}

#[cfg(test)]
fn build_transport_results_with_runtime_checks(
    overflow_checks: bool,
    results: &[(VerificationCondition, VerificationResult)],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    cleancic: Option<&[Option<trust_ir::ProofEvidence>]>,
) -> Vec<TransportObligationResult> {
    build_transport_results_with_runtime_checks_for_target(
        overflow_checks,
        None,
        results,
        full_verification,
        cleancic,
    )
}

fn build_transport_results_with_runtime_checks_for_target(
    overflow_checks: bool,
    target: Option<&str>,
    results: &[(VerificationCondition, VerificationResult)],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    cleancic: Option<&[Option<trust_ir::ProofEvidence>]>,
) -> Vec<TransportObligationResult> {
    let computed;
    let cleancic = match cleancic {
        Some(cleancic) => cleancic,
        None => {
            computed = certify_all(results, None);
            &computed
        }
    };
    // Without a row binding, a full-run envelope cannot authorize any row.
    // Kernel evidence remains exact because `cleancic` is index-aligned.
    let proof_authorities = build_result_proof_authorities(results, &[], None, cleancic);
    build_transport_results_with_runtime_checks_bound(
        overflow_checks,
        target,
        results,
        full_verification,
        cleancic,
        &[],
        &proof_authorities,
    )
}

fn build_transport_results_with_runtime_checks_bound(
    overflow_checks: bool,
    target: Option<&str>,
    results: &[(VerificationCondition, VerificationResult)],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    _cleancic: &[Option<trust_ir::ProofEvidence>],
    result_bindings: &[Option<ResultObligationBinding>],
    proof_authorities: &[Option<ResultProofAuthority>],
) -> Vec<TransportObligationResult> {
    let full_index = full_verification.map(build_full_verification_transport_index);
    let live_run_validation = full_verification
        .map(|run| build_live_authority_run_validation_cache(proof_authorities, run));
    let mut rows: Vec<TransportObligationResult> = results
        .iter()
        .enumerate()
        .map(|(index, (vc, result))| {
            let tag = format_vc_kind(&vc.kind).to_string();
            let desc = vc.kind.description();
            let raw_binding = result_bindings.get(index).and_then(Option::as_ref);
            let row_binding = raw_binding.filter(|binding| binding.matches_row(index, vc));
            // Validate the private token once before *any* transport consumer,
            // including evidence attachment. Checking only the outcome arm
            // still let a moved native-evidence token select and attach its
            // old evidence row to a runtime-checked neighbor.
            let candidate_authority =
                proof_authorities.get(index).and_then(Option::as_ref).filter(|authority| {
                    authority.matches_row(index, vc, row_binding)
                        && authority.matches_compiler_result(result)
                        && live_authority_run_is_valid(authority, live_run_validation.as_ref())
                });
            let candidate_definition_entry_assumption =
                candidate_authority.is_some_and(|authority| {
                    authority.is_definition_entry_assumption_for(index, vc, row_binding)
                });
            let candidate_assumed_total_assumption = candidate_authority.is_some_and(|authority| {
                authority.is_assumed_total_callee_assumption_for(index, vc, row_binding)
            });
            let candidate_catalog_assumption =
                candidate_definition_entry_assumption || candidate_assumed_total_assumption;
            // A private row token is not enough when a full-verifier carrier
            // was returned: the one unique public obligation at that ID must
            // still be byte-for-byte identical to the compiler-sealed
            // obligation. Otherwise the row is an attempted native binding,
            // not a legacy row, and every authority-bearing transport field
            // must fail closed. Catalog-only definition-entry assumptions are
            // intentionally absent from the request carrier, but an ambiguous
            // duplicate ID is never equivalent to absence.
            let binding = row_binding.filter(|binding| {
                full_index.as_ref().is_none_or(|full_index| {
                    !full_index
                        .ambiguous_requested_ids
                        .contains(binding.public_obligation_id.as_str())
                        && if candidate_catalog_assumption {
                            full_index
                                .requested_by_id
                                .get(binding.public_obligation_id.as_str())
                                .is_none_or(|obligation| {
                                    binding.matches_public_obligation(obligation)
                                })
                        } else {
                            full_index
                                .requested_by_id
                                .get(binding.public_obligation_id.as_str())
                                .is_some_and(|obligation| {
                                    binding.matches_public_obligation(obligation)
                                })
                        }
                })
            });
            let invalid_binding_attempt = raw_binding.is_some() && binding.is_none();
            let authority = candidate_authority.filter(|_| !invalid_binding_attempt);
            let definition_entry_assumption = authority.is_some_and(|authority| {
                authority.is_definition_entry_assumption_for(index, vc, binding)
            });
            let assumed_total_assumption = authority.is_some_and(|authority| {
                authority.is_assumed_total_callee_assumption_for(index, vc, binding)
            });
            let runtime_fallback = runtime_check_available(&vc.kind, overflow_checks);
            let (mut outcome, solver, time_ms, counterexample, counterexample_model, mut reason) =
                match result {
                    VerificationResult::Proved { solver, time_ms, .. }
                        if authority.is_some_and(|authority| {
                            authority
                                .permits_static_proved_transport_for(index, vc, result, binding)
                        }) =>
                    {
                        (Outcome::Proved, solver.to_string(), *time_ms, None, None, None)
                    }
                    VerificationResult::Proved { solver, time_ms, .. }
                        if definition_entry_assumption =>
                    {
                        (
                            Outcome::Skipped,
                            solver.to_string(),
                            *time_ms,
                            None,
                            None,
                            Some(TRUST_ENTRY_ASSUMPTION_REASON.to_string()),
                        )
                    }
                    VerificationResult::Proved { solver, time_ms, .. }
                        if assumed_total_assumption =>
                    {
                        (
                            Outcome::Skipped,
                            solver.to_string(),
                            *time_ms,
                            None,
                            None,
                            Some(TRUST_ASSUMED_TOTAL_REASON.to_string()),
                        )
                    }
                    VerificationResult::Proved { solver, time_ms, .. } => {
                        let outcome = if runtime_fallback {
                            Outcome::RuntimeChecked
                        } else {
                            Outcome::Unknown
                        };
                        (
                            outcome,
                            solver.to_string(),
                            *time_ms,
                            None,
                            None,
                            Some(
                                "solver reported Proved without exact kernel/native proof authority"
                                    .to_string(),
                            ),
                        )
                    }
                    VerificationResult::Failed { solver, time_ms, counterexample } => {
                        let cex_str = counterexample.as_ref().map(|c| c.to_string());
                        (
                            Outcome::Failed,
                            solver.to_string(),
                            *time_ms,
                            cex_str,
                            counterexample.clone(),
                            None,
                        )
                    }
                    VerificationResult::Unknown { solver, time_ms, reason } => {
                        let outcome = if runtime_fallback {
                            Outcome::RuntimeChecked
                        } else {
                            Outcome::Unknown
                        };
                        (outcome, solver.to_string(), *time_ms, None, None, Some(reason.clone()))
                    }
                    VerificationResult::Timeout { solver, timeout_ms } => {
                        let outcome = if runtime_fallback {
                            Outcome::RuntimeChecked
                        } else {
                            Outcome::Timeout
                        };
                        (
                            outcome,
                            solver.to_string(),
                            *timeout_ms,
                            None,
                            None,
                            Some("solver timed out".to_string()),
                        )
                    }
                    _ => (
                        Outcome::Unknown,
                        result.solver_name().to_string(),
                        result.time_ms(),
                        None,
                        None,
                        Some("unsupported verification result variant".to_string()),
                    ),
                };
            fail_closed_unsupported_mir_transport_outcome(&vc.kind, &mut outcome, &mut reason);
            let mut transport = TransportObligationResult {
                // Monitor status comes only from the private binding minted
                // from the original compiler-stamped bundle. Exact row sealing
                // prevents a moved/reordered binding from donating execution
                // evidence to a neighboring obligation.
                monitor: binding
                    .and_then(|binding| binding.monitor_evidence_for(index, vc))
                    .cloned(),
                // A catalog-only definition-entry assumption has no requested
                // evidence row for the generic attachment path below. Retain
                // its exact compiler-sealed public ID directly from the private
                // row binding so transport stays traceable without pretending
                // the assumption was proved or dispatched.
                obligation_id: (definition_entry_assumption || assumed_total_assumption)
                    .then(|| binding.map(|binding| binding.public_obligation_id.clone()))
                    .flatten(),
                claim_digest_sha256: exact_vc_claim_digest_sha256(vc, overflow_checks, target),
                kind: if definition_entry_assumption {
                    TRUST_ENTRY_ASSUMPTION_TRANSPORT_KIND.to_string()
                } else if assumed_total_assumption {
                    format!(
                        "assumption:{}",
                        trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_TAG
                    )
                } else {
                    tag
                },
                // Trust: carry the producer's exact typed VC classification so
                // consumers need not re-derive parameterized families from the
                // lossy compact tag. An assumption row (definition-entry or
                // assumed-total) transports a synthetic `assumption:*`
                // classification, not the VC's own kind, so it deliberately
                // carries no typed kind — same rule as the assumption rewrites
                // below, which clear `typed_kind` whenever `kind` is rewritten
                // to a synthetic classification.
                typed_kind: (!definition_entry_assumption && !assumed_total_assumption)
                    .then(|| Box::new(vc.kind.clone())),
                description: desc,
                location: Some(vc.location.clone()),
                outcome,
                solver,
                time_ms,
                counterexample,
                counterexample_model,
                reason,
                // Trust (hardened evidence gate): the compiler-provided
                // design-mandate bit. A hardened-category VC whose violation
                // formula is the tautology `true` (e.g. "[unsafe] missing
                // SAFETY comment", raw-API migration mandates) is a DESIGN
                // MANDATE, not a discharge target — a tautological violation
                // can never be proved UNSAT. Only the compiler sees the VC
                // formula, so only it may set this; targo uses it to exclude
                // mandate rows from the proof-evidence denominator (keeping
                // them as inventory) instead of guessing from row text.
                design_mandate: vc.kind.hardened_category().is_some()
                    && matches!(vc.formula, Formula::Bool(true)),
                native_trust_ir: None,
                proof_evidence: None,
            };
            if !definition_entry_assumption
                && !assumed_total_assumption
                && let (Some(full_verification), Some(full_index), Some(binding)) =
                    (full_verification, full_index.as_ref(), binding)
            {
                attach_full_verification_transport_evidence(
                    &mut transport,
                    full_verification,
                    full_index,
                    index,
                    vc,
                    result,
                    binding,
                    authority,
                );
            }
            // A kernel token is represented by the exact CleanCic artifact
            // below; an entry assumption has no proof artifact. Do not retain
            // a full-run evidence row for either case (or for an unbound public
            // Proved label). A live body-bound replay receipt carries the exact
            // accepted evidence observed during its in-process dispatch.
            if matches!(result, VerificationResult::Proved { .. })
                && !matches!(
                    authority,
                    Some(
                        ResultProofAuthority::BodyBoundNativeReplay { .. }
                            | ResultProofAuthority::DirectTrustVcLive { .. }
                            | ResultProofAuthority::FreshExactDirectChcPdr { .. }
                    )
                )
            {
                transport.proof_evidence = None;
            }
            // M-Pkg: carry the kernel-checked CleanCic proof term as an evidence
            // artifact so a Certified obligation's report row ships the proof a
            // consumer can independently re-check — the label never out-runs the
            // proof. The private kernel token owns the exact CleanCic payload
            // selected at certification time; transport consumes that payload,
            // never a separately re-indexed evidence vector.
            if let Some(evidence @ trust_ir::ProofEvidence::CleanCic { .. }) =
                authority.and_then(|authority| authority.kernel_evidence_for(index, vc, binding))
            {
                if let Ok(payload) = serde_json::to_value(evidence)
                    && let Ok(bytes) = serde_json::to_vec(&payload)
                {
                    // Trust (hardened evidence gate): content-address the
                    // kernel-checked CleanCic payload. The digest is sha256
                    // over the EXACT serialized bytes of the metadata payload
                    // carried in this same artifact — real, held bytes a
                    // consumer can re-serialize and re-check, never an
                    // invented digest. It is a kernel certificate, not a
                    // solver transcript. Its outer proof identity is the SAME
                    // content address as the artifact identity, binding the
                    // transport envelope to these exact serialized proof
                    // bytes. Downstream publication still re-computes this
                    // identity and applies the strict clean-kernel-only gate.
                    let digest =
                        domain_length_bound_sha256_hex("trustc.transport-clean-cic.v2", &bytes);
                    let proof_id = format!("clean-cic:v2:{digest}");
                    let artifact = trust_types::TransportEvidenceArtifact {
                        kind: "clean_cic".to_string(),
                        format: Some("trust-ir-cleancic-v2".to_string()),
                        artifact_id: Some(proof_id.clone()),
                        digest: Some(trust_types::TransportArtifactDigest {
                            algorithm: "sha256".to_string(),
                            value: digest.clone(),
                        }),
                        uri: Some(format!("trust-certify://clean-cic/{digest}")),
                        materialization: None,
                        metadata: Some(payload),
                    };
                    // The private `KernelCertified` capability is the authority
                    // for both axes. Do not inherit the public solver's
                    // strength: CleanCic is constructive reasoning accepted by
                    // the clean kernel, hence Certified. Derive ProofEvidence
                    // from that same value so the two transport fields cannot
                    // disagree.
                    let strength = ProofStrength {
                        reasoning: ReasoningKind::Constructive,
                        assurance: trust_types::AssuranceLevel::Certified,
                    };
                    let proof_evidence = trust_types::ProofEvidence::from(strength.clone());
                    transport.proof_evidence = Some(trust_types::TransportProofEvidence {
                        suite: "trust-certify".to_string(),
                        backend: "clean-kernel".to_string(),
                        request_id: None,
                        proof_id: Some(proof_id),
                        native_id: None,
                        status: trust_types::TransportProofStatus::Proved,
                        strength: Some(strength),
                        evidence: Some(proof_evidence),
                        artifacts: vec![artifact],
                        diagnostics: Vec::new(),
                    });
                }
            }
            transport
        })
        .collect();
    assign_legacy_transport_obligation_ids(&mut rows, results, result_bindings);
    rows
}

// Trust: STABLE identity for legacy-lane obligation rows.
//
// `obligation_id` is assigned above only inside
// `attach_full_verification_transport_evidence`, which requires a
// `ResultObligationBinding` — i.e. a row the NATIVE full-verification lane
// requested and bound, whose id trust-mir-extract minted as
// `vc:<fn>:<kind-label>:<index>`. A LEGACY-lane row — e.g. the
// `trust-assert-refute` refutation that `refute_full_assert_obligations`
// pushes AFTER the native run, or any v1/vcgen solver-set row produced with
// no native binding — never took that assignment path, so its transport row
// reached consumers with `obligation_id: None` and targo's per-row identity
// gate ("every typed obligation must carry a stable obligation_id") failed.
// Mint the same-shaped DETERMINISTIC id here: `vc:<fn>:<kind-tag>:<ordinal>`
// from the row's own VC identity (function + transport kind tag +
// per-function per-kind ordinal). Row order is the deterministic verification
// pipeline order — never random — so the id is stable across runs.
// A row carrying any private binding attempt is NEVER treated as legacy. A
// valid native binding already received its public ID above; an invalid,
// moved, mutated, or ambiguous binding must retain `None` rather than being
// laundered into a fresh legacy identity. A minted legacy id can never collide
// with an existing or previously-minted one: a taken candidate
// deterministically advances the ordinal, so per-function obligation identity
// stays unique.
fn assign_legacy_transport_obligation_ids(
    rows: &mut [TransportObligationResult],
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
) {
    let mut taken: FxHashSet<String> =
        rows.iter().filter_map(|row| row.obligation_id.clone()).collect();
    let mut next_ordinal: FxHashMap<String, usize> = FxHashMap::default();
    for (index, (row, (vc, _))) in rows.iter_mut().zip(results).enumerate() {
        if row.obligation_id.is_some() || result_bindings.get(index).is_some_and(Option::is_some) {
            continue;
        }
        let function = trust_types::canonical_artifact_id_component(vc.function.as_str());
        let tag = format_vc_kind(&vc.kind);
        let ordinal = next_ordinal.entry(format!("{function}:{tag}")).or_insert(0);
        let id = loop {
            let candidate = format!("vc:{function}:{tag}:{}", *ordinal);
            *ordinal += 1;
            if taken.insert(candidate.clone()) {
                break candidate;
            }
        };
        row.obligation_id = Some(id);
    }
}

/// Enforce the public contract of [`VcKind::UnsupportedMir`] at the final
/// transport boundary. Solver labels and even otherwise-valid private proof
/// authority may be useful diagnostic evidence, but they cannot turn an
/// explicitly unsupported semantic translation into a proof or runtime check.
/// Keeping this guard after outcome selection also catches any future path that
/// accidentally assigns a runtime fallback to this kind.
fn fail_closed_unsupported_mir_transport_outcome(
    kind: &VcKind,
    outcome: &mut Outcome,
    reason: &mut Option<String>,
) {
    if !matches!(kind, VcKind::UnsupportedMir { .. })
        || !matches!(*outcome, Outcome::Proved | Outcome::RuntimeChecked)
    {
        return;
    }

    *outcome = Outcome::Unknown;
    let previous_reason = reason.take();
    *reason = Some(match previous_reason {
        Some(previous) if previous != TRUST_UNSUPPORTED_MIR_TRANSPORT_REASON => {
            format!("{TRUST_UNSUPPORTED_MIR_TRANSPORT_REASON}; producer reason: {previous}")
        }
        _ => TRUST_UNSUPPORTED_MIR_TRANSPORT_REASON.to_string(),
    });
}

// Trust: per-run index shared across every VC's transport-evidence attach.
// Building this once is O(n+m); the prior attach path rescanned all requested
// obligations for every VC and did two nested `.find` scans per hit
// (O(n*m*(e+s))), which hung transport assembly on large generated functions.
type FullVerificationTransportIndex<'a> = FullVerificationEvidenceIndex<'a>;

fn build_full_verification_transport_index(
    full_verification: &trust_verifier_api::VerificationRunResult,
) -> FullVerificationTransportIndex<'_> {
    build_full_verification_evidence_index(full_verification)
}

fn attach_full_verification_transport_evidence(
    transport: &mut TransportObligationResult,
    full_verification: &trust_verifier_api::VerificationRunResult,
    index: &FullVerificationTransportIndex<'_>,
    row_index: usize,
    vc: &VerificationCondition,
    result: &VerificationResult,
    binding: &ResultObligationBinding,
    authority: Option<&ResultProofAuthority>,
) {
    if !binding.matches_row(row_index, vc) {
        return;
    }
    let Some(obligation) =
        index.requested_by_id.get(binding.public_obligation_id.as_str()).copied()
    else {
        return;
    };
    if !binding.matches_public_obligation(obligation) {
        return;
    }
    transport.obligation_id = Some(obligation.obligation_id.clone());

    if matches!(
        authority,
        Some(
            ResultProofAuthority::CallerPropagation { .. }
                | ResultProofAuthority::WholeFunctionPanicFreedomSubsumption { .. }
        )
    ) {
        // Preserve public traceability only. R1's proof is the private sealed
        // certificate, and the panic-freedom subsumption's proof is the
        // compiler-composed conjunction over its premise rows; neither native
        // evidence nor a skipped native row is an honest public proof envelope
        // for either closed-world derivation (the native lane returned
        // Unsupported for the aggregate — attaching that envelope to a proved
        // row would misattribute the proof).
        return;
    }

    let evidence = match authority {
        // Both body-bound lanes hold the same live receipt, so both resolve the
        // native evidence row through it. For the certified sibling the report's
        // proof evidence is overwritten by its kernel certificate downstream;
        // this only fixes the native-TrustIr attribution row.
        Some(
            ResultProofAuthority::BodyBoundNativeReplay { receipt, .. }
            | ResultProofAuthority::BodyBoundKernelCertified { receipt, .. },
        ) => index
            .evidence_by_evidence_id
            .get(receipt.live.evidence.evidence_id.as_str())
            .copied()
            .filter(|evidence| *evidence == &receipt.live.evidence),
        Some(ResultProofAuthority::DirectTrustVcLive { authority }) => index
            .evidence_by_evidence_id
            .get(authority.accepted_evidence.evidence_id.as_str())
            .copied()
            .filter(|evidence| {
                authority.authorizes_row(row_index, vc, Some(binding))
                    && authority.authorizes_compiler_result(result)
                    && evidence.obligation_id == authority.obligation.obligation_id
                    && *evidence == &authority.accepted_evidence
            }),
        Some(ResultProofAuthority::FreshExactDirectChcPdr { authority }) => {
            index.evidence_by_evidence_id.get(authority.evidence_id.as_str()).copied().filter(
                |evidence| {
                    authority.authorizes_row(row_index, vc, Some(binding))
                        && authority.authorizes_compiler_result(result)
                        && evidence.obligation_id == authority.obligation.obligation_id
                        && evidence.evidence_id == authority.evidence_id
                        && evidence.proof_strength.as_ref() == Some(&authority.proof_strength)
                },
            )
        }
        Some(
            ResultProofAuthority::KernelCertified { .. }
            | ResultProofAuthority::ExactSourceClauseDischarge { .. }
            | ResultProofAuthority::EnsuresCitationDischarge { .. }
            | ResultProofAuthority::DefinitionEntryAssumption { .. }
            | ResultProofAuthority::AssumedTotalCalleeAssumption { .. }
            | ResultProofAuthority::SolverRevalidated { .. }
            | ResultProofAuthority::CallerPropagation { .. }
            // Unreachable: both closed-world derivations early-returned above.
            | ResultProofAuthority::WholeFunctionPanicFreedomSubsumption { .. },
        )
        | None => index.evidence_by_obligation_id.get(obligation.obligation_id.as_str()).copied(),
    };
    let skipped = index.skipped_by_id.get(obligation.obligation_id.as_str()).copied();

    transport.native_trust_ir =
        transport_native_trust_ir_evidence(obligation, evidence, skipped, full_verification);
    transport.proof_evidence =
        transport_proof_evidence(obligation, evidence, skipped, full_verification);
}

fn transport_native_trust_ir_evidence(
    obligation: &trust_verifier_api::TrustObligation,
    evidence: Option<&trust_verifier_api::ObligationEvidence>,
    skipped: Option<&trust_verifier_api::SkippedObligation>,
    full_verification: &trust_verifier_api::VerificationRunResult,
) -> Option<TransportNativeTrustIrEvidence> {
    let identity = native_transport_identity(obligation);
    let suite = identity.suite;
    let request_id = identity.request_id;
    let native_id = identity.native_id;
    let _proof_id = identity.proof_id;

    let has_native_identity = suite.is_some() || request_id.is_some() || native_id.is_some();
    let artifacts = evidence.map_or_else(Vec::new, |evidence| {
        evidence
            .artifacts
            .iter()
            .filter(|artifact| artifact.uri.starts_with("trust_ir-native://"))
            .map(transport_evidence_artifact)
            .collect()
    });
    let mut diagnostics = Vec::new();
    if let Some(evidence) = evidence {
        diagnostics.extend(
            evidence.diagnostics.iter().filter(|diagnostic| diagnostic.contains("TrustIr")).map(
                |diagnostic| {
                    transport_diagnostic(
                        "native_trust_ir",
                        TransportEvidenceDiagnosticSeverity::Info,
                        diagnostic,
                    )
                },
            ),
        );
    }
    if let Some(skipped) = skipped {
        diagnostics.push(transport_diagnostic(
            "native_trust_ir_skipped",
            TransportEvidenceDiagnosticSeverity::Warning,
            &format!("native full verifier skipped obligation: {:?}", skipped.reason),
        ));
    }
    let native_transport_status =
        obligation_metadata(obligation, TRUST_TRUST_IR_NATIVE_TRANSPORT_STATUS_METADATA_KEY);
    if let Some(status) = native_transport_status.as_deref() {
        let severity = match status {
            "rejected" | "unsupported" => TransportEvidenceDiagnosticSeverity::Warning,
            _ => TransportEvidenceDiagnosticSeverity::Info,
        };
        diagnostics.push(transport_diagnostic(
            "native_trust_ir_transport_status",
            severity,
            &format!("native TrustIr transport status: {status}"),
        ));
    }
    if let Some(reason) =
        obligation_metadata(obligation, TRUST_TRUST_IR_NATIVE_UNSUPPORTED_REASON_METADATA_KEY)
    {
        let diagnostic_code = match native_transport_status.as_deref() {
            Some("rejected") => "native_trust_ir_rejected",
            _ => "native_trust_ir_unsupported",
        };
        diagnostics.push(transport_diagnostic(
            diagnostic_code,
            TransportEvidenceDiagnosticSeverity::Warning,
            &reason,
        ));
    }
    diagnostics.extend(
        full_verification
            .diagnostics
            .iter()
            .filter(|diagnostic| diagnostic.contains("TrustIr"))
            .map(|diagnostic| {
                transport_diagnostic(
                    "native_trust_ir_run",
                    TransportEvidenceDiagnosticSeverity::Info,
                    diagnostic,
                )
            }),
    );

    if !has_native_identity && artifacts.is_empty() && diagnostics.is_empty() {
        return None;
    }

    let canonical_backend = suite.clone().unwrap_or_else(|| {
        evidence
            .map(|evidence| evidence.engine.name.clone())
            .unwrap_or_else(|| "trust-full-verifier".to_string())
    });
    Some(TransportNativeTrustIrEvidence {
        suite: suite.unwrap_or_else(|| {
            evidence
                .map(|evidence| evidence.engine.name.clone())
                .unwrap_or_else(|| "trust-full-verifier".to_string())
        }),
        backend: canonical_backend,
        request_id,
        native_id,
        present: !artifacts.is_empty(),
        artifacts,
        diagnostics,
    })
}

fn transport_proof_evidence(
    obligation: &trust_verifier_api::TrustObligation,
    evidence: Option<&trust_verifier_api::ObligationEvidence>,
    skipped: Option<&trust_verifier_api::SkippedObligation>,
    full_verification: &trust_verifier_api::VerificationRunResult,
) -> Option<TransportProofEvidence> {
    let identity = native_transport_identity(obligation);
    let suite = identity.suite.unwrap_or_else(|| "trust-full-verifier".to_string());
    let request_id = identity.request_id;
    let proof_id = identity.proof_id;
    let native_id = identity.native_id;

    if let Some(evidence) = evidence {
        let strength = evidence.proof_strength.as_ref().and_then(legacy_proof_strength);
        let mut diagnostics = evidence
            .diagnostics
            .iter()
            .map(|diagnostic| {
                transport_diagnostic(
                    "full_verifier_evidence",
                    TransportEvidenceDiagnosticSeverity::Info,
                    diagnostic,
                )
            })
            .collect::<Vec<_>>();
        diagnostics.push(artifact_policy_diagnostic(evidence));

        return Some(TransportProofEvidence {
            backend: suite.clone(),
            suite,
            request_id,
            proof_id,
            native_id,
            status: transport_proof_status(evidence),
            strength: strength.clone(),
            evidence: strength.map(|strength| {
                trust_types::ProofEvidence::new(strength.reasoning, strength.assurance)
            }),
            artifacts: evidence
                .artifacts
                .iter()
                .filter(|artifact| !artifact.uri.starts_with("trust_ir-native://"))
                .map(transport_evidence_artifact)
                .collect(),
            diagnostics,
        });
    }

    skipped.map(|skipped| {
        let mut diagnostics = vec![transport_diagnostic(
            "full_verifier_skipped",
            TransportEvidenceDiagnosticSeverity::Warning,
            &format!("native full verifier skipped obligation: {:?}", skipped.reason),
        )];
        diagnostics.extend(full_verification.diagnostics.iter().map(|diagnostic| {
            transport_diagnostic(
                "full_verifier_run",
                TransportEvidenceDiagnosticSeverity::Warning,
                diagnostic,
            )
        }));

        TransportProofEvidence {
            suite,
            backend: full_verification.engine.name.clone(),
            request_id,
            proof_id: None,
            native_id,
            status: TransportProofStatus::Unsupported,
            strength: None,
            evidence: None,
            artifacts: Vec::new(),
            diagnostics,
        }
    })
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct NativeTransportIdentity {
    suite: Option<String>,
    request_id: Option<String>,
    proof_id: Option<String>,
    native_id: Option<String>,
}

fn native_transport_identity(
    obligation: &trust_verifier_api::TrustObligation,
) -> NativeTransportIdentity {
    let suite = obligation_metadata(
        obligation,
        trust_router::full_verification::TRUST_TRUST_IR_NATIVE_VERIFIER_SUITE_METADATA_KEY,
    );
    let request_id = obligation_metadata(
        obligation,
        trust_router::full_verification::TRUST_TRUST_IR_NATIVE_REQUEST_ID_METADATA_KEY,
    );
    let proof_id = obligation_metadata(
        obligation,
        trust_router::full_verification::TRUST_TRUST_IR_NATIVE_PROOF_OBLIGATION_ID_METADATA_KEY,
    );
    let native_id = native_trust_ir_canonical_transport_native_id(
        suite.as_deref(),
        request_id.as_deref(),
        proof_id.as_deref(),
    )
    .or_else(|| proof_id.clone());

    NativeTransportIdentity { suite, request_id, proof_id, native_id }
}

fn native_trust_ir_canonical_transport_native_id(
    suite: Option<&str>,
    request_id: Option<&str>,
    proof_obligation_id: Option<&str>,
) -> Option<String> {
    let suite = suite?;
    if !["trust-vc", "trust-wp", "trust-mc"]
        .iter()
        .any(|native_suite| suite.eq_ignore_ascii_case(native_suite))
    {
        return None;
    }
    let request_id = request_id?.parse::<u32>().ok()?;
    let proof_obligation_id = proof_obligation_id?.parse::<u32>().ok()?;
    Some(native_trust_ir_proof_unit_id(suite, request_id, proof_obligation_id))
}

fn native_identity_is_complete_and_canonical(identity: &NativeTransportIdentity) -> bool {
    let (Some(suite), Some(request_id), Some(proof_id), Some(native_id)) = (
        identity.suite.as_deref(),
        identity.request_id.as_deref(),
        identity.proof_id.as_deref(),
        identity.native_id.as_deref(),
    ) else {
        return false;
    };
    native_trust_ir_canonical_transport_native_id(Some(suite), Some(request_id), Some(proof_id))
        .as_deref()
        == Some(native_id)
}

fn solver_revalidation_receipt_matches_row(
    receipt: &SolverRevalidationReceipt,
    index: usize,
    vc: &VerificationCondition,
) -> bool {
    let Some(current_row) = exact_result_row_identity(index, vc) else {
        return false;
    };
    let expected_problem = trust_router::in_process_ay_backend::problem_smt2(&vc.formula);
    receipt.row_index == current_row.index
        && receipt.canonical_vc.as_bytes() == current_row.canonical_vc.as_bytes()
        && receipt.canonical_problem.as_bytes() == expected_problem.as_bytes()
}

/// Mint row authority from evidence the compiler can bind to the exact row.
/// A public result label is consulted only for its outcome; it cannot create an
/// authority token or choose the reported proof strength.
fn build_result_proof_authorities(
    results: &[(VerificationCondition, VerificationResult)],
    bindings: &[Option<ResultObligationBinding>],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    cleancic: &[Option<trust_ir::ProofEvidence>],
) -> Vec<Option<ResultProofAuthority>> {
    build_result_proof_authorities_with_revalidations(
        results,
        bindings,
        full_verification,
        cleancic,
        &[],
    )
}

fn build_result_proof_authorities_with_revalidations(
    results: &[(VerificationCondition, VerificationResult)],
    bindings: &[Option<ResultObligationBinding>],
    full_verification: Option<&trust_verifier_api::VerificationRunResult>,
    cleancic: &[Option<trust_ir::ProofEvidence>],
    // Trust: sealed-authority S1 gate-re-solve receipts, index-aligned with
    // `results` (empty = no SMT revalidation for this call site → those rows
    // simply keep demoting; fail-closed divergence, never a stronger verdict).
    revalidations: &[Option<SolverRevalidationReceipt>],
) -> Vec<Option<ResultProofAuthority>> {
    let full_index = full_verification.map(build_full_verification_evidence_index);
    let supplied_row_counts = exact_result_row_counts(results);
    // A truncated or extra receipt carrier is not positional evidence. Ignore
    // the entire S1 lane rather than accepting the aligned-looking prefix.
    let revalidations_are_aligned = revalidations.len() == results.len();
    results
        .iter()
        .enumerate()
        .map(|(index, (vc, result))| {
            if !matches!(result, VerificationResult::Proved { .. }) {
                return None;
            }
            let binding = bindings.get(index).and_then(Option::as_ref);
            if binding.is_some_and(|binding| !binding.matches_row(index, vc)) {
                return None;
            }
            if let (Some(full_index), Some(binding)) = (full_index.as_ref(), binding)
                && binding.definition_entry_assumption
                // A definition-entry assumption normally remains only in the
                // compiler-sealed catalog, so absence from the proof-request
                // index is expected. If a same-ID requested row is present
                // (legacy/full-catalog callers), it must still be byte-exact;
                // a substituted or duplicate ID cannot mint this authority.
                && !full_index
                    .ambiguous_requested_ids
                    .contains(binding.public_obligation_id.as_str())
                && full_index
                    .requested_by_id
                    .get(binding.public_obligation_id.as_str())
                    .is_none_or(|obligation| binding.matches_public_obligation(obligation))
            {
                if !is_unique_exact_result_row(vc, &supplied_row_counts) {
                    return None;
                }
                return Some(ResultProofAuthority::DefinitionEntryAssumption {
                    row: exact_result_row_identity(index, vc)?,
                    binding: binding.clone(),
                });
            }
            if let (Some(full_index), Some(binding)) = (full_index.as_ref(), binding)
                && binding.assumed_total_callee_assumption
                && !full_index
                    .ambiguous_requested_ids
                    .contains(binding.public_obligation_id.as_str())
                && full_index
                    .requested_by_id
                    .get(binding.public_obligation_id.as_str())
                    .is_none_or(|obligation| binding.matches_public_obligation(obligation))
            {
                if !is_unique_exact_result_row(vc, &supplied_row_counts) {
                    return None;
                }
                return Some(ResultProofAuthority::AssumedTotalCalleeAssumption {
                    row: exact_result_row_identity(index, vc)?,
                    binding: binding.clone(),
                });
            }
            // A kernel proof of the legacy `Bool(false)` bookkeeping
            // placeholder proves only that placeholder. Likewise an accepted
            // native envelope cannot make a non-semantic row representation
            // authoritative. Mint no token unless the ordinary vacuity gate
            // preserves this exact row as Proved.
            if !matches!(
                apply_vacuity_gate_with_authority(
                    index,
                    vc,
                    result.clone(),
                    binding,
                    None,
                ),
                VerificationResult::Proved { .. }
            ) {
                return None;
            }
            if let Some(evidence @ trust_ir::ProofEvidence::CleanCic { .. }) =
                cleancic.get(index).and_then(Option::as_ref)
            {
                return Some(ResultProofAuthority::KernelCertified {
                    row: exact_result_row_identity(index, vc)?,
                    evidence: evidence.clone(),
                });
            }
            // Trust: sealed-authority S1 mint rung. The gate independently
            // re-solved THIS row's violation formula to strict-UNSAT
            // (`revalidate_all_solver_proofs`), so seal that re-derivation to the
            // exact row. Placed AFTER the vacuity gate (a placeholder row never
            // reaches here) and AFTER the KernelCertified attempt (kernel
            // outranks; a kernel-certified row does not need the SMT lane). The
            // receipt is index-aligned; the `ExactResultRowIdentity` carries the
            // canonical VC payload, so this token cannot transplant to any other
            // row.
            if revalidations_are_aligned
                && let Some(receipt) = revalidations.get(index).and_then(Option::as_ref)
                && solver_revalidation_receipt_matches_row(receipt, index, vc)
            {
                if std::env::var_os("TRUST_S1_DEBUG").is_some() {
                    eprintln!(
                        "TRUST_S1_DEBUG: SolverRevalidated MINT index={index} kind='{}' fn={} sha={}",
                        vc.kind.description(),
                        vc.function.as_str(),
                        &receipt.problem_sha256[..16.min(receipt.problem_sha256.len())],
                    );
                }
                return Some(ResultProofAuthority::SolverRevalidated {
                    row: exact_result_row_identity(index, vc)?,
                    receipt: receipt.clone(),
                });
            }

            // S2 freeze: a structurally valid verifier-api run, exact-looking
            // artifacts, and an accepted manifest decision are all serializable
            // public data. They may select attribution/diagnostics, but cannot
            // mint compiler proof authority. Native lanes must carry a private
            // live-dispatch receipt (the narrow body-bound Trust-WP rung is
            // applied separately) or a kernel/fresh-revalidation capability.
            None
        })
        .collect()
}

fn obligation_metadata(
    obligation: &trust_verifier_api::TrustObligation,
    key: &str,
) -> Option<String> {
    obligation.metadata.iter().find(|entry| entry.key == key).map(|entry| entry.value.clone())
}

fn transport_evidence_artifact(
    artifact: &trust_verifier_api::EvidenceArtifact,
) -> TransportEvidenceArtifact {
    let materialization = artifact.materialization.as_ref().and_then(|materialization| {
        let referenced_artifacts = materialization
            .referenced_artifacts()
            .iter()
            .map(|reference| trust_types::TransportArtifactReference {
                kind: reference
                    .kind
                    .canonical_wire_label()
                    .unwrap_or("UnrecognizedArtifactKind")
                    .to_string(),
                digest: TransportArtifactDigest {
                    algorithm: reference.hash.algorithm.clone(),
                    value: reference.hash.value.clone(),
                },
            })
            .collect();
        trust_types::TransportArtifactMaterialization::from_exact_bytes(
            materialization.bytes(),
            materialization.proof_binding_id().to_string(),
            referenced_artifacts,
        )
    });
    TransportEvidenceArtifact {
        kind: artifact
            .kind
            .canonical_wire_label()
            .unwrap_or("UnrecognizedArtifactKind")
            .to_string(),
        format: None,
        artifact_id: None,
        digest: Some(TransportArtifactDigest {
            algorithm: artifact.hash.algorithm.clone(),
            value: artifact.hash.value.clone(),
        }),
        uri: Some(artifact.uri.clone()),
        materialization,
        metadata: None,
    }
}

fn externalize_native_transport_materialization(
    sess: &Session,
    artifact: &mut TransportEvidenceArtifact,
) -> Result<(), String> {
    if !artifact
        .uri
        .as_deref()
        .is_some_and(|uri| uri.starts_with("trust_ir-native://verification-bundle/"))
    {
        return Ok(());
    }
    let Some(materialization) = artifact.materialization.take() else {
        return Ok(());
    };
    if materialization.materialized_path.is_some() {
        artifact.materialization = Some(materialization);
        return Ok(());
    }
    let digest = artifact
        .digest
        .as_ref()
        .ok_or_else(|| "native structural artifact has no digest".to_string())?;
    if !materialization.matches_sha256_digest(digest) {
        return Err("native structural artifact bytes do not match SHA-256 digest".to_string());
    }
    let Some(configured_root) = sess.opts.unstable_opts.trust_proof_artifact_root.as_deref() else {
        // Direct trustc invocations without an explicit artifact root retain
        // bounded inline bytes. Never write proof authority into ambient cwd.
        artifact.materialization = Some(materialization);
        return Ok(());
    };
    if !configured_root.is_absolute() {
        return Err("proof artifact root must be an explicit absolute path".to_string());
    }
    let bytes = materialization.decoded_bytes()?;
    // The descriptor crossing compiler transport carries only a canonical
    // relative content-addressed path. Targo supplies this same explicit
    // canonical working/report root when it grants path-backed proof credit;
    // an arbitrary absolute producer path is never opened by a consumer.
    let (output_root, store) = prepare_private_proof_artifact_store(configured_root)?;
    let final_path = store.join(&digest.value);
    if final_path.exists() {
        let metadata = std::fs::symlink_metadata(&final_path)
            .map_err(|error| format!("could not inspect existing proof artifact: {error}"))?;
        if metadata.file_type().is_symlink() || !metadata.is_file() {
            return Err("existing proof artifact is not a non-symlink regular file".to_string());
        }
        if metadata.len() != materialization.byte_len {
            return Err("existing content-addressed proof artifact has different bytes".to_string());
        }
    } else {
        use std::sync::atomic::{AtomicU64, Ordering};
        static TEMP_SEQUENCE: AtomicU64 = AtomicU64::new(0);
        let sequence = TEMP_SEQUENCE.fetch_add(1, Ordering::Relaxed);
        let temp_path =
            store.join(format!(".{}.{}.{}.tmp", digest.value, std::process::id(), sequence));
        let mut temp = std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temp_path)
            .map_err(|error| format!("could not create temporary proof artifact: {error}"))?;
        if let Err(error) = temp.write_all(&bytes).and_then(|()| temp.sync_all()) {
            let _ = std::fs::remove_file(&temp_path);
            return Err(format!("could not persist temporary proof artifact: {error}"));
        }
        drop(temp);
        match std::fs::hard_link(&temp_path, &final_path) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                let metadata = std::fs::symlink_metadata(&final_path).map_err(|read_error| {
                    format!("could not inspect concurrently stored proof artifact: {read_error}")
                })?;
                if metadata.file_type().is_symlink()
                    || !metadata.is_file()
                    || metadata.len() != materialization.byte_len
                {
                    let _ = std::fs::remove_file(&temp_path);
                    return Err(
                        "concurrently stored content-addressed artifact has different bytes"
                            .to_string(),
                    );
                }
            }
            Err(error) => {
                let _ = std::fs::remove_file(&temp_path);
                return Err(format!("could not publish proof artifact atomically: {error}"));
            }
        }
        let _ = std::fs::remove_file(&temp_path);
    }
    let final_path = std::fs::canonicalize(&final_path)
        .map_err(|error| format!("could not canonicalize stored proof artifact: {error}"))?;
    if final_path.parent() != Some(store.as_path()) {
        return Err("stored proof artifact escaped the content-addressed store".to_string());
    }
    let relative_path =
        format!("{}/sha256/{}", trust_types::TRANSPORT_ARTIFACT_STORE_DIRECTORY, digest.value);
    let Some(path_materialization) = materialization.with_materialized_path(relative_path) else {
        return Err("stored proof artifact materialization descriptor is invalid".to_string());
    };
    let stored = path_materialization.decoded_bytes_at_root(digest, &output_root)?;
    if stored != bytes {
        return Err("stored content-addressed proof artifact has different bytes".to_string());
    }
    artifact.materialization = Some(path_materialization);
    Ok(())
}

/// Validate the run-scoped proof authority and create its two fixed store
/// components without ever traversing a pre-existing symlink.  `create_dir_all`
/// is deliberately not used here: it follows intermediate symlinks and would
/// let an attacker redirect proof bytes before the final-directory check.
fn prepare_private_proof_artifact_store(
    configured_root: &Path,
) -> Result<(PathBuf, PathBuf), String> {
    let root_metadata = std::fs::symlink_metadata(configured_root)
        .map_err(|error| format!("could not inspect configured proof artifact root: {error}"))?;
    validate_private_proof_directory(&root_metadata, "proof artifact root")?;
    let output_root = std::fs::canonicalize(configured_root)
        .map_err(|error| format!("could not canonicalize proof artifact root: {error}"))?;
    if output_root != configured_root {
        return Err("proof artifact root must already be a canonical absolute path".to_string());
    }

    let store_root = ensure_private_proof_directory_component(
        &output_root,
        trust_types::TRANSPORT_ARTIFACT_STORE_DIRECTORY,
    )?;
    let store = ensure_private_proof_directory_component(&store_root, "sha256")?;
    if store.parent() != Some(store_root.as_path())
        || store_root.parent() != Some(output_root.as_path())
    {
        return Err("proof artifact store escaped compiler output directory".to_string());
    }
    Ok((output_root, store))
}

fn ensure_private_proof_directory_component(
    parent: &Path,
    component: &str,
) -> Result<PathBuf, String> {
    let child = parent.join(component);
    match std::fs::symlink_metadata(&child) {
        Ok(metadata) => validate_private_proof_directory(&metadata, "proof artifact store")?,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            std::fs::create_dir(&child)
                .map_err(|error| format!("could not create proof artifact store: {error}"))?;
            set_private_proof_directory_permissions(&child)?;
            let metadata = std::fs::symlink_metadata(&child)
                .map_err(|error| format!("could not inspect proof artifact store: {error}"))?;
            validate_private_proof_directory(&metadata, "proof artifact store")?;
        }
        Err(error) => {
            return Err(format!("could not inspect proof artifact store: {error}"));
        }
    }
    let canonical = std::fs::canonicalize(&child)
        .map_err(|error| format!("could not canonicalize proof artifact store: {error}"))?;
    if canonical != child || canonical.parent() != Some(parent) {
        return Err("proof artifact store contains a symlinked or escaping component".to_string());
    }
    Ok(canonical)
}

fn validate_private_proof_directory(
    metadata: &std::fs::Metadata,
    label: &str,
) -> Result<(), String> {
    if metadata.file_type().is_symlink() || !metadata.is_dir() {
        return Err(format!("{label} is not a non-symlink directory"));
    }
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt as _;

        if metadata.permissions().mode() & 0o777 != 0o700 {
            return Err(format!("{label} is not owner-private (expected mode 0700)"));
        }
    }
    Ok(())
}

#[cfg(unix)]
fn set_private_proof_directory_permissions(path: &Path) -> Result<(), String> {
    use std::os::unix::fs::PermissionsExt as _;

    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o700))
        .map_err(|error| format!("could not make proof artifact store owner-private: {error}"))
}

#[cfg(not(unix))]
fn set_private_proof_directory_permissions(_path: &Path) -> Result<(), String> {
    // Targo creates the run root with the platform's per-user temporary-file
    // ACL. The standard library cannot portably introspect Windows ACLs; the
    // no-symlink/canonical containment checks still apply to every component.
    Ok(())
}

fn transport_proof_status(
    evidence: &trust_verifier_api::ObligationEvidence,
) -> TransportProofStatus {
    match evidence.status {
        // A bounded proof establishes the claim only up to its unwinding depth,
        // which is not what a transport `Proved` asserts. That demotion is the
        // one place this lane departs from the shared status mapping; every
        // other status keeps whatever the engine said, through the single
        // conversion the rest of Trust uses.
        trust_verifier_api::EvidenceStatus::Proved if !evidence.is_unbounded_proof() => {
            TransportProofStatus::Unknown
        }
        status => TransportProofStatus::from(status.outcome()),
    }
}

fn artifact_policy_diagnostic(
    evidence: &trust_verifier_api::ObligationEvidence,
) -> TransportEvidenceDiagnostic {
    let satisfied = evidence.satisfies_proof_artifact_policy();
    transport_diagnostic(
        "full_verifier_artifact_policy",
        if satisfied {
            TransportEvidenceDiagnosticSeverity::Info
        } else {
            TransportEvidenceDiagnosticSeverity::Warning
        },
        &format!(
            "proof artifact policy satisfied={satisfied}; replay_or_check={}; solver_transcript={}",
            evidence.has_replay_or_check_artifact_metadata(),
            evidence.has_solver_transcript_artifacts()
        ),
    )
}

fn transport_diagnostic(
    code: &str,
    severity: TransportEvidenceDiagnosticSeverity,
    message: &str,
) -> TransportEvidenceDiagnostic {
    TransportEvidenceDiagnostic {
        code: code.to_string(),
        severity,
        message: message.to_string(),
        detail: None,
    }
}

/// A synthetic transport evidence row for a VERIFIED function with zero panic
/// obligations. Emitted only from the post-Verify, post-lowering path, so it
/// cannot stand in for an unverified or skipped function.
fn transport_no_obligations_row() -> TransportObligationResult {
    TransportObligationResult {
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: "no_obligations".to_string(),
        typed_kind: None,
        description: "function has no panic obligations (trivially panic-free)".to_string(),
        location: None,
        outcome: Outcome::Proved,
        solver: "trust-structural".to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some("verified: zero panic obligations".to_string()),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
    }
}

fn transport_tainted_body_row() -> TransportObligationResult {
    TransportObligationResult {
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: "compiler-error".to_string(),
        typed_kind: None,
        description: "function body was not verified because compilation already contained errors"
            .to_string(),
        location: None,
        outcome: Outcome::Unknown,
        solver: "trust-compiler".to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(
            "tainted MIR is coverage-attributed for identity accounting but carries no proof credit"
                .to_string(),
        ),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
    }
}

fn transport_native_verification_gap_row() -> TransportObligationResult {
    TransportObligationResult {
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: "native-verification-gap".to_string(),
        typed_kind: None,
        description: "native typed verification did not produce a complete obligation inventory"
            .to_string(),
        location: None,
        outcome: Outcome::Unknown,
        solver: "trust-native".to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(
            "the function was not proved; native lowering or dispatch did not complete".to_string(),
        ),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
    }
}

/// Trust (assumption ledger): the skip reasons recorded as explicit unverified
/// assumptions under an explicitly nonfatal policy. Survey records the
/// broad classifier/user-opt-out inventory; strict memory-safe mode records
/// only its separately checked no-unsafe capability gaps. Deliberately excludes
/// `ContractGeneratedClosure`: it marks inherited compatibility machinery that
/// is never part of Trust's proof inventory and is never-a-gap in
/// `skip_is_full_verification_failure`, so it never reaches
/// this demotion question. Also excludes the dependency skips (crate-granularity ledger entries
/// produced by targo from the dep-TCB set, and their include-deps abort
/// contract is explicit). `UserOptOut` is included: survey
/// must expose the user's assumption, while strict verification aborts before the
/// row can be recorded.
fn skip_reason_is_recorded_assumption(reason: &TrustVerifySkipReason) -> bool {
    matches!(
        reason,
        TrustVerifySkipReason::TreatedAsAssumption(_)
            | TrustVerifySkipReason::UnreachableStart
            | TrustVerifySkipReason::UserOptOut
            | TrustVerifySkipReason::AssumedTotal
    )
}

/// Trust (assumption ledger): stable machine-readable tag for a
/// recorded-assumption skip. Delegates to `UnsupportedReason::tag()` for
/// classifier gaps; `unreachable-start` is pinned by a unit test.
fn skip_assumption_tag(reason: &TrustVerifySkipReason) -> &'static str {
    match reason {
        TrustVerifySkipReason::TreatedAsAssumption(r) => r.tag(),
        TrustVerifySkipReason::UnreachableStart => "unreachable-start",
        TrustVerifySkipReason::UserOptOut => "user-opt-out",
        TrustVerifySkipReason::AssumedTotal => "assumed-total",
        // Unreachable while `skip_reason_is_recorded_assumption` gates callers;
        // a stable fallback beats a panic in a diagnostics path.
        _ => "other",
    }
}

/// Trust (assumption ledger): the transport row for an unverified assumption.
/// Fail-closed labeling contract: `outcome` is the pre-existing `"skipped"`
/// wire value (counted unknown+skipped by every consumer, never proof);
/// `kind` is `assumption:<tag>` (never `no_obligations`, never `transport:*`
/// so it still counts as evidence the verifier ran); no field may contain
/// full-verifier marker text (`is_full_verifier_text` in targo would
/// misclassify the row as full-verifier evidence).
fn transport_assumption_row(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    tag: &str,
    detail: &str,
    solver: &str,
) -> TransportObligationResult {
    let reason_class = assumption_reason_class(tag);
    TransportObligationResult {
        monitor: None,
        obligation_id: None,
        claim_digest_sha256: None,
        kind: format!("assumption:{tag}"),
        typed_kind: None,
        description: format!("unverified assumption: {detail}"),
        location: Some(source_span_from_rustc_span(tcx, body.span)),
        outcome: Outcome::Skipped,
        solver: solver.to_string(),
        time_ms: 0,
        counterexample: None,
        counterexample_model: None,
        reason: Some(format!(
            "{reason_class} `{tag}`: this function was NOT verified; \
             the crate's proof is conditional on it"
        )),
        design_mandate: false,
        native_trust_ir: None,
        proof_evidence: None,
    }
}

const COROUTINE_PROTOCOL_ASSUMPTION_TAG: &str = "coroutine";
const COROUTINE_PROTOCOL_ASSUMPTION_DETAIL: &str = "coroutine resume-state executor protocol is assumed valid; supported user data-safety \
     obligations were still verified";

/// Whether this optimized MIR body contains one of rustc's three coroutine
/// executor-protocol sentinels. The allowlist is intentionally exact: null,
/// alignment, invalid-enum, and future assert kinds remain ordinary fail-closed
/// safety obligations in vcgen.
fn body_has_coroutine_protocol_assert(body: &Body<'_>) -> bool {
    body.basic_blocks.iter().any(|block| {
        matches!(
            &block.terminator().kind,
            TerminatorKind::Assert { msg, .. }
                if matches!(
                    msg.as_ref(),
                    rustc_middle::mir::AssertKind::ResumedAfterReturn(_)
                        | rustc_middle::mir::AssertKind::ResumedAfterPanic(_)
                        | rustc_middle::mir::AssertKind::ResumedAfterDrop(_)
                )
        )
    })
}

/// Add exactly one coroutine-protocol assumption while preserving all real
/// verification rows. Every lane receives the same honest inventory; callers
/// separately decide whether explicit advisory policy may continue or strict /
/// memory-safe policy must reject the unproved premise.
fn rows_with_coroutine_protocol_assumption(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    if !body_has_coroutine_protocol_assert(body) {
        return None;
    }

    let row_kind = format!("assumption:{COROUTINE_PROTOCOL_ASSUMPTION_TAG}");
    let mut out: Vec<_> = rows.iter().filter(|row| row.kind != row_kind).cloned().collect();
    let mut coroutine_row = transport_assumption_row(
        tcx,
        body,
        COROUTINE_PROTOCOL_ASSUMPTION_TAG,
        COROUTINE_PROTOCOL_ASSUMPTION_DETAIL,
        "trust-classifier",
    );
    coroutine_row.reason = Some(
        "coroutine executor-protocol assumption `coroutine`: supported user data-safety \
         obligations were verified; the crate's result remains conditional on correct executor use"
            .to_string(),
    );
    out.push(coroutine_row);
    Some(out)
}

/// Reject the unproved coroutine executor-protocol premise in every fail-closed
/// lane. This runs only after human result reporting and JSON transport emission,
/// so the premise never masks or replaces genuine arithmetic/bounds/refutation
/// evidence from the same coroutine body.
fn abort_on_coroutine_protocol_assumption(tcx: TyCtxt<'_>, body: &Body<'_>, func_path: &str) {
    tcx.dcx()
        .struct_span_err(
            body.span,
            format!(
                "Trust strict verification failed for `{func_path}`: coroutine \
                 executor-protocol premise is unproved"
            ),
        )
        .with_note(
            "the compiler-generated ResumedAfterReturn/Panic/Drop sentinels are executor-protocol \
             preconditions rather than user data-safety checks; supported user obligations were \
             still verified and reported independently",
        )
        .with_note(
            "strict and memory-safe policy accept no unproved in-scope premise; use the explicit \
             -Ztrust-policy=advisory advisory lane to retain this as conditional \
             evidence",
        )
        .emit();
}

fn transport_row_is_coroutine_protocol_assumption(row: &TransportObligationResult) -> bool {
    row.kind.strip_prefix("assumption:") == Some(COROUTINE_PROTOCOL_ASSUMPTION_TAG)
        && row.outcome == Outcome::Skipped
        && row.solver == "trust-classifier"
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

fn assumption_reason_class(tag: &str) -> &'static str {
    match tag {
        "user-opt-out" => "explicit user opt-out",
        "assumed-total" | "assumed-total-callee" => "explicit user-audited assumption",
        "unreachable-start" => "verification policy assumption",
        _ => "verifier capability gap",
    }
}

/// Trust (assumption ledger, W3.5): is this transport row an EXTERN print/format/
/// write dispatch panic-freedom row (marked by the bridge with
/// `EXTERN_CALL_ASSUMPTION_PREFIX`) that is NOT proved? Such a row is a recorded
/// may-panic-via-user-`Display` gap, eligible for demotion to `assumption:extern-
/// call` in advisory mode. A proved row is never demoted.
fn transport_row_is_unproved_extern_call(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
}

/// FIX b59: the dispatch callee the bridge carries between the backticks of an
/// `EXTERN_CALL_ASSUMPTION_PREFIX` row description (the bridge emits
/// "…dispatch `{callee}` runs a user Display/Debug impl…", see `extern_fmt_dispatch_call`).
/// The prefix and the "extern print/format/write dispatch " lead-in carry no backticks,
/// so the first backtick pair delimits the callee.
fn extern_call_row_callee(description: &str) -> Option<&str> {
    let (_, after) = description.split_once('`')?;
    let (callee, _) = after.split_once('`')?;
    Some(callee)
}

/// FIX b59: the SAFE SUBSET of the unproved extern-call dispatch rows — the
/// `fmt::format` (`format!` macro backend) leg SPECIFICALLY. `alloc::fmt::format`
/// builds a `String` with NO stdout sink, so — unlike the `_print`/`_eprint` legs
/// (which drive a `Display` INTO stdout and can additionally hit a broken pipe /
/// SIGPIPE) or the `write_fmt`/`fmt::write` writer legs — it is the one dispatch leg
/// eligible for demotion OUTSIDE the memory-safe lane (strict fail-closed and the
/// survey `ny-cert` lane included). Reads the callee the bridge carried in the
/// row description; the row's provenance (only `core::`/`alloc::`/`std::` dispatch
/// callees ever mint an `EXTERN_CALL_ASSUMPTION_PREFIX` row) makes the
/// `::fmt::format` suffix unambiguous. A proved row is never demoted.
fn transport_row_is_unproved_fmt_format_extern_call(row: &TransportObligationResult) -> bool {
    transport_row_is_unproved_extern_call(row)
        && extern_call_row_callee(&row.description)
            .is_some_and(|callee| callee.ends_with("::fmt::format"))
}

/// Trust (assumption ledger): is this transport row an ABSENT-CALLEE panic-freedom
/// row (marked by the bridge with `ABSENT_CALLEE_ASSUMPTION_PREFIX` — the target's
/// body was not in the lowered bundle) that is NOT proved? Eligible for demotion to
/// `assumption:absent-callee` in advisory mode only; the strict full lane keeps
/// it Unknown (fail-closed). A proved row is never demoted.
fn transport_row_is_unproved_absent_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
        // The EXPECTED-absent prefix is NOT a substring of the fatal one (guarded
        // by the assumption-crate `assumption_prefixes_are_mutually_non_substring`
        // test), but `.contains` on the fatal prefix would false-negate here only
        // if it were — belt-and-suspenders, exclude it explicitly so a future
        // prefix edit cannot silently make an expected-absent row fatal.
        && !transport_row_is_unproved_expected_absent_callee(row)
        && !transport_row_is_unproved_assumed_total_callee(row)
}

/// Trust: is this an UNPROVED EXPECTED-absent callee row — a user
/// `#[trust::skip]` or a compiler-authenticated non-unwinding C-family call
/// (marked by the bridge with `EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX`)? It is
/// still an assumption, never proof: only survey may rewrite it to an
/// `assumption:expected-absent-callee` ledger row. Strict and memory-safe reject
/// it. Unresolved generic dispatch is deliberately not in this producer class.
fn transport_row_is_unproved_expected_absent_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row
            .description
            .contains(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
}

/// SOUNDNESS GAP — RECORDED, NOT FIXED. `.contains()` on a USER-CONTROLLED string.
///
/// `row.description` is user-reachable text. The shortest path found:
/// `unsupported_predicate_reason` in `trust_contract_query.rs` inlines
/// `span_to_snippet(span)` raw into "unsupported contract predicate expression
/// `{snippet}`" for any `#[requires(EXPR)]` that declines to lower — e.g. one
/// containing a string literal — and that text flows unsanitized through
/// trust-mir-extract into this row's description. Embedding the assumption prefix
/// in a contract expression therefore classifies the row as an
/// `#[trust::assume_total]` callee assumption the author never wrote.
///
/// Effect, scoped honestly: this is a GATE DOWNGRADE, not a false proof. Strict
/// and Certify fold `assumed` back into `unknown`, so only the Advisory lane
/// flips — `unknown > 0 => Inconclusive/exit 1` becomes
/// `assumed > 0, F=U=0 => ConditionalPass/exit 0`. In the memory-safe lane the
/// marker causes OVER-rejection, not a bypass; do not "fix" in that direction.
/// What is real: an unverified user string launders a fail-closed unknown into
/// the "explicit user-audited assumption" bucket and flips a documented blocking
/// status.
///
/// This file already knows the hazard — see the note that "the description is
/// user-controlled, so only the final `contract_id` suffix is authoritative",
/// hardening applied to the ensures-citation parser and not here. The sibling
/// check on this same marker, `api_obligation_is_assumed_total_callee_marker`,
/// does it correctly with `strip_prefix` plus full provenance recomputation, and
/// has an adversarial test whose first case is literally "embedded marker". This
/// predicate has none.
///
/// FIX SHAPE: carry the class on an authenticated channel, as the compiler
/// already does for the assumed-total SET via `insert_exact_absent_call_identity`
/// (whose own comment warns of "the 'spelling as authority' hazard"); or sanitize
/// `obligation.description` in `legacy_unsupported_kind_detail` before it becomes
/// `detail`. NOT applied here because this crate cannot be compile-validated
/// without a full bootstrap, and the change wants a regression test modelled on
/// the sibling's — which needs the same build.
fn transport_row_is_unproved_assumed_total_callee(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX)
}

fn transport_row_is_assumed_total_assumption(row: &TransportObligationResult) -> bool {
    row.kind.strip_prefix("assumption:")
        == Some(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_TAG)
        && row.outcome == Outcome::Skipped
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

fn expected_absent_callee_demotion_applies(
    policy: &TrustVerifyPolicy,
    rows: &[TransportObligationResult],
) -> bool {
    policy.is_explicit_advisory()
        && rows.iter().any(transport_row_is_unproved_expected_absent_callee)
}

/// Trust (assumption ledger): drop-glue twin of the absent-callee predicate —
/// a `PanicFreedom` row for a Drop whose glue's panic-freedom is unproven.
fn transport_row_is_unproved_drop_glue(row: &TransportObligationResult) -> bool {
    row.outcome != Outcome::Proved
        && row.description.contains(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
}

/// Trust: fail-closed on absent-callee / expected-absent / drop-glue panic
/// (revert of d8a9bbc28e / d848dcad97 fail-open; unproven panic MUST fail
/// closed). An UNPROVEN `PanicFreedom` row marked by any of those bridge prefixes
/// is a genuine undischarged panic obligation: the
/// bridge lowers the site with an `Assert(false)+NoPanic` marker that keeps the
/// panic REACHABLE, so the obligation is Unknown by construction (never a false
/// PROVE) — but Unknown here means "a panic path we could not rule out", not a
/// mere coverage gap. The originating commits claimed the strict lane "keeps it
/// Unknown, fail-closed"; empirically the abort predicate below only consulted
/// `failure.failed`, so these Unknown rows returned rc=0 (accept a program that
/// panics — a FAIL-OPEN). This predicate re-arms the fail-closed abort: an
/// unproven assumption-tagged panic row is FATAL in the fail-closed (default +
/// strict) lane. SOUNDNESS: the row is never `proved` (the reachable panic marker
/// forbids it), so treating it as fatal can never false-refute provably-safe code
/// — it only rejects a call/drop whose panic-freedom the native lane genuinely
/// could not establish, which is exactly the fail-closed doctrine. The demotion
/// explicit survey rewrite path is unaffected: this predicate is consulted
/// only where strict enforcement requires a hard build error.
fn transport_row_is_unproved_assumption_panic(row: &TransportObligationResult) -> bool {
    transport_row_is_unproved_absent_callee(row)
        || transport_row_is_unproved_expected_absent_callee(row)
        || transport_row_is_unproved_drop_glue(row)
}

/// Trust: fail-closed on absent-callee / expected-absent / drop-glue panic. Does
/// ANY transport row carry such an UNPROVEN panic-freedom assumption? Such a row
/// is a genuine undischarged panic obligation that must abort the fail-closed lane
/// (see [`transport_row_is_unproved_assumption_panic`]). Pure so it can be
/// unit-tested without a TyCtxt.
#[cfg(test)]
fn transport_rows_have_unproved_assumption_panic(rows: &[TransportObligationResult]) -> bool {
    rows.iter().any(transport_row_is_unproved_assumption_panic)
}

fn artifacts_have_unproved_assumption_panic(artifacts: &VerificationArtifacts) -> bool {
    artifacts.transport_results.iter().any(transport_row_is_unproved_assumption_panic)
}

/// Trust (assumption ledger, W3.6): does this transport row count as a REAL
/// obligation that must be Proved before the fail-closed extern-call catch-all may
/// fire? Design-mandate rows (inventory, never a discharge target) and the extern-
/// call rows themselves are excluded by the caller; here we treat only the genuine
/// verdict outcomes as blockers, so a lingering unresolved obligation keeps the whole
/// function fail-closed (UNKNOWN), never blanket-demoted. `proved` passes; bookkeeping
/// rows (`skipped` assumptions, `cached`, `no_obligations`→`proved`) do not block.
///
/// Stated as "neither discharged nor a bookkeeping skip" rather than as a list of
/// blocking outcomes: an outcome this compiler has not heard of is by definition
/// unresolved, so the fail-closed reading is the one that survives a widened
/// taxonomy.
fn transport_row_blocks_extern_call_demotion(row: &TransportObligationResult) -> bool {
    !row.outcome.is_proved() && !row.outcome.is_skipped()
}

/// Trust (assumption ledger, W2.1): rows that SURVIVE the native-lowering collapse.
/// A genuine PROOF (`proved`) and a genuine REFUTATION (`failed`) must both survive —
/// only the POISONED (unknown/unsupported/runtime-checked/…) rows fold into the single
/// `assumption:native-lowering` row. SOUNDNESS: never hide a refutation behind an
/// assumption (a `failed` row must keep failing the crate closed).
fn native_lowering_collapse_keeps_row(row: &TransportObligationResult) -> bool {
    matches!(row.outcome, Outcome::Proved | Outcome::Failed)
        || (row.kind.strip_prefix("assumption:")
            == Some(trust_types::assumption::MEMORY_SAFE_PANIC_ASSUMPTION_TAG)
            && row.solver == trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE
            && row.outcome == Outcome::Skipped)
}

fn vc_kind_has_contract_panic_marker(kind: &VcKind) -> bool {
    let classified = |text: &str| {
        trust_types::tolerance::classify_contract_panic(
            &trust_types::tolerance::ContractPanicView { text, row_kind: None },
        ) != trust_types::tolerance::ContractPanicClass::None
    };
    match kind {
        VcKind::Assertion { message } => classified(message),
        VcKind::UnsupportedMir { kind, detail } => classified(kind) || classified(detail),
        _ => false,
    }
}

fn vc_kind_has_expected_absent_callee_marker(kind: &VcKind) -> bool {
    let has_marker = |text: &str| {
        text.contains(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
    };
    match kind {
        VcKind::Assertion { message } => has_marker(message),
        VcKind::UnsupportedMir { kind, detail } => has_marker(kind) || has_marker(detail),
        _ => false,
    }
}

fn vc_kind_has_assumed_total_callee_marker(kind: &VcKind) -> bool {
    let has_marker =
        |text: &str| text.contains(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX);
    match kind {
        VcKind::Assertion { message } => has_marker(message),
        VcKind::UnsupportedMir { kind, detail } => has_marker(kind) || has_marker(detail),
        _ => false,
    }
}

/// Whether a typed VC failure is exactly a Rust runtime panic that the explicit
/// memory-safe policy may conditionally admit. This is intentionally narrower
/// than all L0 kinds: hardened findings, raw/ownership/FFI memory safety,
/// unbounded-allocation policy, contracts, and other non-panic properties stay
/// fail-closed even in a source-unsafe-free function.
fn vc_kind_is_memory_safe_panic(kind: &VcKind) -> bool {
    if kind.hardened_category().is_some()
        || vc_kind_has_contract_panic_marker(kind)
        || vc_kind_has_expected_absent_callee_marker(kind)
        || vc_kind_has_assumed_total_callee_marker(kind)
    {
        return false;
    }
    match kind {
        VcKind::ArithmeticOverflow { .. }
        | VcKind::ShiftOverflow { .. }
        | VcKind::DivisionByZero
        | VcKind::RemainderByZero
        | VcKind::IndexOutOfBounds
        | VcKind::SliceBoundsCheck
        | VcKind::NegationOverflow { .. }
        | VcKind::Unreachable => true,
        VcKind::Assertion { .. } => true,
        VcKind::UnsupportedMir { kind: unsupported_kind, .. } => {
            // Known unwrap/expect panic gaps and native arithmetic/bounds
            // round-trips are panic-class. Native MemorySafety is deliberately
            // excluded: an unsupported UB obligation is never a safe panic.
            is_known_panicking_call_unsupported_mir(kind)
                || unsupported_kind.starts_with("FullVerification::ArithmeticSafety")
                || unsupported_kind.starts_with("FullVerification::BoundsCheck")
        }
        _ => false,
    }
}

/// Reclassify only compiler-typed, genuinely FAILED safe-panic rows into the
/// explicit memory-safe assumption protocol. The caller passes `enabled` only
/// after `memory_safe_demotion_applies` established both the tracked flag and
/// the absence of source/inlined unsafe code.
///
/// Fail-closed invariants:
/// * typed results and flat rows must be exactly index-aligned;
/// * both layers must say `failed`;
/// * only the narrow panic-kind classifier above qualifies;
/// * proofs, non-panic failures, contract panics, mandates, and every unsafe-body
///   invocation remain byte-unchanged.
fn rewrite_memory_safe_panic_refutation_rows(
    enabled: bool,
    results: &[(VerificationCondition, VerificationResult)],
    rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    if !enabled || results.len() != rows.len() {
        return None;
    }
    let mut changed = false;
    let rewritten = results
        .iter()
        .zip(rows)
        .map(|((vc, result), row)| {
            if !matches!(result, VerificationResult::Failed { .. })
                || !row.outcome.is_failed()
                || row.design_mandate
                || transport_row_is_failed_contract_panic(row)
                || transport_row_is_failed_contract_panic_unused(row)
                || transport_row_is_unproved_expected_absent_callee(row)
                || transport_row_is_unproved_assumed_total_callee(row)
                || !vc_kind_is_memory_safe_panic(&vc.kind)
            {
                return row.clone();
            }

            changed = true;
            let mut assumption = row.clone();
            assumption.kind =
                format!("assumption:{}", trust_types::assumption::MEMORY_SAFE_PANIC_ASSUMPTION_TAG);
            // A synthetic assumption classification must not retain the
            // original VC's typed identity.
            assumption.typed_kind = None;
            // Rebuild rather than copy the raw native description: an
            // UnsupportedMir row can contain `FullVerification::...`, which a
            // downstream evidence classifier treats as a full-verifier marker.
            // Assumption text must be clean so it can never masquerade as proof
            // evidence (the source location/counterexample still identify the
            // original failure).
            assumption.description =
                "unverified memory-safe panic: a typed Level-0 Rust runtime panic remains \
                 reachable (conditional policy result, not proved)"
                    .to_string();
            assumption.outcome = Outcome::Skipped;
            assumption.solver =
                trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE.to_string();
            assumption.reason = Some(
                "the explicit memory-safe policy admitted this reachable Rust runtime panic only \
                 because the compiler established that the function contains neither source nor \
                 inlined unsafe code; this is an assumption, never proof credit"
                    .to_string(),
            );
            // A failed native/solver artifact is useful diagnostic history, but
            // it is not proof evidence for the newly-classified assumption and
            // must not survive under a proof-looking field.
            assumption.native_trust_ir = None;
            assumption.proof_evidence = None;
            assumption.claim_digest_sha256 = None;
            assumption
        })
        .collect();
    changed.then_some(rewritten)
}

fn transport_row_is_authenticated_memory_safe_assumption(row: &TransportObligationResult) -> bool {
    row.kind.starts_with("assumption:")
        && row.outcome == Outcome::Skipped
        && row.solver == trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE
        && !row.design_mandate
        && row.native_trust_ir.is_none()
        && row.proof_evidence.is_none()
}

/// Typed non-proved shapes the memory-safe policy may send through its
/// row-level classifier. The effective-row gate below is still authoritative:
/// a candidate that was not actually rewritten to an authenticated assumption
/// remains fatal. Functional contracts, UB/memory/ownership, hardened, and
/// domain obligations are deliberately absent.
fn vc_kind_is_memory_safe_demotable_gap(kind: &VcKind) -> bool {
    if vc_kind_has_contract_panic_marker(kind)
        || vc_kind_has_expected_absent_callee_marker(kind)
        || vc_kind_has_assumed_total_callee_marker(kind)
    {
        return false;
    }
    if vc_kind_is_memory_safe_panic(kind) {
        return true;
    }
    matches!(
        kind,
        VcKind::UnsupportedMir { kind, detail }
            if kind.starts_with("FullVerification::ArithmeticSafety")
                || kind.starts_with("FullVerification::BoundsCheck")
                || kind.starts_with("FullVerification::Assertion")
                || detail.contains(KNOWN_PANICKING_CALL_UNSUPPORTED_MARKER)
    )
}

/// Compiler-side counterpart of Targo's memory-safe result gate. The raw
/// compiler must not exit 0 merely because a no-unsafe function selected the
/// policy: every non-proved row must have been *actually* reclassified by the
/// compiler under the shared authenticated source label, and every typed raw
/// gap must belong to the narrow safe-panic/capability family.
fn memory_safe_artifacts_have_non_demotable_failure(
    artifacts: &VerificationArtifacts,
    effective_rows: &[TransportObligationResult],
) -> bool {
    let has_unauthenticated_nonproved_row = effective_rows.iter().any(|row| {
        !row.outcome.is_proved()
            && !transport_row_is_authenticated_memory_safe_assumption(row)
            && !transport_row_is_assumed_total_assumption(row)
    });
    if artifacts.proof_results.summary.total == 0 {
        let native_gap = match artifacts.full_verification.as_ref() {
            Some(run) => !native_run_is_vacuously_clean(run),
            None => !(artifacts.results.is_empty() && artifacts.transport_results.is_empty()),
        };
        // Synthetic policy rows are additive to the verifier's real-obligation
        // count. In particular, a coroutine protocol premise can be the only
        // effective row even when native verification is otherwise vacuously
        // clean; memory-safe must still reject that unauthenticated premise.
        return native_gap || has_unauthenticated_nonproved_row;
    }

    // A raw Proved result only counts when its exact private authority is an
    // independent static proof. `Trusted + None` is the contract-assumed
    // bookkeeping bucket and must not bypass the memory-safe proof gate.
    for (index, (vc, result)) in artifacts.results.iter().enumerate() {
        let authority = artifacts.proof_authorities.get(index).and_then(Option::as_ref);
        let binding = artifacts.result_bindings.get(index).and_then(Option::as_ref);
        let statically_accepted = authority
            .is_some_and(|authority| authority.is_static_proof_for(index, vc, result, binding));
        let exact_entry_assumption = authority.is_some_and(|authority| {
            authority.is_definition_entry_assumption_for(index, vc, binding)
        });
        let exact_assumed_total = authority.is_some_and(|authority| {
            authority.is_assumed_total_callee_assumption_for(index, vc, binding)
        });
        // The def-site marker is not a safety obligation to discharge; it is
        // the exact conditional premise under which the body was verified.
        // Ignore it here without counting it as static proof.
        if statically_accepted || exact_entry_assumption || exact_assumed_total {
            continue;
        }
        if matches!(result, VerificationResult::Proved { .. })
            || !vc_kind_is_memory_safe_demotable_gap(&vc.kind)
        {
            return true;
        }
    }

    effective_rows.is_empty() || has_unauthenticated_nonproved_row
}

fn abort_on_memory_safe_non_demotable_failure<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    func_path: &str,
    artifacts: &VerificationArtifacts,
    effective_rows: &[TransportObligationResult],
) {
    if !memory_safe_artifacts_have_non_demotable_failure(artifacts, effective_rows) {
        return;
    }

    let has_coroutine_protocol_premise =
        effective_rows.iter().any(transport_row_is_coroutine_protocol_assumption);
    let mut diag = tcx.dcx().struct_span_err(
        body.span,
        if has_coroutine_protocol_premise {
            format!(
                "Trust memory-safe verification failed for `{func_path}`: coroutine \
                 executor-protocol premise is unproved"
            )
        } else {
            format!(
                "Trust memory-safe verification failed for `{func_path}`: at least one result is \
                 not an authenticated memory-safe assumption"
            )
        },
    );
    if has_coroutine_protocol_premise {
        diag.note(
            "supported user data-safety obligations were still verified and reported \
             independently; memory-safe policy does not admit the compiler-generated \
             ResumedAfterReturn/Panic/Drop executor premise",
        );
    }
    diag.note(
        "-Ztrust-policy=memory-safe conditionally admits only compiler-marked safe-code panic \
         or lowering assumptions in functions with neither source nor inlined unsafe; proofs \
         remain proofs, while UB, hardened, contract, functional, unmarked unknown, runtime-checked, \
         and other failed rows remain build errors",
    );
    diag.note(format!(
        "effective transport rows: {} total, {} authenticated memory-safe assumption(s)",
        effective_rows.len(),
        effective_rows
            .iter()
            .filter(|row| transport_row_is_authenticated_memory_safe_assumption(row))
            .count(),
    ));
    diag.emit();
}

/// Trust (assumption ledger, W3.6): the fail-closed gate — is every OTHER counted
/// obligation Proved, so the marked extern-call row(s) may demote? Design-mandate
/// rows (inventory) and the extern-call rows themselves are excluded; any remaining
/// `failed`/`unknown`/`runtime_checked`/`timeout` row BLOCKS the demotion (keep the
/// function fail-closed / UNKNOWN — never blanket-demote a genuine gap). Pure so it
/// can be unit-tested without a TyCtxt.
fn extern_call_demotion_others_all_proved(rows: &[TransportObligationResult]) -> bool {
    rows.iter().all(|row| {
        if row.design_mandate || transport_row_is_unproved_extern_call(row) {
            return true;
        }
        !transport_row_blocks_extern_call_demotion(row)
    })
}

/// Trust (assumption ledger): the pure decision core for
/// [`demote_transport_rows_for_default_lane`], factored out so the F2 strict-lane
/// gate, the W2.1 memory-safe gate, and the W3.6 fail-closed extern-call gate can be
/// unit-tested without a TyCtxt.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum DefaultLaneDemotion {
    /// Emit the original rows unchanged.
    None,
    /// Collapse poisoned non-proved rows into one `assumption:native-lowering` row.
    NativeLowering,
    /// Demote the marked extern-call rows to `assumption:extern-call`.
    ExternCall,
    /// FIX b59: demote ONLY the `fmt::format` (`format!` backend) dispatch rows to
    /// `assumption:extern-call`, leaving any stdout `_print`/`_eprint` leg (SIGPIPE
    /// hazard) and every other row untouched. This is the one demotion the
    /// fail-closed / non-memory-safe lanes permit.
    FmtFormat,
}

fn default_lane_demotion_decision(
    strict_enforcement: bool,
    fmt_format_demotable: bool,
    memory_safe: bool,
    lowering_failed: bool,
    has_unproved_extern_call: bool,
    others_all_proved: bool,
) -> DefaultLaneDemotion {
    // Strict enforcement never demotes an ORDINARY gap. An explicit memory-safe
    // policy passes `false` here only after proving the function contains no `unsafe`.
    //
    // FIX b59: the ONE exception both fail-closed guards now permit is the SAFE
    // `fmt::format` (the `format!` macro backend) subset — `fmt_format_demotable` is
    // set by the caller only after pinning BOTH existing guards: the no-`unsafe` half
    // of `memory_safe_demotion_applies` (an unsafe gap could be UB the fmt panic masks)
    // AND `extern_call_demotion_others_all_proved` (every OTHER obligation Proved, so
    // demoting the fmt row can never mask a real failure elsewhere), scoped to the
    // `::fmt::format` callee so the SIGPIPE-hazard `_print`/`_eprint` stdout legs are
    // EXCLUDED. The fmt `Display` CAN panic, but the row is recorded as an HONEST
    // `assumption:extern-call` ledger entry (never claimed proved) — the
    // allocator-class trust boundary, exactly as the memory-safe lane already demotes
    // it below. This clears the `ny-cert` survey lane's `fmt::format` UNKNOWN rows.
    if strict_enforcement {
        return fmt_format_demotion_only(fmt_format_demotable);
    }
    // W2.1: only a memory-safe (no-unsafe) function demotes a BROAD gap; an unsafe gap
    // could be UB. The safe `fmt::format` subset is still permitted here — this is the
    // survey lane (`ny-cert`) that runs WITHOUT the memory-safe flag.
    if !memory_safe {
        return fmt_format_demotion_only(fmt_format_demotable);
    }
    // The native-lowering backstop takes precedence: a failed lowering left no usable
    // per-obligation rows, so the whole function's gap collapses to one honest row.
    if lowering_failed {
        return DefaultLaneDemotion::NativeLowering;
    }
    // Extern-call demotion is fail-closed: only when a marked row exists AND every
    // OTHER counted obligation is Proved (W3.6). Otherwise stay UNKNOWN.
    if has_unproved_extern_call && others_all_proved {
        return DefaultLaneDemotion::ExternCall;
    }
    DefaultLaneDemotion::None
}

/// FIX b59: the safe-subset demotion decision shared by the two fail-closed guards of
/// [`default_lane_demotion_decision`] — demote to the `fmt::format`-only leg when the
/// caller certified it demotable, otherwise stay fail-closed / UNKNOWN.
fn fmt_format_demotion_only(demotable: bool) -> DefaultLaneDemotion {
    if demotable { DefaultLaneDemotion::FmtFormat } else { DefaultLaneDemotion::None }
}

/// FIX b59: the pure gate for the safe `fmt::format` subset demotion. ALL THREE pins
/// are required (any one false keeps the function fail-closed / UNKNOWN):
///   * `has_fmt_format` — the function has an unproved `fmt::format` dispatch row (the
///     safe subset; the caller excludes the `_print`/`_eprint` stdout legs);
///   * `function_is_unsafe_free` — the no-`unsafe` half of `memory_safe_demotion_applies`
///     (an unsafe gap could be UB the fmt panic masks);
///   * `others_all_proved` — `extern_call_demotion_others_all_proved` (every OTHER
///     obligation Proved, so demoting the fmt row can never mask a real failure).
/// Pure so it can be unit-tested without a `TyCtxt`.
fn fmt_format_demotion_gate(
    has_fmt_format: bool,
    function_is_unsafe_free: bool,
    others_all_proved: bool,
) -> bool {
    has_fmt_format && function_is_unsafe_free && others_all_proved
}

/// Trust (T9 contract-panic): is this row a FAILED panic-freedom/assertion row
/// that trust-vcgen stamped with the contract-panic MATCHED marker? Marker
/// presence == the annotation's `message_contains` payload was a substring of a
/// `&str` CONSTANT operand of that exact panic call (site + message matched at
/// VC mint time). ONLY a `failed` row qualifies: Proved stays Proved (and feeds
/// the unused-annotation check), Unknown stays Unknown — a marker can
/// reclassify only a genuine refutation of the ANNOTATED panic, nothing else.
fn transport_row_is_failed_contract_panic(row: &TransportObligationResult) -> bool {
    // SINGLE SOURCE OF TRUTH (trust_types::tolerance): a raw row carries the marker
    // in its description (its `kind` is not yet a `contract-panic:` prefix), so
    // project the description and ask the shared classifier — do not spell the
    // marker inline. Only a `failed` row qualifies (Matched here is a refutation of
    // the annotated panic; Proved/Unknown are unaffected).
    row.outcome == Outcome::Failed
        && trust_types::tolerance::classify_contract_panic(
            &trust_types::tolerance::ContractPanicView { text: &row.description, row_kind: None },
        ) == trust_types::tolerance::ContractPanicClass::Matched
}

/// Trust (T9 contract-panic): the unused-annotation twin — the FAILED
/// always-SAT row trust-vcgen mints when a `contract_panic` annotation matched
/// NO panic call in the function.
fn transport_row_is_failed_contract_panic_unused(row: &TransportObligationResult) -> bool {
    // SINGLE SOURCE OF TRUTH (trust_types::tolerance): the anti-abuse UNUSED class —
    // an annotation that matched no panic call. Never a declared panic; stays a
    // refutation. Classified from the row description, not spelled inline.
    row.outcome == Outcome::Failed
        && trust_types::tolerance::classify_contract_panic(
            &trust_types::tolerance::ContractPanicView { text: &row.description, row_kind: None },
        ) == trust_types::tolerance::ContractPanicClass::Unused
}

/// Trust (T9 contract-panic): rewrite vcgen-stamped contract-panic rows only in
/// explicit survey policy. Returns `Some(rewritten)` when at least one row
/// rewrites, `None` to emit the original rows unchanged. Strict and memory-safe
/// therefore retain the original failed row and fail closed.
///
///   * a FAILED row carrying the MATCHED marker → kind
///     `contract-panic:matched` (source `trust-contract`), outcome stays
///     `failed` on the wire. targo's partition diverts the `contract-panic:`
///     kind prefix into the always-visible `contract_panics` bucket
///     (conditional-pass-eligible, never proof credit, fail-closed against a
///     Proved/RuntimeChecked claim);
///   * a FAILED row carrying the UNUSED marker → kind `contract-panic-unused`
///     (NOT the `contract-panic:` prefix — dash, not colon — so targo counts it
///     as a genuine FAILURE): an annotation on panic-free code is an ERROR;
///   * every other row — Proved, Unknown, and every unstamped row — is
///     BYTE-UNTOUCHED ("never hide a refutation": an unstamped `failed` row
///     keeps failing the crate closed, exactly like the native-lowering
///     collapse above keeps `failed` rows).
///
/// Contract-panic annotations remain visible conditional evidence only in the
/// broad advisory lanes, never proof credit. This is deliberately disjoint from
/// memory-safe's authenticated safe-code assumptions: an intentional panic must
/// select survey even when the function contains no `unsafe`.
fn rewrite_contract_panic_transport_rows(
    policy: &TrustVerifyPolicy,
    rows: &[TransportObligationResult],
) -> Option<Vec<TransportObligationResult>> {
    if !policy.admits_contract_panic_conditional_evidence() {
        return None;
    }

    // In survey, a declared, message-matched contract panic becomes a
    // `contract-panic:matched` row that targo partitions into its visible
    // `contract_panics` bucket (a CONDITIONAL pass, never a proof); the UNUSED
    // annotation becomes a `contract-panic-unused` row targo counts as a genuine
    // FAILURE. Strict and memory-safe keep the original failure; intentional
    // panic APIs such as `ArrayVec::push` must explicitly choose a nonfatal lane
    // rather than weakening the proof contract of the default compiler.
    if !rows.iter().any(|row| {
        transport_row_is_failed_contract_panic(row)
            || transport_row_is_failed_contract_panic_unused(row)
    }) {
        return None;
    }
    // Pass 1: reclassify the per-site panic-CALL rows (matched → `contract-panic:matched`,
    // unused → `contract-panic-unused`).
    let mut rewritten: Vec<TransportObligationResult> = rows
        .iter()
        .map(|row| {
            if transport_row_is_failed_contract_panic_unused(row) {
                let mut rewritten = row.clone();
                rewritten.kind =
                    trust_types::assumption::CONTRACT_PANIC_UNUSED_ROW_KIND.to_string();
                rewritten.typed_kind = None;
                rewritten.solver = trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE.to_string();
                rewritten.reason = Some(
                    "unused contract_panic annotation: its `message_contains` payload \
                     matched no panic call in this function; an annotation on panic-free \
                     code is an error"
                        .to_string(),
                );
                rewritten
            } else if transport_row_is_failed_contract_panic(row) {
                let mut rewritten = row.clone();
                rewritten.kind =
                    trust_types::assumption::CONTRACT_PANIC_MATCHED_ROW_KIND.to_string();
                rewritten.typed_kind = None;
                rewritten.solver = trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE.to_string();
                rewritten.reason = Some(
                    "declared contract panic: the function's contract_panic annotation \
                     message-matched this reachable panic; recorded as an intentional \
                     fail-closed panic (never a proof), counted visibly by targo"
                        .to_string(),
                );
                rewritten
            } else {
                row.clone()
            }
        })
        .collect();

    // Pass 2: the WHOLE-FUNCTION panic-freedom AGGREGATE row. The native trust-mc
    // lane cannot lower this function-level obligation to a typed CHC (it carries a
    // router-placeholder input and defers to a path-sensitive transport that does
    // not model diverging-`Call` panics), so it comes back UNKNOWN even when every
    // reachable panic is a declared contract panic — leaving `ArrayVec::push` with a
    // lone `1 unknown` after its per-site panic was already `contract-panic:matched`.
    // Reclassify that aggregate into the visible `contract_panics` bucket, but ONLY
    // when the function is CLEAN-MODULO-DECLARED-PANICS:
    //   (a) it has ≥1 `contract-panic:matched` per-site row (a declared panic to
    //       attribute the aggregate's non-freedom to), AND
    //   (b) it has NO blocking failure — no `failed` row whose kind is not itself
    //       `contract-panic:` (the aggregate row itself is excluded from this test).
    // SOUNDNESS: in a function with ≥1 obligation (which a contract-panic function
    // always is), EVERY panic — declared or not — gets its OWN per-site obligation
    // (proven empirically: an undeclared `assert!`/`panic!` alongside a declared one
    // still emits its own `panic call: core::panicking::panic` FAILED row). So any
    // UNdeclared reachable panic is a blocking failure that trips (b); an undeclared
    // panic left merely UNKNOWN keeps its own UNKNOWN row that still fails the gate.
    // The canonical-description match excludes an aggregate whose text was REPLACED by
    // a folded extern-call / absent-callee / drop-glue gap, so an unmodeled-callee
    // panic is never laundered. The aggregate never becomes `proved`. Strict
    // and memory-safe never enter this rewrite, so they retain the UNKNOWN
    // aggregate and fail closed.
    let has_matched = rewritten
        .iter()
        .any(|row| row.kind == trust_types::assumption::CONTRACT_PANIC_MATCHED_ROW_KIND);
    let has_blocking_failure = rewritten.iter().any(|row| {
        row.outcome == Outcome::Failed
            && !row.kind.starts_with(trust_types::assumption::CONTRACT_PANIC_ROW_KIND_PREFIX)
            && !transport_row_is_panic_freedom_aggregate(row)
    });
    if has_matched && !has_blocking_failure {
        for row in &mut rewritten {
            // Reclassify on any NON-`proved` outcome. The aggregate commonly comes
            // back `unknown` (native lane can't lower it) or `runtime_checked`
            // (`runtime_check_available` counts the panic itself as its own runtime
            // check) — both mean "not proven panic-free". A genuinely `proved`
            // aggregate is a real proof and is left untouched.
            if transport_row_is_panic_freedom_aggregate(row) && row.outcome != Outcome::Proved {
                row.kind = trust_types::assumption::CONTRACT_PANIC_AGGREGATE_ROW_KIND.to_string();
                row.typed_kind = None;
                // A reachable — but DECLARED — panic. Force `failed`: targo buckets a
                // `contract-panic:` row into `contract_panics` only when the outcome is
                // not `proved`/`runtime_checked` (it fail-closes either of those to a
                // transport-defect `unknown`, refusing to launder a claimed proof), so
                // `runtime_checked` must not survive on the reclassified row.
                row.outcome = Outcome::Failed;
                row.solver = trust_types::assumption::CONTRACT_PANIC_ROW_SOURCE.to_string();
                row.reason = Some(
                    "whole-function panic-freedom aggregate covered by declared contract \
                     panic(s): every reachable panic in this function is message-matched to \
                     its contract_panic annotation (no undeclared panic remains unproved), \
                     and the native lane cannot lower the function-level aggregate to a typed \
                     CHC; recorded as a conditional contract panic (never a proof)"
                        .to_string(),
                );
            }
        }
    }
    Some(rewritten)
}

/// Trust (T9 contract-panic): the WHOLE-FUNCTION panic-freedom AGGREGATE row —
/// the compiler's synthesized `assertion:panic-freedom:0` obligation carrying the
/// canonical "panic freedom: no assertion, …" description. Matching the canonical
/// text (rather than only the id) EXCLUDES an aggregate whose description was
/// replaced by a folded extern-call / absent-callee / drop-glue gap, so those
/// unmodeled-panic gaps are never reclassified as covered contract panics.
fn transport_row_is_panic_freedom_aggregate(row: &TransportObligationResult) -> bool {
    row.description.contains(trust_types::assumption::PANIC_FREEDOM_AGGREGATE_DESCRIPTION_PREFIX)
        && row.obligation_id.as_deref().is_none_or(|id| id.contains("panic-freedom"))
}

/// Trust (assumption ledger, W2.1 + W3.5/W3.6): under the explicit authenticated
/// memory-safe no-unsafe policy,
/// rewrite the transport rows a verifier CAPABILITY GAP produced into honest
/// `assumption:*` ledger rows, so code that uses `println!`/`format!` (or a construct
/// the native bridge cannot lower) COMPILES with a recorded, machine-
/// readable ledger entry instead of hard-aborting. Returns `Some(rewritten)` when it
/// fires, `None` to emit the original rows unchanged.
///
/// Fires only when strict enforcement is loosened by the explicit memory-safe
/// policy and the function contains no `unsafe`. Two disjoint cases:
///
///   * NATIVE-LOWERING backstop (W2.1): the native typed-TrustIr lowering FAILED
///     (bundle build failed → every obligation poisoned `Unsupported`). Collapse the
///     poisoned NON-proved rows into ONE `assumption:native-lowering` row (keeping any
///     genuinely-proved rows). The rebuilt row's reason is clean
///     (`transport_assumption_row`), never the poisoned rows' verbatim text — which
///     names the full verifier and would trip targo's `is_full_verifier_text` (F3).
///
///   * EXTERN-CALL demotion (W3.5/W3.6): lowering SUCCEEDED but a print/format/write
///     dispatch left an UNKNOWN panic-freedom row marked `EXTERN_CALL_ASSUMPTION_
///     PREFIX`. Demote each such row to `assumption:extern-call`, but ONLY when every
///     OTHER counted obligation (non-mandate, non-extern-call) is Proved — otherwise
///     stay fail-closed (keep UNKNOWN), never blanket-demote a genuine gap. Design-
///     mandate rows are untouched (bucketed as mandates by the targo counting).
///
/// SOUNDNESS: no row is ever rewritten to `proved`; an extern dispatch (which runs
/// arbitrary user `Display` code and CAN panic) becomes an UNVERIFIED assumption,
/// never a proof. Unmodified strict enforcement returns `None` here.
fn demote_transport_rows_for_default_lane<'tcx>(
    tcx: TyCtxt<'tcx>,
    body: &Body<'tcx>,
    policy: &TrustVerifyPolicy,
    artifacts: &VerificationArtifacts,
) -> Option<Vec<TransportObligationResult>> {
    let memory_safe = memory_safe_demotion_applies(tcx, body);
    let memory_safe_panics = rewrite_memory_safe_panic_refutation_rows(
        memory_safe,
        &artifacts.results,
        &artifacts.transport_results,
    );
    let rows = memory_safe_panics.as_deref().unwrap_or(&artifacts.transport_results);
    // EXPECTED-absent is still an unproved call boundary. Only explicit
    // survey policy may turn it into a visible assumption row. Strict keeps
    // the original row and the full-verification fatal gate rejects it;
    // memory-safe likewise excludes the marker from its authenticated
    // safe-panic/capability demotions.
    let has_expected_absent = expected_absent_callee_demotion_applies(policy, rows);
    let lowering_failed =
        artifacts.full_verification.as_ref().is_some_and(native_run_trust_ir_lowering_failed);
    let has_extern_call = rows.iter().any(transport_row_is_unproved_extern_call);
    let others_all_proved = extern_call_demotion_others_all_proved(rows);
    // FIX b59: the `fmt::format` (`format!` backend) leg is the SAFE SUBSET of the
    // extern-call rows — it builds a `String` with NO stdout sink, so (unlike the
    // `_print`/`_eprint` broken-pipe / SIGPIPE legs) it may demote in EVERY lane once
    // BOTH existing guards hold: the function is unsafe-free (the no-`unsafe` half of
    // `memory_safe_demotion_applies`) AND every OTHER obligation is Proved
    // (`extern_call_demotion_others_all_proved`). Both pins are computed HERE and fed
    // to the pure decision core as one boolean.
    let has_fmt_format_extern_call =
        rows.iter().any(transport_row_is_unproved_fmt_format_extern_call);
    let fmt_format_demotable = fmt_format_demotion_gate(
        has_fmt_format_extern_call,
        !function_uses_unsafe(tcx, body),
        others_all_proved,
    );
    let standard = match default_lane_demotion_decision(
        policy.fail_closed() && !memory_safe,
        fmt_format_demotable,
        // W2.1: only memory-safe (no-unsafe) functions demote; an unsafe gap could be UB.
        memory_safe,
        lowering_failed,
        has_extern_call,
        others_all_proved,
    ) {
        DefaultLaneDemotion::None => memory_safe_panics.clone(),
        DefaultLaneDemotion::NativeLowering => {
            // Keep genuine PROOFS and genuine REFUTATIONS; collapse only the POISONED
            // (unknown/unsupported/runtime-checked/…) rows into one honest
            // `assumption:native-lowering` row with REBUILT (marker-free) reason text.
            // SOUNDNESS: a `failed` row (e.g. a reachable assert the vcgen-refutation
            // path found even when the bridge could not lower the body) MUST survive so
            // targo still fails closed (F>0 → exit 1) — never hide a refutation behind
            // an assumption.
            let mut rebuilt: Vec<TransportObligationResult> = rows
                .iter()
                .filter(|row| native_lowering_collapse_keeps_row(row))
                .cloned()
                .collect();
            // Only a clean boundary DESCRIPTION survives here (F3): no full-verifier
            // marker strings, no verbatim poisoned-row reason.
            let detail = "native typed-TrustIr lowering did not complete for this function; \
                          an unmodeled construct (e.g. an unsupported external call) left its \
                          panic-freedom obligations undischarged";
            rebuilt.push(transport_assumption_row(
                tcx,
                body,
                trust_types::assumption::NATIVE_LOWERING_ASSUMPTION_TAG,
                detail,
                trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
            ));
            Some(rebuilt)
        }
        DefaultLaneDemotion::ExternCall => Some(demote_extern_call_transport_rows(tcx, body, rows)),
        // FIX b59: demote ONLY the `fmt::format` rows (the safe subset), leaving any
        // stdout `_print`/`_eprint` leg and every drop-glue row untouched.
        DefaultLaneDemotion::FmtFormat => {
            Some(demote_fmt_format_extern_call_transport_rows(tcx, body, rows))
        }
    };
    // Advisory expected-absent post-pass: demote those rows over whatever the
    // standard decision produced (or the original rows when it produced None).
    let after_expected = match (standard, has_expected_absent) {
        (Some(demoted), true) => {
            Some(demote_expected_absent_callee_transport_rows(tcx, body, &demoted))
        }
        (Some(demoted), false) => Some(demoted),
        (None, true) => Some(demote_expected_absent_callee_transport_rows(tcx, body, rows)),
        (None, false) => None,
    };
    let current = after_expected.as_deref().unwrap_or(rows);
    if !current.iter().any(transport_row_is_unproved_assumed_total_callee) {
        return after_expected;
    }
    Some(demote_assumed_total_callee_transport_rows(tcx, body, current))
}

/// Trust: under explicit survey policy, rewrite each unproved
/// EXPECTED-absent-callee row (user skip or compiler-authenticated non-unwinding
/// C-family call) into a recorded `assumption:expected-absent-callee` ledger
/// row, leaving every other row untouched. Never rewrites to `proved`.
fn demote_expected_absent_callee_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_unproved_expected_absent_callee(row) {
                let detail = row
                    .description
                    .split(trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "a user-skipped callee or compiler-authenticated non-unwinding C-family \
                         call whose body is absent from this verification unit",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::EXPECTED_ABSENT_CALLEE_ASSUMPTION_TAG,
                    detail,
                    "trust-bridge",
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

fn demote_assumed_total_callee_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_unproved_assumed_total_callee(row) {
                let detail = row
                    .description
                    .split(trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|detail| !detail.is_empty())
                    .unwrap_or(
                        "a call to a user-audited #[trust::assume_total] wrapper whose body is deliberately absent from this verification unit",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::ASSUMED_TOTAL_CALLEE_ASSUMPTION_TAG,
                    detail,
                    "trust-bridge",
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

/// Trust (assumption ledger, W3.5): rewrite each marked extern-call panic-freedom row
/// into a recorded `assumption:extern-call` ledger row (clean, marker-free text via
/// `transport_assumption_row`), leaving every other row untouched.
fn demote_extern_call_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_unproved_extern_call(row) {
                // Carry the dispatch callee into the ledger detail (strip the marker and
                // the reconstructed `assertion: ` VC-kind prefix), so the row can name
                // e.g. `alloc::fmt::format`. Marker-free by construction of the prefix.
                let detail = row
                    .description
                    .split(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "an extern print/format/write dispatch runs a user Display/Debug impl that may panic",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::EXTERN_CALL_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else if transport_row_is_unproved_drop_glue(row) {
                let detail = row
                    .description
                    .split(trust_types::assumption::DROP_GLUE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or("drop glue with unproven panic-freedom may panic");
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::DROP_GLUE_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else if transport_row_is_unproved_absent_callee(row) {
                // Same demotion shape for a call whose target body was absent
                // from the lowered bundle; the detail names the callee.
                let detail = row
                    .description
                    .split(trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "a call to a callee whose body is not in the lowered bundle may panic",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::ABSENT_CALLEE_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

/// FIX b59: the `fmt::format`-only demotion — rewrite ONLY the `fmt::format`
/// (`format!` macro backend) extern-dispatch rows to a recorded
/// `assumption:extern-call` ledger row, leaving EVERY other row BYTE-UNTOUCHED: any
/// stdout `_print`/`_eprint` leg (broken-pipe / SIGPIPE hazard) and any writer leg
/// keep failing closed, every drop-glue / absent-callee row is preserved, and every
/// real obligation is preserved. Used by the fail-closed / non-memory-safe lanes,
/// which admit only this safe subset — unlike [`demote_extern_call_transport_rows`],
/// which (in the memory-safe lane) demotes ALL extern-call, drop-glue, and
/// absent-callee legs. The demoted row is NEVER `proved`; it is an HONEST recorded
/// assumption (the fmt `Display` may panic), same class as the memory-safe lane.
fn demote_fmt_format_extern_call_transport_rows(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    rows: &[TransportObligationResult],
) -> Vec<TransportObligationResult> {
    rows.iter()
        .map(|row| {
            if transport_row_is_unproved_fmt_format_extern_call(row) {
                // Carry the dispatch callee into the ledger detail (strip the marker
                // and the reconstructed `assertion: ` VC-kind prefix), so the row can
                // name `alloc::fmt::format`. Marker-free by construction of the prefix.
                let detail = row
                    .description
                    .split(trust_types::assumption::EXTERN_CALL_ASSUMPTION_PREFIX)
                    .nth(1)
                    .map(str::trim)
                    .filter(|d| !d.is_empty())
                    .unwrap_or(
                        "the `format!` macro backend (`fmt::format`) runs a user Display/Debug impl that may panic",
                    );
                transport_assumption_row(
                    tcx,
                    body,
                    trust_types::assumption::EXTERN_CALL_ASSUMPTION_TAG,
                    detail,
                    trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE,
                )
            } else {
                row.clone()
            }
        })
        .collect()
}

/// Trust (assumption ledger): record a capability-gap skip as a
/// machine-readable unverified assumption. This is what makes the
/// `TreatedAsAssumption` doc promise ("recorded in the proof report — not
/// silently dropped") true: advisory mode emits a `TRUST_JSON` transport
/// row (under `-Z trust-verify-output=json|both`) and a human `eprintln` line
/// (under the default human mode), and the build continues. Explicit
/// Strict verification aborts before reaching this path.
fn record_skip_assumption(
    tcx: TyCtxt<'_>,
    body: &Body<'_>,
    func_path: &str,
    reason: &TrustVerifySkipReason,
    memory_safe_demotion: bool,
) {
    // Trust: do not add a process-global "seen" guard here. The optimized-MIR
    // query and pass schedule invoke this once per Body in a Session; distinct
    // coroutine bodies can intentionally share a def-path/tag and each needs an
    // honest row. A global guard both collapsed those rows and suppressed every
    // matching row in a later rustc_driver Session. The run-make assumption
    // transport regression pins the exact per-Body count.
    let tag = skip_assumption_tag(reason);
    let output_mode = TrustOutputMode::parse(tcx.sess);
    let detail = match reason {
        TrustVerifySkipReason::TreatedAsAssumption(_) => {
            format!("MIR shape the verifier cannot lower yet ({tag})")
        }
        TrustVerifySkipReason::UnreachableStart => {
            "function body starts at an unreachable terminator; \
             no executable path to verify"
                .to_string()
        }
        TrustVerifySkipReason::UserOptOut => {
            "function is excluded by #[trust::skip]; its behavior is an explicit user assumption"
                .to_string()
        }
        TrustVerifySkipReason::AssumedTotal => {
            "function carries #[trust::assume_total]; its totality is an explicit, \
             user-audited assumption (recorded in every mode, never proof)"
                .to_string()
        }
        _ => format!("unsupported body ({tag})"),
    };
    let solver = if memory_safe_demotion {
        trust_types::assumption::MEMORY_SAFE_ASSUMPTION_ROW_SOURCE
    } else {
        match reason {
            TrustVerifySkipReason::UnreachableStart
            | TrustVerifySkipReason::UserOptOut
            | TrustVerifySkipReason::AssumedTotal => "trust-policy",
            _ => "trust-classifier",
        }
    };
    if output_mode.emit_json() {
        emit_transport_json(
            tcx,
            func_path,
            &[transport_assumption_row(tcx, body, tag, &detail, solver)],
            0,
        );
    }
    if output_mode.emit_human() {
        // eprintln, not a diagnostic (house style for verify-pass notes).
        let policy_note = if matches!(reason, TrustVerifySkipReason::AssumedTotal) {
            "recorded in every mode as a visible non-proof premise"
        } else {
            "strict mode rejects it"
        };
        eprintln!(
            "Trust: ASSUMPTION [{tag}] `{func_path}`: {detail} — recorded as an \
             unverified assumption (NOT proved; {policy_note})"
        );
    }
}

/// Trust #542: Emit structured JSON transport line for a function's verification results.
///
/// Writes a single `TRUST_JSON:{"type":"function_result",...}` line to stderr.
/// This is consumed by targo-trust for programmatic access to verification
/// results without fragile text parsing of compiler diagnostics.
fn emit_transport_json(
    tcx: TyCtxt<'_>,
    func_path: &str,
    obligation_results: &[TransportObligationResult],
    cached: u32,
) {
    const MAX_FUNCTION_TRANSPORT_MATERIALIZATION_BYTES: u64 = 32 * 1024 * 1024;
    let mut proved: usize = 0;
    let mut failed: usize = 0;
    let mut unknown: usize = 0;
    let mut timed_out: usize = 0;
    let mut skipped: usize = 0;
    let mut runtime_checked: usize = 0;

    for result in obligation_results {
        match result.outcome {
            Outcome::Proved => proved += 1,
            Outcome::Failed => failed += 1,
            Outcome::RuntimeChecked => runtime_checked += 1,
            Outcome::Timeout => {
                timed_out += 1;
                unknown += 1;
            }
            Outcome::Skipped => {
                skipped += 1;
                unknown += 1;
            }
            // Every residual outcome — including one a later toolchain adds —
            // lands in the legacy `unknown` aggregate. It is the bucket that
            // grants nothing, so an unrecognized row can only understate the
            // crate's assurance, never overstate it.
            _ => unknown += 1,
        }
    }

    let total = proved + failed + unknown + runtime_checked;
    let role = tcx.sess.trust_crate_role();
    let package_name = tcx.sess.opts.unstable_opts.trust_verify_package_name.clone();
    let primary_package = role.is_cargo_primary();
    let crate_name = tcx.crate_name(LOCAL_CRATE).to_string();
    let mut transported_results = obligation_results.to_vec();
    for result in &mut transported_results {
        if let Some(native) = &mut result.native_trust_ir {
            let mut failures = Vec::new();
            for artifact in &mut native.artifacts {
                if let Err(error) = externalize_native_transport_materialization(tcx.sess, artifact)
                {
                    artifact.materialization = None;
                    failures.push(error);
                }
            }
            for failure in failures {
                native.diagnostics.push(transport_diagnostic(
                    "native_materialization_store_failure",
                    TransportEvidenceDiagnosticSeverity::Error,
                    &failure,
                ));
            }
        }
    }
    let mut counted_native_paths = std::collections::BTreeSet::new();
    let mut materialized_bytes = 0u64;
    for artifact in transported_results.iter().flat_map(|result| {
        result
            .native_trust_ir
            .iter()
            .flat_map(|native| &native.artifacts)
            .chain(result.proof_evidence.iter().flat_map(|proof| &proof.artifacts))
    }) {
        let Some(materialization) = &artifact.materialization else {
            continue;
        };
        if let Some(path) = &materialization.materialized_path {
            if counted_native_paths.insert(path.clone()) {
                materialized_bytes = materialized_bytes.saturating_add(materialization.byte_len);
            }
        } else {
            materialized_bytes = materialized_bytes.saturating_add(materialization.byte_len);
        }
    }
    if materialized_bytes > MAX_FUNCTION_TRANSPORT_MATERIALIZATION_BYTES {
        let message = format!(
            "inline proof materialization totals {materialized_bytes} bytes, exceeding the per-function {MAX_FUNCTION_TRANSPORT_MATERIALIZATION_BYTES}-byte transport cap; exact payloads withheld and publication proof credit disabled"
        );
        for result in &mut transported_results {
            if let Some(native) = &mut result.native_trust_ir {
                for artifact in &mut native.artifacts {
                    artifact.materialization = None;
                }
                native.diagnostics.push(transport_diagnostic(
                    "native_materialization_transport_limit",
                    TransportEvidenceDiagnosticSeverity::Error,
                    &message,
                ));
            }
            if let Some(proof) = &mut result.proof_evidence {
                for artifact in &mut proof.artifacts {
                    artifact.materialization = None;
                }
                proof.diagnostics.push(transport_diagnostic(
                    "proof_materialization_transport_limit",
                    TransportEvidenceDiagnosticSeverity::Error,
                    &message,
                ));
            }
        }
    }
    let msg = TransportMessage::FunctionResult(FunctionTransportResult {
        function: func_path.to_string(),
        package_name,
        crate_name: Some(crate_name),
        primary_package,
        verification_session: tcx
            .sess
            .opts
            .unstable_opts
            .trust_verify_session
            .clone()
            .unwrap_or_default(),
        results: transported_results,
        proved,
        failed,
        unknown,
        timed_out,
        skipped,
        runtime_checked,
        // Trust (verify-cache): the authoritative cache-replay count from the
        // summary. The conservative `results` rows above carry these as `unknown`
        // (cross-boundary fail-safe); this surfaces the honest count separately.
        cached: cached as usize,
        total,
    });

    tcx.sess.with_trust_compiler_state::<TransportCrateAccumulator, _>(|summary| {
        summary.functions_analyzed += 1;
        if total > 0 && proved == total {
            summary.functions_verified += 1;
        }
        summary.total_proved += proved;
        summary.total_failed += failed;
        summary.total_unknown += unknown;
        summary.total_timed_out += timed_out;
        summary.total_skipped += skipped;
        summary.total_runtime_checked += runtime_checked;
        summary.total_obligations += total;
    });

    // Trust: Serialize and emit as a single line. Best-effort — serialization
    // failure is non-fatal since text diagnostics are still emitted.
    if let Ok(json) = serde_json::to_string(&msg) {
        emit_transport_payload(tcx, &json);
    }
}

#[derive(Clone, Default, PartialEq, Eq)]
struct TransportCrateAccumulator {
    functions_analyzed: usize,
    functions_verified: usize,
    total_proved: usize,
    total_failed: usize,
    total_unknown: usize,
    total_timed_out: usize,
    total_skipped: usize,
    total_runtime_checked: usize,
    total_obligations: usize,
    emitted: bool,
}

/// Emit one end-of-compile target inventory record, including zero-function
/// targets. Targo uses this to prove that every selected primary package target
/// actually ran the verifier; a global "saw some rows" check is insufficient.
pub fn trust_emit_transport_crate_summary(tcx: TyCtxt<'_>) {
    let role = tcx.sess.trust_crate_role();
    if !verification_enabled(tcx.sess) || !TrustOutputMode::parse(tcx.sess).emit_json() {
        return;
    }

    let crate_name = tcx.crate_name(LOCAL_CRATE).to_string();
    let package_name = tcx.sess.opts.unstable_opts.trust_verify_package_name.clone();
    let primary_package = role.is_cargo_primary();
    let summary = tcx.sess.with_trust_compiler_state::<TransportCrateAccumulator, _>(|state| {
        if state.emitted {
            return None;
        }
        state.emitted = true;
        Some(CrateTransportSummary {
            crate_name,
            package_name,
            primary_package,
            verification_session: tcx
                .sess
                .opts
                .unstable_opts
                .trust_verify_session
                .clone()
                .unwrap_or_default(),
            functions_analyzed: state.functions_analyzed,
            functions_verified: state.functions_verified,
            total_proved: state.total_proved,
            total_failed: state.total_failed,
            total_unknown: state.total_unknown,
            total_timed_out: state.total_timed_out,
            total_skipped: state.total_skipped,
            total_runtime_checked: state.total_runtime_checked,
            total_obligations: state.total_obligations,
        })
    });
    if let Some(summary) = summary
        && let Ok(json) = serde_json::to_string(&TransportMessage::CrateSummary(summary))
    {
        emit_transport_payload(tcx, &json);
    }
}

fn emit_transport_payload(tcx: TyCtxt<'_>, json: &str) {
    let payload = format!("{TRANSPORT_PREFIX}{json}");
    match tcx.sess.opts.error_format {
        ErrorOutputType::HumanReadable { .. } => {
            // Raw trustc/driver consumers retain the one-line protocol. Do not
            // also emit a diagnostic here: human diagnostics render a second
            // `note: TRUST_JSON:...` copy and make one logical row look like two.
            eprintln!("{payload}");
        }
        ErrorOutputType::Json { .. } => {
            // Cargo JSON mode wraps diagnostics in a compiler-message carrying
            // package/target identity. Targo accepts crate-mode evidence only
            // through that envelope, so build-script stderr cannot forge
            // verifier transport. A raw line in this mode would sit outside the
            // Cargo envelope and re-open that provenance ambiguity.
            let mut diagnostic = tcx.dcx().struct_span_note(DUMMY_SP, payload);
            // This code marks a transport envelope, not a version-gated lint;
            // there is no minimum Rust version associated with it.
            diagnostic.is_lint(TRANSPORT_DIAGNOSTIC_CODE.to_string(), false, None);
            diagnostic.emit();
        }
    }
}

/// Trust: Returns true when the generated program retains a corresponding runtime check.
///
/// This is the incremental step toward #22: when static proof fails for an obligation
/// that Rust already guards dynamically, we classify it as `RUNTIME-CHECKED` instead
/// of leaving it as a bare UNKNOWN/TIMEOUT.
fn has_runtime_check(sess: &Session, kind: &VcKind) -> bool {
    runtime_check_available(kind, sess.overflow_checks())
}

/// Trust: Pure runtime-check classification helper for unit tests and diagnostics.
fn runtime_check_available(kind: &VcKind, overflow_checks: bool) -> bool {
    kind.has_runtime_fallback(overflow_checks)
}

/// Trust: Human-readable note explaining the runtime fallback.
fn runtime_check_note(kind: &VcKind) -> &'static str {
    match kind {
        VcKind::ArithmeticOverflow { .. }
        | VcKind::ShiftOverflow { .. }
        | VcKind::NegationOverflow { .. } => {
            "compiler retained the existing overflow check because the proof is not yet static"
        }
        VcKind::DivisionByZero | VcKind::RemainderByZero => {
            "compiler retained the existing division-by-zero check because the proof is not yet static"
        }
        VcKind::IndexOutOfBounds | VcKind::SliceBoundsCheck => {
            "compiler retained the existing bounds check because the proof is not yet static"
        }
        VcKind::Assertion { .. } => {
            "compiler retained the existing assertion because the proof is not yet static"
        }
        VcKind::Unreachable => {
            "compiler retained the existing unreachable trap because the proof is not yet static"
        }
        VcKind::FloatDivisionByZero | VcKind::FloatOverflowToInfinity { .. } => {
            "floating-point operations do not trap at runtime; no dynamic fallback exists"
        }
        VcKind::CastOverflow { .. }
        | VcKind::Precondition { .. }
        | VcKind::Postcondition
        | VcKind::DeadState { .. }
        | VcKind::Deadlock
        | VcKind::Temporal { .. }
        | VcKind::Liveness { .. }
        | VcKind::Fairness { .. }
        | VcKind::TaintViolation { .. }
        | VcKind::RefinementViolation { .. }
        | VcKind::ResilienceViolation { .. }
        | VcKind::ProtocolViolation { .. }
        | VcKind::NonTermination { .. } => {
            "no runtime-check fallback is available for this obligation kind"
        }
        _ => "no runtime-check fallback is available for this obligation kind",
    }
}

/// Trust: Format a VcKind into a short tag for bracketed display.
fn format_vc_kind(kind: &VcKind) -> String {
    // Trust: a native full-lane round-trip row retains the original typed
    // family and description inside `UnsupportedMir`. Recover its REAL kind
    // tag for presentation instead of collapsing to "unknown"; proof identity,
    // strict-L0 classification, and cache keys continue to read the raw typed
    // kind/fields — see `VcKind::recovered_full_lane_vc_tag`.
    if let VcKind::UnsupportedMir { kind: raw, detail } = kind
        && let Some(tag) = VcKind::recovered_full_lane_vc_tag(raw, detail)
    {
        return tag.to_string();
    }
    // Trust: single source of truth for the compact tag. The typed VC now also
    // travels in `TransportObligationResult::typed_kind`, and consumers check
    // the `typed_kind.transport_tag() == kind` correspondence — deriving both
    // from the same `trust_types` method keeps them from drifting.
    kind.transport_tag()
}

/// Trust (M-Pkg perf): run kernel certification ONCE per obligation, up front.
///
/// `trust_certify::certify_vc` reconstructs and re-checks a CIC proof term with
/// the clean kernel — the expensive part of the Certified tier. Both downstream
/// consumers need its result: `build_proof_results` (only the `is_some()` bit,
/// to decide the `Certified` status) and `build_transport_results` (the full
/// `CleanCic` term, to ship as a re-checkable report artifact). Previously each
/// re-ran `certify_vc` independently, kernel-checking every Proved obligation
/// twice. Hoisting it here computes it exactly once; the returned vector is
/// index-aligned with `results` (entry `i` is `Some(evidence)` iff `results[i]`
/// is a Proved obligation the kernel independently certified, else `None`), so
/// both builders can read the precomputed slice positionally.
///
/// Certification is attempted only for `Proved` results — fail-closed: any
/// other outcome (Failed/Unknown/Timeout) is never certifiable and maps to
/// `None` without invoking the kernel.
///
/// Trust (M5 blocker #0 — census core repeatability): `deadline` is the SAME
/// per-function wall-clock deadline the solver dispatch already respects
/// (`verify_fn_deadline` / tracked `-Ztrust-verify-function-budget-ms`; zero means
/// no deadline). Once the
/// deadline is reached this STOPS invoking the kernel for any further
/// obligation in this function — each is mapped to `None` exactly as an
/// obligation the kernel declined to certify already would be. Fail-closed: a
/// skipped certification can only DOWNGRADE the "Certified" evidence tier
/// (the underlying `Proved` verdict from the solver is untouched), never
/// upgrade or fabricate a certification that never ran.
fn certify_all(
    results: &[(VerificationCondition, VerificationResult)],
    deadline: Option<std::time::Instant>,
) -> Vec<Option<trust_ir::ProofEvidence>> {
    let mut evidence = Vec::with_capacity(results.len());
    for (vc, result) in results {
        if deadline.is_some_and(|at| std::time::Instant::now() >= at) {
            evidence.extend((evidence.len()..results.len()).map(|_| None));
            break;
        }
        evidence.push(if matches!(result, VerificationResult::Proved { .. }) {
            trust_certify::certify_vc(vc)
        } else {
            None
        });
    }
    evidence
}

fn strict_smt_revalidate(
    formula: &trust_types::Formula,
    budget_ms: u64,
) -> Option<StrictSmtRevalidation> {
    let outcome =
        trust_router::in_process_ay_backend::revalidate_vc_unsat_strict(formula, budget_ms)?;
    Some(StrictSmtRevalidation {
        canonical_problem: outcome.canonical_problem().to_string(),
        problem_sha256: outcome.canonical_problem_sha256().to_string(),
        time_ms: outcome.time_ms(),
    })
}

/// Trust: sealed-authority S1 (SolverReplayAuthority, SMT lane). Only rows
/// carrying a private, exact [`SolverRevalidationEligibility`] minted by the
/// local AY bridge are re-solved. Public `Proved` labels and evidence strings
/// are deliberately irrelevant. The CleanCIC carrier is consumed alongside the
/// rows so a kernel-certified row is skipped rather than redundantly downgraded
/// to SMT authority. Any carrier-length skew returns all `None` without calling
/// the solver.
fn revalidate_all_solver_proofs(
    results: &[(VerificationCondition, VerificationResult)],
    eligibilities: &[Option<SolverRevalidationEligibility>],
    cleancic: &[Option<trust_ir::ProofEvidence>],
    deadline: Option<std::time::Instant>,
) -> Vec<Option<SolverRevalidationReceipt>> {
    revalidate_all_solver_proofs_with(
        results,
        eligibilities,
        cleancic,
        deadline,
        std::time::Instant::now,
        strict_smt_revalidate,
    )
}

/// Injectable core for deterministic deadline and provenance tests. Production
/// passes `Instant::now` and `strict_smt_revalidate`; the injected callbacks do
/// not add an alternate production authority seam.
fn revalidate_all_solver_proofs_with<Now, Revalidate>(
    results: &[(VerificationCondition, VerificationResult)],
    eligibilities: &[Option<SolverRevalidationEligibility>],
    cleancic: &[Option<trust_ir::ProofEvidence>],
    deadline: Option<std::time::Instant>,
    mut now: Now,
    mut revalidate: Revalidate,
) -> Vec<Option<SolverRevalidationReceipt>>
where
    Now: FnMut() -> std::time::Instant,
    Revalidate: FnMut(&trust_types::Formula, u64) -> Option<StrictSmtRevalidation>,
{
    if results.len() != eligibilities.len() || results.len() != cleancic.len() {
        return vec![None; results.len()];
    }

    let mut receipts = Vec::with_capacity(results.len());
    for (index, (vc, result)) in results.iter().enumerate() {
        let current_row = exact_result_row_identity(index, vc);
        let eligibility = eligibilities[index].as_ref();
        let expected_problem = trust_router::in_process_ay_backend::problem_smt2(&vc.formula);
        let has_kernel_proof = matches!(
            cleancic.get(index).and_then(Option::as_ref),
            Some(trust_ir::ProofEvidence::CleanCic { .. })
        );
        let is_exact_eligible_row = is_strict_smt_proved_result(result)
            && !has_kernel_proof
            && !matches!(vc.kind, VcKind::UnsupportedMir { .. })
            && current_row.as_ref().is_some_and(|row| {
                eligibility.is_some_and(|eligibility| {
                    &eligibility.row == row
                        && eligibility.producer_canonical_problem.as_bytes()
                            == expected_problem.as_bytes()
                })
            });
        if !is_exact_eligible_row {
            receipts.push(None);
            continue;
        }

        // Each fresh solve gets at most four seconds and never more than the
        // remaining absolute function budget. The post-check is equally
        // authoritative: the synchronous AY API cannot enforce time spent
        // waiting for its process-global lock, so a late success is discarded.
        let pre_solve_now = now();
        if deadline.is_some_and(|at| pre_solve_now >= at) {
            receipts.extend((receipts.len()..results.len()).map(|_| None));
            break;
        }
        let Some(budget_ms) =
            remaining_solver_timeout_ms(SOLVER_REVALIDATION_BUDGET_MS, deadline, pre_solve_now)
        else {
            receipts.extend((receipts.len()..results.len()).map(|_| None));
            break;
        };
        let fresh = revalidate(&vc.formula, budget_ms);
        if deadline.is_some_and(|at| now() >= at) {
            receipts.push(None);
            receipts.extend((receipts.len()..results.len()).map(|_| None));
            break;
        }

        let receipt = fresh.and_then(|fresh| {
            if fresh.canonical_problem.as_bytes() != expected_problem.as_bytes() {
                return None;
            }
            let current_row = current_row?;
            Some(SolverRevalidationReceipt {
                row_index: current_row.index,
                canonical_vc: current_row.canonical_vc,
                canonical_problem: fresh.canonical_problem,
                problem_sha256: fresh.problem_sha256,
                time_ms: fresh.time_ms,
            })
        });
        receipts.push(receipt);
    }
    receipts
}

// ---------------------------------------------------------------------------
// Trust: VC + VerificationResult -> TrustProofResults conversion (#35)
//
// Bridges the trust-types verification IR to the compiler-internal
// TrustProofResults type that will be stored in the query system.
// ---------------------------------------------------------------------------

/// Re-generate the compiler-owned VC set and retain only exact definition-site
/// `Requires` bookkeeping rows.
///
/// A recursive call has `callee == function`, exactly like the function's own
/// entry marker, so names and the literal `Bool(false)` representation are not
/// sufficient provenance. The vcgen producer stamps the dense authored-clause
/// index; this consumer validates that index, kind, span, and complete VC bytes
/// against a fresh generation from the canonical [`trust_types::VerifiableFunction`]. Any
/// missing, duplicate, stale, or forged hint therefore yields no exemption.
fn exact_definition_entry_assumption_rows(
    function: &trust_types::VerifiableFunction,
) -> Vec<VerificationCondition> {
    if !function
        .contracts
        .iter()
        .any(|contract| matches!(contract.kind, trust_types::ContractKind::Requires))
    {
        return Vec::new();
    }

    trust_vcgen::generate_vcs(function)
        .into_iter()
        .filter(|vc| {
            let Some(source_index) =
                vc.contract_metadata.and_then(|metadata| metadata.source_contract_index)
            else {
                return false;
            };
            let Some(contract) = function.contracts.get(source_index) else {
                return false;
            };
            matches!(contract.kind, trust_types::ContractKind::Requires)
                && contract.span == vc.location
                && vc.function.as_str() == function.name
                && matches!(
                    &vc.kind,
                    VcKind::Precondition { callee } if callee == &function.name
                )
                && matches!(vc.formula, Formula::Bool(false))
        })
        .collect()
}

fn is_exact_definition_entry_assumption_row(
    vc: &VerificationCondition,
    regenerated_rows: &[VerificationCondition],
) -> bool {
    let Some(key) = exact_vc_key(vc) else { return false };
    regenerated_rows.iter().filter(|expected| exact_vc_key(expected).as_ref() == Some(&key)).count()
        == 1
}

/// The current result carrier must also contain the exact row once. Fresh
/// regeneration proves source ownership, but cannot distinguish one supplied
/// row from two byte-identical copies of that row. A duplicate carrier is
/// ambiguous and must not receive definition-entry assumption authority.
fn exact_result_row_counts(
    results: &[(VerificationCondition, VerificationResult)],
) -> FxHashMap<ExactVcKey, usize> {
    let mut counts = FxHashMap::default();
    for (vc, _) in results {
        if let Some(key) = exact_vc_key(vc) {
            *counts.entry(key).or_default() += 1;
        }
    }
    counts
}

fn is_unique_exact_result_row(
    vc: &VerificationCondition,
    counts: &FxHashMap<ExactVcKey, usize>,
) -> bool {
    let Some(key) = exact_vc_key(vc) else { return false };
    counts.get(&key) == Some(&1)
}

fn fail_closed_unproved_precondition(
    kind: &VcKind,
    status: TrustStatus,
    is_definition_entry: bool,
) -> TrustStatus {
    if matches!(kind, VcKind::Precondition { .. })
        && !is_definition_entry
        && matches!(
            status,
            TrustStatus::Unknown | TrustStatus::Timeout | TrustStatus::RuntimeChecked
        )
    {
        TrustStatus::Failed
    } else {
        status
    }
}

/// Trust: Build compiler-internal TrustProofResults from verification pipeline output.
///
/// Creates one TrustDisposition per (VC, result) pair, computes a 128-bit
/// Fingerprint for each obligation (structural hash of VC kind + function + index),
/// and aggregates a TrustFunctionSummary with counts per status.
///
/// The returned TrustProofResults is ready for storage in the query system
/// (pending #32 query registration).
fn build_proof_results(
    sess: &Session,
    results: &[(VerificationCondition, VerificationResult)],
    fallback_vcs: &[VerificationCondition],
    result_bindings: &[Option<ResultObligationBinding>],
    // Exact private authority, index-aligned with `results`. Missing or
    // misaligned entries fail closed; public result labels cannot substitute.
    authorities: &[Option<ResultProofAuthority>],
    // Canonical source used to distinguish a definition-entry assumption from
    // a recursive call-site precondition. `None` grants no source-based skip.
    source_function: Option<&trust_types::VerifiableFunction>,
) -> TrustProofResults {
    build_proof_results_with_runtime_checks(
        sess.overflow_checks(),
        results,
        fallback_vcs,
        result_bindings,
        authorities,
        source_function,
    )
}

/// Pure core shared with authority-parity unit tests. Runtime fallback is the
/// only part of proof-result conversion that depends on Session configuration.
fn build_proof_results_with_runtime_checks(
    overflow_checks: bool,
    results: &[(VerificationCondition, VerificationResult)],
    fallback_vcs: &[VerificationCondition],
    result_bindings: &[Option<ResultObligationBinding>],
    authorities: &[Option<ResultProofAuthority>],
    source_function: Option<&trust_types::VerifiableFunction>,
) -> TrustProofResults {
    // Trust: Build parallel IndexVec<ObligationId, _> for dispositions and fingerprints.
    let mut dispositions: IndexVec<ObligationId, TrustDisposition> = IndexVec::new();
    let mut fingerprints: IndexVec<ObligationId, Fingerprint> = IndexVec::new();

    // Trust: Summary counters.
    let mut trusted: u32 = 0;
    let mut certified: u32 = 0;
    let mut failed: u32 = 0;
    let mut unknown: u32 = 0;
    let mut runtime_checked: u32 = 0;
    let mut max_level = TrustProofLevel::None;
    let definition_entry_rows =
        source_function.map(exact_definition_entry_assumption_rows).unwrap_or_default();
    let supplied_row_counts = exact_result_row_counts(results);

    // Trust: If results are available (trust-router ran), use paired (VC, result).
    // Otherwise fall back to VCs-only with Unknown status (no solver ran yet).
    if !results.is_empty() {
        for (index, (vc, result)) in results.iter().enumerate() {
            let kind = convert_vc_kind(&vc.kind);
            let unique_result_row = is_unique_exact_result_row(vc, &supplied_row_counts);
            // Trust: phase-A vacuity gate — a Proved result whose violation
            // formula constant-folds to `false` (a literal true/false goal) is
            // vacuous and must not be certified. Downgrades to Unknown so it
            // cannot count as a real proof; genuine symbolic proofs pass through.
            //
            // The authority carrier was minted from this exact row's CleanCic
            // term, fresh solver revalidation, or compiler-owned live body
            // receipt. `.get` is defensive: a length mismatch loses authority
            // rather than borrowing a token.
            let binding = result_bindings.get(index).and_then(Option::as_ref);
            let authority = authorities
                .get(index)
                .and_then(Option::as_ref)
                .filter(|authority| {
                    authority.matches_row(index, vc, binding)
                        && authority.matches_compiler_result(result)
                })
                .filter(|authority| {
                    unique_result_row
                        || !matches!(
                            authority,
                            ResultProofAuthority::DefinitionEntryAssumption { .. }
                        )
                });
            // Trust (P1.2): the def-site `#[requires]` bookkeeping placeholder
            // is exempt from the vacuity gate only when the exact private
            // DefinitionEntryAssumption token is present. The public solver
            // label is attribution, never authority.
            let gated_result =
                apply_vacuity_gate_with_authority(index, vc, result.clone(), binding, authority);
            let (status, strength) =
                convert_result(overflow_checks, index, vc, binding, &gated_result, authority);
            // Trust (#5-PRE-A — caller-side precondition is a CHECKED obligation,
            // fail-closed): a `VcKind::Precondition` is the compensating caller-side
            // check that MUST hold because the callee discharged its OWN Level-0 safety
            // obligation (DivisionByZero / IndexOutOfBounds / overflow / …) by ASSUMING
            // its `#[requires]` (`generate_vcs_with_extra_precondition` conjoins the
            // precondition onto every callee body VC, and the def-site `#[requires]` VC
            // is a trivially-discharged `Bool(false)` ASSUMPTION, not an obligation —
            // contracts.rs). So a caller-side precondition VC whose negation the solver
            // could NOT refute means the callee's assumed precondition was never
            // established here: shipping green would be a false-PROVE of the callee's L0
            // property (the cardinal sin — trust_verify.rs modular-soundness comment).
            //
            // The routing makes this a silent hole: a Precondition VC is
            // `ProofLevel::L1Functional` (vc_kind.rs), excluded from both strict-L0
            // fatal gates (`is_strict_l0_vc_kind` / `is_strict_l0_api_obligation_kind`),
            // and routes to trust-wp whose native replay is a constant-folder that
            // returns Unknown on a free variable — bucketed non-fatally as a coverage
            // gap. Reclassify a non-proved Precondition into `Failed` here so the
            // authoritative `proof_results.summary.failed` (which
            // `abort_on_full_verification_failure` reads via `full_verification_failure`)
            // drives the fail-closed abort. This is the caller-side analogue of the
            // existing `is_known_panicking_call_unsupported_mir` reclassification.
            //
            // SOUNDNESS / no-over-rejection: a caller that GENUINELY establishes a
            // decidable (linear) precondition arrives here ALREADY `Proved` — the ay
            // re-solve (`bridge_v1_ay_proofs_into_native_results`, now that
            // `InProcessAyBackend::can_handle` admits `Precondition`) refutes `¬P[σ]` for a
            // violated linear precondition (→ Failed, kept) and proves it UNSAT for an
            // established one (→ Proved, NOT reclassified). Only a residual
            // Unknown/RuntimeChecked/Timeout Precondition — one no engine could discharge —
            // is reclassified. `Certified`/`Trusted` and `Proved` are preserved. A caller
            // of a genuinely-true NONLINEAR precondition the backends cannot prove now
            // fails closed (a completeness gap the follow-on backend-routing piece
            // addresses), never a false PROVE.
            //
            // CRITICAL SCOPING: exempt only an exact private full-lane entry
            // authority or a source-indexed row byte-identically regenerated
            // from this function. The former `callee != function` heuristic
            // was unsound for recursive self-calls: their call-site obligation
            // also has `callee == function` and could survive Unknown without
            // establishing the recursive precondition.
            let is_definition_entry = unique_result_row
                && (authority.is_some_and(|authority| {
                    authority.is_definition_entry_assumption_for(index, vc, binding)
                }) || is_exact_definition_entry_assumption_row(vc, &definition_entry_rows));
            let status = fail_closed_unproved_precondition(&vc.kind, status, is_definition_entry);
            let is_certified = matches!(status, TrustStatus::Certified);

            let disposition = TrustDisposition { kind, status, strength, certified: is_certified };

            dispositions.push(disposition);
            fingerprints.push(compute_obligation_fingerprint(vc));

            // Trust: Accumulate summary counts.
            match status {
                TrustStatus::Trusted => trusted += 1,
                TrustStatus::Certified => certified += 1,
                TrustStatus::Failed => failed += 1,
                TrustStatus::Unknown | TrustStatus::Timeout => unknown += 1,
                TrustStatus::RuntimeChecked => runtime_checked += 1,
            }

            // Trust: Track max proof level from VC kind.
            let level = convert_proof_level(&vc.kind);
            if level > max_level {
                max_level = level;
            }
        }
    } else {
        // Trust: No solver results — create Unknown dispositions for all VCs.
        for vc in fallback_vcs {
            let kind = convert_vc_kind(&vc.kind);
            let disposition = TrustDisposition {
                kind,
                status: TrustStatus::Unknown,
                strength: TrustProofStrength::None,
                certified: false,
            };

            dispositions.push(disposition);
            fingerprints.push(compute_obligation_fingerprint(vc));
            unknown += 1;

            let level = convert_proof_level(&vc.kind);
            if level > max_level {
                max_level = level;
            }
        }
    }

    let total = dispositions.len() as u32;

    let summary = TrustFunctionSummary {
        total,
        trusted,
        certified,
        failed,
        unknown,
        runtime_checked,
        // Trust: fresh-computed summary (no cache replay), so no cached HITs.
        cached: 0,
        max_level,
    };

    TrustProofResults { dispositions, fingerprints, summary }
}

fn build_proof_telemetry(
    sess: &Session,
    results: &[(VerificationCondition, VerificationResult)],
    result_bindings: &[Option<ResultObligationBinding>],
    authorities: &[Option<ResultProofAuthority>],
) -> TrustProofTelemetry {
    let mut details: IndexVec<ObligationId, TrustObligationDetail> = IndexVec::new();

    for (index, (vc, result)) in results.iter().enumerate() {
        let binding = result_bindings.get(index).and_then(Option::as_ref);
        let fallback_for_row =
            |outcome, reason| runtime_fallback_for(sess, &vc.kind, outcome, reason);
        let (solver, time_ms, counterexample, runtime_fallback) = match result {
            VerificationResult::Proved { solver, time_ms, .. }
                if authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
                    authority.permits_static_proved_transport_for(index, vc, result, binding)
                }) =>
            {
                (solver.as_str(), *time_ms, None, None)
            }
            VerificationResult::Proved { solver, time_ms, .. }
                if authorities.get(index).and_then(Option::as_ref).is_some_and(|authority| {
                    authority.is_definition_entry_assumption_for(index, vc, binding)
                }) =>
            {
                (solver.as_str(), *time_ms, None, None)
            }
            VerificationResult::Proved { solver, time_ms, .. } => {
                let fallback = fallback_for_row(
                    RuntimeFallbackOutcome::Unknown,
                    "solver reported Proved without exact kernel/native proof authority",
                );
                (solver.as_str(), *time_ms, None, fallback)
            }
            VerificationResult::Failed { solver, time_ms, counterexample } => {
                (solver.as_str(), *time_ms, counterexample.as_ref(), None)
            }
            VerificationResult::Unknown { solver, time_ms, reason } => {
                let fallback = fallback_for_row(RuntimeFallbackOutcome::Unknown, reason);
                (solver.as_str(), *time_ms, None, fallback)
            }
            VerificationResult::Timeout { solver, timeout_ms } => {
                let fallback = fallback_for_row(
                    RuntimeFallbackOutcome::Timeout,
                    "solver timed out before proving the obligation",
                );
                (solver.as_str(), *timeout_ms, None, fallback)
            }
            _ => (
                result.solver_name(),
                result.time_ms(),
                None,
                fallback_for_row(
                    RuntimeFallbackOutcome::Unknown,
                    "unsupported verification result variant",
                ),
            ),
        };

        details.push(TrustObligationDetail {
            solver: Symbol::intern(solver),
            time_us: time_ms.saturating_mul(1_000),
            counterexample: counterexample
                .map(|cex| {
                    cex.assignments
                        .iter()
                        .map(|(name, value)| {
                            (Symbol::intern(name), encode_counterexample_value(value))
                        })
                        .collect()
                })
                .unwrap_or_default(),
            runtime_fallback,
        });
    }

    TrustProofTelemetry { details }
}

enum RuntimeFallbackOutcome {
    Unknown,
    Timeout,
}

fn runtime_fallback_for(
    sess: &Session,
    kind: &VcKind,
    outcome: RuntimeFallbackOutcome,
    reason: &str,
) -> Option<TrustRuntimeFallback> {
    if !has_runtime_check(sess, kind) {
        return None;
    }

    Some(runtime_fallback_detail(outcome, reason))
}

fn runtime_fallback_detail(outcome: RuntimeFallbackOutcome, reason: &str) -> TrustRuntimeFallback {
    let (fallback_reason, note) = match outcome {
        RuntimeFallbackOutcome::Unknown => {
            (TrustRuntimeFallbackReason::Unknown, format!("solver returned unknown: {reason}"))
        }
        RuntimeFallbackOutcome::Timeout => {
            (TrustRuntimeFallbackReason::Timeout, reason.to_string())
        }
    };

    TrustRuntimeFallback { reason: fallback_reason, note }
}

/// Trust: Convert a trust-types VcKind to the compiler-internal TrustObligationKind.
///
/// Maps the serde-friendly VcKind variants to the Copy/HashStable/TyEncodable
/// TrustObligationKind used in the query system.
fn convert_vc_kind(kind: &VcKind) -> TrustObligationKind {
    if let Some(category) = kind.hardened_category() {
        return TrustObligationKind::HardenedBoundary(convert_hardened_category(category));
    }

    match kind {
        VcKind::ArithmeticOverflow { op, .. } | VcKind::FloatOverflowToInfinity { op, .. } => {
            convert_binop(op)
                .map(TrustObligationKind::ArithmeticOverflow)
                .unwrap_or(TrustObligationKind::UnsupportedMir)
        }
        VcKind::ShiftOverflow { .. } => TrustObligationKind::ShiftOverflow,
        VcKind::DivisionByZero => TrustObligationKind::DivisionByZero,
        VcKind::FloatDivisionByZero => TrustObligationKind::DivisionByZero,
        VcKind::RemainderByZero => TrustObligationKind::RemainderByZero,
        VcKind::IndexOutOfBounds | VcKind::SliceBoundsCheck => {
            TrustObligationKind::IndexOutOfBounds
        }
        VcKind::Assertion { .. } => TrustObligationKind::Assertion,
        VcKind::Precondition { .. } => TrustObligationKind::Precondition,
        VcKind::Postcondition => TrustObligationKind::Postcondition,
        VcKind::CastOverflow { .. } => TrustObligationKind::CastOverflow,
        VcKind::NegationOverflow { .. } => TrustObligationKind::NegationOverflow,
        VcKind::Unreachable => TrustObligationKind::Unreachable,
        VcKind::UnsupportedMir { .. } => TrustObligationKind::UnsupportedMir,
        VcKind::DeadState { .. } | VcKind::Deadlock => TrustObligationKind::Deadlock,
        VcKind::Temporal { .. } => TrustObligationKind::Temporal,
        VcKind::Liveness { .. } | VcKind::Fairness { .. } => TrustObligationKind::Liveness,
        VcKind::TaintViolation { .. } => TrustObligationKind::TaintViolation,
        VcKind::RefinementViolation { .. } => TrustObligationKind::RefinementViolation,
        VcKind::ResilienceViolation { .. } => TrustObligationKind::ResilienceViolation,
        VcKind::ProtocolViolation { .. } => TrustObligationKind::ProtocolViolation,
        VcKind::NonTermination { .. } => TrustObligationKind::NonTermination,
        _ => fallback_internal_obligation_for_proof_level(kind),
    }
}

fn fallback_internal_obligation_for_proof_level(kind: &VcKind) -> TrustObligationKind {
    match convert_proof_level(kind) {
        TrustProofLevel::None => TrustObligationKind::UnsupportedMir,
        TrustProofLevel::L0Safety => TrustObligationKind::Assertion,
        TrustProofLevel::L1Functional => TrustObligationKind::Postcondition,
        TrustProofLevel::L2Domain => TrustObligationKind::ProtocolViolation,
    }
}

fn convert_hardened_category(category: HardenedVcCategory) -> TrustHardenedVcCategory {
    match category {
        HardenedVcCategory::RawPathApi => TrustHardenedVcCategory::RawPathApi,
        HardenedVcCategory::PathIdentity => TrustHardenedVcCategory::PathIdentity,
        HardenedVcCategory::PermissionChange => TrustHardenedVcCategory::PermissionChange,
        HardenedVcCategory::PermissionCreate => TrustHardenedVcCategory::PermissionCreate,
        HardenedVcCategory::PermissionWindow => TrustHardenedVcCategory::PermissionWindow,
        HardenedVcCategory::Utf8Reject => TrustHardenedVcCategory::Utf8Reject,
        HardenedVcCategory::ByteLoss => TrustHardenedVcCategory::ByteLoss,
        HardenedVcCategory::ErrorDiscard => TrustHardenedVcCategory::ErrorDiscard,
        HardenedVcCategory::PanicBoundary => TrustHardenedVcCategory::PanicBoundary,
        HardenedVcCategory::CompatObservable => TrustHardenedVcCategory::CompatObservable,
        HardenedVcCategory::ProcessSemantics => TrustHardenedVcCategory::ProcessSemantics,
        HardenedVcCategory::TrustDomain => TrustHardenedVcCategory::TrustDomain,
        HardenedVcCategory::TrustDomainOrder => TrustHardenedVcCategory::TrustDomainOrder,
        HardenedVcCategory::UnsafeOperation => TrustHardenedVcCategory::UnsafeOperation,
        HardenedVcCategory::FfiBoundary => TrustHardenedVcCategory::FfiBoundary,
        HardenedVcCategory::Unknown(tag) => {
            TrustHardenedVcCategory::Unknown(Symbol::intern(tag.as_str()))
        }
        _ => TrustHardenedVcCategory::Unknown(Symbol::intern(category.as_tag())),
    }
}

/// Convert an overflow-capable trust-types `BinOp` to its exact compiler
/// representation.
///
/// `TrustBinOp` intentionally has no comparison or bitwise variants because
/// those operations cannot name an arithmetic-overflow obligation. Returning
/// `None` keeps malformed/future `ArithmeticOverflow` inputs fail-closed as
/// `UnsupportedMir`; fabricating `Add` here would corrupt the query identity and
/// could let a cached/addition proof stand in for an unrelated operation.
fn convert_binop(op: &BinOp) -> Option<TrustBinOp> {
    match op {
        BinOp::Add => Some(TrustBinOp::Add),
        BinOp::Sub => Some(TrustBinOp::Sub),
        BinOp::Mul => Some(TrustBinOp::Mul),
        BinOp::Div => Some(TrustBinOp::Div),
        BinOp::Rem => Some(TrustBinOp::Rem),
        BinOp::Shl => Some(TrustBinOp::Shl),
        BinOp::Shr => Some(TrustBinOp::Shr),
        BinOp::Eq
        | BinOp::Ne
        | BinOp::Lt
        | BinOp::Le
        | BinOp::Gt
        | BinOp::Ge
        | BinOp::BitAnd
        | BinOp::BitOr
        | BinOp::BitXor
        | BinOp::Cmp => None,
        // `BinOp` is non-exhaustive. A newly added operation must be modeled
        // explicitly before it can participate in a stable proof/cache key.
        _ => None,
    }
}

/// Trust: Convert a VerificationResult to (TrustStatus, TrustProofStrength).
///
/// Maps a result plus its private exact-row authority to the trust model:
/// - Proved + kernel token -> Certified
/// - Proved + private solver-revalidation token -> Trusted
/// - Proved + exact source-clause/live-body token -> Trusted (deductive derivation)
/// - Proved label without a token -> Unknown
/// - Failed -> (Failed, None)
/// - Unknown/Timeout -> (Unknown/Timeout, None)
fn convert_result(
    overflow_checks: bool,
    index: usize,
    vc: &VerificationCondition,
    binding: Option<&ResultObligationBinding>,
    result: &VerificationResult,
    authority: Option<&ResultProofAuthority>,
) -> (TrustStatus, TrustProofStrength) {
    let runtime_fallback = runtime_check_available(&vc.kind, overflow_checks);
    match result {
        VerificationResult::Proved { .. } => {
            // Trust (#2d): attempt in-process kernel certification FIRST — the de
            // Bruijn criterion. `trust_certify::certify_vc` is INDEPENDENT of the
            // incoming solver's self-reported `strength`: it re-asserts this
            // obligation's violation to clean-auto's own in-process ay backend,
            // confirms `UNSAT`, reconstructs the native proof into a CIC proof
            // term under a ZERO-TRUST budget (no `trustedAy`), and RE-CHECKS that
            // term with the clean kernel (`check_type`, `infer_only = false`). A
            // `Some(CleanCic)` therefore means the clean kernel — not the SMT
            // solver — established the obligation, so the original solver is
            // OUTSIDE the trusted base and we may report `Certified` regardless
            // of that solver's own assurance. The separately tracked, default-off
            // overflow-elision lane additionally requires a unique private
            // VC-to-MIR-block origin and live Add/Sub/Mul Assert recheck. This
            // ordering is the whole point of certification:
            // it is exactly the mechanism that upgrades an `Unchecked` SMT solve
            // (e.g. the ay subprocess proving a guard-bounded slice index) into a
            // kernel-checked proof. The weaker `Trusted` tier requires a
            // separately minted private revalidation, source-clause, or live
            // body-bound capability.
            //
            // FAIL-CLOSED: `None` (any unsupported formula shape, non-`UNSAT`
            // solve, residual trust, or kernel rejection) has no kernel token.
            // The verdict was computed once by `certify_all`; no public bool or
            // strength label is accepted in its place.
            if matches!(authority, Some(ResultProofAuthority::KernelCertified { .. })) {
                if env_flag_enabled("TRUST_VERIFY_TRACE_CERTIFIED") {
                    eprintln!("TRUST_E2E_CERTIFIED fn={} kind={:?}", vc.function.as_str(), vc.kind);
                }
            }
            if let Some(disposition) =
                trust_disposition_for_authority(authority, index, vc, result, binding)
            {
                return disposition;
            }
            // A public `Proved`/strength label without a row-bound authority
            // token is advisory only. It cannot mint Trusted or Certified.
            (TrustStatus::Unknown, TrustProofStrength::None)
        }
        VerificationResult::Failed { .. } => (TrustStatus::Failed, TrustProofStrength::None),
        VerificationResult::Unknown { .. } => {
            if runtime_fallback {
                (TrustStatus::RuntimeChecked, TrustProofStrength::None)
            } else {
                (TrustStatus::Unknown, TrustProofStrength::None)
            }
        }
        VerificationResult::Timeout { .. } => {
            if runtime_fallback {
                (TrustStatus::RuntimeChecked, TrustProofStrength::None)
            } else {
                (TrustStatus::Timeout, TrustProofStrength::None)
            }
        }
        _ => (TrustStatus::Unknown, TrustProofStrength::None),
    }
}

#[cfg(test)]
fn proof_strength_satisfies_static_trust(strength: &ProofStrength) -> bool {
    !strength.is_bounded()
        && strength.reasoning.is_complete()
        && strength.assurance.strength_order()
            >= trust_types::AssuranceLevel::Sound.strength_order()
}

/// Trust: Convert a VcKind to TrustProofLevel (L0/L1/L2).
///
/// Mirrors VcKind::proof_level() but returns the compiler-internal enum.
fn convert_proof_level(kind: &VcKind) -> TrustProofLevel {
    match kind.proof_level() {
        trust_types::ProofLevel::L0Safety => TrustProofLevel::L0Safety,
        trust_types::ProofLevel::L1Functional => TrustProofLevel::L1Functional,
        trust_types::ProofLevel::L2Domain => TrustProofLevel::L2Domain,
        _ => TrustProofLevel::L2Domain,
    }
}

/// Trust: Compute a 128-bit Fingerprint for an obligation.
///
/// The fingerprint is a structural hash over the obligation's function,
/// canonical VC kind payload, and logical formula. This provides a stable identity that
/// does NOT depend on MIR locations (which shift during optimization) or on
/// incidental ordering in the generated VC list.
fn compute_obligation_fingerprint(vc: &VerificationCondition) -> Fingerprint {
    let mut hasher = StableHasher::new();
    "trust-obligation-fingerprint-v3".hash(&mut hasher);
    vc.function.as_str().hash(&mut hasher);
    vc_kind_fingerprint_key(&vc.kind).hash(&mut hasher);
    vc.formula.to_smtlib().hash(&mut hasher);
    hasher.finish()
}

/// Trust: produce a bounded, content-addressed MIR-dump filename.
///
/// The full definition path and exact serialized body participate in the
/// address. Distinct bodies therefore never intentionally share a pathname,
/// even if their human-readable definition paths would sanitize identically.
fn mir_dump_filename(def_path: &str, json: &str) -> String {
    let mut hasher = StableHasher::new();
    "trust-mir-dump-v2".hash(&mut hasher);
    def_path.hash(&mut hasher);
    json.hash(&mut hasher);
    let address: Fingerprint = hasher.finish();
    format!("trust-mir-{address}.json")
}

fn native_bundle_dump_filename(def_path: &str, json: &str) -> String {
    let mut hasher = StableHasher::new();
    "trust-native-bundle-dump-v1".hash(&mut hasher);
    def_path.hash(&mut hasher);
    json.hash(&mut hasher);
    let address: Fingerprint = hasher.finish();
    format!("trust-native-bundle-{address}.json")
}

/// Trust: publish a content-addressed dump without overwriting evidence.
///
/// `create_new` makes a hash collision or accidental duplicate observable. An
/// identical pre-existing file is safe to reuse (for repeated MIR queries),
/// while different contents fail closed instead of destroying the first body.
fn write_mir_dump_create_new(path: &std::path::Path, json: &str) -> std::io::Result<bool> {
    match std::fs::OpenOptions::new().write(true).create_new(true).open(path) {
        Ok(mut file) => {
            if let Err(error) = file.write_all(json.as_bytes()) {
                drop(file);
                let _ = std::fs::remove_file(path);
                return Err(error);
            }
            Ok(true)
        }
        Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
            // Reuse is proof-evidence publication, not an ordinary cache hit:
            // never follow a pre-created leaf symlink. `symlink_metadata`
            // supplies a portable fast rejection and O_NOFOLLOW closes the
            // check/open race on Unix.
            let metadata = std::fs::symlink_metadata(path)?;
            if metadata.file_type().is_symlink() || !metadata.is_file() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    "existing MIR dump is not a non-symlink regular file",
                ));
            }
            let mut options = std::fs::OpenOptions::new();
            options.read(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt as _;

                options.custom_flags(libc::O_NOFOLLOW);
            }
            let mut file = options.open(path)?;
            if !file.metadata()?.is_file() {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::InvalidInput,
                    "existing MIR dump changed away from a regular file",
                ));
            }
            let mut existing = String::new();
            file.read_to_string(&mut existing)?;
            if existing == json {
                Ok(false)
            } else {
                Err(std::io::Error::new(
                    std::io::ErrorKind::AlreadyExists,
                    "MIR dump address collision with different contents",
                ))
            }
        }
        Err(error) => Err(error),
    }
}

fn vc_kind_fingerprint_key(kind: &VcKind) -> String {
    serde_json::to_string(kind).unwrap_or_else(|_| kind.description())
}

fn encode_counterexample_value(value: &CounterexampleValue) -> i128 {
    match value {
        CounterexampleValue::Bool(value) => i128::from(*value),
        CounterexampleValue::Int(value) => *value,
        CounterexampleValue::Uint(value) => (*value).min(i128::MAX as u128) as i128,
        CounterexampleValue::Float(value) => i128::from(value.to_bits()),
        _ => 0,
    }
}

